INSERT INTO `Change_Log` VALUES (30470,'description',NULL,NULL,'Use a modal dialog to specify runtime parameters.\nThere should be a little text are that gives hints as to the spring batch parameter key/value conventions, e.g. for type.\n\nMight be a good idea to have a checkbox that lets you select to \'auto increment\' job instance number.','Use a modal dialog to specify runtime parameters.\nThere should be a little text are that gives hints as to the spring batch parameter key/value conventions, e.g. for type.\n\nMight be a good idea to have a checkbox that lets you select to \'auto increment\' job instance number.\n\n4 columns\nkey, value, type, identifying and an \'add parameter\' button that adds a new row.\n\n','DESCRIPTION','2013-11-04 11:47:07',72,2775);
INSERT INTO `Change_Log` VALUES (30471,'description',NULL,NULL,'Use a modal dialog to specify runtime parameters.\nThere should be a little text are that gives hints as to the spring batch parameter key/value conventions, e.g. for type.\n\nMight be a good idea to have a checkbox that lets you select to \'auto increment\' job instance number.\n\n4 columns\nkey, value, type, identifying and an \'add parameter\' button that adds a new row.\n\n','Use a modal dialog to specify runtime parameters.\nThere should be a little text are that gives hints as to the spring batch parameter key/value conventions, e.g. for type.\n\nMight be a good idea to have a checkbox that lets you select to \'auto increment\' job instance number.\n\n4 columns\nkey, value, type, identifying and an \'add parameter\' button that adds a new row.\n\nThis would appear as a modal dialog box, polling of the state of the deployments would be suspended while the job parameter modal dialog box is shown.\n\n','DESCRIPTION','2013-11-04 11:56:05',72,2775);
