INSERT INTO `Change_Log` VALUES (31287,'description',NULL,NULL,'* User specifies download distribution zip file from properties file\n* Copy the distribution from the shared EBS/S3  the ebs volume assigned to the each node/admin instance  .  \n** If not on shared ebs/s3 pull from http site specified by user and put on the shared EBS volume. \n** Unzip the distribution from on the ebs volume for the instance to the /home/ubuntu directory\n','* User specifies download distribution zip file from properties file\n* Copy the distribution from the shared EBS/S3  the ebs volume assigned to the each node/admin instance  .  \n** If not on shared ebs/s3 pull from http site specified by user and put on the shared EBS volume. \n** Unzip the distribution from on the ebs volume for the instance to the /home/ubuntu directory\n** make sure privileges are set to ubuntu not root.\n','DESCRIPTION','2013-10-21 15:38:08',108,2829);
INSERT INTO `Change_Log` VALUES (31288,'summary',NULL,NULL,'Installer needs to use the XD build zip from a URI specified by a user','Deploy distribution zip to each XD Instance as specifed by user  URI','DESCRIPTION','2013-10-21 16:09:58',108,2829);
INSERT INTO `Change_Log` VALUES (31289,'summary',NULL,NULL,'Deploy distribution zip to each XD Instance as specifed by user  URI','Add functionality to download XD distribution zip to each EC2 instance as specified by user ','DESCRIPTION','2013-10-22 09:09:31',72,2829);
INSERT INTO `Change_Log` VALUES (31290,'description',NULL,NULL,'* User specifies download distribution zip file from properties file\n* Copy the distribution from the shared EBS/S3  the ebs volume assigned to the each node/admin instance  .  \n** If not on shared ebs/s3 pull from http site specified by user and put on the shared EBS volume. \n** Unzip the distribution from on the ebs volume for the instance to the /home/ubuntu directory\n** make sure privileges are set to ubuntu not root.\n','* User specifies download distribution zip file from properties file.  See XD-969 for key-value pairs\n* Copy the distribution from the shared EBS/S3  the ebs volume assigned to the each node/admin instance  .  \n** If not on shared ebs/s3 pull from http site specified by user and put on the shared EBS volume. \n** Unzip the distribution from on the ebs volume for the instance to the /home/ubuntu directory\n** make sure privileges are set to ubuntu not root.\n','DESCRIPTION','2013-10-22 09:09:55',72,2829);
INSERT INTO `Change_Log` VALUES (31291,'description',NULL,NULL,'* User specifies download distribution zip file from properties file.  See XD-969 for key-value pairs\n* Copy the distribution from the shared EBS/S3  the ebs volume assigned to the each node/admin instance  .  \n** If not on shared ebs/s3 pull from http site specified by user and put on the shared EBS volume. \n** Unzip the distribution from on the ebs volume for the instance to the /home/ubuntu directory\n** make sure privileges are set to ubuntu not root.\n','* User specifies download distribution zip file from properties file.  See XD-969 for key-value pairs\n* Copy the distribution from the shared EBS/S3  the ebs volume assigned to the each node/admin instance  .  \n** If not on shared ebs/s3 pull from http site specified by user and put on the shared EBS volume. \n** Unzip the distribution from on the ebs volume for the instance to the /home/ubuntu directory\n** make sure privileges are set to ubuntu not root.\n\n\nHow to verify it works\n* Create a JUNit style integration test that\n** Deletes a known .zip distribution from EBS/S3.\n** Invoke the application functionality (should be a 1 liner) that will start up the instance and download the .zip distribution from the URI provided in xd-ec2.properties.  Verify the file is now in EBS/S3 and also on the instance\n** Tear down created instance\n** Create new instance passing in the same URI of the .zip distribution.  Verify as before\n','DESCRIPTION','2013-10-22 09:13:39',72,2829);
