INSERT INTO `Change_Log` VALUES (32074,'description',NULL,NULL,NULL,'Offers the functionality to make http request to a web service. i.e. outbound http gateway.\ni.e. \nstream create --name foo --definition \"trigger |rest --reply-timeout=1 --url=http://earthquake.usgs.gov/earthquakes/feed/geojson/all/day|log\"\n\n\n','DESCRIPTION','2013-09-30 10:33:22',108,2892);
INSERT INTO `Change_Log` VALUES (32075,'description',NULL,NULL,'Offers the functionality to make http request to a web service. i.e. outbound http gateway.\ni.e. \nstream create --name foo --definition \"trigger |rest --reply-timeout=1 --url=http://earthquake.usgs.gov/earthquakes/feed/geojson/all/day|log\"\n\n\n','Offers the functionality to make http request to a web service. i.e. outbound http gateway.\nExample implementations:\nstream create --name foo --definition \"trigger |rest --reply-timeout=1 --url=http://earthquake.usgs.gov/earthquakes/feed/geojson/all/day|log\"\n\nstream create --name foos --definition \"trigger --payload=lat=34.0567006&lon=-84.34368810000001&site=all&smap=1&searchresult=Roswell%2C%20GA%2030076%2C%20USA#.UktzaWSG1Dd | rest --url=http://forecast.weather.gov/MapClick.php? |log\"\n\n','DESCRIPTION','2013-10-01 19:57:02',108,2892);
