INSERT INTO `Change_Log` VALUES (35271,'summary',NULL,NULL,'Create delete commands for all the metrics','Create list/delete commands for all the metrics','DESCRIPTION','2013-08-04 23:59:39',91,3203);
INSERT INTO `Change_Log` VALUES (35272,'description',NULL,NULL,'We need to add delete commands for the metrics:\n\nInMemoryAggregateCounter\nFieldValueCounter\nGauge\nRichGauge\n\nCurrently, the AbstractMetricsController class has the delete method to delete the metric from the repository. We can probably use the same for all the metrics.','We need to add list/delete commands for the metrics:\n\nInMemoryAggregateCounter\nFieldValueCounter\nGauge\nRichGauge\n\nCurrently, the AbstractMetricsController class has the delete method to delete the metric from the repository. We can probably use the same for all the metrics.','DESCRIPTION','2013-08-05 00:02:31',91,3203);
