INSERT INTO `Change_Log` VALUES (269735,'description',NULL,NULL,'Networking isolators such as `network/cni` need to learn about ports that a container wishes to be exposed to the outside world. This can be achieved by adding a field to the `ContainerConfig` protobuf and allowing the `Containerizer` or framework set these fields to inform the isolator of the ports that the container wishes to be exposed. ','Networking isolators such as `network/cni` need to learn about ports that a container wishes to be exposed to the outside world. This can be achieved by adding a field to the `ImageManifest` protobuf and allowing the `ImageProvisioner` to set these fields to inform the isolator of the ports that the container wishes to be exposed. ','DESCRIPTION','2016-03-01 22:54:26',3576,19831);
INSERT INTO `Change_Log` VALUES (269736,'summary',NULL,NULL,'Introduce a port field in `ContainerConfig` in order to set exposed ports for a container.','Introduce a port field in `ImageManifest` in order to set exposed ports for a container.','DESCRIPTION','2016-03-01 22:54:26',3576,19831);
