INSERT INTO `Change_Log` VALUES (269942,'description',NULL,NULL,NULL,'All {{LevelDBStateTest}} tests write to the current directory. This is bad for a number of reasons, e.g.,\n\n* should the test fail data might be leaked to random locations,\n* the test cannot be executed from a write-only directory, or\n* executing tests from the same suite in parallel (e.g., with {{gtest-parallel}} would race on the existence of the created files, and show bogus behavior.\n\nThe tests should probably be executed from a temporary directory, e.g., via stout\'s {{TemporaryDirectoryTest}} fixture.','DESCRIPTION','2016-02-29 08:39:13',3389,19846);
INSERT INTO `Change_Log` VALUES (269943,'labels',NULL,NULL,'','newbie parallel-tests','OTHER','2016-02-29 08:39:13',3389,19846);
