INSERT INTO `Change_Log` VALUES (270241,'description',NULL,NULL,'src/master/constants.hpp contains:\n\n{code}\n// TODO(bmahler): It appears there may be a bug with gcc-4.1.2 in which the\n// duration constants were not being initialized when having static linkage.\n// This issue did not manifest in newer gcc\'s. Specifically, 4.2.1 was ok.\n// So we\'ve moved these to have external linkage but perhaps in the future\n// we can revert this.\n{code}\n\nFrom commit 232a23b2a2e11f4e905b834aa2a11afe5bf6438a. We should investigate whether this is still necessary; it likely is not.','src/master/constants.hpp contains:\n\n{code}\n// TODO(<USER>: It appears there may be a bug with gcc-4.1.2 in which the\n// duration constants were not being initialized when having static linkage.\n// This issue did not manifest in newer gcc\'s. Specifically, 4.2.1 was ok.\n// So we\'ve moved these to have external linkage but perhaps in the future\n// we can revert this.\n{code}\n\nFrom commit 232a23b2a2e11f4e905b834aa2a11afe5bf6438a. We should investigate whether this is still necessary on supported compilers; it likely is not.','DESCRIPTION','2016-02-26 21:31:53',3662,19862);
