INSERT INTO `Change_Log` VALUES (274759,'description',NULL,NULL,'There might be a bug that may crash the master as pointed out by [~bmahler] in https://reviews.apache.org/r/42222/.','There might be a bug that may crash the master as pointed out by [~<USER> in https://reviews.apache.org/r/42222/:\n{noformat}\nIt looks like if we trip the resume call in addSlave, this delayed resume will crash the master due to the CHECK(paused) that currently resides in resume.\n{noformat}','DESCRIPTION','2016-01-20 09:27:12',3967,20235);
INSERT INTO `Change_Log` VALUES (274760,'description',NULL,NULL,'There might be a bug that may crash the master as pointed out by [~bmahler] in https://reviews.apache.org/r/42222/:\n{noformat}\nIt looks like if we trip the resume call in addSlave, this delayed resume will crash the master due to the CHECK(paused) that currently resides in resume.\n{noformat}','There might be a bug that may crash the master as pointed out by [~<USER> in https://reviews.apache.org/r/42222/:\n{noformat}\nIt looks like if we trip the resume call in addSlave, this delayed resume will crash the master \ndue to the CHECK(paused) that currently resides in resume.\n{noformat}','DESCRIPTION','2016-01-20 09:27:26',3967,20235);
