INSERT INTO `Change_Log` VALUES (292955,'description',NULL,NULL,'In order to persist maintenance schedules across failovers of the master, the schedule information must be kept in the replicated registry.\n\nThis means adding an additional key in src/master/registry.proto.  The status of each individual slave\'s maintenance will also be persisted in this way.\n{code}\nmessage Maintenance {\n  message HostStatus {\n    required string hostname = 1;\n\n    // True if the slave is deactivated for maintenance.\n    // False if the slave is draining in preparation for maintenance.\n    required bool is_down = 2;\n  }\n\n  message Schedule {\n    // The set of affected slave(s).\n    repeated HostStatus hosts = 1;\n\n    // Interval in which this set of slaves is expected to be down for.\n    optional Unavailability interval = 2;\n  }\n\n  message Schedules {\n    repeated Schedule schedules;\n  }\n\n  optional Schedules schedules = 1;\n}\n{code}','In order to persist maintenance schedules across failovers of the master, the schedule information must be kept in the replicated registry.\n\nThis means adding an additional key in src/master/registry.proto.  The status of each individual slave\'s maintenance will also be persisted in this way.\n{code}\nmessage Maintenance {\n  message HostStatus {\n    required string hostname = 1;\n\n    // True if the slave is deactivated for maintenance.\n    // False if the slave is draining in preparation for maintenance.\n    required bool is_down = 2;\n  }\n\n  message Schedule {\n    // The set of affected slave(s).\n    repeated HostStatus hosts = 1;\n\n    // Interval in which this set of slaves is expected to be down for.\n    optional Unavailability interval = 2;\n  }\n\n  message Schedules {\n    repeated Schedule schedules;\n  }\n\n  optional Schedules schedules = 1;\n}\n{code}\n\nNote: There can be multiple SlaveID\'s attached to a single hostname.','DESCRIPTION','2015-07-21 21:49:37',3391,21583);
INSERT INTO `Change_Log` VALUES (292956,'description',NULL,NULL,'In order to persist maintenance schedules across failovers of the master, the schedule information must be kept in the replicated registry.\n\nThis means adding an additional key in src/master/registry.proto.  The status of each individual slave\'s maintenance will also be persisted in this way.\n{code}\nmessage Maintenance {\n  message HostStatus {\n    required string hostname = 1;\n\n    // True if the slave is deactivated for maintenance.\n    // False if the slave is draining in preparation for maintenance.\n    required bool is_down = 2;\n  }\n\n  message Schedule {\n    // The set of affected slave(s).\n    repeated HostStatus hosts = 1;\n\n    // Interval in which this set of slaves is expected to be down for.\n    optional Unavailability interval = 2;\n  }\n\n  message Schedules {\n    repeated Schedule schedules;\n  }\n\n  optional Schedules schedules = 1;\n}\n{code}\n\nNote: There can be multiple SlaveID\'s attached to a single hostname.','In order to persist maintenance schedules across failovers of the master, the schedule information must be kept in the replicated registry.\n\nThis means adding an additional message in the Registry protobuf in src/master/registry.proto.  The status of each individual slave\'s maintenance will also be persisted in this way.\n{code}\nmessage Maintenance {\n  message HostStatus {\n    required string hostname = 1;\n\n    // True if the slave is deactivated for maintenance.\n    // False if the slave is draining in preparation for maintenance.\n    required bool is_down = 2;  // Or an enum\n  }\n\n  message Schedule {\n    // The set of affected slave(s).\n    repeated HostStatus hosts = 1;\n\n    // Interval in which this set of slaves is expected to be down for.\n    optional Unavailability interval = 2;\n  }\n\n  message Schedules {\n    repeated Schedule schedules;\n  }\n\n  optional Schedules schedules = 1;\n}\n{code}\n\nNote: There can be multiple SlaveID\'s attached to a single hostname.','DESCRIPTION','2015-07-30 22:45:08',3391,21583);
