INSERT INTO `Change_Log` VALUES (293114,'description',NULL,NULL,'We want to expose docker container IP to Mesos-DNS. One potential solution is to make it available via Master\'s state.json. We can set a label \"docker_inspect\" in TaskStatus message (when it is sent the first time with TASK_RUNNING status).','We want to expose docker container IP to Mesos-DNS. One potential solution is to make it available via Master\'s state.json. We can set a label \"Docker.NetworkSettings.IPAddress\" in TaskStatus message (when it is sent the first time with TASK_RUNNING status).','DESCRIPTION','2015-07-21 18:25:32',3491,21588);
