INSERT INTO `Change_Log` VALUES (8160930,'summary',NULL,NULL,'Windows: Ti.UI.Label.border* properties do not work when using width and height','Windows: Ti.UI.Label.border* properties do not work when not using width and height','DESCRIPTION','2016-07-19 21:21:39',166018,406386);
INSERT INTO `Change_Log` VALUES (8160931,'description',NULL,NULL,'{{Titanium.UI.Label}} disappears if any {{border*}} properties are used.\r\n\r\n{code}\r\nvar win = Ti.UI.createWindow({backgroundColor: \'red\'}),\r\n    lbl = Ti.UI.createLabel({\r\n        backgroundColor: \'orange\',\r\n        borderWidth: 5,\r\n        borderColor: \'yellow\',\r\n        borderRadius: 5,\r\n        text:\'TEST TEXT\'\r\n    });\r\nwin.add(lbl);\r\nwin.open();\r\n{code}','{{Titanium.UI.Label}} disappears if any {{border*}} properties are used and {{width}} and {{height}} are not defined.\r\n\r\n{code}\r\nvar win = Ti.UI.createWindow({backgroundColor: \'red\'}),\r\n    lbl = Ti.UI.createLabel({\r\n        backgroundColor: \'orange\',\r\n        borderWidth: 5,\r\n        borderColor: \'yellow\',\r\n        borderRadius: 5,\r\n        text:\'TEST TEXT\'\r\n    });\r\nwin.add(lbl);\r\nwin.open();\r\n{code}','DESCRIPTION','2016-07-19 21:22:02',166018,406386);
