INSERT INTO `Change_Log` VALUES (8162948,'description',NULL,NULL,'When {{overlay}} is specified for {{Ti.Media.showCamera}}, there is no \"Auto-Focus\" support as well as \"Focus-At-Point\" (Tap to Focus) now, which makes it difficult to focus at certain point at shooting.\r\n\r\n{code}\r\nvar win = Ti.UI.createWindow({ backgroundColor: \'green\', layout: \'vertical\' }),\r\n    openButton = Ti.UI.createButton({ title: \'OPEN CAMERA\', backgroundColor: \'blue\' }),\r\n    imageView = Ti.UI.createImageView({ width: Ti.UI.FILL, height: \'80%\' });\r\n\r\nvar overlay = Ti.UI.createView({\r\n    layout: \'vertical\',\r\n    height: \'20%\', width: Ti.UI.FILL,\r\n    bottom: 0\r\n}),\r\ntakeButton = Ti.UI.createButton({ title: \'TAKE A PHOTO\', backgroundColor: \'red\' }),\r\nhideButton = Ti.UI.createButton({ title: \'HIDE PREVIEW\', backgroundColor: \'red\' });\r\n\r\ntakeButton.addEventListener(\'click\', function () {\r\n    Ti.Media.takePicture();\r\n});\r\nhideButton.addEventListener(\'click\', function () {\r\n    Ti.Media.hideCamera();\r\n});\r\noverlay.add(takeButton);\r\noverlay.add(hideButton);\r\n\r\nopenButton.addEventListener(\'click\', function () {\r\n    Ti.Media.showCamera({\r\n        mediaTypes: [Ti.Media.MEDIA_TYPE_PHOTO],\r\n        overlay: overlay,\r\n        success: function (e) {\r\n            Ti.API.info(\'showCamera() success\');\r\n            imageView.image = e.media;\r\n        },\r\n        error: function (e) {\r\n            alert(\'showCamera() error: \' + JSON.stringify(e));\r\n        }\r\n    });\r\n});\r\n\r\nwin.add(openButton);\r\nwin.add(imageView);\r\nwin.open();\r\n{code}\r\n\r\n','When {{overlay}} is specified for {{Ti.Media.showCamera}}, there is no\"Focus-At-Point\" (Tap to Focus) support now, which makes it difficult to focus at certain point at shooting.\r\n\r\n{code}\r\nvar win = Ti.UI.createWindow({ backgroundColor: \'green\', layout: \'vertical\' }),\r\n    openButton = Ti.UI.createButton({ title: \'OPEN CAMERA\', backgroundColor: \'blue\' }),\r\n    imageView = Ti.UI.createImageView({ width: Ti.UI.FILL, height: \'80%\' });\r\n\r\nvar overlay = Ti.UI.createView({\r\n    layout: \'vertical\',\r\n    height: \'20%\', width: Ti.UI.FILL,\r\n    bottom: 0\r\n}),\r\ntakeButton = Ti.UI.createButton({ title: \'TAKE A PHOTO\', backgroundColor: \'red\' }),\r\nhideButton = Ti.UI.createButton({ title: \'HIDE PREVIEW\', backgroundColor: \'red\' });\r\n\r\ntakeButton.addEventListener(\'click\', function () {\r\n    Ti.Media.takePicture();\r\n});\r\nhideButton.addEventListener(\'click\', function () {\r\n    Ti.Media.hideCamera();\r\n});\r\noverlay.add(takeButton);\r\noverlay.add(hideButton);\r\n\r\nopenButton.addEventListener(\'click\', function () {\r\n    Ti.Media.showCamera({\r\n        mediaTypes: [Ti.Media.MEDIA_TYPE_PHOTO],\r\n        overlay: overlay,\r\n        success: function (e) {\r\n            Ti.API.info(\'showCamera() success\');\r\n            imageView.image = e.media;\r\n        },\r\n        error: function (e) {\r\n            alert(\'showCamera() error: \' + JSON.stringify(e));\r\n        }\r\n    });\r\n});\r\n\r\nwin.add(openButton);\r\nwin.add(imageView);\r\nwin.open();\r\n{code}\r\n\r\n','DESCRIPTION','2016-06-27 04:15:07',166083,406489);
