INSERT INTO `Change_Log` VALUES (8166905,'description',NULL,NULL,'Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} and {{separatorColor}} for {{Ti.UI.TableView}}.','Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} for {{Ti.UI.TableView}}.','DESCRIPTION','2016-07-20 04:26:11',166083,406681);
INSERT INTO `Change_Log` VALUES (8166906,'description',NULL,NULL,'Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} for {{Ti.UI.TableView}}.','Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} for {{Ti.UI.TableView}}.\r\n\r\n*sample code*\r\n{code}\r\nvar win = Ti.UI.createWindow({ backgroundColor: \'red\' }),\r\n    tableView = Ti.UI.createTableView({\r\n        width: \'80%\',\r\n        height: \'80%\',\r\n        backgroundColor: \'orange\',\r\n        borderWidth: 5,\r\n        borderColor: \'yellow\',\r\n        borderRadius: 5,\r\n        data: [{ title: \'Apples\' }, { title: \'Bananas\' }, { title: \'Carrots\' }, { title: \'Potatoes\' }]\r\n    });\r\n\r\ntableView.addEventListener(\'click\', function (e) {\r\n    alert(JSON.stringify(e.row.title));\r\n});\r\n\r\nwin.add(tableView);\r\nwin.open();\r\n{code}\r\n\r\n*Expected*\r\n\r\n','DESCRIPTION','2016-07-20 04:28:26',166083,406681);
INSERT INTO `Change_Log` VALUES (8166907,'Attachment',NULL,'59834',NULL,'Capture.PNG','OTHER','2016-07-20 04:28:43',166083,406681);
INSERT INTO `Change_Log` VALUES (8166908,'description',NULL,NULL,'Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} for {{Ti.UI.TableView}}.\r\n\r\n*sample code*\r\n{code}\r\nvar win = Ti.UI.createWindow({ backgroundColor: \'red\' }),\r\n    tableView = Ti.UI.createTableView({\r\n        width: \'80%\',\r\n        height: \'80%\',\r\n        backgroundColor: \'orange\',\r\n        borderWidth: 5,\r\n        borderColor: \'yellow\',\r\n        borderRadius: 5,\r\n        data: [{ title: \'Apples\' }, { title: \'Bananas\' }, { title: \'Carrots\' }, { title: \'Potatoes\' }]\r\n    });\r\n\r\ntableView.addEventListener(\'click\', function (e) {\r\n    alert(JSON.stringify(e.row.title));\r\n});\r\n\r\nwin.add(tableView);\r\nwin.open();\r\n{code}\r\n\r\n*Expected*\r\n\r\n','Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} for {{Ti.UI.TableView}}.\r\n\r\n*sample code*\r\n{code}\r\nvar win = Ti.UI.createWindow({ backgroundColor: \'red\' }),\r\n    tableView = Ti.UI.createTableView({\r\n        width: \'80%\',\r\n        height: \'80%\',\r\n        backgroundColor: \'orange\',\r\n        borderWidth: 5,\r\n        borderColor: \'yellow\',\r\n        borderRadius: 5,\r\n        data: [{ title: \'Apples\' }, { title: \'Bananas\' }, { title: \'Carrots\' }, { title: \'Potatoes\' }]\r\n    });\r\n\r\ntableView.addEventListener(\'click\', function (e) {\r\n    alert(JSON.stringify(e.row.title));\r\n});\r\n\r\nwin.add(tableView);\r\nwin.open();\r\n{code}\r\n\r\n*Expected*\r\n\r\n\r\n','DESCRIPTION','2016-07-20 04:28:53',166083,406681);
INSERT INTO `Change_Log` VALUES (8166909,'description',NULL,NULL,'Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} for {{Ti.UI.TableView}}.\r\n\r\n*sample code*\r\n{code}\r\nvar win = Ti.UI.createWindow({ backgroundColor: \'red\' }),\r\n    tableView = Ti.UI.createTableView({\r\n        width: \'80%\',\r\n        height: \'80%\',\r\n        backgroundColor: \'orange\',\r\n        borderWidth: 5,\r\n        borderColor: \'yellow\',\r\n        borderRadius: 5,\r\n        data: [{ title: \'Apples\' }, { title: \'Bananas\' }, { title: \'Carrots\' }, { title: \'Potatoes\' }]\r\n    });\r\n\r\ntableView.addEventListener(\'click\', function (e) {\r\n    alert(JSON.stringify(e.row.title));\r\n});\r\n\r\nwin.add(tableView);\r\nwin.open();\r\n{code}\r\n\r\n*Expected*\r\n\r\n\r\n','Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} for {{Ti.UI.TableView}}.\r\n\r\n*sample code*\r\n{code}\r\nvar win = Ti.UI.createWindow({ backgroundColor: \'red\' }),\r\n    tableView = Ti.UI.createTableView({\r\n        width: \'80%\',\r\n        height: \'80%\',\r\n        backgroundColor: \'orange\',\r\n        borderWidth: 5,\r\n        borderColor: \'yellow\',\r\n        borderRadius: 5,\r\n        data: [{ title: \'Apples\' }, { title: \'Bananas\' }, { title: \'Carrots\' }, { title: \'Potatoes\' }]\r\n    });\r\n\r\ntableView.addEventListener(\'click\', function (e) {\r\n    alert(JSON.stringify(e.row.title));\r\n});\r\n\r\nwin.add(tableView);\r\nwin.open();\r\n{code}\r\n\r\n*Expected*\r\n\r\n!Capture.PNG|thumbnail!\r\n','DESCRIPTION','2016-07-20 04:29:10',166083,406681);
