INSERT INTO `Change_Log` VALUES (8168347,'description',NULL,NULL,'Currently if you need to create module project for VS 2013, you need to run {{ti create -p windows -t module --wp-sdk 8.1}} . Bad thing is {{appc new --wp-sdk 8.1 ...}} doesn\'t work in this case. But basically Titanium CLI should be able to select appropriate VS version accordingly without demanding user input.','Currently if you need to create module project for VS 2013, you need to run {{ti create -p windows -t module --wp-sdk 8.1}} . Bad thing is {{appc new --wp-sdk 8.1 ...}} doesn\'t work in this case. But basically Titanium CLI should be able to select appropriate VS version accordingly without demanding user input.\r\n\r\nSo on {{appc new}}, CLI should select VS version accordingly:\r\n\r\n- When user installs VS 2013 only, cmake VS 2013 generator should be selected\r\n- When user installs VS 2015 only, cmake VS 2015 generator should be selected\r\n- When user installs both VS 2015 and VS 2013, cmake VS 2015 generator should be selected because it\'s newer\r\n\r\n','DESCRIPTION','2016-04-20 14:27:14',166083,406744);
INSERT INTO `Change_Log` VALUES (8168348,'status','1','3','Open','In Progress','STATUS','2016-04-20 14:27:33',166083,406744);
INSERT INTO `Change_Log` VALUES (8168349,'description',NULL,NULL,'Currently if you need to create module project for VS 2013, you need to run {{ti create -p windows -t module --wp-sdk 8.1}} . Bad thing is {{appc new --wp-sdk 8.1 ...}} doesn\'t work in this case. But basically Titanium CLI should be able to select appropriate VS version accordingly without demanding user input.\r\n\r\nSo on {{appc new}}, CLI should select VS version accordingly:\r\n\r\n- When user installs VS 2013 only, cmake VS 2013 generator should be selected\r\n- When user installs VS 2015 only, cmake VS 2015 generator should be selected\r\n- When user installs both VS 2015 and VS 2013, cmake VS 2015 generator should be selected because it\'s newer\r\n\r\n','Currently if you need to create module project for VS 2013, you need to run {{ti create -p windows -t module --wp-sdk 8.1}} . Unfortunately {{appc new --wp-sdk 8.1 ...}} doesn\'t work in this case. But basically Titanium CLI should be able to select appropriate VS version accordingly without demanding user input.\r\n\r\nSo on {{appc new}}, CLI should select VS version accordingly:\r\n\r\n- When user installs VS 2013 only, cmake VS 2013 generator should be selected\r\n- When user installs VS 2015 only, cmake VS 2015 generator should be selected\r\n- When user installs both VS 2015 and VS 2013, cmake VS 2015 generator should be selected because it\'s newer\r\n\r\n','DESCRIPTION','2016-04-20 14:38:05',166083,406744);
INSERT INTO `Change_Log` VALUES (8168350,'description',NULL,NULL,'Currently if you need to create module project for VS 2013, you need to run {{ti create -p windows -t module --wp-sdk 8.1}} . Unfortunately {{appc new --wp-sdk 8.1 ...}} doesn\'t work in this case. But basically Titanium CLI should be able to select appropriate VS version accordingly without demanding user input.\r\n\r\nSo on {{appc new}}, CLI should select VS version accordingly:\r\n\r\n- When user installs VS 2013 only, cmake VS 2013 generator should be selected\r\n- When user installs VS 2015 only, cmake VS 2015 generator should be selected\r\n- When user installs both VS 2015 and VS 2013, cmake VS 2015 generator should be selected because it\'s newer\r\n\r\n','Currently if you need to create module project for VS 2013, you need to run {{ti create -p windows -t module --wp-sdk 8.1}} . Unfortunately {{appc new --wp-sdk 8.1 ...}} doesn\'t work in this case. But basically Titanium CLI should be able to select appropriate VS version accordingly without demanding user input.\r\n\r\nSo on {{appc new}} or {{ti create}}, CLI should select VS version accordingly:\r\n\r\n- When user installs VS 2013 only, cmake VS 2013 generator should be selected\r\n- When user installs VS 2015 only, cmake VS 2015 generator should be selected\r\n- When user installs both VS 2015 and VS 2013, cmake VS 2015 generator should be selected because it\'s newer\r\n\r\n','DESCRIPTION','2016-04-20 14:38:29',166083,406744);
