INSERT INTO `Change_Log` VALUES (8169318,'description',NULL,NULL,'Steps to reproduce\r\n\r\n1. Create a Picker with 2 columns\r\n2. PickerRow title set to \"0\" in XML (or \"1\", \"2\", etc)\r\n3. App crashes immediately\r\n\r\nSetting the PickerRow title to \"0\" in the controller js works fine. Android either method works fine.\r\n\r\n*index.xml*\r\n{{\r\n<Alloy>\r\n	<Window class=\"container\">\r\n      <View top=\"10\" layout=\"vertical\" height=\"Ti.UI.SIZE\" width=\"Ti.UI.FILL\">\r\n        <Label color=\"white\">How Much To Add?</Label>\r\n        <Picker id=\"timeAmount\" useSpinner=\"true\">\r\n          <PickerColumn id=\"hours\" width=\"50%\">\r\n            <PickerRow title=\"0\"/>\r\n            <PickerRow title=\"1\"/>\r\n            <PickerRow title=\"2\"/>\r\n            <PickerRow title=\"3\"/>\r\n            <PickerRow title=\"4\"/>\r\n          </PickerColumn>\r\n          <PickerColumn id=\"min\" useSpinner=\"true\" width=\"50%\">\r\n            <PickerRow title=\".00\"/>\r\n            <PickerRow title=\".25\"/>\r\n            <PickerRow title=\".50\"/>\r\n            <PickerRow title=\".75\"/>\r\n          </PickerColumn>\r\n        </Picker>\r\n      </View>\r\n	</Window>\r\n</Alloy>\r\n}}\r\n\r\n*index.js*\r\n{{\r\n$.index.open();\r\n}}','Steps to reproduce\r\n\r\n1. Create a Picker with 2 columns\r\n2. PickerRow title set to \"0\" in XML (or \"1\", \"2\", etc)\r\n3. App crashes immediately\r\n\r\nSetting the PickerRow title to \"0\" in the controller js works fine. Android either method works fine.\r\n\r\n*index.xml*\r\n<Alloy>\r\n   <Window class=\"container\">\r\n      <View top=\"10\" layout=\"vertical\" height=\"Ti.UI.SIZE\" width=\"Ti.UI.FILL\">\r\n        <Label color=\"white\">How Much To Add?</Label>\r\n        <Picker id=\"timeAmount\" useSpinner=\"true\">\r\n          <PickerColumn id=\"hours\" width=\"50%\">\r\n            <PickerRow title=\"0\"/>\r\n            <PickerRow title=\"1\"/>\r\n            <PickerRow title=\"2\"/>\r\n            <PickerRow title=\"3\"/>\r\n            <PickerRow title=\"4\"/>\r\n          </PickerColumn>\r\n          <PickerColumn id=\"min\" useSpinner=\"true\" width=\"50%\">\r\n            <PickerRow title=\".00\"/>\r\n            <PickerRow title=\".25\"/>\r\n            <PickerRow title=\".50\"/>\r\n            <PickerRow title=\".75\"/>\r\n          </PickerColumn>\r\n        </Picker>\r\n      </View>\r\n	</Window>\r\n</Alloy>\r\n\r\n*index.js*\r\n\r\n$.index.open();\r\n','DESCRIPTION','2016-04-11 21:02:44',166480,406790);
INSERT INTO `Change_Log` VALUES (8169319,'description',NULL,NULL,'Steps to reproduce\r\n\r\n1. Create a Picker with 2 columns\r\n2. PickerRow title set to \"0\" in XML (or \"1\", \"2\", etc)\r\n3. App crashes immediately\r\n\r\nSetting the PickerRow title to \"0\" in the controller js works fine. Android either method works fine.\r\n\r\n*index.xml*\r\n<Alloy>\r\n   <Window class=\"container\">\r\n      <View top=\"10\" layout=\"vertical\" height=\"Ti.UI.SIZE\" width=\"Ti.UI.FILL\">\r\n        <Label color=\"white\">How Much To Add?</Label>\r\n        <Picker id=\"timeAmount\" useSpinner=\"true\">\r\n          <PickerColumn id=\"hours\" width=\"50%\">\r\n            <PickerRow title=\"0\"/>\r\n            <PickerRow title=\"1\"/>\r\n            <PickerRow title=\"2\"/>\r\n            <PickerRow title=\"3\"/>\r\n            <PickerRow title=\"4\"/>\r\n          </PickerColumn>\r\n          <PickerColumn id=\"min\" useSpinner=\"true\" width=\"50%\">\r\n            <PickerRow title=\".00\"/>\r\n            <PickerRow title=\".25\"/>\r\n            <PickerRow title=\".50\"/>\r\n            <PickerRow title=\".75\"/>\r\n          </PickerColumn>\r\n        </Picker>\r\n      </View>\r\n	</Window>\r\n</Alloy>\r\n\r\n*index.js*\r\n\r\n$.index.open();\r\n','Steps to reproduce\r\n\r\n1. Create a Picker with 2 columns\r\n2. PickerRow title set to \"0\" in XML (or \"1\", \"2\", etc)\r\n3. App crashes immediately\r\n\r\nSetting the PickerRow title to \"0\" in the controller js works fine. Android either method works fine.\r\n\r\n*index.xml*\r\n{{<Alloy>\r\n   <Window class=\"container\">\r\n      <View top=\"10\" layout=\"vertical\" height=\"Ti.UI.SIZE\" width=\"Ti.UI.FILL\">\r\n        <Label color=\"white\">How Much To Add?</Label>\r\n        <Picker id=\"timeAmount\" useSpinner=\"true\">\r\n          <PickerColumn id=\"hours\" width=\"50%\">\r\n            <PickerRow title=\"0\"/>\r\n            <PickerRow title=\"1\"/>\r\n            <PickerRow title=\"2\"/>\r\n            <PickerRow title=\"3\"/>\r\n            <PickerRow title=\"4\"/>\r\n          </PickerColumn>\r\n          <PickerColumn id=\"min\" useSpinner=\"true\" width=\"50%\">\r\n            <PickerRow title=\".00\"/>\r\n            <PickerRow title=\".25\"/>\r\n            <PickerRow title=\".50\"/>\r\n            <PickerRow title=\".75\"/>\r\n          </PickerColumn>\r\n        </Picker>\r\n      </View>\r\n	</Window>\r\n</Alloy>}}\r\n\r\n*index.js*\r\n{{\r\n$.index.open();}}\r\n','DESCRIPTION','2016-04-11 21:04:03',166480,406790);
