INSERT INTO `Change_Log` VALUES (8179061,'description',NULL,NULL,'For iOS, {{onload}} event attached to any liveview template items is not fired. It does fire for Android.\r\n\r\nh5. Step to reproduce\r\n1. Run attach app on iOS Simulator\r\n2. Run attach app on on Android Emulator\r\n3. Compare both results\r\n\r\nh5. Expected Result\r\nOn 3rd row, images are animating for both OS\r\n\r\nh5. Actual Result\r\nOn 3rd row, images are animating on Android, but not on iOS.\r\n','For iOS, {{onload}} event attached to any listview template items is not fired. It does fire for Android.\r\n\r\nh5. Step to reproduce\r\n1. Run attach app on iOS Simulator\r\n2. Run attach app on on Android Emulator\r\n3. Compare both results\r\n\r\nh5. Expected Result\r\nOn 3rd row, images are animating for both OS\r\n\r\nh5. Actual Result\r\nOn 3rd row, images are animating on Android, but not on iOS.\r\n','DESCRIPTION','2016-03-22 22:57:57',166201,407217);
INSERT INTO `Change_Log` VALUES (8179062,'description',NULL,NULL,'For iOS, {{onload}} event attached to any listview template items is not fired. It does fire for Android.\r\n\r\nh5. Step to reproduce\r\n1. Run attach app on iOS Simulator\r\n2. Run attach app on on Android Emulator\r\n3. Compare both results\r\n\r\nh5. Expected Result\r\nOn 3rd row, images are animating for both OS\r\n\r\nh5. Actual Result\r\nOn 3rd row, images are animating on Android, but not on iOS.\r\n','For iOS, {{onload}} event attached to any listview template items is not fired. It does fire for Android.\r\n\r\nh5. Step to reproduce\r\n1. Run attach app on iOS Simulator\r\n2. Run attach app on on Android Emulator\r\n3. Compare both results\r\n\r\nh5. Expected Result\r\nOn 3rd row, images are animating for both OS\r\n\r\nh5. Actual Result\r\nOn 3rd row, images are animating on Android, but not on iOS.\r\n\r\n','DESCRIPTION','2016-03-22 23:09:22',166201,407217);
