er and the index.js file inside controllers\r\n-Build and run\r\n-Click open\r\n-Select a contact\r\n\r\nh6.Test Case\r\nIndex.xml\r\n{code}\r\n<Alloy>\r\n		<Window id=\"nav\" backgroundColor=\"#fff\">\r\n			<Button onClick=\"open\">Open</Button>\r\n		</Window>\r\n</Alloy>\r\n{code}\r\n\r\nIndex.js\r\n{code}\r\n$.nav.open(); \r\n\r\nfunction open(){\r\n	Ti.Contacts.showContacts({\r\n		selectedProperty: function(e){\r\n			alert(JSON.stringify(e));\r\n		}\r\n	});\r\n}\r\n{code}','DESCRIPTION','2015-11-24 17:34:35',166197,407350);
