INSERT INTO `Change_Log` VALUES (8182702,'description',NULL,NULL,'The TextField and [TextArea.appearance|http://docs.appcelerator.com/platform/latest/#!/api/Titanium.UI.TextArea-property-appearance] properties should be renamed to {{keyboardAppearance}} to better describe what appearance they are about.\r\n\r\nTIMOB-19940 has already used this new name for adding appearance control to the AlertDialog input fields. To prevent confusion we should resolve this ticket together.','The TextField and [TextArea.appearance|http://docs.<USER>com/platform/latest/#!/api/Titanium.UI.TextArea-property-appearance] properties should be renamed to {{keyboardAppearance}} to better describe what appearance they are about.\r\n\r\nFor SearchBar the property is named [keyboardType|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.SearchBar-property-keyboardType] which should be renamed to {{keyboardAppearance}} as well and the API reference should also list the values as right now it does not.\r\n\r\nTIMOB-19940 has already used this new name for adding appearance control to the AlertDialog input fields. To prevent confusion we should resolve this ticket together.','DESCRIPTION','2015-11-17 19:02:20',166377,407400);
INSERT INTO `Change_Log` VALUES (8182703,'description',NULL,NULL,'The TextField and [TextArea.appearance|http://docs.appcelerator.com/platform/latest/#!/api/Titanium.UI.TextArea-property-appearance] properties should be renamed to {{keyboardAppearance}} to better describe what appearance they are about.\r\n\r\nFor SearchBar the property is named [keyboardType|https://appcelerator.github.io/appc-docs/latest/#!/api/Titanium.UI.SearchBar-property-keyboardType] which should be renamed to {{keyboardAppearance}} as well and the API reference should also list the values as right now it does not.\r\n\r\nTIMOB-19940 has already used this new name for adding appearance control to the AlertDialog input fields. To prevent confusion we should resolve this ticket together.','The TextField and [TextArea.appearance|http://docs.<USER>com/platform/latest/#!/api/Titanium.UI.TextArea-property-appearance] properties should be renamed to {{keyboardAppearance}} to better describe what appearance they are about.\r\n\r\nTIMOB-19940 has already used this new name for adding appearance control to the AlertDialog input fields. To prevent confusion we should resolve this ticket together.','DESCRIPTION','2015-11-17 19:05:43',166377,407400);
