INSERT INTO `Change_Log` VALUES (8183566,'description',NULL,NULL,'Currently {{Ti.UI.Button}} doesn\'t support {{image}} property.','Currently {{Ti.UI.Button}} doesn\'t support {{image}} property.\r\n\r\n{code:javascript}\r\nvar window = Ti.UI.createWindow({\r\n    backgroundColor: \'green\'\r\n});\r\n\r\nvar view = Ti.UI.createView({\r\n    backgroundColor: \'red\',\r\n    width: \'100%\',\r\n    height: 150\r\n});\r\n\r\nvar button = Ti.UI.createButton({ title: \'Bar bar bar\' });\r\n//button.image = \"http://www.<USER>com/wp-content/themes/appc-rwd/assets/media/images/logo.png\";\r\nbutton.image = Ti.Filesystem.getFile(\'Logo.png\').read();\r\n\r\nview.add(button);\r\n\r\nwindow.add(view);\r\nwindow.open();\r\n{code}','DESCRIPTION','2015-12-03 08:54:59',166083,407445);
