INSERT INTO `Change_Log` VALUES (8183659,'description',NULL,NULL,'As of [PR 433|https://github.com/appcelerator/titanium_mobile_windows/pull/433], font cache is introduced to improve font lookup, but {{TextArea}} and {{Button}} are not using it.','As of [PR 433|https://github.com/<USER>titanium_mobile_windows/pull/433], font cache is introduced to improve font lookup, but {{TextArea}} and {{Button}} are not using it. Make sure to use {{TitaniumWindows::UI::ViewHelper::SetFont}} for the font lookup.','DESCRIPTION','2015-11-13 05:01:57',166083,407449);
