INSERT INTO `Change_Log` VALUES (8184415,'description',NULL,NULL,'Adding tintColor property to Android using ImageView.setColorFilter()\r\n\r\nPull Request: \r\nhttps://github.com/appcelerator/titanium_mobile/pull/7410','Adding tintColor property to Android using ImageView.setColorFilter()\r\n\r\nPull Request: \r\nhttps://github.com/<USER>titanium_mobile/pull/7410\r\n\r\n','DESCRIPTION','2015-11-07 10:52:32',166025,407484);
INSERT INTO `Change_Log` VALUES (8184416,'description',NULL,NULL,'Adding tintColor property to Android using ImageView.setColorFilter()\r\n\r\nPull Request: \r\nhttps://github.com/appcelerator/titanium_mobile/pull/7410\r\n\r\n','Adding tintColor property to Android using ImageView.setColorFilter()\r\n\r\nPull Request: \r\nhttps://github.com/<USER>titanium_mobile/pull/7410\r\n\r\n{code:java}\r\n$.img2.setTintColor(\"#FF0000\");\r\n$.img3.tintColor = \"#F0FF0F\";\r\n$.index.open();\r\n{code}\r\n\r\n{code:java}\r\n<Alloy>\r\n	<Window class=\"container\">\r\n		<ImageView id=\"img1\"></ImageView>\r\n		<ImageView id=\"img2\"></ImageView>\r\n		<ImageView id=\"img3\"></ImageView>\r\n	</Window>\r\n</Alloy>\r\n{code}\r\n\r\n{code:java}\r\n\".container\" : {\r\n    backgroundColor: \"white\"\r\n}\r\n\"#img1\" : {\r\n    image: \"/images/img.png\",\r\n    top: 0,\r\n    width: 150,\r\n    height: 150\r\n}\r\n\"#img2\" : {\r\n    image: \"/images/img.png\",\r\n    width: 150,\r\n    height: 150\r\n}\r\n\r\n\"#img3\" : {\r\n    image: \"/images/img.png\",\r\n    bottom: 0,\r\n    width: 150,\r\n    height: 150\r\n}\r\n{code}','DESCRIPTION','2015-11-07 10:53:42',166025,407484);
