INSERT INTO `Change_Log` VALUES (8188222,'summary',NULL,NULL,'KitchenSink: Ensure it works for auto layout','KitchenSink: Ensure KitchenSink works for auto layout','DESCRIPTION','2015-10-09 06:58:10',166198,407679);
INSERT INTO `Change_Log` VALUES (8188223,'description',NULL,NULL,'KitchenSink https://github.com/appcelerator/KitchenSink *stable branch* is a comprehensive test suite for UI-related components and views, but it\'s been outdated. We should fix certain things to make sure it works with the latest master branch:\r\n\r\n1. Update DefaultIcon.png to make sure it\'s the right size and that it doesn\'t have alpha channel.\r\n2. Enable auto layout, add the following tag to the ios tag in tiapp.xml\r\n<use-autolayout>true</use-autolayout>\r\n3. With auto layout enabled, fix all deprecated warnings\r\n4. Any differences in UI behavior for auto layout enabled vs disabled should have tickets filed under the same epic with detailed descriptions so that we can tackle them one by one.','KitchenSink https://github.com/<USER>KitchenSink *stable branch* is a comprehensive test suite for UI-related components and views, but it\'s been outdated. We should fix certain things to make sure it works with the latest master branch:\r\n\r\n1. Update DefaultIcon.png to make sure it\'s the right size and that it doesn\'t have alpha channel.\r\n2. Enable auto layout, add the following tag to the ios tag in tiapp.xml\r\n<use-autolayout>true</use-autolayout>\r\n3. With auto layout enabled, fix all deprecated warnings (mostly to do with AUTO property)\r\n4. Any differences in UI behavior for auto layout enabled vs disabled should have tickets filed under the same epic with detailed descriptions so that we can tackle them one by one.','DESCRIPTION','2015-10-09 06:58:37',166198,407679);
