INSERT INTO `Change_Log` VALUES (8188369,'description',NULL,NULL,'In TIMOB-18976 we added the ability to execute JS on the main thread. We now should set this as default.\r\n\r\nNote, this can ONLY be merged in 5.1.0 if it causes NO behavior changes. If it does, then we must wait until 6.0.','In TIMOB-18976 we added the ability to execute JS on the main thread. We now should set this as default.\r\n\r\nNote, this can ONLY be merged in 5.1.0 if it causes NO behavior changes. If it does, then we must wait until 6.0.\r\n\r\n{code}\r\n<ios>\r\n    <run-on-main-thread>true</run-on-main-thread>\r\n    <!-- more iOS stuff here... -->\r\n</ios>\r\n{code}','DESCRIPTION','2015-10-23 23:47:19',166152,407688);
