INSERT INTO `Change_Log` VALUES (8191512,'description',NULL,NULL,'Apple just presented the new 3DTouch feature of the iPhone6S. User can press a view and will review an instant feedback providing a preview of a view to select different actions, called {{UIPreviewAction}}. Each action have a {{title}}, {{style}} and {{handler}} property. Multiple actions can also be assigned to {{UIPreviewActionGroup}}. That group can have have a {{title}}, {{style}} and {{actions}} property to keep track of the assigned actions.\r\n\r\n*Related documents:*\r\n- https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewAction_Class/\r\n- https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewActionGroup_Class/\r\n\r\n*Example:*\r\n{code}\r\nvar rootWindow = Ti.UI.createWindow({\r\n	backgroundColor : \"#CA2127\"\r\n});\r\n\r\nvar detailWindow = Ti.UI.createWindow({\r\n	backgroundColor: \"white\"\r\n});\r\n\r\nvar action1 = Ti.UI.iOS.createPreviewAction({\r\n	title: \"Test 1\",\r\n        style: Ti.UI.iOS.PREVIEW_ACTION_STYLE_DEFAULT\r\n});\r\n\r\nvar action2 = Ti.UI.iOS.createPreviewAction({\r\n	title: \"Test 2\",\r\n        style: Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE\r\n});\r\n\r\naction1.addEventListener(\"click\", function(e) {\r\n	alert(e.title);\r\n});\r\n\r\naction2.addEventListener(\"click\", function(e) {\r\n	alert(e.title);\r\n});\r\n\r\nvar btn = Ti.UI.createButton({\r\n	title : \"Open Window!\",\r\n	previewWindow: detailWindow,\r\n	previewActions: [action1, action2],\r\n	tintColor: \"#fff\"\r\n});\r\n\r\nvar container = Ti.UI.createView({\r\n	backgroundColor: \"#A6171C\",\r\n	width: 300,\r\n	height: 300,\r\n	borderRadius: 150,\r\n});\r\n\r\ncontainer.add(btn);\r\n\r\nvar label = Ti.UI.createLabel({\r\n	text: \"I\'m the Detail Window, you made it!\"\r\n});\r\n\r\nlabel.addEventListener(\"click\", function() {\r\n	detailWindow.close();\r\n});\r\n\r\ndetailWindow.add(label);\r\n\r\nrootWindow.add(container);\r\nrootWindow.open();\r\n{code}','Apple just presented the new 3DTouch feature of the iPhone6S. User can press a view and will review an instant feedback providing a preview of a view to select different actions, called {{UIPreviewAction}}. Each action have a {{title}}, {{style}} and {{handler}} property. Multiple actions can also be assigned to {{UIPreviewActionGroup}}. That group can have have a {{title}}, {{style}} and {{actions}} property to keep track of the assigned actions.\r\n\r\n*Related documents:*\r\n- https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewAction_Class/\r\n- https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewActionGroup_Class/\r\n\r\n*Example:*\r\n{code}\r\nvar sendAction = Ti.UI.iOS.createPreviewAction({\r\n	title : \"Send per Mail\",\r\n	style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DEFAULT\r\n});\r\n\r\nsendAction.addEventListener(\"click\", function() {\r\n	alert(\"send mail!\");\r\n});\r\n\r\nvar confirmAction = Ti.UI.iOS.createPreviewAction({\r\n	title : \"Confirm\",\r\n	style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE\r\n});\r\n\r\nvar cancelAction = Ti.UI.iOS.createPreviewAction({\r\n	title : \"Cancel\"\r\n});\r\n\r\nvar deleteAction = Ti.UI.iOS.createPreviewActionGroup({\r\n	title : \"Delete\",\r\n	actions : [confirmAction, cancelAction],\r\n	style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE\r\n});\r\n\r\nconfirmAction.addEventListener(\"click\", function() {\r\n	alert(\"delete!\");\r\n});\r\n\r\nvar win = Ti.UI.createWindow({\r\n	backgroundColor : \"white\"\r\n});\r\n\r\n// The view to be previewed while popping.\r\nvar previewView = Ti.UI.createView({\r\n	backgroundColor : \"blue\"\r\n});\r\n\r\npreviewView.add(Ti.UI.createLabel({\r\n	color : \"#fff\",\r\n	text : \"Preview!\"\r\n}));\r\n\r\n// The window to be opened after popping the preview.\r\nvar detailWindow = Ti.UI.createWindow({\r\n	backgroundColor : \"yellow\"\r\n});\r\n\r\ndetailWindow.add(Ti.UI.createLabel({\r\n	text : \"You made it!\"\r\n}));\r\n\r\n// Create the preview context\r\nvar context = Ti.UI.iOS.createPreviewContext({\r\n	preview : previewView,\r\n	actions : [sendAction, deleteAction], // Can have both Ti.UI.iOS.PreviewAction + Ti.UI.iOS.PreviewActionGroup\r\n	contentHeight : 100, // When unspecified, we use the available height\r\n	pop : function(e) {// Called after popping the preview\r\n		detailWindow.open();\r\n	}\r\n});\r\n\r\n// Assign the preview context\r\nvar trigger = Ti.UI.createButton({\r\n	title: \"Peek here!\"\r\n	backgroundColor : \"green\",\r\n	tintColor: \"#fff\",\r\n	width : 200,\r\n	height : 50,\r\n	previewContext : context\r\n});\r\n\r\nwin.add(trigger);\r\nwin.open(); \r\n{code}','DESCRIPTION','2015-10-08 04:16:50',166010,407861);
INSERT INTO `Change_Log` VALUES (8191513,'description',NULL,NULL,'Apple just presented the new 3DTouch feature of the iPhone6S. User can press a view and will review an instant feedback providing a preview of a view to select different actions, called {{UIPreviewAction}}. Each action have a {{title}}, {{style}} and {{handler}} property. Multiple actions can also be assigned to {{UIPreviewActionGroup}}. That group can have have a {{title}}, {{style}} and {{actions}} property to keep track of the assigned actions.\r\n\r\n*Related documents:*\r\n- https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewAction_Class/\r\n- https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewActionGroup_Class/\r\n\r\n*Example:*\r\n{code}\r\nvar sendAction = Ti.UI.iOS.createPreviewAction({\r\n	title : \"Send per Mail\",\r\n	style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DEFAULT\r\n});\r\n\r\nsendAction.addEventListener(\"click\", function() {\r\n	alert(\"send mail!\");\r\n});\r\n\r\nvar confirmAction = Ti.UI.iOS.createPreviewAction({\r\n	title : \"Confirm\",\r\n	style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE\r\n});\r\n\r\nvar cancelAction = Ti.UI.iOS.createPreviewAction({\r\n	title : \"Cancel\"\r\n});\r\n\r\nvar deleteAction = Ti.UI.iOS.createPreviewActionGroup({\r\n	title : \"Delete\",\r\n	actions : [confirmAction, cancelAction],\r\n	style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE\r\n});\r\n\r\nconfirmAction.addEventListener(\"click\", function() {\r\n	alert(\"delete!\");\r\n});\r\n\r\nvar win = Ti.UI.createWindow({\r\n	backgroundColor : \"white\"\r\n});\r\n\r\n// The view to be previewed while popping.\r\nvar previewView = Ti.UI.createView({\r\n	backgroundColor : \"blue\"\r\n});\r\n\r\npreviewView.add(Ti.UI.createLabel({\r\n	color : \"#fff\",\r\n	text : \"Preview!\"\r\n}));\r\n\r\n// The window to be opened after popping the preview.\r\nvar detailWindow = Ti.UI.createWindow({\r\n	backgroundColor : \"yellow\"\r\n});\r\n\r\ndetailWindow.add(Ti.UI.createLabel({\r\n	text : \"You made it!\"\r\n}));\r\n\r\n// Create the preview context\r\nvar context = Ti.UI.iOS.createPreviewContext({\r\n	preview : previewView,\r\n	actions : [sendAction, deleteAction], // Can have both Ti.UI.iOS.PreviewAction + Ti.UI.iOS.PreviewActionGroup\r\n	contentHeight : 100, // When unspecified, we use the available height\r\n	pop : function(e) {// Called after popping the preview\r\n		detailWindow.open();\r\n	}\r\n});\r\n\r\n// Assign the preview context\r\nvar trigger = Ti.UI.createButton({\r\n	title: \"Peek here!\"\r\n	backgroundColor : \"green\",\r\n	tintColor: \"#fff\",\r\n	width : 200,\r\n	height : 50,\r\n	previewContext : context\r\n});\r\n\r\nwin.add(trigger);\r\nwin.open(); \r\n{code}','Apple just presented the new 3DTouch feature of the iPhone6S. User can press a view and will review an instant feedback providing a preview of a view to select different actions, called {{UIPreviewAction}}. Each action have a {{title}}, {{style}} and {{handler}} property. Multiple actions can also be assigned to {{UIPreviewActionGroup}}. That group can have have a {{title}}, {{style}} and {{actions}} property to keep track of the assigned actions.\r\n\r\n*Related documents:*\r\n- https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewAction_Class/\r\n- https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewActionGroup_Class/\r\n\r\n*Example:*\r\n{code}\r\nvar sendAction = Ti.UI.iOS.createPreviewAction({\r\n	title : \"Send per Mail\",\r\n	style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DEFAULT\r\n});\r\n\r\nsendAction.addEventListener(\"click\", function() {\r\n	alert(\"send mail!\");\r\n});\r\n\r\nvar confirmAction = Ti.UI.iOS.createPreviewAction({\r\n	title : \"Confirm\",\r\n	style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE\r\n});\r\n\r\nvar cancelAction = Ti.UI.iOS.createPreviewAction({\r\n	title : \"Cancel\"\r\n});\r\n\r\nvar deleteAction = Ti.UI.iOS.createPreviewActionGroup({\r\n	title : \"Delete\",\r\n	actions : [confirmAction, cancelAction],\r\n	style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE\r\n});\r\n\r\nconfirmAction.addEventListener(\"click\", function() {\r\n	alert(\"delete!\");\r\n});\r\n\r\nvar win = Ti.UI.createWindow({\r\n	backgroundColor : \"white\"\r\n});\r\n\r\n// The view to be previewed while popping.\r\nvar previewView = Ti.UI.createView({\r\n	backgroundColor : \"blue\"\r\n});\r\n\r\npreviewView.add(Ti.UI.createLabel({\r\n	color : \"#fff\",\r\n	text : \"Preview!\"\r\n}));\r\n\r\n// The window to be opened after popping the preview.\r\nvar detailWindow = Ti.UI.createWindow({\r\n	backgroundColor : \"yellow\"\r\n});\r\n\r\ndetailWindow.add(Ti.UI.createLabel({\r\n	text : \"You made it!\"\r\n}));\r\n\r\n// Create the preview context\r\nvar context = Ti.UI.iOS.createPreviewContext({\r\n	preview : previewView,\r\n	actions : [sendAction, deleteAction], // Can have both Ti.UI.iOS.PreviewAction + Ti.UI.iOS.PreviewActionGroup\r\n	contentHeight : 100, // When unspecified, we use the available height\r\n	pop : function(e) {// Called after popping the preview\r\n		detailWindow.open();\r\n	}\r\n});\r\n\r\n// Assign the preview context\r\nvar trigger = Ti.UI.createButton({\r\n	title: \"Peek here!\",\r\n	backgroundColor : \"#000\",\r\n	tintColor: \"#fff\",\r\n	width : 200,\r\n	height : 50,\r\n	previewContext : context\r\n});\r\n\r\nwin.add(trigger);\r\nwin.open(); \r\n{code}','DESCRIPTION','2015-10-08 04:18:58',166010,407861);
