INSERT INTO `Change_Log` VALUES (8207028,'description',NULL,NULL,'The {{--publisher-guid}} or {{-G}} option is required for {{ti build}}, so it must be given on every build if not set via {{ti setup}} (TIMOB-16748).\r\n\r\nOn Android, we use the the {{dev_keystore}} included in the SDK when none is given.\r\n\r\nWould it be an option to have a similar approach for Windows and default to the {{00000000-0000-1000-8000-000000000000}} mentioned in the [blog|http://www.appcelerator.com/blog/2014/12/windows-platform-preview/] for example ?','The {{--win-publisher-id}} or {{-I}} option is required for {{ti build}}, so it must be given on every build if not set via {{ti setup}} (TIMOB-16748).\r\n\r\nOn Android, we use the the {{dev_keystore}} included in the SDK when none is given.\r\n\r\nWould it be an option to have a similar approach for Windows and default to the {{00000000-0000-1000-8000-000000000000}} mentioned in the [blog|http://www.<USER>com/blog/2014/12/windows-platform-preview/] for example ?','DESCRIPTION','2015-10-02 14:22:22',166009,408702);
