INSERT INTO `Change_Log` VALUES (8267805,'summary',NULL,NULL,'JNI ERROR (app bug): local reference table overflow (max=512)','Android: JNI ERROR (app bug): local reference table overflow (max=512)','DESCRIPTION','2013-11-21 01:26:17',166443,411078);
