INSERT INTO `Comment` VALUES (7463,'According to Janne \"spring-hadoop is broken for this specific use case if you want to mix resources from hdfs and file\", which causes an error if we define, for example, a DB initialization script as a file resource in the job module, along with HDFS resources to load. Should be fixed by SHDP-201.','\"According to Janne \"\"spring-hadoop is broken for this specific use case if you want to mix resources from hdfs and file\"\", which causes an error if we define, for example, a DB initialization script as a file resource in the job module, along with HDFS resources to load. Should be fixed by SHDP-201.\"','','2013-10-28 10:46:28',222,2818);
