INSERT INTO `Comment` VALUES (8561,'Issue does not longer depend on BATCH-2109 as we now use *Kryo* for serialization, which works much better out of the box with the Spring Batch objects.','\"Issue does not longer depend on BATCH-2109 as we now use *Kryo* for serialization, which works much better out of the box with the Spring Batch objects.\"','','2013-09-24 09:53:39',93,3775);
INSERT INTO `Comment` VALUES (48162,'why is this targeted for 0.28.0?','\"why is this targeted for 0.28.0?\"','','2016-03-10 02:47:36',3371,19749);
INSERT INTO `Comment` VALUES (48163,'Here is the review request: https://reviews.apache.org/r/44694/','\"Here is the review request: https://reviews.apache.org/r/44694/\"','','2016-03-11 01:35:57',3491,19749);
INSERT INTO `Comment` VALUES (48164,'{code}\ncommit 5ea02aea22122a833fb133f0a6e7c085fcd5c01c\nAuthor: <USER><<EMAIL>>\nDate:   Thu Mar 10 21:50:21 2016 -0500\n\n    Enabled multiple calls to ModuleManager::load().\n    \n    As long as the module manifest(s) being loaded don\'t conflict with the\n    already loaded manifests, the module manager will allow multiple calls\n    to `load()`.\n    \n    Review: https://reviews.apache.org/r/44694\n{code}','\"{code} commit 5ea02aea22122a833fb133f0a6e7c085fcd5c01c Author: <USER><<EMAIL>> Date:   Thu Mar 10 21:50:21 2016 -0500      Enabled multiple calls to ModuleManager::load().          As long as the module manifest(s) being loaded don\'t conflict with the     already loaded manifests, the module manager will allow multiple calls     to `load()`.          Review: https://reviews.apache.org/r/44694 {code}\"','','2016-03-11 10:31:14',3491,19749);
INSERT INTO `Comment` VALUES (48214,'https://reviews.apache.org/r/44468/\n','\"https://reviews.apache.org/r/44468/ \"','','2016-03-08 01:24:52',3406,19764);
INSERT INTO `Comment` VALUES (48215,'commit e42f740ccb655c0478a3002c0b6fa90c1144f41c\nAuthor: <USER><<EMAIL>>\nDate:   Mon Mar 7 17:32:10 2016 -0800\n\n    Fixed the logic for default docker cmd case.\n    \n    Review: https://reviews.apache.org/r/44468/','\"commit e42f740ccb655c0478a3002c0b6fa90c1144f41c Author: <USER><<EMAIL>> Date:   Mon Mar 7 17:32:10 2016 -0800      Fixed the logic for default docker cmd case.          Review: https://reviews.apache.org/r/44468/\"','','2016-03-09 17:58:48',3406,19764);
INSERT INTO `Comment` VALUES (48260,'https://reviews.apache.org/r/44414','\"https://reviews.apache.org/r/44414\"','','2016-03-05 02:20:36',3415,19779);
INSERT INTO `Comment` VALUES (48261,'commit 7de8cdd4d8ed1d222fa03ea0d8fa6740c4a9f84b\nAuthor: <USER><<EMAIL>>\nDate:   Fri Mar 4 18:16:23 2016 -0800\n\n    Added documentation about container image support.\n    \n    Review: https://reviews.apache.org/r/44414','\"commit 7de8cdd4d8ed1d222fa03ea0d8fa6740c4a9f84b Author: <USER><<EMAIL>> Date:   Fri Mar 4 18:16:23 2016 -0800      Added documentation about container image support.          Review: https://reviews.apache.org/r/44414\"','','2016-03-08 01:10:58',3415,19779);
INSERT INTO `Comment` VALUES (48294,'Review Chain: https://reviews.apache.org/r/44578','\"Review Chain: https://reviews.apache.org/r/44578\"','','2016-03-09 18:04:01',3604,19794);
INSERT INTO `Comment` VALUES (48295,'commit 295b58022523c636d4331af760e5d3ba6f8e4703\nAuthor: <USER><<EMAIL>>\nDate:   Sat Mar 12 19:31:33 2016 -0500\n\n    Made changes to the executor library around managing connections.\n    \n    This change makes the following modifications to the library:\n    \n    \\- Removes passing connection objects to \\`defer\\` callbacks as it can\n    sometimes lead to deadlocks around destruction in the same execution\n    context.\n    \\- Introduced 3 additional states \\`CONNECTING\\`, \\`SUBSCRIBING\\` and\n    \\`SUBSCRIBED\\`. The \\`CONNECTING\\` state helps us in identifying if a\n    connection attempt is in progress while the latter two states allows\n    us to drop subscribe calls if one is already is in progress.\n    \\- Creates a random \\`connectionID\\` to demarcate a new connection\n    instance and  allowing to discard a state connection attempt.\n    \\- Changes around setting the recovery timeout timer only once.\n    This allows us to later discard the recoveryTimeout callback\n    if we connected with the agent at a later point of time.\n    \n    Review: https://reviews.apache.org/r/44580/\n\ncommit 441c278459f9dc6f35e9dff8b6be7704ed075bc9\nAuthor: <USER><<EMAIL>>\nDate:   Sat Mar 12 19:31:28 2016 -0500\n\n    Minor fix to output state during a `CHECK` failure.\n    \n    This change outputs the state when a check fails inside the scheduler library.\n    \n    Review: https://reviews.apache.org/r/44579/\n\ncommit 2aff8f7fb8c6b55bf234294abdd5784659632d5c\nAuthor: <USER><<EMAIL>>\nDate:   Sat Mar 12 19:31:22 2016 -0500\n\n    Pass `received` argument by const ref in the executor library.\n    \n    Review: https://reviews.apache.org/r/44578/\n','\"commit 295b58022523c636d4331af760e5d3ba6f8e4703 Author: <USER><<EMAIL>> Date:   Sat Mar 12 19:31:33 2016 -0500      Made changes to the executor library around managing connections.          This change makes the following modifications to the library:          \\- Removes passing connection objects to \\`defer\\` callbacks as it can     sometimes lead to deadlocks around destruction in the same execution     context.     \\- Introduced 3 additional states \\`CONNECTING\\`, \\`SUBSCRIBING\\` and     \\`SUBSCRIBED\\`. The \\`CONNECTING\\` state helps us in identifying if a     connection attempt is in progress while the latter two states allows     us to drop subscribe calls if one is already is in progress.     \\- Creates a random \\`connectionID\\` to demarcate a new connection     instance and  allowing to discard a state connection attempt.     \\- Changes around setting the recovery timeout timer only once.     This allows us to later discard the recoveryTimeout callback     if we connected with the agent at a later point of time.          Review: https://reviews.apache.org/r/44580/  commit 441c278459f9dc6f35e9dff8b6be7704ed075bc9 Author: <USER><<EMAIL>> Date:   Sat Mar 12 19:31:28 2016 -0500      Minor fix to output state during a `CHECK` failure.          This change outputs the state when a check fails inside the scheduler library.          Review: https://reviews.apache.org/r/44579/  commit 2aff8f7fb8c6b55bf234294abdd5784659632d5c Author: <USER><<EMAIL>> Date:   Sat Mar 12 19:31:22 2016 -0500      Pass `received` argument by const ref in the executor library.          Review: https://reviews.apache.org/r/44578/ \"','','2016-03-13 00:32:52',3371,19794);
INSERT INTO `Comment` VALUES (48299,'commit 5a5d58f23da28455952b1c758e51bd0bf9753452\nAuthor: Avinash sridharan <<EMAIL>>\nDate:   Thu Mar 3 11:34:13 2016 -0800\n\n    Added net_cls isolator to CHANGELOG.\n    \n    Review: https://reviews.apache.org/r/44350/','\"commit 5a5d58f23da28455952b1c758e51bd0bf9753452 Author: Avinash sridharan <<EMAIL>> Date:   Thu Mar 3 11:34:13 2016 -0800      Added net_cls isolator to CHANGELOG.          Review: https://reviews.apache.org/r/44350/\"','','2016-03-03 19:34:58',3415,19798);
