INSERT INTO `Comment` VALUES (48308,'commit 5892058cdbe839a601bafe3e0dd5de9a54730ce1\nAuthor: <USER><<EMAIL>>\nDate:   Wed Mar 23 02:30:34 2016 -0700\n\n    Added agent HTTP authentication to the docs.\n    \n    Review: https://reviews.apache.org/r/44554/\n\ncommit c2927b88cbd85fac0d618b9eaaf5c05477d2c8ce\nAuthor: <USER><<EMAIL>>\nDate:   Wed Mar 23 20:02:37 2016 -0700\n\n    Added authentication to agent HTTP endpoints.\n    \n    This patch adds HTTP authentication to the `/state`, `/state.json`,\n    and `/flags` endpoints. Tests are also updated to use authentication\n    when hitting these endpoints, and a new test was added to probe these\n    endpoints\' behavior when bad credentials are supplied:\n    `SlaveTest.HTTPEndpointsBadAuthentication`.\n    \n    Review: https://reviews.apache.org/r/44553/\n\n','\"commit 5892058cdbe839a601bafe3e0dd5de9a54730ce1 Author: <USER><<EMAIL>> Date:   Wed Mar 23 02:30:34 2016 -0700      Added agent HTTP authentication to the docs.          Review: https://reviews.apache.org/r/44554/  commit c2927b88cbd85fac0d618b9eaaf5c05477d2c8ce Author: <USER><<EMAIL>> Date:   Wed Mar 23 20:02:37 2016 -0700      Added authentication to agent HTTP endpoints.          This patch adds HTTP authentication to the `/state`, `/state.json`,     and `/flags` endpoints. Tests are also updated to use authentication     when hitting these endpoints, and a new test was added to probe these     endpoints\' behavior when bad credentials are supplied:     `SlaveTest.HTTPEndpointsBadAuthentication`.          Review: https://reviews.apache.org/r/44553/  \"','','2016-03-24 06:19:42',3581,19802);
INSERT INTO `Comment` VALUES (48309,'Reviews here:\n\nhttps://reviews.apache.org/r/44678/\nhttps://reviews.apache.org/r/44703/\nhttps://reviews.apache.org/r/44515/\nhttps://reviews.apache.org/r/44523/\nhttps://reviews.apache.org/r/45088/','\"Reviews here:  https://reviews.apache.org/r/44678/ https://reviews.apache.org/r/44703/ https://reviews.apache.org/r/44515/ https://reviews.apache.org/r/44523/ https://reviews.apache.org/r/45088/\"','','2016-03-08 19:02:06',3361,19803);
INSERT INTO `Comment` VALUES (48310,'commit 265f46844e53587d032a42b9540f940e5b0b94a7\nAuthor: <USER><<EMAIL>>\nDate:   Wed Mar 23 02:30:47 2016 -0700\n\n    Edited master\'s flag help strings to match the agent.\n    \n    With the addition of the `--authenticate_http` and `--http_credentials`\n    flags for the agent, the flag help strings have been improved slightly.\n    This patch edits the master\'s help string to match that of the agent.\n    \n    Review: https://reviews.apache.org/r/45088/\n\ncommit 919bb71581458a7d42bed10262f91a63b2441d75\nAuthor: <USER><<EMAIL>>\nDate:   Wed Mar 23 02:29:46 2016 -0700\n\n    Changed the master\'s default HTTP authentication realm.\n    \n    Review: https://reviews.apache.org/r/44523/\n\ncommit 401387299a04b71f62021adc6ee5e7545ac63376\nAuthor: <USER><<EMAIL>>\nDate:   Wed Mar 23 02:46:26 2016 -0700\n\n    Added agent flags for HTTP authentication.\n    \n    Three command-line flags have been added to the agent to enable\n    HTTP authentication: `--authenticate_http`, `--http_credentials`,\n    and `--http_authenticators`.\n    \n    Review: https://reviews.apache.org/r/44515/\n\ncommit a1482ac04407fb653b7ba4af1ca5ed51df83cb03\nAuthor: <USER><<EMAIL>>\nDate:   Wed Mar 23 02:27:43 2016 -0700\n\n    Added Doxygen docs for basic HTTP authenticator.\n    \n    The structure of the module parameters for the basic HTTP authenticator\n    has changed, so Doxygen comments were added to the module\'s header file\n    to provide an example.\n    \n    Review: https://reviews.apache.org/r/44703/\n\ncommit 8e51b37fed466b3cc2d1a5f73d47d4f919044c31\nAuthor: <USER><<EMAIL>>\nDate:   Wed Mar 23 02:26:57 2016 -0700\n\n    Modified basic HTTP authenticator creator to accept realm.\n\n    To accommodate different authentication realms for the master and agent,\n    the default basic HTTP authenticator needs to accept its authentication\n    realm as a parameter. This patch adds this parameter and modifies the\n    HTTP authentication tests to validate it appropriately. A new test was\n    also added: `HttpAuthenticationTest.BasicWithoutRealm`.\n\n    Review: https://reviews.apache.org/r/44678/','\"commit 265f46844e53587d032a42b9540f940e5b0b94a7 Author: <USER><<EMAIL>> Date:   Wed Mar 23 02:30:47 2016 -0700      Edited master\'s flag help strings to match the agent.          With the addition of the `--authenticate_http` and `--http_credentials`     flags for the agent, the flag help strings have been improved slightly.     This patch edits the master\'s help string to match that of the agent.          Review: https://reviews.apache.org/r/45088/  commit 919bb71581458a7d42bed10262f91a63b2441d75 Author: <USER><<EMAIL>> Date:   Wed Mar 23 02:29:46 2016 -0700      Changed the master\'s default HTTP authentication realm.          Review: https://reviews.apache.org/r/44523/  commit 401387299a04b71f62021adc6ee5e7545ac63376 Author: <USER><<EMAIL>> Date:   Wed Mar 23 02:46:26 2016 -0700      Added agent flags for HTTP authentication.          Three command-line flags have been added to the agent to enable     HTTP authentication: `--authenticate_http`, `--http_credentials`,     and `--http_authenticators`.          Review: https://reviews.apache.org/r/44515/  commit a1482ac04407fb653b7ba4af1ca5ed51df83cb03 Author: <USER><<EMAIL>> Date:   Wed Mar 23 02:27:43 2016 -0700      Added Doxygen docs for basic HTTP authenticator.          The structure of the module parameters for the basic HTTP authenticator     has changed, so Doxygen comments were added to the module\'s header file     to provide an example.          Review: https://reviews.apache.org/r/44703/  commit 8e51b37fed466b3cc2d1a5f73d47d4f919044c31 Author: <USER><<EMAIL>> Date:   Wed Mar 23 02:26:57 2016 -0700      Modified basic HTTP authenticator creator to accept realm.      To accommodate different authentication realms for the master and agent,     the default basic HTTP authenticator needs to accept its authentication     realm as a parameter. This patch adds this parameter and modifies the     HTTP authentication tests to validate it appropriately. A new test was     also added: `HttpAuthenticationTest.BasicWithoutRealm`.      Review: https://reviews.apache.org/r/44678/\"','','2016-03-24 06:18:09',3581,19803);
INSERT INTO `Comment` VALUES (48311,'These changes look pretty straightforward, so I didn\'t go for a full design doc, just a short report. Summary can be found [here|https://docs.google.com/a/<USER>io/document/d/1697N7jiDfyDbpz8tiEoKtQHykvYWmnUl_mea4j6GRvg/edit?usp=sharing], and the document is linked to this ticket.','\"These changes look pretty straightforward, so I didn\'t go for a full design doc, just a short report. Summary can be found [here|https://docs.google.com/a/<USER>io/document/d/1697N7jiDfyDbpz8tiEoKtQHykvYWmnUl_mea4j6GRvg/edit?usp=sharing], and the document is linked to this ticket.\"','','2016-03-04 22:46:09',3361,19804);
