INSERT INTO `Comment` VALUES (48320,'2 of 3 patches committed; Tests for bad authentication still under review at https://reviews.apache.org/r/44621/\n\ncommit 83f3db0580370253df7c914066532d74c6732cac\nAuthor: Joerg Schad <<EMAIL>>\nDate:   Mon Mar 7 17:29:33 2016 -0800\n\n    Unified/added Future checks for http methods in tests.\n    \n    Review: https://reviews.apache.org/r/44286/\n\ncommit 37eff3337e67e32005fbd6d1ca9d45b336701106\nAuthor: Joerg Schad <<EMAIL>>\nDate:   Sat Mar 12 23:59:12 2016 -0800\n\n    Added authentication to master endpoints.\n    \n    Added Authentication to master process http endpoints\n    (except version, health, redirect, scheduler).\n    \n    Review: https://reviews.apache.org/r/44186/','\"2 of 3 patches committed; Tests for bad authentication still under review at https://reviews.apache.org/r/44621/  commit 83f3db0580370253df7c914066532d74c6732cac Author: Joerg Schad <<EMAIL>> Date:   Mon Mar 7 17:29:33 2016 -0800      Unified/added Future checks for http methods in tests.          Review: https://reviews.apache.org/r/44286/  commit 37eff3337e67e32005fbd6d1ca9d45b336701106 Author: Joerg Schad <<EMAIL>> Date:   Sat Mar 12 23:59:12 2016 -0800      Added authentication to master endpoints.          Added Authentication to master process http endpoints     (except version, health, redirect, scheduler).          Review: https://reviews.apache.org/r/44186/\"','','2016-03-13 11:17:42',3581,19808);
INSERT INTO `Comment` VALUES (48321,'commit abd911ccfcb09a6755e91b02a38977d898a31b0d\nAuthor: Joerg Schad <<EMAIL>>\nDate:   Mon Mar 14 01:12:20 2016 -0700\n\n    Added tests for http endpoints with bad authentication.\n    \n    With enabling http authentication for http endpoints we should also\n    add tests to check that http request to those endpoints return\n    \"401 Unauthorized\" if queried without or with bad credentials.\n    \n    Review: https://reviews.apache.org/r/44621/\n\ncommit e78be41521a45c5d58efbdf3e00e2194056a7570\nAuthor: Joerg Schad <<EMAIL>>\nDate:   Mon Mar 14 01:14:43 2016 -0700\n\n    Updated authentication.md after many endpoints enable authentication.\n    \n    Review: https://reviews.apache.org/r/44711/\n','\"commit abd911ccfcb09a6755e91b02a38977d898a31b0d Author: Joerg Schad <<EMAIL>> Date:   Mon Mar 14 01:12:20 2016 -0700      Added tests for http endpoints with bad authentication.          With enabling http authentication for http endpoints we should also     add tests to check that http request to those endpoints return     \"\"401 Unauthorized\"\" if queried without or with bad credentials.          Review: https://reviews.apache.org/r/44621/  commit e78be41521a45c5d58efbdf3e00e2194056a7570 Author: Joerg Schad <<EMAIL>> Date:   Mon Mar 14 01:14:43 2016 -0700      Updated authentication.md after many endpoints enable authentication.          Review: https://reviews.apache.org/r/44711/ \"','','2016-03-14 10:23:09',3581,19808);
