INSERT INTO `Comment` VALUES (48515,'{noformat}\ncommit 845fa6abdc163676cde225e2dc72cee9e3e964f5\nAuthor: <USER><<EMAIL>>\nDate:   Thu Mar 10 19:14:18 2016 -0800\n\n    Added \'delegate\' info to the Help process.\n\n    Just as the ProcessManager needs the delegate name to know which\n    process to service root HTTP requests from, the Help process needs to\n    know the delegate name so it can generate the proper USAGE strings.\n\n    Review: https://reviews.apache.org/r/44690/\n{noformat}\n{noformat}\ncommit 9913743f75e0b81729d7979796be8a7d65c30789\nAuthor: <USER><<EMAIL>>\nDate:   Thu Mar 10 19:14:23 2016 -0800\n\n    Fixed comment in support/generate-endpoint-help.py.\n\n    Review: https://reviews.apache.org/r/44691/\n{noformat}\n{noformat}\ncommit 72084c791b0ce576941ed810db5a5f654abe12c3\nAuthor: <USER><<EMAIL>>\nDate:   Thu Mar 10 19:14:30 2016 -0800\n\n    Added exception for master/slave(id) in endpoint help documentation.\n\n    Specifically, the \'master\' and \'slave(id)\' processes should not\n    include their names in the endpoint help documentation because we\n    encourage usage of the shorter form.\n\n    Review: https://reviews.apache.org/r/44692/\n{noformat}\n{noformat}\ncommit 3605b5a9d12bbaf57f0a1306d92fe0cd64ef81e7\nAuthor: <USER><<EMAIL>>\nDate:   Thu Mar 10 19:15:11 2016 -0800\n\n    Updated endpoint docs based on adding the delegate to the Help process.\n\n    Also updated the permissions on the generate-endpoint-help.py script\n    to make it executable.\n\n    Review: https://reviews.apache.org/r/44693/\n{noformat}','\"{noformat} commit 845fa6abdc163676cde225e2dc72cee9e3e964f5 Author: <USER><<EMAIL>> Date:   Thu Mar 10 19:14:18 2016 -0800      Added \'delegate\' info to the Help process.      Just as the ProcessManager needs the delegate name to know which     process to service root HTTP requests from, the Help process needs to     know the delegate name so it can generate the proper USAGE strings.      Review: https://reviews.apache.org/r/44690/ {noformat} {noformat} commit 9913743f75e0b81729d7979796be8a7d65c30789 Author: <USER><<EMAIL>> Date:   Thu Mar 10 19:14:23 2016 -0800      Fixed comment in support/generate-endpoint-help.py.      Review: https://reviews.apache.org/r/44691/ {noformat} {noformat} commit 72084c791b0ce576941ed810db5a5f654abe12c3 Author: <USER><<EMAIL>> Date:   Thu Mar 10 19:14:30 2016 -0800      Added exception for master/slave(id) in endpoint help documentation.      Specifically, the \'master\' and \'slave(id)\' processes should not     include their names in the endpoint help documentation because we     encourage usage of the shorter form.      Review: https://reviews.apache.org/r/44692/ {noformat} {noformat} commit 3605b5a9d12bbaf57f0a1306d92fe0cd64ef81e7 Author: <USER><<EMAIL>> Date:   Thu Mar 10 19:15:11 2016 -0800      Updated endpoint docs based on adding the delegate to the Help process.      Also updated the permissions on the generate-endpoint-help.py script     to make it executable.      Review: https://reviews.apache.org/r/44693/ {noformat}\"','','2016-03-11 03:18:26',3363,19865);
INSERT INTO `Comment` VALUES (48538,'https://reviews.apache.org/r/43904/\nhttps://reviews.apache.org/r/43905/\nhttps://reviews.apache.org/r/40938/\nhttps://reviews.apache.org/r/40939/','\"https://reviews.apache.org/r/43904/ https://reviews.apache.org/r/43905/ https://reviews.apache.org/r/40938/ https://reviews.apache.org/r/40939/\"','','2016-03-01 21:30:35',3647,19872);
INSERT INTO `Comment` VALUES (48539,'{code}\ncommit 9f1b115a67a1625a4807c2a7d4e1a41bca1af2a6\nAuthor: <USER><<EMAIL>>\nDate:   Tue Mar 1 14:18:41 2016 -0800\n\n    Stout: Marked `os::su` as deleted on Windows.\n    \n    Review: https://reviews.apache.org/r/40939/\n\ncommit a1f731746657b1cbcf136ddb2bf154ca3da271fc\nAuthor: <USER><<EMAIL>>\nDate:   Tue Mar 1 14:16:08 2016 -0800\n\n    Stout: Marked `os::chroot` as deleted on Windows.\n    \n    Review: https://reviews.apache.org/r/40938/\n\ncommit a1a9cd5939d25f82214a5c533bde96a3493f81f3\nAuthor: <USER><<EMAIL>>\nDate:   Tue Mar 1 13:35:13 2016 -0800\n\n    Windows: Stout: Removed user based functions.\n    \n    Review: https://reviews.apache.org/r/43905/\n\ncommit b9de8c6a06f0d0246ea38ab5586de1d0b2478c38\nAuthor: <USER><<EMAIL>>\nDate:   Tue Mar 1 13:33:37 2016 -0800\n\n    Windows: Removed `user` launcher flag, preventing `su`.\n    \n    `su` does not exist on Windows. Unfortunately, the launcher also depends\n    on it. In this commit, we remove Windows support for the launcher flag\n    `user`, which controls whether we use `su` in the launcher. This\n    allows us to divest ourselves of `su` altogether on Windows.\n    \n    Review: https://reviews.apache.org/r/43905/\n{code}','\"{code} commit 9f1b115a67a1625a4807c2a7d4e1a41bca1af2a6 Author: <USER><<EMAIL>> Date:   Tue Mar 1 14:18:41 2016 -0800      Stout: Marked `os::su` as deleted on Windows.          Review: https://reviews.apache.org/r/40939/  commit a1f731746657b1cbcf136ddb2bf154ca3da271fc Author: <USER><<EMAIL>> Date:   Tue Mar 1 14:16:08 2016 -0800      Stout: Marked `os::chroot` as deleted on Windows.          Review: https://reviews.apache.org/r/40938/  commit a1a9cd5939d25f82214a5c533bde96a3493f81f3 Author: <USER><<EMAIL>> Date:   Tue Mar 1 13:35:13 2016 -0800      Windows: Stout: Removed user based functions.          Review: https://reviews.apache.org/r/43905/  commit b9de8c6a06f0d0246ea38ab5586de1d0b2478c38 Author: <USER><<EMAIL>> Date:   Tue Mar 1 13:33:37 2016 -0800      Windows: Removed `user` launcher flag, preventing `su`.          `su` does not exist on Windows. Unfortunately, the launcher also depends     on it. In this commit, we remove Windows support for the launcher flag     `user`, which controls whether we use `su` in the launcher. This     allows us to divest ourselves of `su` altogether on Windows.          Review: https://reviews.apache.org/r/43905/ {code}\"','','2016-03-01 21:40:13',3647,19872);
