INSERT INTO `Comment` VALUES (48586,'Hi Qian,\n I think there are bunch of reviews out for this JIRA. Can we move this to \"Reviewable\" and point to the RBs that relate to this JIRA?\n\nThanks,\nAvinash','\"Hi Qian,  I think there are bunch of reviews out for this JIRA. Can we move this to \"\"Reviewable\"\" and point to the RBs that relate to this JIRA?  Thanks, Avinash\"','','2016-04-25 18:49:15',3576,19889);
INSERT INTO `Comment` VALUES (48587,'[~<EMAIL>], I think what you mean should be the JIRA: https://issues.apache.org/jira/browse/MESOS-5167. I have already move that JIRA into \"Reviewable\" and posted the RBs there.\n\nFor this JIRA, I think we will not work on it since we do not need to implement a separate mock plugin script anymore (we have embedded such script in the tests).','\"[~<EMAIL>], I think what you mean should be the JIRA: https://issues.apache.org/jira/browse/MESOS-5167. I have already move that JIRA into \"\"Reviewable\"\" and posted the RBs there.  For this JIRA, I think we will not work on it since we do not need to implement a separate mock plugin script anymore (we have embedded such script in the tests).\"','','2016-04-25 23:58:14',3360,19889);
INSERT INTO `Comment` VALUES (48588,'The test cases are being implemented as part of MESOS-5167 so we no longer need this ticket.','\"The test cases are being implemented as part of MESOS-5167 so we no longer need this ticket.\"','','2016-04-26 00:38:14',3576,19889);
INSERT INTO `Comment` VALUES (48589,'Sounds good. Thanks !! , closing this and tracking MESOS-5167 in the Agile board. ','\"Sounds good. Thanks !! , closing this and tracking MESOS-5167 in the Agile board. \"','','2016-04-26 00:39:12',3576,19889);
