INSERT INTO `Comment` VALUES (48651,'{code}\ncommit 312ad65c929db8ce76c0c66bf8a2bfd27686bc95\nAuthor: <USER><<EMAIL>>\nDate:   Tue Mar 1 23:07:16 2016 -0800\n\n    CMake: Added leveldb library to 3rdparty external builds.\n    \n    Review: https://reviews.apache.org/r/43889/\n{code}','\"{code} commit 312ad65c929db8ce76c0c66bf8a2bfd27686bc95 Author: <USER><<EMAIL>> Date:   Tue Mar 1 23:07:16 2016 -0800      CMake: Added leveldb library to 3rdparty external builds.          Review: https://reviews.apache.org/r/43889/ {code}\"','','2016-03-02 07:57:13',3647,19906);
INSERT INTO `Comment` VALUES (48652,'We apparently have added leveldb to the 3rdparty external builds.\r\n\r\nAs of today, we are not linking it against the master on windows and we also are not building it on windows. We do however have it stored in our re-bundling repository in a version that seems to be identical to the one we are bundling - we might want to reconsider this as it appears to add no value.\r\n','\"We apparently have added leveldb to the 3rdparty external builds.    As of today, we are not linking it against the master on windows and we also are not building it on windows. We do however have it stored in our re-bundling repository in a version that seems to be identical to the one we are bundling - we might want to reconsider this as it appears to add no value.  \"','','2018-11-25 14:10:17',3390,19906);
INSERT INTO `Comment` VALUES (48727,'https://reviews.apache.org/r/43819/','\"https://reviews.apache.org/r/43819/\"','','2016-03-07 20:15:46',3572,19926);
INSERT INTO `Comment` VALUES (48728,'commit 79e28b61447a96aa30289a109283b490f312b66b\nAuthor: Joerg Schad <<EMAIL>>\nDate:   Mon Mar 14 01:38:21 2016 -0700\n\n    Added Scheduler-Driver API to app-framework-development-guide.md.\n    \n    Previously the app-framework-development-guide only explained the\n    scheduler callback interface. Equally important when developing\n    frameworks is the knowledge if potential actions a scheduler can\n    trigger via the SchedulerDriver.\n    \n    Review: https://reviews.apache.org/r/43819/','\"commit 79e28b61447a96aa30289a109283b490f312b66b Author: Joerg Schad <<EMAIL>> Date:   Mon Mar 14 01:38:21 2016 -0700      Added Scheduler-Driver API to app-framework-development-guide.md.          Previously the app-framework-development-guide only explained the     scheduler callback interface. Equally important when developing     frameworks is the knowledge if potential actions a scheduler can     trigger via the SchedulerDriver.          Review: https://reviews.apache.org/r/43819/\"','','2016-03-14 10:23:59',3581,19926);
INSERT INTO `Comment` VALUES (48754,'Review chain: https://reviews.apache.org/r/44218/','\"Review chain: https://reviews.apache.org/r/44218/\"','','2016-03-01 19:48:55',3371,19940);
INSERT INTO `Comment` VALUES (48755,'commit fb8a60cde7d75ceb3f4cbaa683d4bc4850037d7c\nAuthor: <USER><<EMAIL>>\nDate:   Tue Mar 1 11:40:45 2016 -0800\n\n    Updated the CHANGELOG and doc about \'subscribe.force\' field removal.\n    \n    Marked this as an API change in the CHANGELOG and removed references of this\n    field in the user doc. Also, updated the semantics for schedulers that\n    resubscribe.\n    \n    Review: https://reviews.apache.org/r/44220\n\ncommit f5cccf23f96f521d19fef06c188e4e85e5b3e233\nAuthor: <USER><<EMAIL>>\nDate:   Tue Mar 1 16:14:11 2016 -0800\n\n    Updated master to ignore \'Subscribe.force\' for HTTP framework.\n    \n    Master always closes any old active streaming connection when it gets a\n    SUBSCRIBE request.\n    \n    Review: https://reviews.apache.org/r/44243\n\ncommit 503fa896def670e0911b6dcd8affb478b82c1c6e\nAuthor: <USER><<EMAIL>>\nDate:   Tue Mar 1 11:13:55 2016 -0800\n\n    Removed \'Subscribe.force\' field from v1 Scheduler API.\n    \n    See the https://issues.apache.org/jira/browse/MESOS-4712 for details.\n    \n    Review: https://reviews.apache.org/r/44218\n','\"commit fb8a60cde7d75ceb3f4cbaa683d4bc4850037d7c Author: <USER><<EMAIL>> Date:   Tue Mar 1 11:40:45 2016 -0800      Updated the CHANGELOG and doc about \'subscribe.force\' field removal.          Marked this as an API change in the CHANGELOG and removed references of this     field in the user doc. Also, updated the semantics for schedulers that     resubscribe.          Review: https://reviews.apache.org/r/44220  commit f5cccf23f96f521d19fef06c188e4e85e5b3e233 Author: <USER><<EMAIL>> Date:   Tue Mar 1 16:14:11 2016 -0800      Updated master to ignore \'Subscribe.force\' for HTTP framework.          Master always closes any old active streaming connection when it gets a     SUBSCRIBE request.          Review: https://reviews.apache.org/r/44243  commit 503fa896def670e0911b6dcd8affb478b82c1c6e Author: <USER><<EMAIL>> Date:   Tue Mar 1 11:13:55 2016 -0800      Removed \'Subscribe.force\' field from v1 Scheduler API.          See the https://issues.apache.org/jira/browse/MESOS-4712 for details.          Review: https://reviews.apache.org/r/44218 \"','','2016-03-03 02:11:09',3371,19940);
