INSERT INTO `Comment` VALUES (49400,'{code}\ncommit 8d2504b3d6e705ebbaccc1e0836f1036c85b0bd5\nAuthor: <USER><<EMAIL>>\nDate:   Tue Jan 26 16:00:56 2016 -0800\n\n    Fixed logrotate ContainerLogger on Centos6.\n    \n    The `logrotate --version` flag is actually a very recent addition (3.9.1).\n    \n    The `--help` flag is more likely to be present on a supported\n    system-with-logrotate, given logrotate\'s usage of popopt.\n    \n    Review: https://reviews.apache.org/r/42820/\n{code}','\"{code} commit 8d2504b3d6e705ebbaccc1e0836f1036c85b0bd5 Author: <USER><<EMAIL>> Date:   Tue Jan 26 16:00:56 2016 -0800      Fixed logrotate ContainerLogger on Centos6.          The `logrotate --version` flag is actually a very recent addition (3.9.1).          The `--help` flag is more likely to be present on a supported     system-with-logrotate, given logrotate\'s usage of popopt.          Review: https://reviews.apache.org/r/42820/ {code}\"','','2016-01-27 00:01:47',3506,20137);
