INSERT INTO `Comment` VALUES (49478,'{noformat}\ncommit 0226620747e1769434a1a83da547bfc3470a9549\nAuthor: <USER><<EMAIL>>\nDate:   Thu Feb 4 14:47:13 2016 -0800\n\n    Used `std::any_of` instead of `std::count_if` when validating IDs.\n\n    This makes the intent slightly clearer. In principle, it should save a\n    few cycles as well, but nothing significant. Also, clarify the name of\n    a helper function.\n\n    Review: https://reviews.apache.org/r/42750/\n{noformat}','\"{noformat} commit 0226620747e1769434a1a83da547bfc3470a9549 Author: <USER><<EMAIL>> Date:   Thu Feb 4 14:47:13 2016 -0800      Used `std::any_of` instead of `std::count_if` when validating IDs.      This makes the intent slightly clearer. In principle, it should save a     few cycles as well, but nothing significant. Also, clarify the name of     a helper function.      Review: https://reviews.apache.org/r/42750/ {noformat}\"','','2016-02-05 23:30:39',3565,20173);
INSERT INTO `Comment` VALUES (49479,'{noformat}\ncommit 8b5cb55e6f8f1ed78ee43e7d497d9f01f8f0e5fd\nAuthor: <USER><<EMAIL>>\nDate:   Fri Feb 5 14:12:22 2016 -0800\n\n    Allowed `createLabel` to take an optional `value`.\n\n    This better matches the underlying protobuf definition.\n\n    Review: https://reviews.apache.org/r/42753/\n{noformat}\n{noformat}\ncommit 60015ea893dd0dbd96077035a9155c90012173bc\nAuthor: <USER><<EMAIL>>\nDate:   Fri Feb 5 14:12:14 2016 -0800\n\n    Fixed some typos in test case comments.\n\n    Review: https://reviews.apache.org/r/42752/\n{noformat}\n{noformat}\ncommit b5833d4d7a8358326149abd1f8d090be0335a7c6\nAuthor: <USER><<EMAIL>>\nDate:   Fri Feb 5 14:11:40 2016 -0800\n\n    Tweaked some resource test cases.\n\n    We should check that two reservations with the same role but different\n    principals are considered distinct.\n\n    Review: https://reviews.apache.org/r/42751/\n{noformat}\n{noformat}\ncommit d9d966d9e636fd4bee8b902742eaa9cf6dd1b342\nAuthor: <USER><<EMAIL>>\nDate:   Fri Feb 5 14:11:33 2016 -0800\n\n    Added `Resources::size()`.\n\n    Review: https://reviews.apache.org/r/43239/\n{noformat}','\"{noformat} commit 8b5cb55e6f8f1ed78ee43e7d497d9f01f8f0e5fd Author: <USER><<EMAIL>> Date:   Fri Feb 5 14:12:22 2016 -0800      Allowed `createLabel` to take an optional `value`.      This better matches the underlying protobuf definition.      Review: https://reviews.apache.org/r/42753/ {noformat} {noformat} commit 60015ea893dd0dbd96077035a9155c90012173bc Author: <USER><<EMAIL>> Date:   Fri Feb 5 14:12:14 2016 -0800      Fixed some typos in test case comments.      Review: https://reviews.apache.org/r/42752/ {noformat} {noformat} commit b5833d4d7a8358326149abd1f8d090be0335a7c6 Author: <USER><<EMAIL>> Date:   Fri Feb 5 14:11:40 2016 -0800      Tweaked some resource test cases.      We should check that two reservations with the same role but different     principals are considered distinct.      Review: https://reviews.apache.org/r/42751/ {noformat} {noformat} commit d9d966d9e636fd4bee8b902742eaa9cf6dd1b342 Author: <USER><<EMAIL>> Date:   Fri Feb 5 14:11:33 2016 -0800      Added `Resources::size()`.      Review: https://reviews.apache.org/r/43239/ {noformat}\"','','2016-02-05 23:31:14',3565,20173);
