INSERT INTO `Comment` VALUES (49690,'{code}\ncommit e34ac7747204a825c92ffcfda697a9b69989d524\nAuthor: <USER><<EMAIL>>\nDate:   Wed Jan 20 22:44:28 2016 -0800\n\n    Multiple Disk: Adjusted DiskInfo validation.\n    \n    Review: https://reviews.apache.org/r/42505/\n\ncommit 0aef5253de8f4ef7ef4766d8cdcd75978e2cba86\nAuthor: <USER><<EMAIL>>\nDate:   Mon Jan 18 15:30:39 2016 -0500\n\n    Multiple Disk: Updated Slave initialize to create DiskInfo paths.\n    \n    Create disk paths based on \'DiskInfo.Source\' if the type is \'PATH\'\n    and the directory does not yet exist. On linux we validate mounts\n    against the mount table.\n    \n    Review: https://reviews.apache.org/r/42474\n{code}','\"{code} commit e34ac7747204a825c92ffcfda697a9b69989d524 Author: <USER><<EMAIL>> Date:   Wed Jan 20 22:44:28 2016 -0800      Multiple Disk: Adjusted DiskInfo validation.          Review: https://reviews.apache.org/r/42505/  commit 0aef5253de8f4ef7ef4766d8cdcd75978e2cba86 Author: <USER><<EMAIL>> Date:   Mon Jan 18 15:30:39 2016 -0500      Multiple Disk: Updated Slave initialize to create DiskInfo paths.          Create disk paths based on \'DiskInfo.Source\' if the type is \'PATH\'     and the directory does not yet exist. On linux we validate mounts     against the mount table.          Review: https://reviews.apache.org/r/42474 {code}\"','','2016-01-24 01:25:48',3647,20249);
INSERT INTO `Comment` VALUES (49691,'https://reviews.apache.org/r/42473/','\"https://reviews.apache.org/r/42473/\"','','2016-01-18 21:26:52',3647,20250);
INSERT INTO `Comment` VALUES (49692,'{code}\ncommit 3e9cf548cdd3dd68b46c74b96f623fec71dc606e\nAuthor: <USER><<EMAIL>>\nDate:   Mon Jan 18 15:00:58 2016 -0500\n\n    Multiple Disk: Updated filesystem isolators to use \'DiskInfo.Source\'.\n    \n    Review: https://reviews.apache.org/r/42473\n{code}','\"{code} commit 3e9cf548cdd3dd68b46c74b96f623fec71dc606e Author: <USER><<EMAIL>> Date:   Mon Jan 18 15:00:58 2016 -0500      Multiple Disk: Updated filesystem isolators to use \'DiskInfo.Source\'.          Review: https://reviews.apache.org/r/42473 {code}\"','','2016-01-24 01:24:46',3647,20250);
INSERT INTO `Comment` VALUES (49696,'https://reviews.apache.org/r/42331','\"https://reviews.apache.org/r/42331\"','','2016-01-15 17:32:52',3415,20255);
INSERT INTO `Comment` VALUES (49697,'commit 331939ff779ce932e53976d757e8bb3c5354f47a\nAuthor: <USER><<EMAIL>>\nDate:   Fri Jan 15 09:08:19 2016 -0800\n\n    Renamed ContainerPrepareInfo to ContainerLaunchInfo.\n    \n    This better captures the purpose of this struct. ContainerLaunchInfo is\n    returned by the isolator \'prepare\' function. It contains information\n    about how a container should be launched (e.g., environment variables,\n    namespaces, commands, etc.). The information will be used by the Mesos\n    Containerizer when launching the container.\n    \n    Review: https://reviews.apache.org/r/42331/','\"commit 331939ff779ce932e53976d757e8bb3c5354f47a Author: <USER><<EMAIL>> Date:   Fri Jan 15 09:08:19 2016 -0800      Renamed ContainerPrepareInfo to ContainerLaunchInfo.          This better captures the purpose of this struct. ContainerLaunchInfo is     returned by the isolator \'prepare\' function. It contains information     about how a container should be launched (e.g., environment variables,     namespaces, commands, etc.). The information will be used by the Mesos     Containerizer when launching the container.          Review: https://reviews.apache.org/r/42331/\"','','2016-01-15 17:33:29',3415,20255);
INSERT INTO `Comment` VALUES (49753,'commit 1b56d99bfa8f64b81413908987f11539d4978a61\nAuthor: <USER><<EMAIL>>\nDate:   Sat Jan 16 12:45:59 2016 -0800\n\n    Documented endpoint failure when HTTP authentication disabled.\n    \n    The `/reserve` and `/unreserve` endpoints currently do not work when\n    HTTP authentication is disabled. To enable correct behavior, the\n    `principal` field of `ReservationInfo` is being migrated from `required`\n    to `optional`. This patch documents this behavior of these endpoints.\n    \n    Review: https://reviews.apache.org/r/42336/\n\ncommit 1dd713516d4f5e175ce45086263d71717bd9591e\nAuthor: <USER><<EMAIL>>\nDate:   Sat Jan 16 12:40:02 2016 -0800\n\n    Changed \'ReservationInfo.principal\' from required to optional.\n    \n    In order to allow dynamic reservation without a principal, this field is\n    being changed to optional. However, the current patch alters the master\n    to invalidate any reserve operations that do not set this field. After a\n    deprecation cycle, the master will allow the field to be unset.\n    \n    Review: https://reviews.apache.org/r/42334/','\"commit 1b56d99bfa8f64b81413908987f11539d4978a61 Author: <USER><<EMAIL>> Date:   Sat Jan 16 12:45:59 2016 -0800      Documented endpoint failure when HTTP authentication disabled.          The `/reserve` and `/unreserve` endpoints currently do not work when     HTTP authentication is disabled. To enable correct behavior, the     `principal` field of `ReservationInfo` is being migrated from `required`     to `optional`. This patch documents this behavior of these endpoints.          Review: https://reviews.apache.org/r/42336/  commit 1dd713516d4f5e175ce45086263d71717bd9591e Author: <USER><<EMAIL>> Date:   Sat Jan 16 12:40:02 2016 -0800      Changed \'ReservationInfo.principal\' from required to optional.          In order to allow dynamic reservation without a principal, this field is     being changed to optional. However, the current patch alters the master     to invalidate any reserve operations that do not set this field. After a     deprecation cycle, the master will allow the field to be unset.          Review: https://reviews.apache.org/r/42334/\"','','2016-01-16 20:48:55',3415,20270);
INSERT INTO `Comment` VALUES (49758,'The design doc can be found here: https://docs.google.com/document/d/1E2KpJpTY2BeA_rvUeGHIt5XsBA7fU3mACfBE1NZe82M/edit#\n\nComments welcome!','\"The design doc can be found here: https://docs.google.com/document/d/1E2KpJpTY2BeA_rvUeGHIt5XsBA7fU3mACfBE1NZe82M/edit#  Comments welcome!\"','','2016-01-15 23:27:00',3662,20273);
