INSERT INTO `Comment` VALUES (49963,'{noformat}\ncommit d291930d93c5e679c698ee7a8480e244afcea16d\nAuthor: <USER><<EMAIL>>\nDate:   Mon Jan 11 16:54:40 2016 -0800\n\n    Fixed protobuf::parse to surface nested message parsing errors.\n\n    Previously, errors parsing nested messages were ignored.\n\n    Review: https://reviews.apache.org/r/42167/\n{noformat}\n\n{noformat}\ncommit 9632dd84134b96ada563b9b26358d507a2cb0d9a\nAuthor: <USER><<EMAIL>>\nDate:   Mon Jan 11 17:06:53 2016 -0800\n\n    Added test for protobuf::parse with nested parse errors.\n\n    Review: https://reviews.apache.org/r/42058\n{noformat}','\"{noformat} commit d291930d93c5e679c698ee7a8480e244afcea16d Author: <USER><<EMAIL>> Date:   Mon Jan 11 16:54:40 2016 -0800      Fixed protobuf::parse to surface nested message parsing errors.      Previously, errors parsing nested messages were ignored.      Review: https://reviews.apache.org/r/42167/ {noformat}  {noformat} commit 9632dd84134b96ada563b9b26358d507a2cb0d9a Author: <USER><<EMAIL>> Date:   Mon Jan 11 17:06:53 2016 -0800      Added test for protobuf::parse with nested parse errors.      Review: https://reviews.apache.org/r/42058 {noformat}\"','','2016-01-12 01:23:34',3363,20341);
INSERT INTO `Comment` VALUES (49987,'change\n{noformat}\n    if (strings::startsWith(hdfsPath, \"hdfs://\") ||\n        strings::startsWith(hdfsPath, \"/\")) {\n      return hdfsPath;\n    }\n{noformat}\nto allow \"maprfs\" should be enough. But I think \"maprfs\" only appears in MapR hadoop version, right?','\"change  to allow \"\"maprfs\"\" should be enough. But I think \"\"maprfs\"\" only appears in MapR hadoop version, right?\"','\"     if (strings::startsWith(hdfsPath, \"\"hdfs://\"\") ||         strings::startsWith(hdfsPath, \"\"/\"\")) {       return hdfsPath;     } \"','2016-01-07 02:33:07',3414,20348);
INSERT INTO `Comment` VALUES (49988,'What about other schemes (e.g., s3://)? I think we should instead check if \'scheme\' is presented in the URI.','\"What about other schemes (e.g., s3://)? I think we should instead check if \'scheme\' is presented in the URI.\"','','2016-01-07 02:36:10',3415,20348);
INSERT INTO `Comment` VALUES (49989,'Oh, yes. Could be s3','\"Oh, yes. Could be s3\"','','2016-01-07 02:38:38',3414,20348);
INSERT INTO `Comment` VALUES (49990,'I agree with Jie. While I could easily add whatever protocol I wanted, the client is intended to be robust enough to try and handle any previously unknown protocols. Checking for any sort of scheme would most likely alleviate the problem.','\"I agree with Jie. While I could easily add whatever protocol I wanted, the client is intended to be robust enough to try and handle any previously unknown protocols. Checking for any sort of scheme would most likely alleviate the problem.\"','','2016-01-07 02:43:46',4063,20348);
INSERT INTO `Comment` VALUES (49991,'[~<USER>, [~<USER> Is this a blocker for 0.27.0? Is anyone working on this currently?','\"[~<USER>, [~<USER> Is this a blocker for 0.27.0? Is anyone working on this currently?\"','','2016-01-13 06:11:38',3565,20348);
INSERT INTO `Comment` VALUES (49992,'[~<USER> I would say: YES, this is a blocker for 0.27.0. Let\'s fix this bug for the release. It should be pretty straightforward.\n\n[~<USER> do you have cycles for this since you did the fix last time? I can shepherd it.','\"[~<USER> I would say: YES, this is a blocker for 0.27.0. Let\'s fix this bug for the release. It should be pretty straightforward.  [~<USER> do you have cycles for this since you did the fix last time? I can shepherd it.\"','','2016-01-13 07:05:50',3415,20348);
