INSERT INTO `Comment` VALUES (49995,'commit 6afd1b682df9809a9113ab9f61caf26b8c6a02d9\nAuthor: <USER><<EMAIL>>\nDate:   Fri Jan 22 11:36:12 2016 +0100\n\n    Fixed support for non-HDFS URIs by Hadoop client.\n    \n    Review: https://reviews.apache.org/r/42246/','\"commit 6afd1b682df9809a9113ab9f61caf26b8c6a02d9 Author: <USER><<EMAIL>> Date:   Fri Jan 22 11:36:12 2016 +0100      Fixed support for non-HDFS URIs by Hadoop client.          Review: https://reviews.apache.org/r/42246/\"','','2016-01-22 10:38:02',3967,20348);
INSERT INTO `Comment` VALUES (50009,'While fixing this log line, found another bug.\n\nEssentially:\n# {{validation::offer::validate}} returns an error when an {{InverseOffer}} is accepted.\n# If an {{Offer}} is part of the same {{Call::ACCEPT}}, the master sees {{error.isSome()}} and returns a {{TASK_LOST}} for normal offers.  (https://github.com/apache/mesos/blob/fafbdca610d0a150b9fa9cb62d1c63cb7a6fdaf3/src/master/master.cpp#L3117)\n\nRegression test:\nhttps://reviews.apache.org/r/42092/ (discarded)','\"While fixing this log line, found another bug.  Essentially: # {{validation::offer::validate}} returns an error when an {{InverseOffer}} is accepted. # If an {{Offer}} is part of the same {{Call::ACCEPT}}, the master sees {{error.isSome()}} and returns a {{TASK_LOST}} for normal offers.  (https://github.com/apache/mesos/blob/fafbdca610d0a150b9fa9cb62d1c63cb7a6fdaf3/src/master/master.cpp#L3117)  Regression test: https://reviews.apache.org/r/42092/ (discarded)\"','','2016-01-08 23:05:24',3391,20351);
INSERT INTO `Comment` VALUES (50010,'Review to:\n* Fix the logging.\n* Fix the bug found above.\n* Refactor {{Master::accept}} to read more sequentially.\n\nhttps://reviews.apache.org/r/42086/ (discarded)','\"Review to: * Fix the logging. * Fix the bug found above. * Refactor {{Master::accept}} to read more sequentially.  https://reviews.apache.org/r/42086/ (discarded)\"','','2016-01-08 23:25:58',3391,20351);
INSERT INTO `Comment` VALUES (50011,'The plan is to:\n* Fix the misleading log message here (for 0.27)\n* Defer the decision for mixing {{Offers}} and {{InverseOffers}} for a future release.  This means keeping the above \"bug\" in-tact.  (Note: The current behavior is effectively prohibiting the mixing of offer types.)','\"The plan is to: * Fix the misleading log message here (for 0.27) * Defer the decision for mixing {{Offers}} and {{InverseOffers}} for a future release.  This means keeping the above \"\"bug\"\" in-tact.  (Note: The current behavior is effectively prohibiting the mixing of offer types.)\"','','2016-01-14 21:34:10',3391,20351);
INSERT INTO `Comment` VALUES (50012,'Minimal patch just to silence the log line:\nhttps://reviews.apache.org/r/42324/','\"Minimal patch just to silence the log line: https://reviews.apache.org/r/42324/\"','','2016-01-14 22:41:52',3391,20351);
INSERT INTO `Comment` VALUES (50013,'We (BenM & I) decided it was not worthwhile to silence the log line without also fixing the underlying semantics that go along with mixing offers & inverse offers.  \n\nThe more comprehensive fix is tracked here: [MESOS-4385]','\"We (BenM & I) decided it was not worthwhile to silence the log line without also fixing the underlying semantics that go along with mixing offers & inverse offers.    The more comprehensive fix is tracked here: [MESOS-4385]\"','','2016-01-19 21:44:11',3391,20351);
