INSERT INTO `Comment` VALUES (54305,'{noformat}\ncommit cbb2099919a0790bdbdffb8e2a7f2231f632567c\nAuthor: <USER><<EMAIL>>\nDate:   Fri Jul 24 14:51:11 2015 -0700\n\n    Used std::thread instead of pthread for Libprocess process.\n    \n    Review: https://reviews.apache.org/r/36715\n\ncommit f24db46b92796efaa15766c625b8ef4706240f2f\nAuthor: <USER><<EMAIL>>\nDate:   Fri Jul 24 14:39:43 2015 -0700\n\n    Replaced ThreadLocal use with thread_local.\n    \n    Review: https://reviews.apache.org/r/36705\n\ncommit 1bd50fc5c0c0825bab1195c608d9cd2c5b3f0479\nAuthor: <USER><<EMAIL>>\nDate:   Fri Jul 24 14:35:02 2015 -0700\n\n    Removed pthread from Once and Gate.\n    \n    Review: https://reviews.apache.org/r/36673\n{noformat}','\"{noformat} commit cbb2099919a0790bdbdffb8e2a7f2231f632567c Author: <USER><<EMAIL>> Date:   Fri Jul 24 14:51:11 2015 -0700      Used std::thread instead of pthread for Libprocess process.          Review: https://reviews.apache.org/r/36715  commit f24db46b92796efaa15766c625b8ef4706240f2f Author: <USER><<EMAIL>> Date:   Fri Jul 24 14:39:43 2015 -0700      Replaced ThreadLocal use with thread_local.          Review: https://reviews.apache.org/r/36705  commit 1bd50fc5c0c0825bab1195c608d9cd2c5b3f0479 Author: <USER><<EMAIL>> Date:   Fri Jul 24 14:35:02 2015 -0700      Removed pthread from Once and Gate.          Review: https://reviews.apache.org/r/36673 {noformat}\"','','2015-07-24 23:33:42',3506,21530);
INSERT INTO `Comment` VALUES (54306,'Turns out we can\'t use {{thread_local}} with the default installed clang on OS X. See https://devforums.apple.com/message/1079348#1079348. Relevant snippet: \"We don\'t support the thread_local implementation from the open-source Clang because we believe we can provide a higher-performance implementation for our platforms using various features in the dynamic linker. Such an implementation would be ABI-incompatible with the implementation in the open-source Clang, so we won\'t support {{thread_local}} until we get an implementation we can live with for the foreseeable future.\"\n\nSo, I\'ve reopened this issue and reverted {{f24db46b92796efaa15766c625b8ef4706240f2f}} for now.\n\nOne possible path forward is to use {{\\_\\_thread}} since it\'s supported by both clang and gcc (and we could introduce something similar for non-POSIX platforms), but we\'d need to be careful because it has C style semantics, which means that we won\'t get object construction/destruction (which we would with {{thread_local}} IIUC). We currently don\'t need object construction/destruction in our code base, but I\'d still prefer to wrap {{\\_\\_thread}} in some sort of macro that makes it clear that we need to create _pointers_ when using {{\\_\\_thread}}.','\"Turns out we can\'t use {{thread_local}} with the default installed clang on OS X. See https://devforums.apple.com/message/1079348#1079348. Relevant snippet: \"\"We don\'t support the thread_local implementation from the open-source Clang because we believe we can provide a higher-performance implementation for our platforms using various features in the dynamic linker. Such an implementation would be ABI-incompatible with the implementation in the open-source Clang, so we won\'t support {{thread_local}} until we get an implementation we can live with for the foreseeable future.\"\"  So, I\'ve reopened this issue and reverted {{f24db46b92796efaa15766c625b8ef4706240f2f}} for now.  One possible path forward is to use {{\\_\\_thread}} since it\'s supported by both clang and gcc (and we could introduce something similar for non-POSIX platforms), but we\'d need to be careful because it has C style semantics, which means that we won\'t get object construction/destruction (which we would with {{thread_local}} IIUC). We currently don\'t need object construction/destruction in our code base, but I\'d still prefer to wrap {{\\_\\_thread}} in some sort of macro that makes it clear that we need to create _pointers_ when using {{\\_\\_thread}}.\"','','2015-07-25 00:48:32',3506,21530);
INSERT INTO `Comment` VALUES (54307,'Hi Anand, The motiviation is in the epic :-)','\"Hi Anand, The motiviation is in the epic :-)\"','','2015-07-25 14:40:25',3647,21530);
INSERT INTO `Comment` VALUES (54308,'{noformat}\ncommit 2b952a76b1bdae58d416768a2608d800cc049937\nAuthor: <USER><<EMAIL>>\nDate:   Wed Jul 29 16:57:27 2015 -0700\n\n    Removed and guarded pthread specifics for libevent-openssl.\n    \n    Review: https://reviews.apache.org/r/36827\n{noformat}','\"{noformat} commit 2b952a76b1bdae58d416768a2608d800cc049937 Author: <USER><<EMAIL>> Date:   Wed Jul 29 16:57:27 2015 -0700      Removed and guarded pthread specifics for libevent-openssl.          Review: https://reviews.apache.org/r/36827 {noformat}\"','','2015-07-30 23:11:13',3506,21530);
INSERT INTO `Comment` VALUES (54309,'{noformat}\ncommit b80ef400d139fae5c843173163e6a392e75bff4a\nAuthor: <USER><<EMAIL>>\nDate:   Thu Jul 30 15:29:01 2015 -0700\n\n    Used THREAD_LOCAL to replace ThreadLocal.\n    \n    Review: https://reviews.apache.org/r/36844\n\ncommit 9c86375cd9297cc02ed17d5043597d4b240bfbba\nAuthor: <USER><<EMAIL>>\nDate:   Thu Jul 30 15:27:37 2015 -0700\n\n    Stout: Introduced THREAD_LOCAL wrapper for thread local storage.\n    \n    This replaced the `ThreadLocal` primitive with the new C++11 standard.\n    The exception is on OSX where we use `__thread` as `thread_local` is\n    not supported.\n    \n    Review: https://reviews.apache.org/r/36845\n{noformat}','\"{noformat} commit b80ef400d139fae5c843173163e6a392e75bff4a Author: <USER><<EMAIL>> Date:   Thu Jul 30 15:29:01 2015 -0700      Used THREAD_LOCAL to replace ThreadLocal.          Review: https://reviews.apache.org/r/36844  commit 9c86375cd9297cc02ed17d5043597d4b240bfbba Author: <USER><<EMAIL>> Date:   Thu Jul 30 15:27:37 2015 -0700      Stout: Introduced THREAD_LOCAL wrapper for thread local storage.          This replaced the `ThreadLocal` primitive with the new C++11 standard.     The exception is on OSX where we use `__thread` as `thread_local` is     not supported.          Review: https://reviews.apache.org/r/36845 {noformat}\"','','2015-07-30 23:30:53',3506,21530);
INSERT INTO `Comment` VALUES (54310,'{noformat}\ncommit 1b9ce37f37592125487d8a0979364cf6bbce6b6f\nAuthor: <USER><<EMAIL>>\nDate:   Thu Jul 30 15:04:21 2015 -0700\n\n    Used std::thread instead of pthread for stout proc tests.\n    \n    Review: https://reviews.apache.org/r/36828\n\ncommit 3817760ca52a4433686ef5f171cef0a9806e8ab8\nAuthor: <USER><<EMAIL>>\nDate:   Fri Jul 24 14:34:46 2015 -0700\n\n    Removed pthread specialization from Synchronized.\n    \n    Review: https://reviews.apache.org/r/36672\n{noformat}','\"{noformat} commit 1b9ce37f37592125487d8a0979364cf6bbce6b6f Author: <USER><<EMAIL>> Date:   Thu Jul 30 15:04:21 2015 -0700      Used std::thread instead of pthread for stout proc tests.          Review: https://reviews.apache.org/r/36828  commit 3817760ca52a4433686ef5f171cef0a9806e8ab8 Author: <USER><<EMAIL>> Date:   Fri Jul 24 14:34:46 2015 -0700      Removed pthread specialization from Synchronized.          Review: https://reviews.apache.org/r/36672 {noformat}\"','','2015-07-24 23:35:39',3506,21531);
