INSERT INTO `Comment` VALUES (54360,'commit 5b183ee215847cdb4a5121bedf9af0952426cef7\nAuthor: <USER><<EMAIL>>\nDate:   Tue Jul 28 12:00:18 2015 -0700\n\n    Added https support in libprocess.\n\n    Current http implementation lacks a https interface. This change exposes\n    SSL socket for \"https\" URL scheme.\n\n    Review: https://reviews.apache.org/r/36757','\"commit 5b183ee215847cdb4a5121bedf9af0952426cef7 Author: <USER><<EMAIL>> Date:   Tue Jul 28 12:00:18 2015 -0700      Added https support in libprocess.      Current http implementation lacks a https interface. This change exposes     SSL socket for \"\"https\"\" URL scheme.      Review: https://reviews.apache.org/r/36757\"','','2015-07-29 18:49:50',3664,21556);
