INSERT INTO `Comment` VALUES (54418,'commit bbd3104b0a42dca470716b6cedfcb9baa28be0fa\nAuthor: <USER><<EMAIL>>\nDate:   Tue Jul 21 13:29:32 2015 -0700\n\n    Added Labels to TaskStatus protobuf and expose them via state.json.\n    \n    The labels would allow executors and Slave modules to pass in some\n    meta-data about the task to the framework and Mesos-DNS (via\n    state.json).\n    \n    Review: https://reviews.apache.org/r/36575\n','\"commit bbd3104b0a42dca470716b6cedfcb9baa28be0fa Author: <USER><<EMAIL>> Date:   Tue Jul 21 13:29:32 2015 -0700      Added Labels to TaskStatus protobuf and expose them via state.json.          The labels would allow executors and Slave modules to pass in some     meta-data about the task to the framework and Mesos-DNS (via     state.json).          Review: https://reviews.apache.org/r/36575 \"','','2015-07-23 04:42:06',3491,21573);
