INSERT INTO `Comment` VALUES (54429,'{code}\ncommit 462f64d30b192498ded7804894eae98f984a21c6\nAuthor: <USER><<EMAIL>>\nDate:   Mon Nov 16 09:37:45 2015 +0100\n\n    Quota: Created stubs for quota set requests.\n    \n    Processing quota request consists of several stages: request\n    validation, sanity check and so on. This patch creates a basic\n    workflow for quota requests, while the stages are implemented\n    in subsequent patches.\n    \n    Review: https://reviews.apache.org/r/38059\ncommit 77b5de74772f1a9fd91e17d56317393b2c1e1fa0\nAuthor: Joerg Schad <<EMAIL>>\nDate:   Mon Nov 16 09:00:43 2015 +0100\n\n    Quota: Added /quota HTTP Endpoint for Quota handling.\n    \n    Review: https://reviews.apache.org/r/36913\n{code}','\"{code} commit 462f64d30b192498ded7804894eae98f984a21c6 Author: <USER><<EMAIL>> Date:   Mon Nov 16 09:37:45 2015 +0100      Quota: Created stubs for quota set requests.          Processing quota request consists of several stages: request     validation, sanity check and so on. This patch creates a basic     workflow for quota requests, while the stages are implemented     in subsequent patches.          Review: https://reviews.apache.org/r/38059 commit 77b5de74772f1a9fd91e17d56317393b2c1e1fa0 Author: Joerg Schad <<EMAIL>> Date:   Mon Nov 16 09:00:43 2015 +0100      Quota: Added /quota HTTP Endpoint for Quota handling.          Review: https://reviews.apache.org/r/36913 {code}\"','','2015-11-16 16:23:49',3647,21576);
