INSERT INTO `Comment` VALUES (54749,'This came up again in the context of an external storage manager that needs to know when a slave exits, so it can unmount any volumes that were attached to that slave. Maybe the real solution would be a Mesos event bus that the other process can listen to.','\"This came up again in the context of an external storage manager that needs to know when a slave exits, so it can unmount any volumes that were attached to that slave. Maybe the real solution would be a Mesos event bus that the other process can listen to.\"','','2015-09-15 07:16:27',3581,21634);
