INSERT INTO `Comment` VALUES (1322674,'https://github.com/<USER>titanium_mobile_windows/pull/779\r\n\r\nWe have observed this saves over 70% of time.\r\n\r\n- Ti SDK 6.0.0.v20160714010528 ... 5.5 sec\r\n- Ti SDK 6.0.0.v20160714010528 with this update ... 1.7 sec\r\n\r\n{code}\r\nvar win = Ti.UI.createWindow({ backgroundColor: \'green\' });\r\nvar data = [];\r\n\r\nvar start = +new Date();\r\nfor (var i = 0; i < 100; i++) {\r\n    var task = {\r\n        Id: i,\r\n        Title: \'Row \' + i,\r\n        Data: \'Data \' + i\r\n    };\r\n    var tvr = Ti.UI.createTableViewRow({\r\n        height: 70,\r\n        taskId: task.Id\r\n    });\r\n    tvr.add(Ti.UI.createLabel({\r\n        text: task.Title,\r\n        color: \"#000\",\r\n        top: 5,\r\n        left: 20\r\n    }));\r\n    tvr.add(Ti.UI.createLabel({\r\n        text: task.Data,\r\n        color: \"#000\",\r\n        top: 30,\r\n        left: 20,\r\n        font: {\r\n            fontSize: 12\r\n        }\r\n    }));\r\n    data.push(tvr);\r\n}\r\n\r\nvar table = Ti.UI.createTableView({data: data});\r\n\r\ntable.addEventListener(\'click\', function (e) {\r\n    alert(e.row.taskId)\r\n});\r\n\r\nalert(\'Total: \' + (+new Date() - start));\r\n\r\nwin.add(table);\r\nwin.open();\r\n{code}','\"https://github.com/<USER>titanium_mobile_windows/pull/779    We have observed this saves over 70% of time.    - Ti SDK 6.0.0.v20160714010528 ... 5.5 sec  - Ti SDK 6.0.0.v20160714010528 with this update ... 1.7 sec    \"','\"  var win = Ti.UI.createWindow({ backgroundColor: \'green\' });  var data = [];    var start = +new Date();  for (var i = 0; i < 100; i++) {      var task = {          Id: i,          Title: \'Row \' + i,          Data: \'Data \' + i      };      var tvr = Ti.UI.createTableViewRow({          height: 70,          taskId: task.Id      });      tvr.add(Ti.UI.createLabel({          text: task.Title,          color: \"\"#000\"\",          top: 5,          left: 20      }));      tvr.add(Ti.UI.createLabel({          text: task.Data,          color: \"\"#000\"\",          top: 30,          left: 20,          font: {              fontSize: 12          }      }));      data.push(tvr);  }    var table = Ti.UI.createTableView({data: data});    table.addEventListener(\'click\', function (e) {      alert(e.row.taskId)  });    alert(\'Total: \' + (+new Date() - start));    win.add(table);  win.open();  \"','2016-07-20 06:26:34',166083,406406);
