INSERT INTO `Comment` VALUES (1322958,'PR: https://github.com/<USER>titanium_mobile/pull/8096\r\n\r\nDemo:\r\n{code:javascript}\r\n// Check the initial properties (should only be the iOS ones)\r\nTi.API.warn(Ti.App.Properties.listProperties());\r\n\r\n// Add all possible property-types (bool, int, double, string, object & list)\r\nTi.App.Properties.setBool(\"testBool\", true)\r\nTi.API.warn(Ti.App.Properties.getBool(\"testBool\"));\r\n\r\nTi.App.Properties.setInt(\"testInt\", 1337)\r\nTi.API.warn(Ti.App.Properties.getInt(\"testInt\", 1337));\r\n\r\nTi.App.Properties.setDouble(\"testDouble\", 13.37);\r\nTi.API.warn(Ti.App.Properties.getDouble(\"testDouble\", 13.37));\r\n\r\nTi.App.Properties.setString(\"testString\", \"john_doe\")\r\nTi.API.warn(Ti.App.Properties.getString(\"testString\", \"john_doe\"));\r\n\r\nTi.App.Properties.setObject(\"testObject\", {appc: \"rocks\"})\r\nTi.API.warn(Ti.App.Properties.getObject(\"testObject\", {appc: \"rocks\"}));\r\n\r\nTi.App.Properties.setList(\"testList\", [\"appc\", \"rocks\"])\r\nTi.API.warn(Ti.App.Properties.getList(\"testList\", [\"appc\", \"rocks\"]));\r\n\r\n// Check the properties again. It should now include the keys of the custom properties\r\nTi.API.warn(Ti.App.Properties.listProperties());\r\n\r\n// Remove all custom properties\r\nTi.API.warn(Ti.App.Properties.removeAllProperties());\r\n\r\n// Check the properties a last time. The custom properties should not be included anymore\r\nTi.API.warn(Ti.App.Properties.listProperties());\r\n{code}','\"PR: https://github.com/<USER>titanium_mobile/pull/8096    Demo:  \"','\"  // Check the initial properties (should only be the iOS ones)  Ti.API.warn(Ti.App.Properties.listProperties());    // Add all possible property-types (bool, int, double, string, object & list)  Ti.App.Properties.setBool(\"\"testBool\"\", true)  Ti.API.warn(Ti.App.Properties.getBool(\"\"testBool\"\"));    Ti.App.Properties.setInt(\"\"testInt\"\", 1337)  Ti.API.warn(Ti.App.Properties.getInt(\"\"testInt\"\", 1337));    Ti.App.Properties.setDouble(\"\"testDouble\"\", 13.37);  Ti.API.warn(Ti.App.Properties.getDouble(\"\"testDouble\"\", 13.37));    Ti.App.Properties.setString(\"\"testString\"\", \"\"john_doe\"\")  Ti.API.warn(Ti.App.Properties.getString(\"\"testString\"\", \"\"john_doe\"\"));    Ti.App.Properties.setObject(\"\"testObject\"\", {appc: \"\"rocks\"\"})  Ti.API.warn(Ti.App.Properties.getObject(\"\"testObject\"\", {appc: \"\"rocks\"\"}));    Ti.App.Properties.setList(\"\"testList\"\", [\"\"appc\"\", \"\"rocks\"\"])  Ti.API.warn(Ti.App.Properties.getList(\"\"testList\"\", [\"\"appc\"\", \"\"rocks\"\"]));    // Check the properties again. It should now include the keys of the custom properties  Ti.API.warn(Ti.App.Properties.listProperties());    // Remove all custom properties  Ti.API.warn(Ti.App.Properties.removeAllProperties());    // Check the properties a last time. The custom properties should not be included anymore  Ti.API.warn(Ti.App.Properties.listProperties());  \"','2016-06-29 04:51:42',166010,406465);
