INSERT INTO `Comment` VALUES (1324592,'Verified as fixed\r\n\r\nTested on: \r\nWindows 10 Pro \r\nWindows Phone 10.0 (Microsoft Lumia 640 LTE) \r\nAppc Studio: 4.6.0.201604290815\r\nTi SDK: 5.3.0.v20160430043601\r\nAppc NPM: 4.2.5-5\r\nAppc Core: 5.3.0-40\r\nNode: v4.4.2\r\n\r\n*Closing Ticket.*','\"Verified as fixed    Tested on:   Windows 10 Pro   Windows Phone 10.0 (Microsoft Lumia 640 LTE)   Appc Studio: 4.6.0.201604290815  Ti SDK: 5.3.0.v20160430043601  Appc NPM: 4.2.5-5  Appc Core: 5.3.0-40  Node: v4.4.2    *Closing Ticket.*\"','','2016-05-02 19:58:15',166404,406753);
INSERT INTO `Comment` VALUES (1324631,'We need a master PR first since it\'s the base branch. Backports can make as soon as the master is approved. Since this is a feature, it probably won\'t go into 5_2_X, but it can be cherry-picked if anyone needs it. If we can review and merge the upcoming master-PR soon, it can go into 5.4.0. Thanks everyone!','\"We need a master PR first since it\'s the base branch. Backports can make as soon as the master is approved. Since this is a feature, it probably won\'t go into 5_2_X, but it can be cherry-picked if anyone needs it. If we can review and merge the upcoming master-PR soon, it can go into 5.4.0. Thanks everyone!\"','','2016-04-18 22:54:06',166010,406760);
