INSERT INTO `Comment` VALUES (1324824,'PR: https://github.com/<USER>titanium_mobile/pull/7935\r\n\r\nDemo:\r\n{code:javascript}\r\n \r\nvar win = Ti.UI.createWindow({backgroundColor: \"white\"});\r\nvar picker = Ti.UI.createPicker();\r\n\r\nvar data = [];\r\ndata[0]=Ti.UI.createPickerRow({title:12});\r\ndata[1]=Ti.UI.createPickerRow({title:true});\r\ndata[2]=Ti.UI.createPickerRow({title:-1});\r\ndata[3]=Ti.UI.createPickerRow({title:\'Grapes\'});\r\n\r\npicker.add(data);\r\npicker.selectionIndicator = true;\r\n\r\nwin.add(picker);\r\nwin.open();\r\n{code}','\"PR: https://github.com/<USER>titanium_mobile/pull/7935    Demo:  \"','\"     var win = Ti.UI.createWindow({backgroundColor: \"\"white\"\"});  var picker = Ti.UI.createPicker();    var data = [];  data[0]=Ti.UI.createPickerRow({title:12});  data[1]=Ti.UI.createPickerRow({title:true});  data[2]=Ti.UI.createPickerRow({title:-1});  data[3]=Ti.UI.createPickerRow({title:\'Grapes\'});    picker.add(data);  picker.selectionIndicator = true;    win.add(picker);  win.open();  \"','2016-04-11 22:44:03',166010,406790);
