INSERT INTO `Comment` VALUES (1325244,'The fix Gary made wasn\'t actually enough. It avoids the failure when we try to connect to win 10 mobile devices, but doesn\'t make any mention in the CLI telling the user to open the app, nor does it prevent failure when the command is \"launch\" and not \"connect\".\r\n\r\nI believe this PR addresses the issue: https://github.com/<USER>titanium_mobile_windows/pull/646','\"The fix Gary made wasn\'t actually enough. It avoids the failure when we try to connect to win 10 mobile devices, but doesn\'t make any mention in the CLI telling the user to open the app, nor does it prevent failure when the command is \"\"launch\"\" and not \"\"connect\"\".    I believe this PR addresses the issue: https://github.com/<USER>titanium_mobile_windows/pull/646\"','','2016-04-25 19:00:04',166009,406877);
INSERT INTO `Comment` VALUES (1325245,'Verified as fixed, Now get an appropriate warning message returned in the event that the app cannot be launched automatically for windows 10 mobile:\r\n{code:java}\r\n[INFO]  Installing the application...\r\n[INFO]  Finished installing the application\r\n[INFO]  Waiting for app to connect to log relay\r\n[WARN]  We were unable to launch the app for you on the device/emulator due to an error (common causes include un-paired devices). Please launch the app manually.\r\n{code}\r\n\r\nTested on: \r\nWindows 10 Pro \r\nWindows Phone 10.0 (Microsoft Lumia 640 LTE) \r\nTi SDK: 5.3.0.v20160428072113 \r\nAppc NPM: 4.2.5-3\r\nAppc Core: 5.3.0-40\r\nNode: v4.4.2\r\n\r\n*Closing Ticket.*\r\n','\"Verified as fixed, Now get an appropriate warning message returned in the event that the app cannot be launched automatically for windows 10 mobile:      Tested on:   Windows 10 Pro   Windows Phone 10.0 (Microsoft Lumia 640 LTE)   Ti SDK: 5.3.0.v20160428072113   Appc NPM: 4.2.5-3  Appc Core: 5.3.0-40  Node: v4.4.2    *Closing Ticket.*  \"','\"  [INFO]  Installing the application...  [INFO]  Finished installing the application  [INFO]  Waiting for app to connect to log relay  [WARN]  We were unable to launch the app for you on the device/emulator due to an error (common causes include un-paired devices). Please launch the app manually.  \"','2016-04-28 23:48:32',166404,406877);
