INSERT INTO `Comment` VALUES (1326709,'[~<EMAIL>] thanks but I meant how the builtin support [~<USER> is adding will be used.','\"[~<EMAIL>] thanks but I meant how the builtin support [~<USER> is adding will be used.\"','','2016-04-15 09:23:50',166377,407109);
INSERT INTO `Comment` VALUES (1326710,'Link to PR again: https://github.com/<USER>titanium_mobile/pull/7948\r\nImplemented 2 new methods hasPermission() and requestPermissions(). (please read documentation in the PR for usage).\r\nSample usage code:\r\n{code}\r\nvar cameraPermission = \"android.permission.CAMERA\";\r\nvar storagePermission = \"android.permission.READ_EXTERNAL_STORAGE\";\r\nvar hasCameraPerm = Ti.Android.hasPermission(cameraPermission);\r\nvar hasStoragePerm = Ti.Android.hasPermission(storagePermission);\r\nvar permissionsToRequest = [];\r\nif (!hasCameraPerm) {\r\n	permissionsToRequest.push(cameraPermission);\r\n}\r\nif (!hasStoragePerm) {\r\n	permissionsToRequest.push(storagePermission);\r\n}\r\nif (permissionsToRequest.length > 0) {\r\n	Ti.Android.requestPermissions(permissionsToRequest, function(e) {\r\n    	if (e.success) {\r\n    		Ti.API.info(\"SUCCESS\");\r\n    	} else {\r\n    		Ti.API.info(\"ERROR: \" + e.error);\r\n    	}\r\n	});\r\n}\r\n{code}','\"Link to PR again: https://github.com/<USER>titanium_mobile/pull/7948  Implemented 2 new methods hasPermission() and requestPermissions(). (please read documentation in the PR for usage).  Sample usage code:  \"','\"  var cameraPermission = \"\"android.permission.CAMERA\"\";  var storagePermission = \"\"android.permission.READ_EXTERNAL_STORAGE\"\";  var hasCameraPerm = Ti.Android.hasPermission(cameraPermission);  var hasStoragePerm = Ti.Android.hasPermission(storagePermission);  var permissionsToRequest = [];  if (!hasCameraPerm) {   permissionsToRequest.push(cameraPermission);  }  if (!hasStoragePerm) {   permissionsToRequest.push(storagePermission);  }  if (permissionsToRequest.length > 0) {   Ti.Android.requestPermissions(permissionsToRequest, function(e) {       if (e.success) {        Ti.API.info(\"\"SUCCESS\"\");       } else {        Ti.API.info(\"\"ERROR: \"\" + e.error);       }   });  }  \"','2016-04-18 22:46:17',166600,407109);
INSERT INTO `Comment` VALUES (1326711,'We could also use this library: https://github.com/00ec454/Ask','\"We could also use this library: https://github.com/00ec454/Ask\"','','2016-04-20 08:33:46',166377,407109);
INSERT INTO `Comment` VALUES (1326712,'I\'m generally not in favour of adding in an external library if possible to reduce the complexity of dependencies if this can be done without an external library.','\"I\'m generally not in favour of adding in an external library if possible to reduce the complexity of dependencies if this can be done without an external library.\"','','2016-04-20 08:40:45',166526,407109);
