INSERT INTO `Comment` VALUES (1328276,'PR here: https://github.com/<USER>titanium_mobile/pull/7506\r\n\r\nh4. Steps to test\r\nUse this sample code:\r\n{code}\r\nTi.API.info(Ti.Media.CAMERA_AUTHORIZATION_NOT_DETERMINED);\r\nTi.API.info(Ti.Media.CAMERA_AUTHORIZATION_UNKNOWN);\r\n{code}\r\n\r\nh4. Expected Result\r\n{code}\r\n[WARN] Ti.Media.CAMERA_AUTHORIZATION_NOT_DETERMINED DEPRECATED in 5.2.0, in favor of Ti.Media.CAMERA_AUTHORIZATION_UNKNOWN\r\n[INFO] 0\r\n[INFO] 0\r\n{code}','\"PR here: https://github.com/<USER>titanium_mobile/pull/7506    h4. Steps to test  Use this sample code:      h4. Expected Result  \"','\"  Ti.API.info(Ti.Media.CAMERA_AUTHORIZATION_NOT_DETERMINED);  Ti.API.info(Ti.Media.CAMERA_AUTHORIZATION_UNKNOWN);    [WARN] Ti.Media.CAMERA_AUTHORIZATION_NOT_DETERMINED DEPRECATED in 5.2.0, in favor of Ti.Media.CAMERA_AUTHORIZATION_UNKNOWN  [INFO] 0  [INFO] 0  \"','2015-11-27 03:14:01',166198,407399);
