INSERT INTO `Comment` VALUES (1328591,'PR approved, great work [~<USER>!\r\n\r\nDemo:\r\n{code:javascript}\r\n\r\nvar win1 = Titanium.UI.createWindow({\r\n    title:\'Tab 1\',\r\n    backgroundColor:\'#fff\'\r\n});\r\n\r\nvar img = Ti.UI.createImageView({\r\n    image: \"KS_nav_ui.png\",\r\n    tintColor: \"red\",\r\n    top: 20\r\n});\r\n\r\nvar img2 = Ti.UI.createImageView({\r\n    image: \"KS_nav_ui.png\",\r\n    tintColor: \"#ff0\",\r\n    top: 200\r\n});\r\n\r\nsetTimeout(function() {\r\n    img.setTintColor(\"#ff0\");\r\n    img2.setTintColor(\"red\");\r\n},3000);\r\n\r\nwin1.add(img);\r\nwin1.add(img2);\r\n\r\nwin1.open();\r\n{code}','\"PR approved, great work [~<USER>!    Demo:  \"','\"    var win1 = Titanium.UI.createWindow({      title:\'Tab 1\',      backgroundColor:\'#fff\'  });    var img = Ti.UI.createImageView({      image: \"\"KS_nav_ui.png\"\",      tintColor: \"\"red\"\",      top: 20  });    var img2 = Ti.UI.createImageView({      image: \"\"KS_nav_ui.png\"\",      tintColor: \"\"#ff0\"\",      top: 200  });    setTimeout(function() {      img.setTintColor(\"\"#ff0\"\");      img2.setTintColor(\"\"red\"\");  },3000);    win1.add(img);  win1.add(img2);    win1.open();  \"','2016-04-02 09:55:53',166010,407484);
