INSERT INTO `Comment` VALUES (1329632,'[~<USER> [~<USER> I try to add this to the 5.2 sample but the code in the description doesn\'t add an additional launcher shortcut for me (Android 6.0 device, 5.2.0.GA).','\"[~<USER> [~<USER> I try to add this to the 5.2 sample but the code in the description doesn\'t add an additional launcher shortcut for me (Android 6.0 device, 5.2.0.GA).\"','','2016-02-23 10:45:04',166377,407691);
INSERT INTO `Comment` VALUES (1329633,'[~<USER>, I had to use this permission in tiapp.xml for the launcher shortcut to get added :\r\n{code}\r\n<uses-permission android:name=\"com.android.launcher.permission.INSTALL_SHORTCUT\"/>\r\n{code}\r\n','\"[~<USER>, I had to use this permission in tiapp.xml for the launcher shortcut to get added :    \"','\"  <uses-permission android:name=\"\"com.android.launcher.permission.INSTALL_SHORTCUT\"\"/>  \"','2016-02-23 16:49:26',166012,407691);
INSERT INTO `Comment` VALUES (1329634,'Thanks [~<USER>, I got it to work. I also found it\'s better to use {{Ti.App.Android.launchIntent}} then {{Ti.Android.currentActivity.getIntent()}} since the last one will not be useful if the primary window is no longer the current one.\r\n\r\nWhen the app starts I can use {{Ti.App.Android.launchIntent.getStringExtra()}} to see if the shortcut was used to launch it. However, if the app is already running the {{newintent}} event on either {{Ti.Android.currentActivity}} or the current Window/TabGroup\'s activity doesn\'t fire. Any idea?','\"Thanks [~<USER>, I got it to work. I also found it\'s better to use {{Ti.App.Android.launchIntent}} then {{Ti.Android.currentActivity.getIntent()}} since the last one will not be useful if the primary window is no longer the current one.    When the app starts I can use {{Ti.App.Android.launchIntent.getStringExtra()}} to see if the shortcut was used to launch it. However, if the app is already running the {{newintent}} event on either {{Ti.Android.currentActivity}} or the current Window/TabGroup\'s activity doesn\'t fire. Any idea?\"','','2016-02-24 10:17:20',166377,407691);
INSERT INTO `Comment` VALUES (1329635,'@<USER>I actually had to abandon the launcher shortcut because I could not get {{newintent}} working. I figured it was related to the launcher shortcut but maybe this event is broken?','\"@<USER>I actually had to abandon the launcher shortcut because I could not get {{newintent}} working. I figured it was related to the launcher shortcut but maybe this event is broken?\"','','2016-02-24 14:06:54',166666,407691);
