INSERT INTO `Comment` VALUES (1329731,'Test code:\r\n{code}\r\nvar url = \"http://httpbin.org/post\";\r\nvar data = {\r\n    \"entry.id\": \"data\"\r\n    , \"_eventName\": \"name\"\r\n    , \"caption\": \"the caption\"\r\n    , \"fileName\": \"Name of file\"\r\n};\r\n\r\nvar xhr = Ti.Network.createHTTPClient();\r\n    xhr.onload = function (event) {\r\n         Ti.API.info(\"Received text: \" + this.responseText);\r\n         alert(\'success\');\r\n    };\r\n    xhr.onerror = function (event) {\r\n         Ti.API.debug(e.error);\r\n         alert(\'error\');\r\n    };\r\n    xhr.url = url;\r\n    xhr.open(\"POST\", url);\r\n    xhr.send(data);\r\n{code}','\"Test code:  \"','\"  var url = \"\"http://httpbin.org/post\"\";  var data = {      \"\"entry.id\"\": \"\"data\"\"      , \"\"_eventName\"\": \"\"name\"\"      , \"\"caption\"\": \"\"the caption\"\"      , \"\"fileName\"\": \"\"Name of file\"\"  };    var xhr = Ti.Network.createHTTPClient();      xhr.onload = function (event) {           Ti.API.info(\"\"Received text: \"\" + this.responseText);           alert(\'success\');      };      xhr.onerror = function (event) {           Ti.API.debug(e.error);           alert(\'error\');      };      xhr.url = url;      xhr.open(\"\"POST\"\", url);      xhr.send(data);  \"','2015-10-02 07:20:08',166526,407708);
