INSERT INTO `Comment` VALUES (1329755,'Tested with this code. \r\n\r\n{code}\r\nTitanium.Media.showCamera({\r\n	success:function(event) {\r\n		// called when media returned from the camera\r\n		Ti.API.debug(\'Our type was: \'+event.mediaType);\r\n		if(event.mediaType == Ti.Media.MEDIA_TYPE_PHOTO) {\r\n			var imageView = Ti.UI.createImageView({\r\n				width:win.width,\r\n				height:win.height,\r\n				image:event.media\r\n			});\r\n			win.add(imageView);\r\n		} else {\r\n			alert(\"got the wrong type back =\"+event.mediaType);\r\n		}\r\n	},\r\n	cancel:function() {\r\n		// called when user cancels taking a picture\r\n	},\r\n	error:function(error) {\r\n		// called when there\'s an error\r\n		var a = Titanium.UI.createAlertDialog({title:\'Camera\'});\r\n		a.setMessage(JSON.stringify(error));\r\n		a.show();\r\n	},\r\n	saveToPhotoGallery:true\r\n});\r\n{code}\r\n\r\nPR https://github.com/<USER>titanium_mobile/pull/7258','\"Tested with this code.         PR https://github.com/<USER>titanium_mobile/pull/7258\"','\"  Titanium.Media.showCamera({   success:function(event) {    // called when media returned from the camera    Ti.API.debug(\'Our type was: \'+event.mediaType);    if(event.mediaType == Ti.Media.MEDIA_TYPE_PHOTO) {     var imageView = Ti.UI.createImageView({      width:win.width,      height:win.height,      image:event.media     });     win.add(imageView);    } else {     alert(\"\"got the wrong type back =\"\"+event.mediaType);    }   },   cancel:function() {    // called when user cancels taking a picture   },   error:function(error) {    // called when there\'s an error    var a = Titanium.UI.createAlertDialog({title:\'Camera\'});    a.setMessage(JSON.stringify(error));    a.show();   },   saveToPhotoGallery:true  });  \"','2015-10-01 07:02:18',166650,407715);
