INSERT INTO `Comment` VALUES (1330406,'It looks like {{<project-dir>/platforms/PLATFORM/DefaultIcon.png}} support is not implemented in the titanium CLI yet. I think we want to skip {{<project-dir>/platforms/windows/}} support for 5.1.1...should be done in the different ticket & next release. Do you agree, [~<USER> [~<USER> ?','\"It looks like {{<project-dir>/platforms/PLATFORM/DefaultIcon.png}} support is not implemented in the titanium CLI yet. I think we want to skip {{<project-dir>/platforms/windows/}} support for 5.1.1...should be done in the different ticket & next release. Do you agree, [~<USER> [~<USER> ?\"','','2015-11-16 23:27:14',166083,407862);
INSERT INTO `Comment` VALUES (1330407,'[~kota] [~<USER> The DefaultIcon.png should go in the root of the project (i.e. {{<project-dir>/DefaultIcon.png}}), not in a platform specific directory.','\"[~kota] [~<USER> The DefaultIcon.png should go in the root of the project (i.e. {{<project-dir>/DefaultIcon.png}}), not in a platform specific directory.\"','','2015-11-16 23:33:02',166050,407862);
