INSERT INTO `Comment` VALUES (1331111,'NOTE: We only support adding default launch images to the asset catalog. We do not support adding i18n launch images. Not sure if we can even support that.','\"NOTE: We only support adding default launch images to the asset catalog. We do not support adding i18n launch images. Not sure if we can even support that.\"','','2015-08-15 00:00:25',166050,408033);
INSERT INTO `Comment` VALUES (1331112,'It seems indeed that launch asset catalogs or storyboard no longer support that:\r\nhttp://db42.in/2015/02/15/locale-based-ios-app-branding/\r\n\r\nWe should communicatie this as breaking change (by Apple) in our release notes.','\"It seems indeed that launch asset catalogs or storyboard no longer support that:  http://db42.in/2015/02/15/locale-based-ios-app-branding/    We should communicatie this as breaking change (by Apple) in our release notes.\"','','2015-08-20 07:17:26',166377,408033);
