INSERT INTO `Comment` VALUES (1334829,'I\'m having the same problem in 5.2.0.GA\r\n\r\nFailed to run dexer:\r\n[ERROR] :  \r\n[ERROR] :  trouble writing output: Too many method references: 66795; max is 65536.\r\n[ERROR] :  You may try using --multi-dex option.','\"I\'m having the same problem in 5.2.0.GA    Failed to run dexer:  [ERROR] :    [ERROR] :  trouble writing output: Too many method references: 66795; max is 65536.  [ERROR] :  You may try using --multi-dex option.\"','','2016-03-09 10:48:30',166128,409082);
