INSERT INTO `Issue` VALUES (2765,51751,'XD-1041','https://jira.spring.io/rest/api/2/issue/51751','\"Upgrade to Spring for Apache Hadoop 1.0.2.RELEASE and Pivotal HD 1.1\"','\"Make sure the sinks and jobs work against Pivotal HD 1.1\"','\"\"\"Make sure the sinks and jobs work against Pivotal HD 1.1\"\"\"','','Story','Minor','Done','Complete','2013-11-08 09:12:37','2013-11-08 09:12:37','2013-11-12 15:06:14','2013-11-12 15:06:14',3,NULL,5851,5851,6113,0,0,0,'',84,84,84,1,49);
INSERT INTO `Issue` VALUES (2770,51708,'XD-1036','https://jira.spring.io/rest/api/2/issue/51708','\"Support composed module deletion\"','\"Provided it is not currently used in any stream:  V) Attempt to destroy a composed module Should not be supported at all Should not be supported if involved in at least one stream (EB?, MF!) Should be supported and have no other consequences whatsoever (see IV) (EB?) Should be supported and invalidate/destroy streams involving it \"','\"\"\"Provided it is not currently used in any stream:  V) Attempt to destroy a composed module Should not be supported at all Should not be supported if involved in at least one stream (EB?, MF!) Should be supported and have no other consequences whatsoever (see IV) (EB?) Should be supported and invalidate/destroy streams involving it \"\"\"','','Story','Minor','Done','Complete','2013-11-06 01:24:13','2013-11-06 01:24:13','2013-11-11 09:28:25','2013-11-12 15:04:06',10,NULL,6079,6079,7684,0,0,0,'',94,94,94,1,49);
INSERT INTO `Issue` VALUES (2771,51707,'XD-1035','https://jira.spring.io/rest/api/2/issue/51707','\"Attempt to compose a module with same name+type as existing should fail\"','\"As per discussion, any attempt to create something that would collide with existing should fail:  II) Attempt to create a composed module with same name as an already existing, not composed module, with same type should fail (EB, MF) should work and shadow previous module from now on  III) Attempt to create a composed module with same name as an already existing composed module, with same type should fail (EB, MF) should work and shadow previous module from now on should work and retroactively change definitions of streams with that module \"','\"\"\"As per discussion, any attempt to create something that would collide with existing should fail:  II) Attempt to create a composed module with same name as an already existing, not composed module, with same type should fail (EB, MF) should work and shadow previous module from now on  III) Attempt to create a composed module with same name as an already existing composed module, with same type should fail (EB, MF) should work and shadow previous module from now on should work and retroactively change definitions of streams with that module \"\"\"','','Story','Minor','Done','Complete','2013-11-06 01:22:38','2013-11-06 01:22:38','2013-11-06 12:10:05','2013-11-12 15:04:11',5,NULL,472,472,647,0,0,0,'',94,94,94,1,49);
INSERT INTO `Issue` VALUES (2773,51694,'XD-1033','https://jira.spring.io/rest/api/2/issue/51694','\"Add a tcp-client source module\"','\"Add a module that can act as a tcp *client* (as opposed to our current tcp module, which acts as a server, waiting for an incoming connection)  Also, the module should allow to send \"\"commands\"\" to the remote server. The typical minimal case for such a protocol is to send \"\"PING\"\" messages, but a stateful mechanism should be put in place for more complex cases.\"','\"\"\"Add a module that can act as a tcp *client* (as opposed to our current tcp module, which acts as a server, waiting for an incoming connection)  Also, the module should allow to send \"\"\"\"commands\"\"\"\" to the remote server. The typical minimal case for such a protocol is to send \"\"\"\"PING\"\"\"\" messages, but a stateful mechanism should be put in place for more complex cases.\"\"\"','','Story','Minor','Done','Complete','2013-11-05 06:11:57','2013-11-05 06:11:57','2013-11-06 02:22:29','2013-11-12 15:04:02',5,NULL,0,0,1210,0,0,0,'',94,94,94,1,49);
INSERT INTO `Issue` VALUES (2775,51681,'XD-1031','https://jira.spring.io/rest/api/2/issue/51681','\"UI - Launch a job with parameters\"','\"Use a modal dialog to specify runtime parameters. There should be a little text are that gives hints as to the spring batch parameter key/value conventions, e.g. for type.  Might be a good idea to have a checkbox that lets you select to \'auto increment\' job instance number.  4 columns key, value, type, identifying and an \'add parameter\' button that adds a new row.  This would appear as a modal dialog box, polling of the state of the deployments would be suspended while the job parameter modal dialog box is shown.  \"','\"\"\"Use a modal dialog to specify runtime parameters. There should be a little text are that gives hints as to the spring batch parameter key/value conventions, e.g. for type.  Might be a good idea to have a checkbox that lets you select to \'auto increment\' job instance number.  4 columns key, value, type, identifying and an \'add parameter\' button that adds a new row.  This would appear as a modal dialog box, polling of the state of the deployments would be suspended while the job parameter modal dialog box is shown.  \"\"\"','','Story','Minor','Done','Complete','2013-11-04 11:44:59','2013-11-04 11:44:59','2013-11-11 21:11:04','2013-11-12 15:04:02',8,NULL,7899,7899,10646,0,0,0,'',72,72,93,1,49);
INSERT INTO `Issue` VALUES (2777,51643,'XD-1029','https://jira.spring.io/rest/api/2/issue/51643','\"Migrate to SI Redis Queue and Topic Adapters\"','','','','Story','Minor','Done','Complete','2013-11-01 09:17:17','2013-11-01 09:17:17','2013-11-08 09:12:30','2013-11-12 15:04:09',3,NULL,5717,5717,10075,1,0,0,'',82,82,82,1,49);
INSERT INTO `Issue` VALUES (2778,51641,'XD-1028','https://jira.spring.io/rest/api/2/issue/51641','\"UI - Do not hard-code server url\"','\"Specify the default URL as:  {code} urlRoot: location.protocol+\'//\'+location.hostname+(location.port ? \':\'+location.port: \'\') {code}\"','\"\"\"Specify the default URL as:  \"\"\"','\" urlRoot: location.protocol+\'//\'+location.hostname+(location.port ? \':\'+location.port: \'\') \"','Story','Minor','Done','Complete','2013-11-01 08:09:36','2013-11-01 08:09:36','2013-11-04 07:42:12','2013-11-12 15:04:11',1,NULL,4007,4007,4292,0,0,0,'',93,93,93,1,49);
INSERT INTO `Issue` VALUES (2781,51632,'XD-1025','https://jira.spring.io/rest/api/2/issue/51632','\"UI: Implement Job Deploy/Undeploy from the Job Definitions page\"','\"From XD-1023, the job status(deployed/undeployed) is available from JobInstance Repository and a job can be deployed/undeployed correctly.   Implement Job deploy/undeploy for a given job from JobDefinitions page and indicate status of the job definition (deployed/undeployed).\"','\"\"\"From XD-1023, the job status(deployed/undeployed) is available from JobInstance Repository and a job can be deployed/undeployed correctly.   Implement Job deploy/undeploy for a given job from JobDefinitions page and indicate status of the job definition (deployed/undeployed).\"\"\"','','Story','Minor','Done','Complete','2013-10-31 13:26:00','2013-10-31 13:26:00','2013-11-01 10:34:14','2013-11-12 15:04:04',2,NULL,1266,1266,1268,0,0,0,'',91,91,91,1,49);
INSERT INTO `Issue` VALUES (2782,51604,'XD-1024','https://jira.spring.io/rest/api/2/issue/51604','\"Kryo Redis Serializer\"','\"The current (XD) uses an inadequate {{MessageRedisSerializer}} when {{extractPayload}} is false (not currently being used). When porting this to SI, the serializer will be dropped.  Suggest creation of Kryo serializer for Messages for when Redis source/sinks are created.\"','\"\"\"The current (XD) uses an inadequate {{MessageRedisSerializer}} when {{extractPayload}} is false (not currently being used). When porting this to SI, the serializer will be dropped.  Suggest creation of Kryo serializer for Messages for when Redis source/sinks are created.\"\"\"','','Story','Minor','Done','Complete','2013-10-30 09:06:01','2013-10-30 09:06:01','2013-11-08 11:21:16','2013-11-12 15:04:18',5,NULL,1565,1565,13095,0,0,0,'',82,82,89,1,49);
INSERT INTO `Issue` VALUES (2783,51579,'XD-1023','https://jira.spring.io/rest/api/2/issue/51579','\"Refactor job deploy to go through XDController.deploy(name)\"','\"Job deployment currently goes through an overloaded version of deploy() that takes 4 parameters. This prohibits job handling code from benefiting from common behavior (and eg currently breaks deployAll)  Given that the 3 additional parameters are in fine handled as module parameters, let\'s push them to the job definition, known at creation time, rather than at deployment time (as it does not really make sense to change those between deploys)\"','\"\"\"Job deployment currently goes through an overloaded version of deploy() that takes 4 parameters. This prohibits job handling code from benefiting from common behavior (and eg currently breaks deployAll)  Given that the 3 additional parameters are in fine handled as module parameters, let\'s push them to the job definition, known at creation time, rather than at deployment time (as it does not really make sense to change those between deploys)\"\"\"','','Story','Minor','Done','Complete','2013-10-29 08:01:17','2013-10-29 08:01:17','2013-10-31 10:54:35','2013-11-12 15:04:18',4,NULL,3027,3027,3053,0,0,0,'',94,94,94,1,49);
INSERT INTO `Issue` VALUES (2787,51570,'XD-1019','https://jira.spring.io/rest/api/2/issue/51570','\"Add Spring Retry to Rabbit Message Bus\"','\"Log and purge bad messages\"','\"\"\"Log and purge bad messages\"\"\"','','Improvement','Minor','Done','Complete','2013-10-28 15:30:39','2013-10-28 15:30:39','2013-10-31 10:21:54','2013-11-12 15:04:13',2,NULL,4010,4010,4011,0,0,0,'',82,82,82,1,49);
INSERT INTO `Issue` VALUES (2788,51566,'XD-1018','https://jira.spring.io/rest/api/2/issue/51566','\"JobDeployer hides root exceptions on failure\"','\"When deploying jobs, the following code (line 103), hides the root cause of deployment failure:    if (exceptionClassName.equals(BEAN_CREATION_EXCEPTION) || exceptionClassName.equals(BEAN_DEFINITION_EXEPTION)) {     throw new MissingRequiredDefinitionException(definition.getName(), cause.getMessage());   }  For example:  org.springframework.xd.dirt.stream.MissingRequiredDefinitionException: Error creating bean with name \'dataSourceInitializer\' defined in file [/Users/<USER>Work/spring-xd/build/dist/spring-xd/xd/modules/job/hdfsjdbc/config/hdfsjdbc.xml]: Cannot resolve reference to bean \'databasePopulator\' while setting bean property \'databasePopulator\'; nested exception is org.springframework.beans.factory.BeanCreationException: Error creating bean with name \'databasePopulator\' defined in file [/Users/<USER>Work/spring-xd/build/dist/spring-xd/xd/modules/job/hdfsjdbc/config/hdfsjdbc.xml]: Initialization of bean failed; nested exception is java.lang.NullPointerException  at org.springframework.xd.dirt.stream.JobDeployer.deploy(JobDeployer.java:103)  at org.springframework.xd.dirt.stream.JobDeployer.deploy(JobDeployer.java:67)  at org.springframework.xd.dirt.rest.XDController.save(XDController.java:242)\"','\"\"\"When deploying jobs, the following code (line 103), hides the root cause of deployment failure:    if (exceptionClassName.equals(BEAN_CREATION_EXCEPTION) || exceptionClassName.equals(BEAN_DEFINITION_EXEPTION)) {     throw new MissingRequiredDefinitionException(definition.getName(), cause.getMessage());   }  For example:  org.springframework.xd.dirt.stream.MissingRequiredDefinitionException: Error creating bean with name \'dataSourceInitializer\' defined in file [/Users/<USER>Work/spring-xd/build/dist/spring-xd/xd/modules/job/hdfsjdbc/config/hdfsjdbc.xml]: Cannot resolve reference to bean \'databasePopulator\' while setting bean property \'databasePopulator\'; nested exception is org.springframework.beans.factory.BeanCreationException: Error creating bean with name \'databasePopulator\' defined in file [/Users/<USER>Work/spring-xd/build/dist/spring-xd/xd/modules/job/hdfsjdbc/config/hdfsjdbc.xml]: Initialization of bean failed; nested exception is java.lang.NullPointerException  at org.springframework.xd.dirt.stream.JobDeployer.deploy(JobDeployer.java:103)  at org.springframework.xd.dirt.stream.JobDeployer.deploy(JobDeployer.java:67)  at org.springframework.xd.dirt.rest.XDController.save(XDController.java:242)\"\"\"','','Bug','Major','Done','Won\'t Fix','2013-10-28 11:06:30','2013-10-28 11:06:30','2013-11-04 11:29:40','2013-11-12 15:04:19',1,NULL,7491,7491,10103,0,0,0,'',222,222,222,1,49);
INSERT INTO `Issue` VALUES (2791,51540,'XD-1015','https://jira.spring.io/rest/api/2/issue/51540','\"Create a reusable responsive UI layout to render the XD PagedResoures in tabular view\"','\"Create a reusable responsive UI layout to render the PagedResources returned from REST endpoint.   As part of this, try upgrading the bootstrap to 3.0.0 and use the responsive styles offered in it.\"','\"\"\"Create a reusable responsive UI layout to render the PagedResources returned from REST endpoint.   As part of this, try upgrading the bootstrap to 3.0.0 and use the responsive styles offered in it.\"\"\"','','Story','Minor','Done','Complete','2013-10-25 10:14:41','2013-10-25 09:14:41','2013-10-31 15:36:24','2013-11-12 15:03:58',5,NULL,9018,9018,9021,0,0,0,'',91,91,91,1,49);
