INSERT INTO `Issue` VALUES (2865,51271,'XD-937','https://jira.spring.io/rest/api/2/issue/51271','\"Inject ModuleDefinitionRepository into ModulesController\"','\"Currently, ModulesController creates the ModuleDefinitionRepository instance with ModuleRegistry. Instead, we should inject the moduleDefinitionRepository into ModulesController directly.\"','\"\"\"Currently, ModulesController creates the ModuleDefinitionRepository instance with ModuleRegistry. Instead, we should inject the moduleDefinitionRepository into ModulesController directly.\"\"\"','','Story','Minor','Done','Complete','2013-10-09 11:20:39','2013-10-09 10:20:39','2013-10-29 05:19:21','2013-11-12 15:04:17',1,NULL,8377,8377,28498,0,0,0,'',91,91,110,1,49);
INSERT INTO `Issue` VALUES (2878,51221,'XD-924','https://jira.spring.io/rest/api/2/issue/51221','\"Split integration.x in dedicated XD projects where appropriate\"','\"Similar to what is done for e.g. hadoop, reactor, and http, some of the classes in the .x package (namely gemfire, splunk, twitter) should go in dedicated (albeit small) projects. This would enable further modularization (see XD-915)\"','\"\"\"Similar to what is done for e.g. hadoop, reactor, and http, some of the classes in the .x package (namely gemfire, splunk, twitter) should go in dedicated (albeit small) projects. This would enable further modularization (see XD-915)\"\"\"','','Story','Minor','Done','Complete','2013-10-07 02:43:58','2013-10-07 01:43:58','2013-10-09 13:16:13','2013-11-12 15:04:21',3,NULL,3511,3511,3512,0,0,0,'',94,94,94,1,51);
INSERT INTO `Issue` VALUES (2880,51182,'XD-922','https://jira.spring.io/rest/api/2/issue/51182','\"Handle SingleNodeServer\'s stop()  method cleanly\"','\"SingleNode server needs to stop cleanly with stopping both the admin server & container server.   Also, all the tests that require SingleNode main server needs to handle the server shutdown appropriately.\"','\"\"\"SingleNode server needs to stop cleanly with stopping both the admin server & container server.   Also, all the tests that require SingleNode main server needs to handle the server shutdown appropriately.\"\"\"','','Story','Minor','Done','Complete','2013-10-02 23:36:21','2013-10-02 22:36:21','2013-10-03 11:43:49','2013-11-12 15:04:21',2,NULL,0,0,727,0,0,0,'',91,91,91,1,51);
INSERT INTO `Issue` VALUES (2882,51175,'XD-920','https://jira.spring.io/rest/api/2/issue/51175','\"MQTT source module does not cleanly undeploy\"','\"Was attempting to test mqtt, turns out I don\'t have the proper rabbitmq thing installed. So far so good, I get these kinds of exceptions: {noformat} Unable to connect to server (32103) - java.net.ConnectException: Connection refused  at org.eclipse.paho.client.mqttv3.internal.TCPNetworkModule.start(TCPNetworkModule.java:75)  at org.eclipse.paho.client.mqttv3.internal.ClientComms$ConnectBG.run(ClientComms.java:521)  at java.lang.Thread.run(Thread.java:724) Caused by: java.net.ConnectException: Connection refused  at java.net.PlainSocketImpl.socketConnect(Native Method)  at java.net.AbstractPlainSocketImpl.doConnect(AbstractPlainSocketImpl.java:339)  at java.net.AbstractPlainSocketImpl.connectToAddress(AbstractPlainSocketImpl.java:200)  at java.net.AbstractPlainSocketImpl.connect(AbstractPlainSocketImpl.java:182)  at java.net.SocksSocketImpl.connect(SocksSocketImpl.java:392)  at java.net.Socket.connect(Socket.java:579)  at org.eclipse.paho.client.mqttv3.internal.TCPNetworkModule.start(TCPNetworkModule.java:66)  ... 2 more {noformat}  Problem is, I still get them after undeploying my \"\"mqtt | log\"\" stream\"','\"\"\"Was attempting to test mqtt, turns out I don\'t have the proper rabbitmq thing installed. So far so good, I get these kinds of exceptions:   Problem is, I still get them after undeploying my \"\"\"\"mqtt | log\"\"\"\" stream\"\"\"','\" Unable to connect to server (32103) - java.net.ConnectException: Connection refused  at org.eclipse.paho.client.mqttv3.internal.TCPNetworkModule.start(TCPNetworkModule.java:75)  at org.eclipse.paho.client.mqttv3.internal.ClientComms$ConnectBG.run(ClientComms.java:521)  at java.lang.Thread.run(Thread.java:724) Caused by: java.net.ConnectException: Connection refused  at java.net.PlainSocketImpl.socketConnect(Native Method)  at java.net.AbstractPlainSocketImpl.doConnect(AbstractPlainSocketImpl.java:339)  at java.net.AbstractPlainSocketImpl.connectToAddress(AbstractPlainSocketImpl.java:200)  at java.net.AbstractPlainSocketImpl.connect(AbstractPlainSocketImpl.java:182)  at java.net.SocksSocketImpl.connect(SocksSocketImpl.java:392)  at java.net.Socket.connect(Socket.java:579)  at org.eclipse.paho.client.mqttv3.internal.TCPNetworkModule.start(TCPNetworkModule.java:66)  ... 2 more \"','Bug','Major','Done','Complete','2013-10-02 09:20:28','2013-10-02 08:20:28','2013-10-03 06:49:17','2013-11-12 15:04:12',2,NULL,1005,1005,1288,0,0,1,'',94,94,82,1,51);
INSERT INTO `Issue` VALUES (2887,51157,'XD-915','https://jira.spring.io/rest/api/2/issue/51157','\"Convert modules to be CP-aware\"','\"Once XD-887 is merged, gradually convert more modules.  Recipe: 1) Move the <module>.xml file to <module>/config/<module>.xml 2) Declare a :module.<type>.<module> gradle project 3) Move dependencies from dirt project to newly created module project 4) gradle build picks it up.  gradle clean build + manual test Also have a look at gradle cleanEclipse eclipse\"','\"\"\"Once XD-887 is merged, gradually convert more modules.  Recipe: 1) Move the <module>.xml file to <module>/config/<module>.xml 2) Declare a :module.<type>.<module> gradle project 3) Move dependencies from dirt project to newly created module project 4) gradle build picks it up.  gradle clean build + manual test Also have a look at gradle cleanEclipse eclipse\"\"\"','','Story','Minor','Done','Complete','2013-10-01 10:45:36','2013-10-01 09:45:36','2013-10-10 09:32:13','2013-11-12 15:04:00',8,NULL,9045,9045,12886,0,0,0,'',94,94,94,1,51);
INSERT INTO `Issue` VALUES (2892,51134,'XD-910','https://jira.spring.io/rest/api/2/issue/51134','\"Add a Processor for Restful webservices\"','\"Offers the functionality to make http request to a web service. i.e. outbound http gateway. Example implementations: stream create --name foo --definition \"\"trigger |rest --reply-timeout=1 --url=http://earthquake.usgs.gov/earthquakes/feed/geojson/all/day|log\"\"  stream create --name foos --definition \"\"trigger --payload=lat=34.0567006&lon=-84.34368810000001&site=all&smap=1&searchresult=Roswell%2C%20GA%2030076%2C%20USA#.UktzaWSG1Dd | rest --url=http://forecast.weather.gov/MapClick.php? |log\"\"  \"','\"\"\"Offers the functionality to make http request to a web service. i.e. outbound http gateway. Example implementations: stream create --name foo --definition \"\"\"\"trigger |rest --reply-timeout=1 --url=http://earthquake.usgs.gov/earthquakes/feed/geojson/all/day|log\"\"\"\"  stream create --name foos --definition \"\"\"\"trigger --payload=lat=34.0567006&lon=-84.34368810000001&site=all&smap=1&searchresult=Roswell%2C%20GA%2030076%2C%20USA#.UktzaWSG1Dd | rest --url=http://forecast.weather.gov/MapClick.php? |log\"\"\"\"  \"\"\"','','Story','Minor','Done','Complete','2013-09-30 08:26:42','2013-09-30 07:26:42','2013-10-08 09:21:42','2013-11-12 15:04:13',1,NULL,11466,11466,11574,1,0,0,'',108,108,108,1,51);
INSERT INTO `Issue` VALUES (2894,51130,'XD-908','https://jira.spring.io/rest/api/2/issue/51130','\"Add aggregate counter query by number of points\"','\"It should be possible to supply a start or end date (or none for the present), plus a \"\"count\"\" value for the number of points required (i.e. after or prior to the given time).\"','\"\"\"It should be possible to supply a start or end date (or none for the present), plus a \"\"\"\"count\"\"\"\" value for the number of points required (i.e. after or prior to the given time).\"\"\"','','Story','Minor','Done','Complete','2013-09-30 04:31:49','2013-09-30 03:31:49','2013-10-10 08:03:26','2013-11-12 15:04:14',3,NULL,0,0,14611,0,0,1,'',222,222,222,1,51);
