INSERT INTO `Issue` VALUES (2925,50995,'XD-877','https://jira.spring.io/rest/api/2/issue/50995','\"Taps do not work when JMX is enabled\"','\"When JMX is enabled, the Module\'s output channel processed by StreamPlugin is a Proxy. Thus it fails the \"\"instanceof\"\" test used to apply the WireTap to the output channel. \"','\"\"\"When JMX is enabled, the Module\'s output channel processed by StreamPlugin is a Proxy. Thus it fails the \"\"\"\"instanceof\"\"\"\" test used to apply the WireTap to the output channel. \"\"\"','','Bug','Minor','Done','Complete','2013-09-20 08:29:27','2013-09-20 07:29:27','2013-09-27 10:14:47','2013-11-12 15:03:57',3,NULL,10185,10185,10185,0,0,0,'',240,240,240,1,51);
INSERT INTO `Issue` VALUES (2927,50990,'XD-875','https://jira.spring.io/rest/api/2/issue/50990','\"Handle AdminServer shutdown cleanly\"','\"The admin Server\'s tomcat is not shutdown properly. There is an existing method shutdownCleanly() on AdminServer but the spring-xd-shell tests hang when we use this method to shutdown the admin server.  \"','\"\"\"The admin Server\'s tomcat is not shutdown properly. There is an existing method shutdownCleanly() on AdminServer but the spring-xd-shell tests hang when we use this method to shutdown the admin server.  \"\"\"','','Story','Minor','Done','Complete','2013-09-20 00:17:52','2013-09-19 23:17:52','2013-09-20 12:17:39','2013-11-12 15:04:14',2,NULL,714,714,719,0,0,0,'',91,91,91,1,51);
INSERT INTO `Issue` VALUES (2931,50966,'XD-871','https://jira.spring.io/rest/api/2/issue/50966','\"No errors in Shell when creating stream with HTTP Source + already used port \"','\"2 issues exist:  1)   Current this does not create an error in the shell  {code} stream create --name s1 --definition \"\"http | log\"\" stream create --name s2 --definition \"\"http | log\"\" {code}  On the server-side I see:  {code} Caused by: java.net.BindException: Address already in use  at sun.nio.ch.Net.bind0(Native Method)  at sun.nio.ch.Net.bind(Net.java:344)  at sun.nio.ch.Net.bind(Net.java:336)  at sun.nio.ch.ServerSocketChannelImpl.bind(ServerSocketChannelImpl.java:199)  at sun.nio.ch.ServerSocketAdaptor.bind(ServerSocketAdaptor.java:74)  at org.jboss.netty.channel.socket.nio.NioServerBoss$RegisterTask.run(NioServerBoss.java:193)  at org.jboss.netty.channel.socket.nio.AbstractNioSelector.processTaskQueue(AbstractNioSelector.java:366)  at org.jboss.netty.channel.socket.nio.AbstractNioSelector.run(AbstractNioSelector.java:290)  at org.jboss.netty.channel.socket.nio.NioServerBoss.run(NioServerBoss.java:42)  ... 3 more {code}  2) The Stream should not be saved to the StreamDefinitionRepo in case of an error.  \"','\"\"\"2 issues exist:  1)   Current this does not create an error in the shell    On the server-side I see:    2) The Stream should not be saved to the StreamDefinitionRepo in case of an error.  \"\"\"','\" stream create --name s1 --definition \"\"\"\"http | log\"\"\"\" stream create --name s2 --definition \"\"\"\"http | log\"\"\"\"  Caused by: java.net.BindException: Address already in use  at sun.nio.ch.Net.bind0(Native Method)  at sun.nio.ch.Net.bind(Net.java:344)  at sun.nio.ch.Net.bind(Net.java:336)  at sun.nio.ch.ServerSocketChannelImpl.bind(ServerSocketChannelImpl.java:199)  at sun.nio.ch.ServerSocketAdaptor.bind(ServerSocketAdaptor.java:74)  at org.jboss.netty.channel.socket.nio.NioServerBoss$RegisterTask.run(NioServerBoss.java:193)  at org.jboss.netty.channel.socket.nio.AbstractNioSelector.processTaskQueue(AbstractNioSelector.java:366)  at org.jboss.netty.channel.socket.nio.AbstractNioSelector.run(AbstractNioSelector.java:290)  at org.jboss.netty.channel.socket.nio.NioServerBoss.run(NioServerBoss.java:42)  ... 3 more \"','Bug','Minor','Done','Complete','2013-09-18 14:10:11','2013-09-18 13:10:11','2013-11-05 07:32:36','2013-11-12 15:04:19',4,NULL,32,32,68782,0,0,0,'',93,93,89,1,49);
INSERT INTO `Issue` VALUES (2932,50962,'XD-870','https://jira.spring.io/rest/api/2/issue/50962','\"Support for listing of modules in the Shell\"','\"Commands that pair up with the functionality described in XD-859  module list  (would list all modules in a table format) module list --type=source  (would list only source modules)  and so on.\"','\"\"\"Commands that pair up with the functionality described in XD-859  module list  (would list all modules in a table format) module list --type=source  (would list only source modules)  and so on.\"\"\"','','Story','Minor','Done','Complete','2013-09-18 08:57:51','2013-09-18 07:57:51','2013-10-01 13:47:12','2013-11-12 15:03:55',4,NULL,18805,18805,19009,0,0,0,'',72,72,108,1,51);
INSERT INTO `Issue` VALUES (2934,50960,'XD-868','https://jira.spring.io/rest/api/2/issue/50960','\"Create microbenchmark performance test of reactor syslog adapter vs standard syslog adapter\"','\"We need to verify that we are seeing improved throughput when using the reactor based syslog adapter.    A suggestion on a basic stream to perform a microbenchmark this would be using in-memory counters, singlenode with the stream definition \"\"syslog | counter\"\".  Based on the results of this microbenchmark, other stories may need to be created.\"','\"\"\"We need to verify that we are seeing improved throughput when using the reactor based syslog adapter.    A suggestion on a basic stream to perform a microbenchmark this would be using in-memory counters, singlenode with the stream definition \"\"\"\"syslog | counter\"\"\"\".  Based on the results of this microbenchmark, other stories may need to be created.\"\"\"','','Story','Minor','Done','Complete','2013-09-18 08:25:31','2013-09-18 07:25:31','2013-10-01 10:32:16','2013-11-12 15:04:05',4,NULL,7225,7225,18846,0,0,0,'',72,72,151,1,51);
INSERT INTO `Issue` VALUES (2936,50956,'XD-866','https://jira.spring.io/rest/api/2/issue/50956','\"Remove remaining Thread.sleeps from the job tests\"','\"Get rid of all the thread.sleeps and code that supported them.\"','\"\"\"Get rid of all the thread.sleeps and code that supported them.\"\"\"','','Story','Minor','Done','Complete','2013-09-18 07:00:17','2013-09-18 06:00:17','2013-09-24 12:49:15','2013-11-12 15:03:59',1,NULL,8988,8988,8988,0,0,0,'',108,108,108,1,51);
INSERT INTO `Issue` VALUES (2938,50946,'XD-864','https://jira.spring.io/rest/api/2/issue/50946','\"Move BatchJobExecutionsByJobName to BatchJobsController from BatchJobExecutionsController\"','\"We need to move the BatchJobExecutionsByJobName method to BatchJobsController as that seems appropriate\"','\"\"\"We need to move the BatchJobExecutionsByJobName method to BatchJobsController as that seems appropriate\"\"\"','','Story','Minor','Done','Complete','2013-09-17 14:12:00','2013-09-17 13:12:00','2013-09-23 15:50:49','2013-11-12 15:04:19',1,NULL,0,0,8738,0,0,0,'',91,91,91,1,51);
INSERT INTO `Issue` VALUES (2940,50943,'XD-862','https://jira.spring.io/rest/api/2/issue/50943','\"First class JSON Path support\"','\"Similar to xpath with XML, there are now some initial support in SI that enable the use of filter/routers based on JSON Path expressions.  That support needs to be reviewed and then brought up to the level of exposure in Spring XD so that router/filter modules could use JSON Path.  json-path-filter/router are components that need to be created, perhaps others.  This story needs to be broken down further.\"','\"\"\"Similar to xpath with XML, there are now some initial support in SI that enable the use of filter/routers based on JSON Path expressions.  That support needs to be reviewed and then brought up to the level of exposure in Spring XD so that router/filter modules could use JSON Path.  json-path-filter/router are components that need to be created, perhaps others.  This story needs to be broken down further.\"\"\"','','Story','Minor','Done','Complete','2013-09-17 10:25:20','2013-09-17 09:25:20','2013-09-20 14:43:48','2013-11-12 15:04:01',10,NULL,1148,1148,4578,0,0,0,'',72,72,110,1,51);
INSERT INTO `Issue` VALUES (2942,50940,'XD-859','https://jira.spring.io/rest/api/2/issue/50940','\"Support for listing of modules in the REST API\"','\"From the CLI, one should be able to get a listing of modules and be able to specifically ask for jobs, sources, sinks, and processors.  A brief description of them would also be nice - this might come from adding some metadata into the definition.  Finer grained description/implementation suggestion TBD\"','\"\"\"From the CLI, one should be able to get a listing of modules and be able to specifically ask for jobs, sources, sinks, and processors.  A brief description of them would also be nice - this might come from adding some metadata into the definition.  Finer grained description/implementation suggestion TBD\"\"\"','','Story','Minor','Done','Complete','2013-09-17 10:01:31','2013-09-17 09:01:31','2013-10-04 08:58:16','2013-11-12 15:03:56',8,NULL,21512,21512,24416,1,0,0,'',72,72,108,1,51);
INSERT INTO `Issue` VALUES (2943,50938,'XD-858','https://jira.spring.io/rest/api/2/issue/50938','\"Upgrade to Spring Data Redis 1.1.0.RELEASE\"','','','','Story','Minor','Done','Complete','2013-09-17 08:30:58','2013-09-17 07:30:58','2013-09-18 11:38:42','2013-11-12 15:03:57',1,NULL,0,0,1627,0,0,0,'',240,240,240,1,51);
INSERT INTO `Issue` VALUES (2944,50937,'XD-857','https://jira.spring.io/rest/api/2/issue/50937','\"Refactor FileModuleRegistry as \"\"ResourceModuleRegistry\"\"\"','\"Apart from sanity checks, there is not much that ties FileModuleRegistry to actual java.io.Files. Using the Resource abstraction would work just the same, and would allow loading modules from the classpath in constrained environments or other file systems/locations. (HDFS /HTTP)\"','\"\"\"Apart from sanity checks, there is not much that ties FileModuleRegistry to actual java.io.Files. Using the Resource abstraction would work just the same, and would allow loading modules from the classpath in constrained environments or other file systems/locations. (HDFS /HTTP)\"\"\"','','Story','Minor','Done','Complete','2013-09-17 08:14:02','2013-09-17 07:14:02','2013-11-04 07:20:54','2013-11-12 15:03:56',5,NULL,1,1,69126,0,0,1,'',94,94,94,1,49);
INSERT INTO `Issue` VALUES (2946,50933,'XD-854','https://jira.spring.io/rest/api/2/issue/50933','\"Update doc about modules and spring\"','\"The doc at http://docs.spring.io/spring-xd/docs/1.0.0.M3/reference/html/#_modules_and_spring refers to an old version of the counter sink, when it was still hardwired to use redis. The text next to it that explains placeholders is out of date (with respect to the redis placeholders)\"','\"\"\"The doc at http://docs.spring.io/spring-xd/docs/1.0.0.M3/reference/html/#_modules_and_spring refers to an old version of the counter sink, when it was still hardwired to use redis. The text next to it that explains placeholders is out of date (with respect to the redis placeholders)\"\"\"','','Story','Minor','Done','Complete','2013-09-17 07:46:03','2013-09-17 06:46:03','2013-09-19 08:47:08','2013-11-12 15:04:01',2,NULL,1177,1177,2941,0,0,0,'',94,94,240,1,51);
INSERT INTO `Issue` VALUES (2953,50900,'XD-847','https://jira.spring.io/rest/api/2/issue/50900','\"Revise the available hadoopDistro options\"','\"We should adjust our --hadoopDistro options to the ones supported in the new spring-data-hadoop 1.0.1.RELEASE - hadoop12 (default), cdh4, hdp13, phd1, hadoop20  This includes updating the wiki pages\"','\"\"\"We should adjust our --hadoopDistro options to the ones supported in the new spring-data-hadoop 1.0.1.RELEASE - hadoop12 (default), cdh4, hdp13, phd1, hadoop20  This includes updating the wiki pages\"\"\"','','Story','Minor','Done','Complete','2013-09-14 10:45:14','2013-09-14 09:45:14','2013-09-27 05:26:22','2013-11-12 15:03:57',5,NULL,12645,12645,18401,0,0,0,'',84,84,84,1,51);
INSERT INTO `Issue` VALUES (2972,50791,'XD-828','https://jira.spring.io/rest/api/2/issue/50791','\"rename Bridge to Binding and add direction\"','\"org.springframework.integration.x.bus.Bridge should now be called Binding  we can also move the INBOUND/OUTBOUND direction (or possibly the CONSUMER/PRODUCER role) into this class; that should simplify its usage in conditional code within the MessageBus code and also reduce the use of \"\"in\"\" and \"\"out\"\" as Strings in that same code\"','\"\"\"org.springframework.integration.x.bus.Bridge should now be called Binding  we can also move the INBOUND/OUTBOUND direction (or possibly the CONSUMER/PRODUCER role) into this class; that should simplify its usage in conditional code within the MessageBus code and also reduce the use of \"\"\"\"in\"\"\"\" and \"\"\"\"out\"\"\"\" as Strings in that same code\"\"\"','','Story','Minor','Done','Complete','2013-09-07 21:22:10','2013-09-07 20:22:10','2013-09-20 14:43:23','2013-11-12 15:03:55',2,NULL,3275,3275,18321,0,0,0,'',110,110,110,1,51);
INSERT INTO `Issue` VALUES (2984,50772,'XD-816','https://jira.spring.io/rest/api/2/issue/50772','\"Support for composed streams\"','\"Some recent changes caused this to be turned off. Basically the change was to police whether a stream is well formed at create time, rather than deploy time.  By deferring that check we can create composed streams that are not deployable by themselves but that are when used as building blocks in proper streams.\"','\"\"\"Some recent changes caused this to be turned off. Basically the change was to police whether a stream is well formed at create time, rather than deploy time.  By deferring that check we can create composed streams that are not deployable by themselves but that are when used as building blocks in proper streams.\"\"\"','','Story','Minor','Done','Complete','2013-09-06 12:43:41','2013-09-06 11:43:41','2013-10-09 13:13:57','2013-11-12 15:04:20',2,NULL,0,0,47550,1,0,0,'',103,103,103,1,51);
INSERT INTO `Issue` VALUES (2987,50755,'XD-813','https://jira.spring.io/rest/api/2/issue/50755','\"Destroying XD job should remove job\'s entries at batch job repositories/batch job locator\"','\"When an XD job is destroyed/deleted, the batch jobRepository entries for the job (associated JobInstances, JobExecutions etc.,) and the BatchJobLocator entries.\"','\"\"\"When an XD job is destroyed/deleted, the batch jobRepository entries for the job (associated JobInstances, JobExecutions etc.,) and the BatchJobLocator entries.\"\"\"','','Story','Minor','Done','Complete','2013-09-05 13:28:14','2013-09-05 12:28:14','2013-09-19 11:38:52','2013-11-12 15:04:00',4,NULL,19905,19905,20050,0,0,0,'',91,91,91,1,51);
INSERT INTO `Issue` VALUES (2989,50753,'XD-811','https://jira.spring.io/rest/api/2/issue/50753','\"Add REST endpoint for launching Job\"','\"We need a REST endpoint to launch a job.  Given the constraint on JobRegistry being not persistent and not available outside the container JVM, we can not use the batch job admin controller/service to launch the job.  One possible way is to use the trigger source to launch the job at XD.\"','\"\"\"We need a REST endpoint to launch a job.  Given the constraint on JobRegistry being not persistent and not available outside the container JVM, we can not use the batch job admin controller/service to launch the job.  One possible way is to use the trigger source to launch the job at XD.\"\"\"','','Story','Minor','Done','Complete','2013-09-05 11:45:57','2013-09-05 10:45:57','2013-09-21 10:34:46','2013-11-12 15:03:59',2,NULL,22968,22968,22968,0,0,0,'',91,91,91,1,51);
INSERT INTO `Issue` VALUES (3004,50686,'XD-796','https://jira.spring.io/rest/api/2/issue/50686','\"Create separate commands for \"\"--all\"\" shell commands\"','\"Commands like \"\"stream deploy\"\" have changed over time to allow passing a \"\"--all\"\" option.  So it\'s either {{stream deploy foo}} or {{stream deploy --all}}. This has a number of drawbacks, given that these are the only 2 alternatives: - Implementation code is cumbersome - None of the options can be marked mandatory, yet one of them is required. This has to be checked in the command code itself - TAB completion is less powerful as the shell doesn\'t know if we want the first or the second form.   Consider splitting those commands into two distinct commands, one as before and one literally named {{stream deploy all}}.\"','\"\"\"Commands like \"\"\"\"stream deploy\"\"\"\" have changed over time to allow passing a \"\"\"\"--all\"\"\"\" option.  So it\'s either {{stream deploy foo}} or {{stream deploy --all}}. This has a number of drawbacks, given that these are the only 2 alternatives: - Implementation code is cumbersome - None of the options can be marked mandatory, yet one of them is required. This has to be checked in the command code itself - TAB completion is less powerful as the shell doesn\'t know if we want the first or the second form.   Consider splitting those commands into two distinct commands, one as before and one literally named {{stream deploy all}}.\"\"\"','','Story','Minor','Done','Complete','2013-09-02 07:16:52','2013-09-02 06:16:52','2013-10-04 08:21:12','2013-11-12 15:04:15',5,NULL,334,334,46144,1,0,0,'',94,94,94,1,51);
INSERT INTO `Issue` VALUES (3047,50503,'XD-753','https://jira.spring.io/rest/api/2/issue/50503','\"JDBC property settings need to be made externally configurable\"','\"We need to have a properties section (documented as well) so that users can setup their jdbc connections for the various components.\"','\"\"\"We need to have a properties section (documented as well) so that users can setup their jdbc connections for the various components.\"\"\"','','Story','Critical','Done','Complete','2013-08-24 09:13:06','2013-08-24 08:13:06','2013-11-01 10:10:19','2013-11-12 15:04:17',2,NULL,13159,13159,99477,0,0,0,'',108,108,108,1,49);
