INSERT INTO `Issue` VALUES (3136,50272,'XD-663','https://jira.spring.io/rest/api/2/issue/50272','\"Use correct FS_DEFAULT_NAME_KEY constant based on Hadoop version used\"','\"Keep getting the following warning:  WARN Spring Shell conf.Configuration:817 - fs.default.name is deprecated. Instead, use fs.defaultFS  Should switch to use the runtime value of the FS_DEFAULT_NAME_KEY constant based on Hadoop version used.\"','\"\"\"Keep getting the following warning:  WARN Spring Shell conf.Configuration:817 - fs.default.name is deprecated. Instead, use fs.defaultFS  Should switch to use the runtime value of the FS_DEFAULT_NAME_KEY constant based on Hadoop version used.\"\"\"','','Story','Minor','Done','Complete','2013-08-09 17:00:00','2013-08-09 16:00:00','2013-08-11 13:07:55','2013-08-14 14:20:30',3,NULL,2647,2647,2647,0,0,0,'',84,84,84,1,55);
