INSERT INTO `Issue` VALUES (3143,50261,'XD-655','https://jira.spring.io/rest/api/2/issue/50261','\"Trim output from http post shell command to two lines\"','\"Instead of   xd:>http post --target http://localhost:9898 --data \"\"hello world\"\" > POST (text/plain;charset=UTF-8) http://localhost:9898 hello world > 200 OK > Content-Length: 0 > Connection: keep-alive >  Success sending data \'hello world\' to target \'http://localhost:9898\'   have  xd:>http post --target http://localhost:9898 --data \"\"hello world\"\" > POST (text/plain;charset=UTF-8) http://localhost:9898 hello world > 200 OK   or better yet  xd:>http post --target http://localhost:9898 --data \"\"hello world\"\" > 200 OK POST (text/plain;charset=UTF-8) http://localhost:9898 hello world       \"','\"\"\"Instead of   xd:>http post --target http://localhost:9898 --data \"\"\"\"hello world\"\"\"\" > POST (text/plain;charset=UTF-8) http://localhost:9898 hello world > 200 OK > Content-Length: 0 > Connection: keep-alive >  Success sending data \'hello world\' to target \'http://localhost:9898\'   have  xd:>http post --target http://localhost:9898 --data \"\"\"\"hello world\"\"\"\" > POST (text/plain;charset=UTF-8) http://localhost:9898 hello world > 200 OK   or better yet  xd:>http post --target http://localhost:9898 --data \"\"\"\"hello world\"\"\"\" > 200 OK POST (text/plain;charset=UTF-8) http://localhost:9898 hello world       \"\"\"','','Story','Minor','Done','Complete','2013-08-09 12:23:49','2013-08-09 11:23:49','2013-08-09 13:21:52','2013-08-14 14:20:37',1,NULL,0,0,58,0,0,0,'',72,72,89,1,55);
INSERT INTO `Issue` VALUES (3145,50258,'XD-653','https://jira.spring.io/rest/api/2/issue/50258','\"Configure Jackson ObjectMappers to Allow Single Quotes \"','\"Allow Json payloads from external sources, e.g., http post to contain single quoted field names and values. This is required where XD uses Jackson to convert payloads from Json to object or Tuples.\"','\"\"\"Allow Json payloads from external sources, e.g., http post to contain single quoted field names and values. This is required where XD uses Jackson to convert payloads from Json to object or Tuples.\"\"\"','','Story','Minor','Done','Complete','2013-08-09 10:39:48','2013-08-09 09:39:48','2013-08-09 11:07:24','2013-08-14 14:20:20',1,NULL,26,26,27,0,0,0,'',89,89,89,1,55);
