INSERT INTO `Issue` VALUES (3154,50236,'XD-644','https://jira.spring.io/rest/api/2/issue/50236','\"Connection props in rabbit.properties ignored by xd-admin and xd-container\"','\"I modified rabbit.hostname in rabbit.properties and xd-container still attempted to find Rabbit at localhost with --transport rabbit. Looks like the PPC for xd-container and xd-admin is not pointing to rabbit.properties\"','\"\"\"I modified rabbit.hostname in rabbit.properties and xd-container still attempted to find Rabbit at localhost with --transport rabbit. Looks like the PPC for xd-container and xd-admin is not pointing to rabbit.properties\"\"\"','','Bug','Minor','Done','Complete','2013-08-08 19:50:54','2013-08-08 18:50:54','2013-08-08 20:56:55','2013-08-14 14:20:36',2,NULL,64,64,66,0,0,0,'',240,240,240,1,55);
INSERT INTO `Issue` VALUES (3155,50234,'XD-643','https://jira.spring.io/rest/api/2/issue/50234','\"Map column names with underscore to camelCase style keys for JDBC sink\"','\"We need to add support for matching column names with underscores like \"\"user_name\"\" and map them to camel case style keys like \"\"userName\"\" in the JdbcMessagePayloadTransformer.\"','\"\"\"We need to add support for matching column names with underscores like \"\"\"\"user_name\"\"\"\" and map them to camel case style keys like \"\"\"\"userName\"\"\"\" in the JdbcMessagePayloadTransformer.\"\"\"','','Story','Minor','Done','Complete','2013-08-08 17:03:17','2013-08-08 16:03:17','2013-08-08 19:14:24','2014-02-11 11:39:15',3,NULL,72,72,131,0,0,0,'',84,84,84,1,55);
INSERT INTO `Issue` VALUES (3156,50233,'XD-642','https://jira.spring.io/rest/api/2/issue/50233','\"Update architecture diagram to show rabbit in addition to redis to communicate between admin and containers\"','\"Figure 1 here https://github.com/SpringSource/spring-xd/wiki/Architecture should also show Rabbit as an option, since otherwise people will think we are tied to redis.\"','\"\"\"Figure 1 here https://github.com/SpringSource/spring-xd/wiki/Architecture should also show Rabbit as an option, since otherwise people will think we are tied to redis.\"\"\"','','Story','Minor','Done','Complete','2013-08-08 16:29:55','2013-08-08 15:29:55','2013-08-08 19:14:04','2013-08-14 14:19:58',1,NULL,0,0,164,0,0,0,'',72,72,72,1,55);
INSERT INTO `Issue` VALUES (3158,50230,'XD-640','https://jira.spring.io/rest/api/2/issue/50230','\"Cannot start xd-container with the --hadoopDistro option\"','\"Trying to use xd-container with PHD, and therefore need to start with --hadoopDistro. I get the following error:  $ bin/xd-container --hadoopDistro phd1 17:11:20,305 ERROR main server.ContainerMain:59 - \"\"--hadoopDistro\"\" is not a valid option \"','\"\"\"Trying to use xd-container with PHD, and therefore need to start with --hadoopDistro. I get the following error:  $ bin/xd-container --hadoopDistro phd1 17:11:20,305 ERROR main server.ContainerMain:59 - \"\"\"\"--hadoopDistro\"\"\"\" is not a valid option \"\"\"','','Bug','Minor','Done','Complete','2013-08-08 15:12:18','2013-08-08 14:12:18','2013-08-08 18:02:44','2013-08-14 14:20:06',3,NULL,152,152,170,0,0,0,'',240,240,84,1,55);
