INSERT INTO `Issue` VALUES (3164,50216,'XD-634','https://jira.spring.io/rest/api/2/issue/50216','\"Fix guava dependency for hadoop20 and phd1 \"','\"Spring Xd currently ships with Guava 12.0 while Hadoop 2.0.5 and Pivotal HD 1.0 depends on 11.0.2 - this could lead to classpath problems if we include both.\"','\"\"\"Spring Xd currently ships with Guava 12.0 while Hadoop 2.0.5 and Pivotal HD 1.0 depends on 11.0.2 - this could lead to classpath problems if we include both.\"\"\"','','Story','Minor','Done','Complete','2013-08-08 09:34:47','2013-08-08 08:34:47','2013-08-08 18:58:08','2013-08-14 14:20:32',3,NULL,490,490,563,0,0,0,'',84,84,84,1,55);
