INSERT INTO `Issue` VALUES (3166,50212,'XD-632','https://jira.spring.io/rest/api/2/issue/50212','\"Shell: HTTP Post - Allow posting of local file contents\"','\"E.g. allow for posting of JSON data stored in local files.  * Allow users to specify the *content-type*. * Ensure that Unicode data (UTF) posts correctly.\"','\"\"\"E.g. allow for posting of JSON data stored in local files.  * Allow users to specify the *content-type*. * Ensure that Unicode data (UTF) posts correctly.\"\"\"','','Story','Minor','Done','Complete','2013-08-08 07:23:59','2013-08-08 06:23:59','2013-08-09 12:02:08','2013-08-14 14:20:23',4,NULL,399,399,1718,0,0,0,'',93,93,94,1,55);
INSERT INTO `Issue` VALUES (3172,50198,'XD-626','https://jira.spring.io/rest/api/2/issue/50198','\"Shell: RestTemplate not posting using UTF-8 \"','\"The *http post* command uses the default MediaType by the RestTemplate, which in return triggers the default *StringHttpMessageConverter* which itself uses the default charset *ISO-8859-1*.  This creates issues when posting special characters.\"','\"\"\"The *http post* command uses the default MediaType by the RestTemplate, which in return triggers the default *StringHttpMessageConverter* which itself uses the default charset *ISO-8859-1*.  This creates issues when posting special characters.\"\"\"','','Bug','Minor','Done','Complete','2013-08-07 13:54:03','2013-08-07 12:54:03','2013-08-08 06:20:34','2013-08-14 14:20:09',1,NULL,12,12,986,1,0,0,'',93,93,93,1,55);
