INSERT INTO `Issue` VALUES (3184,50174,'XD-614','https://jira.spring.io/rest/api/2/issue/50174','\"Conversion Enhancements\"','\"Content-Type during transport transit is not the same as the content-type within modules.  \"\"Real\"\" transports always use byte[] which may contain raw byte[] from a source, a byte[] converted from a String (which may or may not already contain JSON), or a byte[] containing JSON converted by the transport on the outbound side.  The transport needs to convey which of these was applied on the outbound side so it can properly reconstruct the message.  Retain any content-type header that already exists in the message, and restore it.  For Rabbit, use normal SI/Rabbit headers to convey this information.  For Redis, add the information to the byte[].\"','\"\"\"Content-Type during transport transit is not the same as the content-type within modules.  \"\"\"\"Real\"\"\"\" transports always use byte[] which may contain raw byte[] from a source, a byte[] converted from a String (which may or may not already contain JSON), or a byte[] containing JSON converted by the transport on the outbound side.  The transport needs to convey which of these was applied on the outbound side so it can properly reconstruct the message.  Retain any content-type header that already exists in the message, and restore it.  For Rabbit, use normal SI/Rabbit headers to convey this information.  For Redis, add the information to the byte[].\"\"\"','','Story','Minor','Done','Complete','2013-08-06 12:14:45','2013-08-06 11:14:45','2013-08-07 16:10:30','2013-08-14 14:20:15',8,NULL,1675,1675,1675,0,0,0,'',82,82,82,1,55);
