INSERT INTO `Issue` VALUES (3194,50142,'XD-603','https://jira.spring.io/rest/api/2/issue/50142','\"NPE on stream destroy\"','\"xd:>stream create ticktock --definition \"\"time | log\"\" --deploy true 18:45:13,310  WARN Spring Shell client.RestTemplate:524 - POST request for \"\"http://localhost:8080/streams\"\" resulted in 400 (Bad Request); invoking error handler Command failed org.springframework.xd.rest.client.impl.SpringXDException: There is already a stream named \'ticktock\'  xd:>stream destroy ticktock 18:45:16,505  WARN Spring Shell client.RestTemplate:524 - DELETE request for \"\"http://localhost:8080/streams/ticktock\"\" resulted in 500 (Internal Server Error); invoking error handler Command failed org.springframework.xd.rest.client.impl.SpringXDException: java.lang.NullPointerException   Caused by: java.lang.NullPointerException  at org.springframework.xd.dirt.module.ModuleDeployer.undeploy(ModuleDeployer.java:143)  at org.springframework.xd.dirt.module.ModuleDeployer.handleMessageInternal(ModuleDeployer.java:97)   \"','\"\"\"xd:>stream create ticktock --definition \"\"\"\"time | log\"\"\"\" --deploy true 18:45:13,310  WARN Spring Shell client.RestTemplate:524 - POST request for \"\"\"\"http://localhost:8080/streams\"\"\"\" resulted in 400 (Bad Request); invoking error handler Command failed org.springframework.xd.rest.client.impl.SpringXDException: There is already a stream named \'ticktock\'  xd:>stream destroy ticktock 18:45:16,505  WARN Spring Shell client.RestTemplate:524 - DELETE request for \"\"\"\"http://localhost:8080/streams/ticktock\"\"\"\" resulted in 500 (Internal Server Error); invoking error handler Command failed org.springframework.xd.rest.client.impl.SpringXDException: java.lang.NullPointerException   Caused by: java.lang.NullPointerException  at org.springframework.xd.dirt.module.ModuleDeployer.undeploy(ModuleDeployer.java:143)  at org.springframework.xd.dirt.module.ModuleDeployer.handleMessageInternal(ModuleDeployer.java:97)   \"\"\"','','Bug','Minor','Done','Complete','2013-08-05 16:48:37','2013-08-05 15:48:37','2013-08-06 10:08:10','2013-08-14 14:20:19',2,NULL,81,81,1039,0,0,0,'',89,89,82,1,55);
INSERT INTO `Issue` VALUES (3198,50133,'XD-599','https://jira.spring.io/rest/api/2/issue/50133','\"Gradle Import Broken by Hadoop Pseudo Projects\"','\"When importing Spring-XD as a gradle project, in STS, while building the model, we get  Root exception: java.lang.IllegalArgumentException: Project location doesn\'t exist:  .../spring-xd/spring-xd-hadoop/hadoop11  ./gradlew eclipse creates these directories, but the plugin needs them before running that task  The problem seems to be that these \"\"projects\"\" are not really projects.  Perhaps a quick fix would be to commit these directories (with a dummy file) ??\"','\"\"\"When importing Spring-XD as a gradle project, in STS, while building the model, we get  Root exception: java.lang.IllegalArgumentException: Project location doesn\'t exist:  .../spring-xd/spring-xd-hadoop/hadoop11  ./gradlew eclipse creates these directories, but the plugin needs them before running that task  The problem seems to be that these \"\"\"\"projects\"\"\"\" are not really projects.  Perhaps a quick fix would be to commit these directories (with a dummy file) ??\"\"\"','','Bug','Minor','Done','Complete','2013-08-05 08:46:18','2013-08-05 07:46:18','2013-08-08 12:48:11','2014-02-20 07:24:50',1,NULL,121,121,4561,0,0,0,'',82,82,84,1,55);
