INSERT INTO `Issue` VALUES (3203,50106,'XD-594','https://jira.spring.io/rest/api/2/issue/50106','\"Create list/delete commands for all the metrics\"','\"We need to add list/delete commands for the metrics:  InMemoryAggregateCounter FieldValueCounter Gauge RichGauge  Currently, the AbstractMetricsController class has the delete method to delete the metric from the repository. We can probably use the same for all the metrics.\"','\"\"\"We need to add list/delete commands for the metrics:  InMemoryAggregateCounter FieldValueCounter Gauge RichGauge  Currently, the AbstractMetricsController class has the delete method to delete the metric from the repository. We can probably use the same for all the metrics.\"\"\"','','Story','Minor','Done','Complete','2013-08-02 10:54:57','2013-08-02 09:54:57','2013-08-05 06:42:56','2013-08-14 14:19:58',2,NULL,4000,4000,4067,1,0,0,'',91,91,91,1,55);
