INSERT INTO `Issue` VALUES (3576,48997,'XD-207','https://jira.spring.io/rest/api/2/issue/48997','\"Provide configurable properties for hdfs sink.\"','\"The config file modules/sink/hdfs.xml has a hardcoded value to locate the namenode.   <hdp:configuration register-url-handler=\"\"false\"\">   fs.default.name=hdfs://localhost:9000  </hdp:configuration>  the fs.default.name proprety should be configurable and we should also support loading an external configuration file using      <hdp:configuration properties-location=\"\"${xd.home}/config/hadoop.properties\"\">     </hdp:configuration>  \"','\"\"\"The config file modules/sink/hdfs.xml has a hardcoded value to locate the namenode.   <hdp:configuration register-url-handler=\"\"\"\"false\"\"\"\">   fs.default.name=hdfs://localhost:9000  </hdp:configuration>  the fs.default.name proprety should be configurable and we should also support loading an external configuration file using      <hdp:configuration properties-location=\"\"\"\"${xd.home}/config/hadoop.properties\"\"\"\">     </hdp:configuration>  \"\"\"','','Story','Minor','Done','Complete','2013-06-06 17:17:09','2013-06-06 16:17:09','2013-06-10 08:45:49','2013-06-11 23:46:19',2,NULL,49,49,5248,0,0,0,'',72,72,110,1,61);
INSERT INTO `Issue` VALUES (3577,48996,'XD-206','https://jira.spring.io/rest/api/2/issue/48996','\"XD AdminMain & ContainerMain should check xd.home property from scripts\"','\"Currently, the system property xd.home is set as JVM_OPTS (via SPRING_XD_ADMIN_OPTS) into xd-admin & xd-container scripts.  Inside the ContainerMain & AdminMain, we need to check if this system property is set and use it. It seems like, this check is missing now.\"','\"\"\"Currently, the system property xd.home is set as JVM_OPTS (via SPRING_XD_ADMIN_OPTS) into xd-admin & xd-container scripts.  Inside the ContainerMain & AdminMain, we need to check if this system property is set and use it. It seems like, this check is missing now.\"\"\"','','Bug','Minor','Done','Complete','2013-06-06 16:37:00','2013-06-06 15:37:00','2013-06-07 15:44:16','2013-06-11 23:46:12',1,NULL,1310,1310,1387,1,0,0,'',91,91,91,1,61);
