INSERT INTO `Issue` VALUES (3583,48987,'XD-200','https://jira.spring.io/rest/api/2/issue/48987','\"Creating a tap throws an exception\"','\"Creating a tap throws an exception. In local mode: Cannot resolve reference to bean \'redisConnectionFactory\' while setting constructor argument; nested exception is org.springframework.beans.factory.NoSuchBeanDefinitionException: No bean named \'redisConnectionFactory\' is defined  But also fails when using redis. \"','\"\"\"Creating a tap throws an exception. In local mode: Cannot resolve reference to bean \'redisConnectionFactory\' while setting constructor argument; nested exception is org.springframework.beans.factory.NoSuchBeanDefinitionException: No bean named \'redisConnectionFactory\' is defined  But also fails when using redis. \"\"\"','','Bug','Critical','Done','Complete','2013-06-06 10:40:50','2013-06-06 09:40:50','2013-06-07 08:40:40','2013-06-11 23:46:11',4,NULL,1314,1314,1319,0,0,0,'',89,89,89,1,61);
INSERT INTO `Issue` VALUES (3584,48986,'XD-199','https://jira.spring.io/rest/api/2/issue/48986','\"Ensure the DELETE Operation can Delete a Tap\"','\"While deleting a stream doesn\'t remove any taps right now, we should be able to explicitly delete a tap.  Determine whether the current DELETE works and, if not, make it so.\"','\"\"\"While deleting a stream doesn\'t remove any taps right now, we should be able to explicitly delete a tap.  Determine whether the current DELETE works and, if not, make it so.\"\"\"','','Bug','Minor','Done','Complete','2013-06-06 09:23:17','2013-06-06 08:23:17','2013-06-08 16:30:21','2013-06-11 23:46:18',3,NULL,1710,1710,3307,0,0,0,'',82,82,82,1,61);
INSERT INTO `Issue` VALUES (3586,48977,'XD-197','https://jira.spring.io/rest/api/2/issue/48977','\"Create a scriptProcessor module that allows the execution of a groovy (potentially jruby,jython) based SI Service Activator\"','\"This will enable arbitrary processing logic to be used in a processing step.  See http://blog.springsource.org/2011/12/08/spring-integration-scripting-support-part-1/  <int:service-activator ...>   <script:script lang=\"\"groovy\"\" location=\"\"file:scripts/groovy/myscript.groovy\"\"> </int:service-activator>  would be the essence of the module.  Probably \'lang\' gets detected from the file extension.\"','\"\"\"This will enable arbitrary processing logic to be used in a processing step.  See http://blog.springsource.org/2011/12/08/spring-integration-scripting-support-part-1/  <int:service-activator ...>   <script:script lang=\"\"\"\"groovy\"\"\"\" location=\"\"\"\"file:scripts/groovy/myscript.groovy\"\"\"\"> </int:service-activator>  would be the essence of the module.  Probably \'lang\' gets detected from the file extension.\"\"\"','','Story','Minor','Done','Complete','2013-06-06 06:26:25','2013-06-06 05:26:25','2013-06-07 15:15:12','2013-06-11 23:46:11',4,NULL,1659,1659,1968,0,0,0,'',72,72,240,1,61);
INSERT INTO `Issue` VALUES (3587,48972,'XD-196','https://jira.spring.io/rest/api/2/issue/48972','\"replace the hacky parser with a good one\"','\"Replace the existing DSL parser that uses string indexing with a more robust one based on a derivative of SpEL.  This will provide a stable base on which to quickly iterate on syntax. \"','\"\"\"Replace the existing DSL parser that uses string indexing with a more robust one based on a derivative of SpEL.  This will provide a stable base on which to quickly iterate on syntax. \"\"\"','','Story','Minor','Done','Complete','2013-06-05 18:31:35','2013-06-05 17:31:35','2013-06-07 11:41:19','2013-06-11 23:46:05',4,NULL,115,115,2469,0,0,0,'',103,103,103,1,61);
INSERT INTO `Issue` VALUES (3588,48970,'XD-195','https://jira.spring.io/rest/api/2/issue/48970','\"The {{time}} Source Should Emit String by Default\"','\"When running in local mode (no Redis) {{time | tcp}} no longer works.  Change the {{time}} source to emit the date as a String, while allowing an option to emit a {{Date}} object.\"','\"\"\"When running in local mode (no Redis) {{time | tcp}} no longer works.  Change the {{time}} source to emit the date as a String, while allowing an option to emit a {{Date}} object.\"\"\"','','Story','Minor','Done','Complete','2013-06-05 13:05:45','2013-06-05 12:05:45','2013-06-05 15:25:14','2013-06-11 23:46:11',1,NULL,139,139,139,0,0,0,'',82,82,82,1,61);
INSERT INTO `Issue` VALUES (3590,48962,'XD-193','https://jira.spring.io/rest/api/2/issue/48962','\"Need more unique resource locations for XD internal configuration\"','\"Currently internal config files are in META-INF/spring with fairly generic names. To avoid potential collisions if users add their own configuration in the classpath, we should have a more unique location, e.g. META-INF/spring/xd\"','\"\"\"Currently internal config files are in META-INF/spring with fairly generic names. To avoid potential collisions if users add their own configuration in the classpath, we should have a more unique location, e.g. META-INF/spring/xd\"\"\"','','Story','Minor','Done','Complete','2013-06-05 05:55:48','2013-06-05 04:55:48','2013-06-10 04:00:34','2013-06-11 23:46:15',3,NULL,5766,5766,7084,0,0,0,'',89,89,94,1,61);
INSERT INTO `Issue` VALUES (3591,48955,'XD-192','https://jira.spring.io/rest/api/2/issue/48955','\"Update getting started documentation to use xd-singlenode start script.\"','\"With the new option of starting without requiring redis, the getting started documentation should reflect this easier way to start processing data.\"','\"\"\"With the new option of starting without requiring redis, the getting started documentation should reflect this easier way to start processing data.\"\"\"','','Story','Minor','Done','Complete','2013-06-04 20:18:58','2013-06-04 19:18:58','2013-06-07 08:42:35','2013-06-11 23:46:09',2,NULL,0,0,3623,0,0,0,'',72,72,222,1,61);
INSERT INTO `Issue` VALUES (3595,48938,'XD-188','https://jira.spring.io/rest/api/2/issue/48938','\"Add  directory to classpath in server startup scripts so groovy based processors can be easily referenced by name without a resource uri prefix\"','\"a stream such as time | filter --script=oddMinuteFilter.groovy | file   would load the groovy script \'oddMinuteFilter.groovy\' that is located in the directory modules/processor or perhaps in modules/processor/scripts.  Not sure the benefit of having a subdirectory below processor just for scripts.\"','\"\"\"a stream such as time | filter --script=oddMinuteFilter.groovy | file   would load the groovy script \'oddMinuteFilter.groovy\' that is located in the directory modules/processor or perhaps in modules/processor/scripts.  Not sure the benefit of having a subdirectory below processor just for scripts.\"\"\"','','Story','Minor','Done','Complete','2013-06-03 21:07:58','2013-06-03 20:07:58','2013-06-04 13:42:06','2013-06-11 23:46:16',1,NULL,74,74,994,0,0,0,'',72,72,240,1,61);
