INSERT INTO `Issue` VALUES (20146,12933989,'MESOS-4506','https://issues.apache.org/jira/rest/api/2/issue/12933989','\"Posix disk isolator should ignore disk quota enforcement for MOUNT type disk resources.\"','\"We assume MOUNT type disk is exclusive and the underlying filesystem will enforce the quota (i.e., the application won\'t be able to exceed the quota, and will get a write error it the disk is full).  Therefore, there\'s no need to enforce it\'s quota in posix disk isolator.\"','\"\"\"We assume MOUNT type disk is exclusive and the underlying filesystem will enforce the quota (i.e., the application won\'t be able to exceed the quota, and will get a write error it the disk is full).  Therefore, there\'s no need to enforce it\'s quota in posix disk isolator.\"\"\"','','Task','Major','Resolved','Fixed','2016-01-26 00:09:59','2016-01-26 00:09:59','2018-11-26 12:20:38','2018-11-26 12:20:38',2,NULL,0,0,1491130,0,0,1,NULL,3415,3415,3415,4,426);
INSERT INTO `Issue` VALUES (20147,12933983,'MESOS-4505','https://issues.apache.org/jira/rest/api/2/issue/12933983','\"Hierarchical allocator performance is slow due to Quota\"','\"Since we do not strip the non-scalar resources during the resource arithmetic for quota, the performance can degrade significantly, as currently resource arithmetic is expensive.  One approach to resolving this is to filter the resources we use to perform this arithmetic to only use scalars. This is valid as quota can currently only be set for scalar resource types.\"','\"\"\"Since we do not strip the non-scalar resources during the resource arithmetic for quota, the performance can degrade significantly, as currently resource arithmetic is expensive.  One approach to resolving this is to filter the resources we use to perform this arithmetic to only use scalars. This is valid as quota can currently only be set for scalar resource types.\"\"\"','','Improvement','Blocker','Resolved','Fixed','2016-01-25 23:50:53','2016-01-25 23:50:53','2018-11-26 12:22:11','2018-11-26 12:22:11',3,NULL,1706,1707,1491151,0,0,0,NULL,3647,3647,3647,4,426);
INSERT INTO `Issue` VALUES (20152,12933879,'MESOS-4500','https://issues.apache.org/jira/rest/api/2/issue/12933879','\"Expose ExecutorInfo and TaskInfo for isolators.\"','\"Currently we do not have these info for isolator. Image once we have docker runtime isolator, CommandInfo is necessary to support either custom executor or command executor. \"','\"\"\"Currently we do not have these info for isolator. Image once we have docker runtime isolator, CommandInfo is necessary to support either custom executor or command executor. \"\"\"','','Bug','Major','Resolved','Fixed','2016-01-25 17:19:20','2016-01-25 17:19:20','2018-11-26 12:21:05','2018-11-26 12:21:05',2,NULL,1,1,1491541,0,0,0,NULL,3406,3406,3406,4,426);
INSERT INTO `Issue` VALUES (20153,12933873,'MESOS-4499','https://issues.apache.org/jira/rest/api/2/issue/12933873','\"Docker provisioner store should reuse existing layers in the cache.\"','\"Currently, the docker provisioner store will download all the layers associated with an image if the image is not found locally, even though some layers of it might already exist in the cache.  This is problematic because anytime a user deploys a new image, Mesos will fetch all layers of that new image, even though most of the layers are already cached locally.  \"','\"\"\"Currently, the docker provisioner store will download all the layers associated with an image if the image is not found locally, even though some layers of it might already exist in the cache.  This is problematic because anytime a user deploys a new image, Mesos will fetch all layers of that new image, even though most of the layers are already cached locally.  \"\"\"','','Bug','Major','Resolved','Fixed','2016-01-25 17:04:41','2016-01-25 17:04:41','2018-11-26 12:21:07','2018-11-26 12:21:07',5,NULL,36463,40812,1491556,0,0,0,NULL,3415,3415,3415,4,426);
