INSERT INTO `Issue` VALUES (20241,12931609,'MESOS-4411','https://issues.apache.org/jira/rest/api/2/issue/12931609','\"Traverse all roles for quota allocation.\"','\"There might be a bug in how resources are allocated to multiple quota\'ed roles if one role\'s quota is met. We need to investigate this behavior.\"','\"\"\"There might be a bug in how resources are allocated to multiple quota\'ed roles if one role\'s quota is met. We need to investigate this behavior.\"\"\"','','Bug','Blocker','Resolved','Fixed','2016-01-15 23:43:54','2016-01-15 23:43:54','2018-11-26 12:22:54','2018-11-26 12:22:54',3,NULL,0,0,1505558,1,0,0,NULL,3426,3426,3737,4,426);
INSERT INTO `Issue` VALUES (20242,12931607,'MESOS-4410','https://issues.apache.org/jira/rest/api/2/issue/12931607','\"Introduce protobuf for quota set request.\"','\"To document quota request JSON schema and simplify request processing, introduce a {{QuotaRequest}} protobuf wrapper.\"','\"\"\"To document quota request JSON schema and simplify request processing, introduce a {{QuotaRequest}} protobuf wrapper.\"\"\"','','Improvement','Blocker','Resolved','Fixed','2016-01-15 23:34:29','2016-01-15 23:34:29','2018-11-26 12:22:33','2018-11-26 12:22:33',3,NULL,2,4275,1505568,0,0,0,NULL,3426,3426,3426,4,426);
INSERT INTO `Issue` VALUES (20249,12931542,'MESOS-4403','https://issues.apache.org/jira/rest/api/2/issue/12931542','\"Check paths in DiskInfo.Source.Path exist during slave initialization.\"','\"We have two options here. We can either check and fail if it does not exists. Or we can create if it does not exist like we did for slave.work_dir.\"','\"\"\"We have two options here. We can either check and fail if it does not exists. Or we can create if it does not exist like we did for slave.work_dir.\"\"\"','','Task','Major','Resolved','Fixed','2016-01-15 18:50:58','2016-01-15 18:50:58','2018-11-26 12:21:39','2018-11-26 12:21:39',2,NULL,0,0,1505850,0,0,0,NULL,3415,3415,3647,4,426);
INSERT INTO `Issue` VALUES (20250,12931538,'MESOS-4402','https://issues.apache.org/jira/rest/api/2/issue/12931538','\"Update filesystem isolators to look for persistent volume directories from the correct location.\"','\"This is related to MESOS-4400.  Since persistent volume directories can be created from non root disk now. We need to adjust both posix and linux filesystem isolator to look for volumes from the correct location based on the information in DiskInfo.Source.  See relevant code in: {code} Future<Nothing> PosixFilesystemIsolatorProcess::update(..); Future<Nothing> LinuxFilesystemIsolatorProcess::update(..); {code}\"','\"\"\"This is related to MESOS-4400.  Since persistent volume directories can be created from non root disk now. We need to adjust both posix and linux filesystem isolator to look for volumes from the correct location based on the information in DiskInfo.Source.  See relevant code in: \"\"\"','\" Future<Nothing> PosixFilesystemIsolatorProcess::update(..); Future<Nothing> LinuxFilesystemIsolatorProcess::update(..); \"','Task','Major','Resolved','Fixed','2016-01-15 18:40:25','2016-01-15 18:40:25','2018-11-26 12:22:22','2018-11-26 12:22:22',2,NULL,0,0,1505861,0,0,0,NULL,3415,3415,3647,4,426);
INSERT INTO `Issue` VALUES (20255,12931523,'MESOS-4397','https://issues.apache.org/jira/rest/api/2/issue/12931523','\"Rename ContainerPrepareInfo to ContainerLaunchInfo for isolators.\"','\"The name \"\"ContainerPrepareInfo\"\" does not really capture the purpose of this struct. ContainerLaunchInfo better captures the purpose of this struct. ContainerLaunchInfo is returned by the isolator \'prepare\' function. It contains information about how a container should be launched (e.g., environment variables, namespaces, commands, etc.). The information will be used by the Mesos Containerizer when launching the container.\"','\"\"\"The name \"\"\"\"ContainerPrepareInfo\"\"\"\" does not really capture the purpose of this struct. ContainerLaunchInfo better captures the purpose of this struct. ContainerLaunchInfo is returned by the isolator \'prepare\' function. It contains information about how a container should be launched (e.g., environment variables, namespaces, commands, etc.). The information will be used by the Mesos Containerizer when launching the container.\"\"\"','','Task','Major','Resolved','Fixed','2016-01-15 17:32:23','2016-01-15 17:32:23','2016-01-15 17:33:29','2016-01-15 18:11:30',2,NULL,0,0,1,0,0,0,NULL,3415,3415,3406,4,427);
INSERT INTO `Issue` VALUES (20270,12930252,'MESOS-4382','https://issues.apache.org/jira/rest/api/2/issue/12930252','\"Change the `principal` in `ReservationInfo` to optional\"','\"With the addition of HTTP endpoints for {{/reserve}} and {{/unreserve}}, it is now desirable to allow dynamic reservations without a principal, in the case where HTTP authentication is disabled. To allow for this, we will change the {{principal}} field in {{ReservationInfo}} from required to optional. For backwards-compatibility, however, the master should currently invalidate any {{ReservationInfo}} messages that do not have this field set.\"','\"\"\"With the addition of HTTP endpoints for {{/reserve}} and {{/unreserve}}, it is now desirable to allow dynamic reservations without a principal, in the case where HTTP authentication is disabled. To allow for this, we will change the {{principal}} field in {{ReservationInfo}} from required to optional. For backwards-compatibility, however, the master should currently invalidate any {{ReservationInfo}} messages that do not have this field set.\"\"\"','','Improvement','Major','Resolved','Fixed','2016-01-14 20:48:07','2016-01-14 20:48:07','2018-11-26 12:20:54','2018-11-26 12:20:54',1,NULL,6833,6978,1507172,0,0,1,NULL,3361,3361,3361,4,427);
