INSERT INTO `Issue` VALUES (20303,12929597,'MESOS-4349','https://issues.apache.org/jira/rest/api/2/issue/12929597','\"GMock warning in SlaveTest.ContainerUpdatedBeforeTaskReachesExecutor\"','\"{noformat} [ RUN      ] SlaveTest.ContainerUpdatedBeforeTaskReachesExecutor  GMOCK WARNING: Uninteresting mock function call - returning directly.     Function call: shutdown(0x7fe189cae850) Stack trace: [       OK ] SlaveTest.ContainerUpdatedBeforeTaskReachesExecutor (51 ms) {noformat}  Occurs non-deterministically for me on OSX 10.10, perhaps one run in ten.\"','\"\"\"  Occurs non-deterministically for me on OSX 10.10, perhaps one run in ten.\"\"\"','\" [ RUN      ] SlaveTest.ContainerUpdatedBeforeTaskReachesExecutor  GMOCK WARNING: Uninteresting mock function call - returning directly.     Function call: shutdown(0x7fe189cae850) Stack trace: [       OK ] SlaveTest.ContainerUpdatedBeforeTaskReachesExecutor (51 ms) \"','Bug','Major','Resolved','Fixed','2016-01-12 21:16:31','2016-01-12 21:16:31','2018-11-26 12:20:31','2018-11-26 12:20:31',1,NULL,0,0,1510023,0,0,0,NULL,3662,3662,3662,4,427);
