INSERT INTO `Issue` VALUES (20305,12929595,'MESOS-4347','https://issues.apache.org/jira/rest/api/2/issue/12929595','\"GMock warning in ReservationTest.ACLMultipleOperations\"','\"{noformat} [ RUN      ] ReservationTest.ACLMultipleOperations  GMOCK WARNING: Uninteresting mock function call - returning directly.     Function call: shutdown(0x7fa2a311b300) Stack trace: [       OK ] ReservationTest.ACLMultipleOperations (174 ms) [----------] 1 test from ReservationTest (174 ms total) {noformat}  Seems to occur non-deterministically for me, maybe once per 50 runs or so. OSX 10.10\"','\"\"\"  Seems to occur non-deterministically for me, maybe once per 50 runs or so. OSX 10.10\"\"\"','\" [ RUN      ] ReservationTest.ACLMultipleOperations  GMOCK WARNING: Uninteresting mock function call - returning directly.     Function call: shutdown(0x7fa2a311b300) Stack trace: [       OK ] ReservationTest.ACLMultipleOperations (174 ms) [----------] 1 test from ReservationTest (174 ms total) \"','Bug','Minor','Resolved','Fixed','2016-01-12 21:08:11','2016-01-12 21:08:11','2018-11-26 12:22:41','2018-11-26 12:22:41',1,NULL,63,85,1510034,0,0,0,NULL,3662,3662,3361,4,427);
