INSERT INTO `Issue` VALUES (20438,12923363,'MESOS-4214','https://issues.apache.org/jira/rest/api/2/issue/12923363','\"Introduce HTTP endpoint /weights for updating weight\"','','','','Task','Major','Resolved','Fixed','2015-12-21 08:15:09','2015-12-21 08:15:09','2016-03-14 11:23:52','2016-05-31 03:11:46',5,NULL,214,214,121148,0,0,0,NULL,3960,3960,3960,4,427);
INSERT INTO `Issue` VALUES (20443,12923245,'MESOS-4209','https://issues.apache.org/jira/rest/api/2/issue/12923245','\"Document \"\"how to program with dynamic reservations and persistent volumes\"\"\"','\"Specifically, some of the gotchas around:  * Retrying reservation attempts after a timeout * Fuzzy-matching resources to determine whether a reservation/PV is successful * Represent client state as a state machine and repeatedly move \"\"toward\"\" successful terminate stats  Should also point to persistent volume example framework. We should also ask Gabriel and others (Arango?) who have built frameworks with PVs/DRs for feedback.\"','\"\"\"Specifically, some of the gotchas around:  * Retrying reservation attempts after a timeout * Fuzzy-matching resources to determine whether a reservation/PV is successful * Represent client state as a state machine and repeatedly move \"\"\"\"toward\"\"\"\" successful terminate stats  Should also point to persistent volume example framework. We should also ask Gabriel and others (Arango?) who have built frameworks with PVs/DRs for feedback.\"\"\"','','Documentation','Major','Resolved','Fixed','2015-12-19 18:48:32','2015-12-19 18:48:32','2018-11-26 12:22:31','2018-11-26 12:22:31',3,NULL,0,1692,1544733,0,0,0,NULL,3662,3662,3662,4,427);
