INSERT INTO `Issue` VALUES (21533,12846615,'MESOS-3116','https://issues.apache.org/jira/rest/api/2/issue/12846615','\"Pass ExecutorInfo argument into Isolator::isolate().\"','\"Some isolators need to lookup the executor environment variables to customize their isolation needs. Currently, one has to use the \"\"prepare()\"\" call to cache the executor-info to use it later during isolate() call.\"','\"\"\"Some isolators need to lookup the executor environment variables to customize their isolation needs. Currently, one has to use the \"\"\"\"prepare()\"\"\"\" call to cache the executor-info to use it later during isolate() call.\"\"\"','','Task','Major','Resolved','Won\'t Fix','2015-07-21 18:45:41','2015-07-21 17:45:41','2018-11-26 12:32:52','2018-11-26 12:32:52',2,NULL,0,14456,1762247,0,0,0,NULL,3491,3491,3491,4,444);
