INSERT INTO `Issue` VALUES (21573,12845968,'MESOS-3076','https://issues.apache.org/jira/rest/api/2/issue/12845968','\"Add Labels to TaskStatus and expose them via state.json\"','\"This would allow the executors and Slave modules to expose some meta-data to frameworks and Mesos-DNS via state.json.  A typical use case is to allow the containers to expose their IP to framework/Mesos-DNS.\"','\"\"\"This would allow the executors and Slave modules to expose some meta-data to frameworks and Mesos-DNS via state.json.  A typical use case is to allow the containers to expose their IP to framework/Mesos-DNS.\"\"\"','','Task','Critical','Resolved','Fixed','2015-07-17 20:54:51','2015-07-17 19:54:51','2018-11-26 12:21:04','2018-11-26 12:21:04',2,NULL,4,4,1767866,0,0,0,NULL,3491,3491,3491,4,444);
INSERT INTO `Issue` VALUES (21575,12845903,'MESOS-3074','https://issues.apache.org/jira/rest/api/2/issue/12845903','\"Add capacity heuristic for quota requests in Master\"','\"We need to to validate quota requests in the Mesos Master as outlined in the Design Doc: https://docs.google.com/document/d/16iRNmziasEjVOblYp5bbkeBZ7pnjNlaIzPQqMTHQ-9I  This ticket aims to validate satisfiability (in terms of available resources) of a quota request using a heuristic algorithm in the Mesos Master, rather than validating the syntax of the request.\"','\"\"\"We need to to validate quota requests in the Mesos Master as outlined in the Design Doc: https://docs.google.com/document/d/16iRNmziasEjVOblYp5bbkeBZ7pnjNlaIzPQqMTHQ-9I  This ticket aims to validate satisfiability (in terms of available resources) of a quota request using a heuristic algorithm in the Mesos Master, rather than validating the syntax of the request.\"\"\"','','Improvement','Major','Resolved','Fixed','2015-07-17 15:49:09','2015-07-17 14:49:09','2018-11-26 12:22:41','2018-11-26 12:22:41',3,NULL,145285,159608,1768173,1,0,1,NULL,3572,3572,3426,4,444);
INSERT INTO `Issue` VALUES (21576,12845902,'MESOS-3073','https://issues.apache.org/jira/rest/api/2/issue/12845902','\"Introduce HTTP endpoints for Quota\"','\"We need to implement the HTTP endpoints for Quota as outlined in the Design Doc: (https://docs.google.com/document/d/16iRNmziasEjVOblYp5bbkeBZ7pnjNlaIzPQqMTHQ-9I). \"','\"\"\"We need to implement the HTTP endpoints for Quota as outlined in the Design Doc: (https://docs.google.com/document/d/16iRNmziasEjVOblYp5bbkeBZ7pnjNlaIzPQqMTHQ-9I). \"\"\"','','Epic','Major','Resolved','Fixed','2015-07-17 15:45:14','2015-07-17 14:45:14','2016-01-15 23:28:39','2016-01-15 23:28:39',3,NULL,8760,17253,262603,0,0,1,NULL,3572,3572,3572,4,444);
INSERT INTO `Issue` VALUES (21583,12845664,'MESOS-3066','https://issues.apache.org/jira/rest/api/2/issue/12845664','\"Replicated registry needs a representation of maintenance schedules\"','\"In order to persist maintenance schedules across failovers of the master, the schedule information must be kept in the replicated registry.  This means adding an additional message in the Registry protobuf in src/master/registry.proto.  The status of each individual slave\'s maintenance will also be persisted in this way. {code} message Maintenance {   message HostStatus {     required string hostname = 1;      // True if the slave is deactivated for maintenance.     // False if the slave is draining in preparation for maintenance.     required bool is_down = 2;  // Or an enum   }    message Schedule {     // The set of affected slave(s).     repeated HostStatus hosts = 1;      // Interval in which this set of slaves is expected to be down for.     optional Unavailability interval = 2;   }    message Schedules {     repeated Schedule schedules;   }    optional Schedules schedules = 1; } {code}  Note: There can be multiple SlaveID\'s attached to a single hostname.\"','\"\"\"In order to persist maintenance schedules across failovers of the master, the schedule information must be kept in the replicated registry.  This means adding an additional message in the Registry protobuf in src/master/registry.proto.  The status of each individual slave\'s maintenance will also be persisted in this way.   Note: There can be multiple SlaveID\'s attached to a single hostname.\"\"\"','\" message Maintenance {   message HostStatus {     required string hostname = 1;      // True if the slave is deactivated for maintenance.     // False if the slave is draining in preparation for maintenance.     required bool is_down = 2;  // Or an enum   }    message Schedule {     // The set of affected slave(s).     repeated HostStatus hosts = 1;      // Interval in which this set of slaves is expected to be down for.     optional Unavailability interval = 2;   }    message Schedules {     repeated Schedule schedules;   }    optional Schedules schedules = 1; } \"','Task','Major','Resolved','Fixed','2015-07-16 19:05:31','2015-07-16 18:05:31','2018-11-26 12:21:14','2018-11-26 12:21:14',3,NULL,49211,49356,1769415,1,0,0,NULL,3391,3391,3391,4,444);
INSERT INTO `Issue` VALUES (21588,12845615,'MESOS-3061','https://issues.apache.org/jira/rest/api/2/issue/12845615','\"Expose docker container IP in Master\'s state.json\"','\"We want to expose docker container IP to Mesos-DNS. One potential solution is to make it available via Master\'s state.json. We can set a label \"\"Docker.NetworkSettings.IPAddress\"\" in TaskStatus message (when it is sent the first time with TASK_RUNNING status).\"','\"\"\"We want to expose docker container IP to Mesos-DNS. One potential solution is to make it available via Master\'s state.json. We can set a label \"\"\"\"Docker.NetworkSettings.IPAddress\"\"\"\" in TaskStatus message (when it is sent the first time with TASK_RUNNING status).\"\"\"','','Task','Critical','Resolved','Fixed','2015-07-16 15:49:43','2015-07-16 14:49:43','2018-11-26 12:21:23','2018-11-26 12:21:23',2,NULL,1647,1647,1769611,1,0,0,NULL,3491,3491,3491,4,444);
INSERT INTO `Issue` VALUES (21634,12843379,'MESOS-3015','https://issues.apache.org/jira/rest/api/2/issue/12843379','\"Add hooks for Slave exits\"','\"The hook will be triggered on slave exits. A master hook module can use this to do Slave-specific cleanups.  In our particular use case, the hook would trigger cleanup of IPs assigned to the given Slave (see the [design doc | https://docs.google.com/document/d/17mXtAmdAXcNBwp_JfrxmZcQrs7EO6ancSbejrqjLQ0g/edit#]).\"','\"\"\"The hook will be triggered on slave exits. A master hook module can use this to do Slave-specific cleanups.  In our particular use case, the hook would trigger cleanup of IPs assigned to the given Slave (see the [design doc | https://docs.google.com/document/d/17mXtAmdAXcNBwp_JfrxmZcQrs7EO6ancSbejrqjLQ0g/edit#]).\"\"\"','','Task','Major','Resolved','Fixed','2015-07-08 02:55:20','2015-07-08 01:55:20','2018-11-26 12:54:16','2018-11-26 12:54:16',2,NULL,4617,83960,1781938,0,0,0,NULL,3491,3491,4008,4,444);
INSERT INTO `Issue` VALUES (21644,12843278,'MESOS-3004','https://issues.apache.org/jira/rest/api/2/issue/12843278','\"Design support running the command executor with provisioned image for running a task in a container\"','\"Mesos Containerizer uses the command executor to actually launch the user defined command, and the command executor then can communicate with the slave about the process lifecycle. When we provision a new container with the user specified image, we also need to be able to run the command executor in the container to support the same semantics. One approach is to dynamically mount in a static binary of the command executor with all its dependencies in a special directory so it doesn\'t interfere with the provisioned root filesystem and configure the mesos containerizer to run the command executor in that directory.\"','\"\"\"Mesos Containerizer uses the command executor to actually launch the user defined command, and the command executor then can communicate with the slave about the process lifecycle. When we provision a new container with the user specified image, we also need to be able to run the command executor in the container to support the same semantics. One approach is to dynamically mount in a static binary of the command executor with all its dependencies in a special directory so it doesn\'t interfere with the provisioned root filesystem and configure the mesos containerizer to run the command executor in that directory.\"\"\"','','Improvement','Major','Resolved','Fixed','2015-07-07 20:24:28','2015-07-07 19:24:28','2018-11-26 12:20:29','2018-11-26 12:20:29',5,NULL,4293,39153,1782296,1,0,0,NULL,3664,3664,3664,4,444);
INSERT INTO `Issue` VALUES (21684,12841794,'MESOS-2964','https://issues.apache.org/jira/rest/api/2/issue/12841794','\"libprocess io does not support peek()\"','\"Finally, I so wish we could just do:  {code} io::peek(request->socket, 6)   .then([request](const string& data) {     // Comment about the rules ...     if (data.length() < 2) { // Rule 1          } else if (...) { // Rule 2.          } else if (...) { // Rule 3.          }          if (ssl) {       accept_SSL_callback(request);     } else {       ...;     }   }); {code}  from: https://reviews.apache.org/r/31207/\"','\"\"\"Finally, I so wish we could just do:    from: https://reviews.apache.org/r/31207/\"\"\"','\" io::peek(request->socket, 6)   .then([request](const string& data) {     // Comment about the rules ...     if (data.length() < 2) { // Rule 1          } else if (...) { // Rule 2.          } else if (...) { // Rule 3.          }          if (ssl) {       accept_SSL_callback(request);     } else {       ...;     }   }); \"','Improvement','Minor','Resolved','Fixed','2015-06-30 21:55:37','2015-06-30 20:55:37','2018-11-26 12:21:28','2018-11-26 12:21:28',3,NULL,0,21931,1792285,1,0,0,NULL,3556,3556,3556,4,444);
INSERT INTO `Issue` VALUES (21699,12840859,'MESOS-2949','https://issues.apache.org/jira/rest/api/2/issue/12840859','\"Draft design for generalized Authorizer interface\"','\"As mentioned in MESOS-2948 the current {{mesos::Authorizer}} interface is rather inflexible if new _Actions_ or _Objects_ need to be added.  A new API needs to be designed in a way that allows for arbitrary _Actions_ and _Objects_ to be added to the authorization mechanism without having to recompile mesos.\"','\"\"\"As mentioned in MESOS-2948 the current {{mesos::Authorizer}} interface is rather inflexible if new _Actions_ or _Objects_ need to be added.  A new API needs to be designed in a way that allows for arbitrary _Actions_ and _Objects_ to be added to the authorization mechanism without having to recompile mesos.\"\"\"','','Task','Major','Resolved','Fixed','2015-06-26 15:24:05','2015-06-26 14:24:05','2018-11-26 12:20:26','2019-04-29 10:27:53',3,NULL,0,15279,1798436,1,0,0,NULL,3466,3466,3466,4,444);
INSERT INTO `Issue` VALUES (21701,12840834,'MESOS-2947','https://issues.apache.org/jira/rest/api/2/issue/12840834','\"Authorizer Module: Implementation, Integration & Tests\"','\"h4.Motivation Provide an example authorizer module based on the {{LocalAuthorizer}} implementation. Make sure that such authorizer module can be fully unit- and integration- tested within the mesos test suite. \"','\"\"\"h4.Motivation Provide an example authorizer module based on the {{LocalAuthorizer}} implementation. Make sure that such authorizer module can be fully unit- and integration- tested within the mesos test suite. \"\"\"','','Improvement','Major','Resolved','Implemented','2015-06-26 14:00:40','2015-06-26 13:00:40','2018-11-26 12:54:29','2018-11-26 12:54:29',8,NULL,2,9674,1798553,0,0,0,NULL,3390,3390,3466,4,444);
INSERT INTO `Issue` VALUES (21702,12840833,'MESOS-2946','https://issues.apache.org/jira/rest/api/2/issue/12840833','\"Authorizer Module: Interface design\"','\"h4.Motivation Design an interface covering authorizer modules while staying minimally invasive in regards to changes to the existing {{LocalAuthorizer}} implementation. \"','\"\"\"h4.Motivation Design an interface covering authorizer modules while staying minimally invasive in regards to changes to the existing {{LocalAuthorizer}} implementation. \"\"\"','','Improvement','Major','Resolved','Implemented','2015-06-26 13:55:04','2015-06-26 12:55:04','2018-11-26 12:54:36','2018-11-26 12:54:36',2,NULL,0,9888,1798559,0,0,0,NULL,3390,3390,3466,4,444);
INSERT INTO `Issue` VALUES (21712,12840599,'MESOS-2936','https://issues.apache.org/jira/rest/api/2/issue/12840599','\"Create a design document for Quota support in Master\"','\"Create a design document for the Quota feature support in Mesos Master (excluding allocator) to be shared with the Mesos community.  Design Doc: https://docs.google.com/document/d/16iRNmziasEjVOblYp5bbkeBZ7pnjNlaIzPQqMTHQ-9I/edit?usp=sharing\"','\"\"\"Create a design document for the Quota feature support in Mesos Master (excluding allocator) to be shared with the Mesos community.  Design Doc: https://docs.google.com/document/d/16iRNmziasEjVOblYp5bbkeBZ7pnjNlaIzPQqMTHQ-9I/edit?usp=sharing\"\"\"','','Documentation','Major','Resolved','Fixed','2015-06-25 18:47:05','2015-06-25 17:47:05','2018-11-26 12:20:35','2018-11-26 12:20:35',8,NULL,36165,36165,1799673,0,0,0,NULL,4135,3426,3426,4,444);
INSERT INTO `Issue` VALUES (21746,12839246,'MESOS-2902','https://issues.apache.org/jira/rest/api/2/issue/12839246','\"Enable Mesos to use arbitrary script / module to figure out IP, HOSTNAME\"','\"Currently Mesos tries to guess the IP, HOSTNAME by doing a reverse DNS lookup. This doesn\'t work on a lot of clouds as we want things like public IPs (which aren\'t the default DNS), there aren\'t FQDN names (Azure), or the correct way to figure it out is to call some cloud-specific endpoint.  If Mesos / Libprocess could load a mesos-module (Or run a script) which is provided per-cloud, we can figure out perfectly the IP / Hostname for the given environment. It also means we can ship one identical set of files to all hosts in a given provider which doesn\'t happen to have the DNS scheme + hostnames that libprocess/Mesos expects. Currently we have to generate host-specific config files which Mesos uses to guess.  The host-specific files break / fall apart if machines change IP / hostname without being reinstalled.\"','\"\"\"Currently Mesos tries to guess the IP, HOSTNAME by doing a reverse DNS lookup. This doesn\'t work on a lot of clouds as we want things like public IPs (which aren\'t the default DNS), there aren\'t FQDN names (Azure), or the correct way to figure it out is to call some cloud-specific endpoint.  If Mesos / Libprocess could load a mesos-module (Or run a script) which is provided per-cloud, we can figure out perfectly the IP / Hostname for the given environment. It also means we can ship one identical set of files to all hosts in a given provider which doesn\'t happen to have the DNS scheme + hostnames that libprocess/Mesos expects. Currently we have to generate host-specific config files which Mesos uses to guess.  The host-specific files break / fall apart if machines change IP / hostname without being reinstalled.\"\"\"','','Improvement','Critical','Resolved','Fixed','2015-06-19 22:36:41','2015-06-19 21:36:41','2018-11-26 12:54:59','2019-04-29 10:26:36',5,NULL,18200,38820,1808118,0,0,0,NULL,3820,3820,4037,4,444);
INSERT INTO `Issue` VALUES (406354,162152,'TIMOB-23691','https://jira.appcelerator.org/rest/api/2/issue/162152','\"iOS: Expose status-bar background-color\"','\"Added ability to change status bar background color\"','\"\"\"Added ability to change status bar background color\"\"\"','','New Feature','Medium','Closed','Fixed','2016-07-27 15:20:32','2016-07-27 15:20:32','2016-07-29 15:58:09','2016-09-15 09:24:37',1,NULL,2814,2827,2917,1,0,0,NULL,166456,166456,166010,12,4822);
INSERT INTO `Issue` VALUES (406360,162104,'TIMOB-23684','https://jira.appcelerator.org/rest/api/2/issue/162104','\"iOS: Expose missing iOS8 properties to hide NavigationBar\"','\"Expose the methods described above:     https://developer.apple.com/library/ios/documentation/UIKit/Reference/UINavigationController_Class/#//apple_ref/doc/uid/TP40006934-CH3-SW36\"','\"\"\"Expose the methods described above:     https://developer.apple.com/library/ios/documentation/UIKit/Reference/UINavigationController_Class/#//apple_ref/doc/uid/TP40006934-CH3-SW36\"\"\"','','Improvement','Medium','Closed','Fixed','2016-07-26 16:27:28','2016-07-26 16:27:28','2016-10-27 02:57:17','2018-05-01 20:20:17',3,NULL,0,12711,133109,1,0,0,NULL,166456,166456,166010,12,4822);
INSERT INTO `Issue` VALUES (406370,160541,'TIMOB-23674','https://jira.appcelerator.org/rest/api/2/issue/160541','\"iOS  - Compilation error\"','\"I was working perfectly on iOS, when suddenly this error appeared without change any cody:      {code:java}  [ERROR] :  ** BUILD FAILED **  [ERROR] :  The following build commands failed:  [ERROR] :   CompileC build/Intermediates/App.build/Debug-iphoneos/App.build/Objects-normal/armv7/TiUIiOSProxy.o Classes/TiUIiOSProxy.m normal armv7 objective-c com.apple.compilers.llvm.clang.1_0.compiler  [ERROR] :  (1 failure)  {code}    Now, I can\'t compile the app. \"','\"\"\"I was working perfectly on iOS, when suddenly this error appeared without change any cody:          Now, I can\'t compile the app. \"\"\"','\"  [ERROR] :  ** BUILD FAILED **  [ERROR] :  The following build commands failed:  [ERROR] :   CompileC build/Intermediates/App.build/Debug-iphoneos/App.build/Objects-normal/armv7/TiUIiOSProxy.o Classes/TiUIiOSProxy.m normal armv7 objective-c com.apple.compilers.llvm.clang.1_0.compiler  [ERROR] :  (1 failure)  \"','Bug','High','Closed','Fixed','2016-05-26 14:36:20','2016-05-26 14:36:20','2016-08-01 02:44:05','2016-08-15 05:10:11',2,NULL,0,479,95767,0,0,0,NULL,166128,166128,166010,12,4822);
INSERT INTO `Issue` VALUES (406378,161896,'TIMOB-23666','https://jira.appcelerator.org/rest/api/2/issue/161896','\"iOS: Button setting remote backgroundImage doesn\'t appear to work\"','\"Setting the backgroundImage property with a remote image doesn\'t appear to be working.    *Demo Code:*  {code:javascript}  var win = Ti.UI.createWindow({          backgroundColor: \'white\'  });     var url = Ti.UI.createButton({          title: \"\"URL Image\"\",   top: 100,          height: 100,   backgroundImage: \"\"http://www.devnetwork.com/wp-content/uploads/2015/07/<USER>logo.png\"\",  });     var local = Ti.UI.createButton({   title: \"\"Local Image\"\",          bottom: 100,          height: 100,   backgroundImage: \"\"images/<USER>small.png\"\",  });    setTimeout(function() {          url.setBackgroundImage(\"\"https://upload.wikimedia.org/wikipedia/commons/a/ab/Logo_TV_2015.png\"\");          local.setBackgroundImage(\"\"images/atlanta.jpg\"\");  },2000);        win.add(local)  win.add(url);  win.open();  {code}    *Test Case:*  Run the app and take a picture.   *Expected Result:*  The two buttons should all have a backgroundImage  one containing a local image, another containing an image from a URL.  *Actual Results*  Passing in a url or local path doesn\'t work with setBackgroundImage. \"','\"\"\"Setting the backgroundImage property with a remote image doesn\'t appear to be working.    *Demo Code:*      *Test Case:*  Run the app and take a picture.   *Expected Result:*  The two buttons should all have a backgroundImage  one containing a local image, another containing an image from a URL.  *Actual Results*  Passing in a url or local path doesn\'t work with setBackgroundImage. \"\"\"','\"  var win = Ti.UI.createWindow({          backgroundColor: \'white\'  });     var url = Ti.UI.createButton({          title: \"\"\"\"URL Image\"\"\"\",   top: 100,          height: 100,   backgroundImage: \"\"\"\"http://www.devnetwork.com/wp-content/uploads/2015/07/Appcelerator-logo.png\"\"\"\",  });     var local = Ti.UI.createButton({   title: \"\"\"\"Local Image\"\"\"\",          bottom: 100,          height: 100,   backgroundImage: \"\"\"\"images/appcelerator_small.png\"\"\"\",  });    setTimeout(function() {          url.setBackgroundImage(\"\"\"\"https://upload.wikimedia.org/wikipedia/commons/a/ab/Logo_TV_2015.png\"\"\"\");          local.setBackgroundImage(\"\"\"\"images/atlanta.jpg\"\"\"\");  },2000);        win.add(local)  win.add(url);  win.open();  \"','Bug','High','Closed','Fixed','2016-07-20 23:54:32','2016-07-20 23:54:32','2017-02-02 21:55:50','2017-02-03 17:56:01',1,NULL,0,72133,283561,1,0,0,NULL,166550,166550,166014,12,4822);
INSERT INTO `Issue` VALUES (406382,161877,'TIMOB-23662','https://jira.appcelerator.org/rest/api/2/issue/161877','\"Windows: can\'t detect Windows Phone SDK if no emulator installed\"','\"Studio and CLI can\'t find the windows phone SDK, even in a clean install.  Other user had the same problem and, installing the Windows Phone emulator the problem was solved.  My problem is that I cannot install WP emulator because my CPU is old and doesn\'t has support for SLAT.    In another modern PC with SLAT and emulator installed, WP SDK is detected correctly.    Some screenshots provided.    I need WP SDK to be detected to be able to build for WP.\"','\"\"\"Studio and CLI can\'t find the windows phone SDK, even in a clean install.  Other user had the same problem and, installing the Windows Phone emulator the problem was solved.  My problem is that I cannot install WP emulator because my CPU is old and doesn\'t has support for SLAT.    In another modern PC with SLAT and emulator installed, WP SDK is detected correctly.    Some screenshots provided.    I need WP SDK to be detected to be able to build for WP.\"\"\"','','Bug','Critical','Closed','Fixed','2016-07-20 14:23:14','2016-07-20 14:23:14','2016-07-20 22:11:08','2016-10-06 07:31:21',8,NULL,51,51,467,0,0,0,NULL,166573,166573,166018,12,4822);
INSERT INTO `Issue` VALUES (406386,161855,'TIMOB-23658','https://jira.appcelerator.org/rest/api/2/issue/161855','\"Windows: Ti.UI.Label.border* properties do not work when not using width and height\"','\"{{Titanium.UI.Label}} disappears if any {{border*}} properties are used and {{width}} and {{height}} are not defined.    {code}  var win = Ti.UI.createWindow({backgroundColor: \'red\'}),      lbl = Ti.UI.createLabel({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5,          text:\'TEST TEXT\'      });  win.add(lbl);  win.open();  {code}\"','\"\"\"{{Titanium.UI.Label}} disappears if any {{border*}} properties are used and {{width}} and {{height}} are not defined.    \"\"\"','\"  var win = Ti.UI.createWindow({backgroundColor: \'red\'}),      lbl = Ti.UI.createLabel({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5,          text:\'TEST TEXT\'      });  win.add(lbl);  win.open();  \"','Bug','Medium','Closed','Fixed','2016-07-19 20:20:25','2016-07-19 20:20:25','2016-07-22 07:46:44','2016-09-06 15:11:32',5,NULL,73,926,3566,1,0,0,NULL,166018,166018,166018,12,4822);
INSERT INTO `Issue` VALUES (406387,161854,'TIMOB-23657','https://jira.appcelerator.org/rest/api/2/issue/161854','\"Windows: borderRadius does not work for some components\"','\"{{borderRadius}} is not implemented for the following components:    - Button  - ScrollView  - WebView  - TextField  - ScrollableView  - Switch  - TextArea  - SearchBar  - Slider    It is likely that these components need {{Windows::UI::Xaml::Controls::Grid^}} parents.    *TEST CASE*  {code}  var win = Ti.UI.createWindow({ backgroundColor: \'purple\' }),      scrollView = Ti.UI.createScrollView({          layout: \'vertical\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      button = Ti.UI.createButton({          backgroundColor: \'orange\',          title: \'BUTTON\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      textField = Ti.UI.createTextField({          backgroundColor: \'orange\',          text: \'TEST TEXT\',          width: Ti.UI.FILL,          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      scrollableView = Ti.UI.createScrollableView({          backgroundColor: \'orange\',          width: Ti.UI.FILL,          height: 70,          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      toggle = Ti.UI.createSwitch({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      textArea = Ti.UI.createTextArea({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      searchBar = Ti.UI.createSearchBar({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      slider = Ti.UI.createSlider({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5,          width: \'50%\'      });  scrollView.add(button);  scrollView.add(textField);  scrollView.add(scrollableView);  scrollView.add(toggle);  scrollView.add(textArea);  scrollView.add(searchBar);  scrollView.add(slider);    win.add(scrollView);  win.open();  {code}    - WebView  {code}  var win = Ti.UI.createWindow({ backgroundColor: \'purple\' }),      webView = Ti.UI.createWebView({          backgroundColor: \'orange\',          url: \'http://www.<USER>com/\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5,      });    win.add(webView);  win.open();  {code}    {{PickerColumn}} was not suitable to fix    *Before Fix*  - {{borderRadius}} would have no effect on the components    *After Fix*  - A {{borderRadius}} is displayed  \"','\"\"\"{{borderRadius}} is not implemented for the following components:    - Button  - ScrollView  - WebView  - TextField  - ScrollableView  - Switch  - TextArea  - SearchBar  - Slider    It is likely that these components need {{Windows::UI::Xaml::Controls::Grid^}} parents.    *TEST CASE*      - WebView      {{PickerColumn}} was not suitable to fix    *Before Fix*  - {{borderRadius}} would have no effect on the components    *After Fix*  - A {{borderRadius}} is displayed  \"\"\"','\"  var win = Ti.UI.createWindow({ backgroundColor: \'purple\' }),      scrollView = Ti.UI.createScrollView({          layout: \'vertical\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      button = Ti.UI.createButton({          backgroundColor: \'orange\',          title: \'BUTTON\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      textField = Ti.UI.createTextField({          backgroundColor: \'orange\',          text: \'TEST TEXT\',          width: Ti.UI.FILL,          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      scrollableView = Ti.UI.createScrollableView({          backgroundColor: \'orange\',          width: Ti.UI.FILL,          height: 70,          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      toggle = Ti.UI.createSwitch({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      textArea = Ti.UI.createTextArea({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      searchBar = Ti.UI.createSearchBar({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5      }),      slider = Ti.UI.createSlider({          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5,          width: \'50%\'      });  scrollView.add(button);  scrollView.add(textField);  scrollView.add(scrollableView);  scrollView.add(toggle);  scrollView.add(textArea);  scrollView.add(searchBar);  scrollView.add(slider);    win.add(scrollView);  win.open();    var win = Ti.UI.createWindow({ backgroundColor: \'purple\' }),      webView = Ti.UI.createWebView({          backgroundColor: \'orange\',          url: \'http://www.appcelerator.com/\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5,      });    win.add(webView);  win.open();  \"','Bug','Medium','Closed','Fixed','2016-07-19 20:15:13','2016-07-19 20:15:13','2016-07-31 22:33:59','2016-10-18 14:37:03',13,NULL,0,13085,17418,0,0,0,NULL,166018,166018,166018,12,4822);
INSERT INTO `Issue` VALUES (406389,161851,'TIMOB-23655','https://jira.appcelerator.org/rest/api/2/issue/161851','\"Windows: Implement Ti.Geolocation.requestLocationPermissions/hasLocationPermissions methods to match iOS and Android behaviour\"','\"h5.Description    As part of TIMOB-19479 the Gelocation permissions was rewritten to be consistent across iOS and Android and use Ti.Geolocation.hasPermissions. Windows currently uses a different way to request permissions that can be seen in TIMOB-23389, however it should move to match iOS and Android. A code sample can be found below and a real world example found [in Geocoder|https://github.com/<USER>developer-relations/appc-sample-geocoder/blob/stable/app/lib/permissions.js#L59]    {code}  Ti.Geolocation.preferredProvider = \"\"gps\"\";      function locationCallback(e) {          if (!e.success || e.error) {              alert(\"\"error:\"\" + JSON.stringify(e.error));              return;          }          Ti.API.info(JSON.stringify(e));          var longitude = e.coords.longitude;          var latitude = e.coords.latitude;      };      if (Ti.Geolocation.hasLocationPermissions(Ti.Geolocation.AUTHORIZATION_ALWAYS)) {          alert(\"\"Access already granted!\"\");          Titanium.Geolocation.addEventListener(\"\"location\"\", locationCallback);      } else {                  Ti.Geolocation.requestLocationPermissions(Ti.Geolocation.AUTHORIZATION_ALWAYS, function(e) {            if (e.success === true) {                              alert(\"\"Access now granted!\"\");                Titanium.Geolocation.addEventListener(\"\"location\"\", locationCallback);            } else {                console.log(\"\"Access denied, error: \"\" + e.error);            }        });      }  {code}    Additionally to this Ti.Geolocation.hasLocationPermissions should also be implemented to allow a user to check if permissions have already been granted    h5.Steps to reproduce    # Run the code above on Windows Platform {{appc run -p windows }}    h5.Actual result    You should be prompted to allow location    h5.Expected result    The app will throw an error as the methods are not implemented\"','\"\"\"h5.Description    As part of TIMOB-19479 the Gelocation permissions was rewritten to be consistent across iOS and Android and use Ti.Geolocation.hasPermissions. Windows currently uses a different way to request permissions that can be seen in TIMOB-23389, however it should move to match iOS and Android. A code sample can be found below and a real world example found [in Geocoder|https://github.com/<USER>developer-relations/appc-sample-geocoder/blob/stable/app/lib/permissions.js#L59]        Additionally to this Ti.Geolocation.hasLocationPermissions should also be implemented to allow a user to check if permissions have already been granted    h5.Steps to reproduce    # Run the code above on Windows Platform {{appc run -p windows }}    h5.Actual result    You should be prompted to allow location    h5.Expected result    The app will throw an error as the methods are not implemented\"\"\"','\"  Ti.Geolocation.preferredProvider = \"\"\"\"gps\"\"\"\";      function locationCallback(e) {          if (!e.success || e.error) {              alert(\"\"\"\"error:\"\"\"\" + JSON.stringify(e.error));              return;          }          Ti.API.info(JSON.stringify(e));          var longitude = e.coords.longitude;          var latitude = e.coords.latitude;      };      if (Ti.Geolocation.hasLocationPermissions(Ti.Geolocation.AUTHORIZATION_ALWAYS)) {          alert(\"\"\"\"Access already granted!\"\"\"\");          Titanium.Geolocation.addEventListener(\"\"\"\"location\"\"\"\", locationCallback);      } else {                  Ti.Geolocation.requestLocationPermissions(Ti.Geolocation.AUTHORIZATION_ALWAYS, function(e) {            if (e.success === true) {                              alert(\"\"\"\"Access now granted!\"\"\"\");                Titanium.Geolocation.addEventListener(\"\"\"\"location\"\"\"\", locationCallback);            } else {                console.log(\"\"\"\"Access denied, error: \"\"\"\" + e.error);            }        });      }  \"','Improvement','High','Closed','Fixed','2016-07-19 17:41:41','2016-07-19 17:41:41','2016-10-11 12:42:21','2016-10-13 14:17:17',5,NULL,2046,10083,120660,0,0,0,NULL,166007,166007,166083,12,4822);
INSERT INTO `Issue` VALUES (406391,161846,'TIMOB-23653','https://jira.appcelerator.org/rest/api/2/issue/161846','\"Windows: Animation returns to original opacity property when finished\"','\"h5.Description    When using the code below, when the animation is complete the opacity property will be what it was set to before the animation started.    {code}  var win = Ti.UI.createWindow({backgroundColor: \'red\'}),      img = Ti.UI.createImageView({width: \'80%\', height: \'80%\', image:\'Logo.png\', opacity:0.5});     var anim = Ti.UI.createAnimation({   opacity:1,   duration:1000  });    win.addEventListener(\'click\', function(){   img.animate(anim);  });    win.add(img);  win.open();  {code}    *This a regression that first appears in 5.3.0.GA,*    *Workaround*    As a workaround add an eventListener for the complete event and then set the property as required like below    {code}  anim.addEventListener(\'complete\', function(){   img.opacity = 1;  });     {code}      h5.Steps to reproduce    # Using the code above, build for Windows Platform {{appc run -p windows -T wp-emulator -C 10-0-1}}  # Click the screen      h5.Actual result    At the end of the animation the opacity of the image will return to the original value      h5.Expected    The value at the end of the animation should be what is defined in the animation\"','\"\"\"h5.Description    When using the code below, when the animation is complete the opacity property will be what it was set to before the animation started.        *This a regression that first appears in 5.3.0.GA,*    *Workaround*    As a workaround add an eventListener for the complete event and then set the property as required like below          h5.Steps to reproduce    # Using the code above, build for Windows Platform {{appc run -p windows -T wp-emulator -C 10-0-1}}  # Click the screen      h5.Actual result    At the end of the animation the opacity of the image will return to the original value      h5.Expected    The value at the end of the animation should be what is defined in the animation\"\"\"','\"  var win = Ti.UI.createWindow({backgroundColor: \'red\'}),      img = Ti.UI.createImageView({width: \'80%\', height: \'80%\', image:\'Logo.png\', opacity:0.5});     var anim = Ti.UI.createAnimation({   opacity:1,   duration:1000  });    win.addEventListener(\'click\', function(){   img.animate(anim);  });    win.add(img);  win.open();    anim.addEventListener(\'complete\', function(){   img.opacity = 1;  });     \"','Bug','None','Closed','Fixed','2016-07-19 14:55:20','2016-07-19 14:55:20','2016-07-20 04:57:03','2016-09-05 15:25:12',5,NULL,199,657,841,0,0,0,NULL,166007,166007,166018,12,4822);
INSERT INTO `Issue` VALUES (406394,161783,'TIMOB-23649','https://jira.appcelerator.org/rest/api/2/issue/161783','\"Use per-platform moduleAPIVersions in the SDK manifest.json\"','\"We need the ability to version the module API\'s at the platform level (and not globally). We updated Android/V8 so only need to bump the moduleAPIVersion to 3 there, but retain 2 on iOS. For the SDK, this involves using an object value for \"\"moduleAPIVersion\"\" property. I propose that the object have the platform ids as the keys and the api version as the value, like so:    {code:javascript}  {    \"\"name\"\": \"\"6.0.0.v20160717220907\"\",    \"\"version\"\": \"\"6.0.0\"\",    \"\"moduleAPIVersion\"\": {      \"\"iphone\"\": \"\"2\"\",      \"\"android\"\": \"\"3\"\",      \"\"mobileweb\"\": \"\"2\"\"    },    \"\"timestamp\"\": \"\"7/18/2016 05:13\"\",    \"\"githash\"\": \"\"e31eb5e\"\",    \"\"platforms\"\": [      \"\"iphone\"\",      \"\"android\"\",      \"\"mobileweb\"\"    ]  }  {code}\"','\"\"\"We need the ability to version the module API\'s at the platform level (and not globally). We updated Android/V8 so only need to bump the moduleAPIVersion to 3 there, but retain 2 on iOS. For the SDK, this involves using an object value for \"\"\"\"moduleAPIVersion\"\"\"\" property. I propose that the object have the platform ids as the keys and the api version as the value, like so:    \"\"\"','\"  {    \"\"\"\"name\"\"\"\": \"\"\"\"6.0.0.v20160717220907\"\"\"\",    \"\"\"\"version\"\"\"\": \"\"\"\"6.0.0\"\"\"\",    \"\"\"\"moduleAPIVersion\"\"\"\": {      \"\"\"\"iphone\"\"\"\": \"\"\"\"2\"\"\"\",      \"\"\"\"android\"\"\"\": \"\"\"\"3\"\"\"\",      \"\"\"\"mobileweb\"\"\"\": \"\"\"\"2\"\"\"\"    },    \"\"\"\"timestamp\"\"\"\": \"\"\"\"7/18/2016 05:13\"\"\"\",    \"\"\"\"githash\"\"\"\": \"\"\"\"e31eb5e\"\"\"\",    \"\"\"\"platforms\"\"\"\": [      \"\"\"\"iphone\"\"\"\",      \"\"\"\"android\"\"\"\",      \"\"\"\"mobileweb\"\"\"\"    ]  }  \"','Improvement','High','Closed','Fixed','2016-07-14 07:38:09','2016-07-14 07:38:09','2016-08-04 13:52:26','2018-08-06 17:49:18',3,NULL,542,4168,30614,1,0,1,NULL,166526,166526,166009,12,4822);
INSERT INTO `Issue` VALUES (406402,161447,'TIMOB-23641','https://jira.appcelerator.org/rest/api/2/issue/161447','\"Windows: list section instertItemsAt not working\"','\"I want to add row to the top pf the list (0 index of row), but instead of this section adding row to the end.    index.xml:      {code:javascript}  <Alloy>      <Window id=\'win\' backgroundColor=\"\"green\"\">      <ListView id=\"\"list\"\" defaultItemTemplate=\"\"t\"\">       <Templates>       <ItemTemplate name=\"\"t\"\" >        <Label bindId=\"\"label\"\" />       </ItemTemplate>                        </Templates>        <ListSection  id=\"\"section\"\">        </ListSection>      </ListView>      <Button backgroundColor=\'red\' width=\'100dp\' height=\'44dp\' onClick=\'doClick\' />      </Window>  </Alloy>  {code}    index.js:      {code:javascript}  function doClick(e) {      $.section.insertItemsAt(0, [{label: {text: \'test4\'}}]);  }    $.section.appendItems([   {label: {text: \'test1\'}},   {label: {text: \'test2\'}},   {label: {text: \'test3\'}},  ]);    $.win.open();  {code}     \"','\"\"\"I want to add row to the top pf the list (0 index of row), but instead of this section adding row to the end.    index.xml:          index.js:           \"\"\"','\"  <Alloy>      <Window id=\'win\' backgroundColor=\"\"\"\"green\"\"\"\">      <ListView id=\"\"\"\"list\"\"\"\" defaultItemTemplate=\"\"\"\"t\"\"\"\">       <Templates>       <ItemTemplate name=\"\"\"\"t\"\"\"\" >        <Label bindId=\"\"\"\"label\"\"\"\" />       </ItemTemplate>                        </Templates>        <ListSection  id=\"\"\"\"section\"\"\"\">        </ListSection>      </ListView>      <Button backgroundColor=\'red\' width=\'100dp\' height=\'44dp\' onClick=\'doClick\' />      </Window>  </Alloy>    function doClick(e) {      $.section.insertItemsAt(0, [{label: {text: \'test4\'}}]);  }    $.section.appendItems([   {label: {text: \'test1\'}},   {label: {text: \'test2\'}},   {label: {text: \'test3\'}},  ]);    $.win.open();  \"','Bug','High','Closed','Fixed','2016-06-29 17:40:34','2016-06-29 17:40:34','2016-07-18 02:29:42','2016-08-22 16:14:28',5,NULL,2,3634,26449,0,0,0,NULL,166324,166324,166018,12,4822);
INSERT INTO `Issue` VALUES (406404,161789,'TIMOB-23639','https://jira.appcelerator.org/rest/api/2/issue/161789','\"Windows: Updating a tableviewsection with the index of a deleted tableviewsection adds the deleted tableviewsection back\"','\"h5.Description    When calling updateSection for a tableviewsection with the index number that once referenced a deleted section, it appears that the deleted section is updated and readded to the tableview.    The code below does the following:    # Create a tableview with two sections  # When the window opens, delete the section at index 1 and append a new section  # When a tableviewrow is clicked, update the section at index    On Android and iOS this code works as expected, with the title of the 2 section being updated    {code}  var win = Ti.UI.createWindow();    var sectionFruit = Ti.UI.createTableViewSection({    headerTitle: \'Fruit\'  });  sectionFruit.add(Ti.UI.createTableViewRow({ title: \'Apples\' }));  sectionFruit.add(Ti.UI.createTableViewRow({ title: \'Bananas\' }));    var testSection = Ti.UI.createTableViewSection({    headerTitle: \'Test\'  });    var table = Ti.UI.createTableView({   data: [sectionFruit, testSection]  });    win.addEventListener(\'open\', function() {   table.deleteSection(1);   table.appendSection(createSection(\'newSection\'));   var sections = table.sections;   for(var i = 0; i < sections.length; i++) {    console.log(sections[i].headerTitle);   }  });    table.addEventListener(\'click\', function() {   table.updateSection(1, createSection(\'updateSection\'));   var sections2 = table.sections;   console.log(table.sections.length);   for(var i = 0; i < sections2.length; i++){    console.log(sections2[i].headerTitle);   }  });    function createSection(title){   return section = Ti.UI.createTableViewSection({ headerTitle: title});  }    win.add(table);  win.open();  {code}    h5.Steps to reproduce    1. Using the code above, build for Windows Platform using {{appc run -p windows -T wp-emulator}}  2. Tap one of the rows in the first section    h5.Actual result    There are now 3 sections Fruit, updateSection and newSection    h5.Expected result    There should only be 2 sections Fruit and updateSection \"','\"\"\"h5.Description    When calling updateSection for a tableviewsection with the index number that once referenced a deleted section, it appears that the deleted section is updated and readded to the tableview.    The code below does the following:    # Create a tableview with two sections  # When the window opens, delete the section at index 1 and append a new section  # When a tableviewrow is clicked, update the section at index    On Android and iOS this code works as expected, with the title of the 2 section being updated        h5.Steps to reproduce    1. Using the code above, build for Windows Platform using {{appc run -p windows -T wp-emulator}}  2. Tap one of the rows in the first section    h5.Actual result    There are now 3 sections Fruit, updateSection and newSection    h5.Expected result    There should only be 2 sections Fruit and updateSection \"\"\"','\"  var win = Ti.UI.createWindow();    var sectionFruit = Ti.UI.createTableViewSection({    headerTitle: \'Fruit\'  });  sectionFruit.add(Ti.UI.createTableViewRow({ title: \'Apples\' }));  sectionFruit.add(Ti.UI.createTableViewRow({ title: \'Bananas\' }));    var testSection = Ti.UI.createTableViewSection({    headerTitle: \'Test\'  });    var table = Ti.UI.createTableView({   data: [sectionFruit, testSection]  });    win.addEventListener(\'open\', function() {   table.deleteSection(1);   table.appendSection(createSection(\'newSection\'));   var sections = table.sections;   for(var i = 0; i < sections.length; i++) {    console.log(sections[i].headerTitle);   }  });    table.addEventListener(\'click\', function() {   table.updateSection(1, createSection(\'updateSection\'));   var sections2 = table.sections;   console.log(table.sections.length);   for(var i = 0; i < sections2.length; i++){    console.log(sections2[i].headerTitle);   }  });    function createSection(title){   return section = Ti.UI.createTableViewSection({ headerTitle: title});  }    win.add(table);  win.open();  \"','Bug','Medium','Closed','Fixed','2016-07-14 17:15:25','2016-07-14 17:15:25','2016-07-18 01:23:22','2016-09-06 14:48:45',5,NULL,14,3618,4807,0,0,0,NULL,166007,166007,166018,12,4822);
INSERT INTO `Issue` VALUES (406405,161787,'TIMOB-23638','https://jira.appcelerator.org/rest/api/2/issue/161787','\"Android: Unable to debug an application with newer V8\"','\"h5.Description    When debugging a project on Titanium SDK 6.0.0+ on Android, the debugger does not work at all.\"','\"\"\"h5.Description    When debugging a project on Titanium SDK 6.0.0+ on Android, the debugger does not work at all.\"\"\"','','Bug','Critical','Closed','Fixed','2016-07-14 14:31:27','2016-07-14 14:31:27','2016-08-02 13:28:54','2018-08-06 17:49:18',13,NULL,241,11324,27297,1,0,0,NULL,166009,166007,166009,12,4822);
INSERT INTO `Issue` VALUES (406406,161786,'TIMOB-23637','https://jira.appcelerator.org/rest/api/2/issue/161786','\"Windows: Titanium object creation takes too long\"','\"I recently found that one the performance bottleneck of Titanium Windows is occurs during object creation ({{Ti.createXXX}} etc). On my Lumia 630 I observed it takes almost 1 second to create 100 proxy object, and it can be serious issue especially on app startup because Windows Phone tend to kill the app when app startup takes too long.    *Sample code*  {code}  var start = +new Date();  for (var i = 0; i < 100; i++) {      var obj = Ti.createBuffer({length: 2});  }  alert((+new Date() - start) + \' msec\');  {code}      {code}  var start = +new Date();  for (var i = 0; i < 100; i++) {      var obj = Ti.UI.createLabel({text:\'test \' + i});  }  alert((+new Date() - start) + \' msec\');  {code}  \"','\"\"\"I recently found that one the performance bottleneck of Titanium Windows is occurs during object creation ({{Ti.createXXX}} etc). On my Lumia 630 I observed it takes almost 1 second to create 100 proxy object, and it can be serious issue especially on app startup because Windows Phone tend to kill the app when app startup takes too long.    *Sample code*          \"\"\"','\"  var start = +new Date();  for (var i = 0; i < 100; i++) {      var obj = Ti.createBuffer({length: 2});  }  alert((+new Date() - start) + \' msec\');    var start = +new Date();  for (var i = 0; i < 100; i++) {      var obj = Ti.UI.createLabel({text:\'test \' + i});  }  alert((+new Date() - start) + \' msec\');  \"','Improvement','High','Closed','Fixed','2016-07-14 12:01:41','2016-07-14 12:01:41','2016-07-21 13:25:32','2016-10-20 15:46:18',8,NULL,3273,5132,10163,0,0,0,NULL,166083,166083,166083,12,4822);
INSERT INTO `Issue` VALUES (406434,161534,'TIMOB-23605','https://jira.appcelerator.org/rest/api/2/issue/161534','\"Android: Recompile ti.urbanairship module against latest SDK\"','\"ti.urbanairship: https://github.com/<USER>modules/ti.urbanairship    Generally this requires some minor changes to each module:  - bump the module\'s version up to the next major (i.e. 2.3.1 -> 3.0.0)  - bump the module\'s apiversion to 3 (for Android)  - bump the minsdk to 6.0.0 (for Android)  At a higher level, we\'ll need to update our CI build scripts for modules to use the master branch SDK to build against, and Android NDK r11c.\"','\"\"\"ti.urbanairship: https://github.com/<USER>modules/ti.urbanairship    Generally this requires some minor changes to each module:  - bump the module\'s version up to the next major (i.e. 2.3.1 -> 3.0.0)  - bump the module\'s apiversion to 3 (for Android)  - bump the minsdk to 6.0.0 (for Android)  At a higher level, we\'ll need to update our CI build scripts for modules to use the master branch SDK to build against, and Android NDK r11c.\"\"\"','','Story','High','Closed','Won\'t Fix','2016-07-01 14:59:38','2016-07-01 14:59:38','2016-07-27 13:53:50','2017-03-23 22:45:04',3,NULL,15,27154,37374,0,0,0,NULL,166009,166009,166009,12,4822);
