INSERT INTO `Issue` VALUES (406465,161432,'TIMOB-23572','https://jira.appcelerator.org/rest/api/2/issue/161432','\"iOS/Android: Add the ability to remove all Ti.App.Properties at once\"','\"The user should be able to remove all {{Ti.App.Properties}} at once. On iOS, the method is even (partly) exposed, yet, but not to the public interface. On Android, we need to implement that method completely.\"','\"\"\"The user should be able to remove all {{Ti.App.Properties}} at once. On iOS, the method is even (partly) exposed, yet, but not to the public interface. On Android, we need to implement that method completely.\"\"\"','','Improvement','Medium','Closed','Fixed','2016-06-29 04:48:43','2016-06-29 04:48:43','2016-07-21 17:23:28','2016-10-19 08:53:26',3,NULL,0,32431,32434,0,0,0,NULL,166010,166010,166010,12,4822);
INSERT INTO `Issue` VALUES (406481,161310,'TIMOB-23554','https://jira.appcelerator.org/rest/api/2/issue/161310','\"Android: Ti.apiName should == \'Ti\'\"','\"On Android, Ti.apiName returns \'Ti.Module\', but should return \'Ti\'.    {code:js}  it(\'apiName\', function () {    should(Ti).have.readOnlyProperty(\'apiName\').which.is.a.String;    should(Ti.apiName).be.eql(\'Ti\'); // equals \'Ti.Module\' on Android, which is incorrect.   });  {code}\"','\"\"\"On Android, Ti.apiName returns \'Ti.Module\', but should return \'Ti\'.    {code:js}  it(\'apiName\', function () {    should(Ti).have.readOnlyProperty(\'apiName\').which.is.a.String;    should(Ti.apiName).be.eql(\'Ti\'); // equals \'Ti.Module\' on Android, which is incorrect.   });  {code}\"\"\"','\"  it(\'apiName\', function () {    should(Ti).have.readOnlyProperty(\'apiName\').which.is.a.String;    should(Ti.apiName).be.eql(\'Ti\'); // equals \'Ti.Module\' on Android, which is incorrect.   });  \"','Bug','High','Closed','Fixed','2016-06-23 22:14:31','2016-06-23 22:14:31','2016-07-14 17:33:27','2016-08-17 21:29:45',3,NULL,56,56,29958,0,0,0,NULL,166009,166009,166009,12,4822);
INSERT INTO `Issue` VALUES (406489,161236,'TIMOB-23546','https://jira.appcelerator.org/rest/api/2/issue/161236','\"Windows: Tap-to-focus for Camera\"','\"When {{overlay}} is specified for {{Ti.Media.showCamera}}, there is no \"\"Tap to Focus\"\" support now, which makes it difficult to focus at shooting.    {code}  var win = Ti.UI.createWindow({ backgroundColor: \'green\', layout: \'vertical\' }),      openButton = Ti.UI.createButton({ title: \'OPEN CAMERA\', backgroundColor: \'blue\' }),      imageView = Ti.UI.createImageView({ width: Ti.UI.FILL, height: \'70%\' });    var overlay = Ti.UI.createView({      layout: \'vertical\',      height: \'20%\', width: Ti.UI.FILL,      bottom: 0  }),  takeButton = Ti.UI.createButton({ title: \'TAKE A PHOTO\', backgroundColor: \'red\' }),  hideButton = Ti.UI.createButton({ title: \'HIDE PREVIEW\', backgroundColor: \'red\' });    takeButton.addEventListener(\'click\', function () {      Ti.Media.takePicture();  });  hideButton.addEventListener(\'click\', function () {      Ti.Media.hideCamera();  });  overlay.add(takeButton);  overlay.add(hideButton);    openButton.addEventListener(\'click\', function () {      Ti.Media.showCamera({          mediaTypes: [Ti.Media.MEDIA_TYPE_PHOTO],          overlay: overlay,          success: function (e) {              Ti.API.info(\'showCamera() success\');              imageView.image = e.media;          },          error: function (e) {              alert(\'showCamera() error: \' + JSON.stringify(e));          }      });  });    win.add(openButton);  win.add(imageView);  win.open();  {code}    \"','\"\"\"When {{overlay}} is specified for {{Ti.Media.showCamera}}, there is no \"\"\"\"Tap to Focus\"\"\"\" support now, which makes it difficult to focus at shooting.        \"\"\"','\"  var win = Ti.UI.createWindow({ backgroundColor: \'green\', layout: \'vertical\' }),      openButton = Ti.UI.createButton({ title: \'OPEN CAMERA\', backgroundColor: \'blue\' }),      imageView = Ti.UI.createImageView({ width: Ti.UI.FILL, height: \'70%\' });    var overlay = Ti.UI.createView({      layout: \'vertical\',      height: \'20%\', width: Ti.UI.FILL,      bottom: 0  }),  takeButton = Ti.UI.createButton({ title: \'TAKE A PHOTO\', backgroundColor: \'red\' }),  hideButton = Ti.UI.createButton({ title: \'HIDE PREVIEW\', backgroundColor: \'red\' });    takeButton.addEventListener(\'click\', function () {      Ti.Media.takePicture();  });  hideButton.addEventListener(\'click\', function () {      Ti.Media.hideCamera();  });  overlay.add(takeButton);  overlay.add(hideButton);    openButton.addEventListener(\'click\', function () {      Ti.Media.showCamera({          mediaTypes: [Ti.Media.MEDIA_TYPE_PHOTO],          overlay: overlay,          success: function (e) {              Ti.API.info(\'showCamera() success\');              imageView.image = e.media;          },          error: function (e) {              alert(\'showCamera() error: \' + JSON.stringify(e));          }      });  });    win.add(openButton);  win.add(imageView);  win.open();  \"','Improvement','Medium','Closed','Fixed','2016-06-21 13:17:54','2016-06-21 13:17:54','2016-07-26 18:16:28','2016-09-06 14:25:07',8,NULL,8244,8244,50698,1,0,0,NULL,166083,166083,166083,12,4822);
INSERT INTO `Issue` VALUES (406492,161205,'TIMOB-23543','https://jira.appcelerator.org/rest/api/2/issue/161205','\"TiAPI: require implementation uses incorrect __filename values\"','\"Our require implementation uses different values for __filename than what may be expected from an implementation like NodeJS. Additionally, our values differ between platforms.    On Windows, we get the base name of the file (\'filename\'). On iOS and Android we get the filename with no path info (\'filename.js\').    To match Node, we should be giving the absolute path to the resolved file (\'/path/to/filename.js\').\"','\"\"\"Our require implementation uses different values for __filename than what may be expected from an implementation like NodeJS. Additionally, our values differ between platforms.    On Windows, we get the base name of the file (\'filename\'). On iOS and Android we get the filename with no path info (\'filename.js\').    To match Node, we should be giving the absolute path to the resolved file (\'/path/to/filename.js\').\"\"\"','','Bug','High','Closed','Fixed','2016-06-20 16:09:41','2016-06-20 16:09:41','2016-07-20 13:47:21','2017-03-31 22:15:31',8,NULL,183,33771,43057,0,0,0,NULL,166009,166009,166009,12,4822);
INSERT INTO `Issue` VALUES (406494,161180,'TIMOB-23538','https://jira.appcelerator.org/rest/api/2/issue/161180','\"iOS: Refactor default new app-projects\"','\"For our Release 6.0.0, we should really refresh our default app templates that are used when we create a new project. We still have those iOS3-like icons with no retina etc. Same for Android: We should use our latest design for the splash-screens and ensure that we use 9-patch for that.    In Addition to that, Alloy and classic projects should both use the same assets and interface. So we need an Alloy PR as well to cover the Alloy templates.\"','\"\"\"For our Release 6.0.0, we should really refresh our default app templates that are used when we create a new project. We still have those iOS3-like icons with no retina etc. Same for Android: We should use our latest design for the splash-screens and ensure that we use 9-patch for that.    In Addition to that, Alloy and classic projects should both use the same assets and interface. So we need an Alloy PR as well to cover the Alloy templates.\"\"\"','','Improvement','Critical','Closed','Fixed','2016-06-17 17:54:29','2016-06-17 17:54:29','2016-07-30 19:00:48','2016-09-15 22:55:05',5,NULL,59992,61630,61986,1,0,1,NULL,166010,166010,166010,12,4822);
INSERT INTO `Issue` VALUES (406518,161064,'TIMOB-23513','https://jira.appcelerator.org/rest/api/2/issue/161064','\"iOS10: Support for new WatchConnectivity features\"','\"We have a few new properties regarding the WatchConnectivity framework in iOS10 that we should expose.\"','\"\"\"We have a few new properties regarding the WatchConnectivity framework in iOS10 that we should expose.\"\"\"','','New Feature','High','Closed','Fixed','2016-06-14 03:45:46','2016-06-14 03:45:46','2016-07-18 15:02:42','2018-08-06 17:49:34',3,NULL,0,49618,49636,0,0,0,NULL,166010,166010,166010,12,4822);
INSERT INTO `Issue` VALUES (406571,160601,'TIMOB-23452','https://jira.appcelerator.org/rest/api/2/issue/160601','\"SDK: Remove all deprecated API\'s with remove-version 6.0.0\"','\"This ticket include the changes being made to remove all deprecated API\'s across iOS and Android. On iOS, we have 106 API\'s that are marked to be removed by 6.0.0 (even API\'s from 1.8.0 and earlier), so it\'s time. On Android, we have 70 API\'s that are annotated with {{@Deprecated}}, without a remove-version. [~<USER> should decide which of them can be removed in 6.0.0.\"','\"\"\"This ticket include the changes being made to remove all deprecated API\'s across iOS and Android. On iOS, we have 106 API\'s that are marked to be removed by 6.0.0 (even API\'s from 1.8.0 and earlier), so it\'s time. On Android, we have 70 API\'s that are annotated with {{@Deprecated}}, without a remove-version. [~<USER> should decide which of them can be removed in 6.0.0.\"\"\"','','Story','High','Closed','Fixed','2016-05-28 09:54:53','2016-05-28 09:54:53','2016-07-14 15:30:51','2017-03-24 20:50:43',5,NULL,0,53964,68015,0,0,0,NULL,166010,166010,166009,12,4822);
INSERT INTO `Issue` VALUES (406587,160367,'TIMOB-23435','https://jira.appcelerator.org/rest/api/2/issue/160367','\"Hyperloop: iOS Memory Leak\"','\"This impacts version 1.2.0 as well as earlier versions of HL for iOS.    SEE :https://www.dropbox.com/sh/ym28ctdtki1il6m/AADZWstALxykj62oYXUJspcja?dl=0    Specifically the leaks I am talking about are in the LEAK-AS-OF-MAY19-2016 folder:    All I did was run the hyperloop-examples program (from master) and click on auto layout and then hit the back arrow and then hit View Animation. As you can see each time I invoke hyperloop objects I got 51 new leaks between those two actions. I got 19 leaks upon initialization of the app.    I think this is the same leak behavior I observed back in February.     I had to custom compile a version of titanium since master is currently broken. see https://jira.<USER>org/browse/AC-3640    I built <USER>titanium_mobile master at has aafdb83   I mention this just to document it, but I don\'t think this is an important detail.\"','\"\"\"This impacts version 1.2.0 as well as earlier versions of HL for iOS.    SEE :https://www.dropbox.com/sh/ym28ctdtki1il6m/AADZWstALxykj62oYXUJspcja?dl=0    Specifically the leaks I am talking about are in the LEAK-AS-OF-MAY19-2016 folder:    All I did was run the hyperloop-examples program (from master) and click on auto layout and then hit the back arrow and then hit View Animation. As you can see each time I invoke hyperloop objects I got 51 new leaks between those two actions. I got 19 leaks upon initialization of the app.    I think this is the same leak behavior I observed back in February.     I had to custom compile a version of titanium since master is currently broken. see https://jira.<USER>org/browse/AC-3640    I built <USER>titanium_mobile master at has aafdb83   I mention this just to document it, but I don\'t think this is an important detail.\"\"\"','','Bug','Critical','Closed','Fixed','2016-05-19 18:56:56','2016-05-19 18:56:56','2016-07-27 18:55:30','2017-03-31 22:16:38',21,NULL,4296,12175,99358,1,0,1,NULL,166452,166452,166044,12,4822);
INSERT INTO `Issue` VALUES (406681,160058,'TIMOB-23329','https://jira.appcelerator.org/rest/api/2/issue/160058','\"Windows: Implement Ti.UI.TableView border properties\"','\"Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} for {{Ti.UI.TableView}}.    *sample code*  {code}  var win = Ti.UI.createWindow({ backgroundColor: \'red\' }),      tableView = Ti.UI.createTableView({          width: \'80%\',          height: \'80%\',          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5,          data: [{ title: \'Apples\' }, { title: \'Bananas\' }, { title: \'Carrots\' }, { title: \'Potatoes\' }]      });    tableView.addEventListener(\'click\', function (e) {      alert(JSON.stringify(e.row.title));  });    win.add(tableView);  win.open();  {code}    *Expected*    !Capture.PNG|thumbnail!  \"','\"\"\"Implement {{borderColor}}, {{borderWidth}}, {{borderRadius}} for {{Ti.UI.TableView}}.    *sample code*      *Expected*    !Capture.PNG|thumbnail!  \"\"\"','\"  var win = Ti.UI.createWindow({ backgroundColor: \'red\' }),      tableView = Ti.UI.createTableView({          width: \'80%\',          height: \'80%\',          backgroundColor: \'orange\',          borderWidth: 5,          borderColor: \'yellow\',          borderRadius: 5,          data: [{ title: \'Apples\' }, { title: \'Bananas\' }, { title: \'Carrots\' }, { title: \'Potatoes\' }]      });    tableView.addEventListener(\'click\', function (e) {      alert(JSON.stringify(e.row.title));  });    win.add(tableView);  win.open();  \"','Improvement','Medium','Closed','Fixed','2016-05-05 14:11:10','2016-05-05 14:11:10','2016-07-20 04:58:18','2016-10-14 17:34:56',5,NULL,1655,2111,108887,0,0,0,NULL,166083,166083,166018,12,4822);
INSERT INTO `Issue` VALUES (406730,159346,'TIMOB-23265','https://jira.appcelerator.org/rest/api/2/issue/159346','\"Cannot access Appcelerator AWS storage from Android httpclient request\"','\"h6. Issue Description    Mark files as private (s3_acl:private) in the <USER>cloud storage is returning 403:forbidden response from AWS in Android when user try to download the file.     h6. Steps to replicate  1. App queries cloud to get a list of files   2. User selects a file from generated list   3. App queries cloud to get temporary URL for selected file   4. returned url is used in httpclient to download the file (A pdf in this case)   5. file is displayed     On iOS this works fine, however on Android is returning a 403:forbidden response from AWS when I try to download the pdf. Before setting the files to private, this solution worked fine and I was able to download and display the files on both OS\'s     h6. Additional notes  All of the calls to the cloud are done through an ArrowDB app hosted on node.js and I\'ve tried using the sessionCookie from that login, but with no luck - though I\'d assume that once the URL has been retrieved it is temporarily available to anyone and doesn\'t require further authentication - can\'t find much in the way of documentation around the differences of setting s3_acl to private. \"','\"\"\"h6. Issue Description    Mark files as private (s3_acl:private) in the <USER>cloud storage is returning 403:forbidden response from AWS in Android when user try to download the file.     h6. Steps to replicate  1. App queries cloud to get a list of files   2. User selects a file from generated list   3. App queries cloud to get temporary URL for selected file   4. returned url is used in httpclient to download the file (A pdf in this case)   5. file is displayed     On iOS this works fine, however on Android is returning a 403:forbidden response from AWS when I try to download the pdf. Before setting the files to private, this solution worked fine and I was able to download and display the files on both OS\'s     h6. Additional notes  All of the calls to the cloud are done through an ArrowDB app hosted on node.js and I\'ve tried using the sessionCookie from that login, but with no luck - though I\'d assume that once the URL has been retrieved it is temporarily available to anyone and doesn\'t require further authentication - can\'t find much in the way of documentation around the differences of setting s3_acl to private. \"\"\"','','Bug','Critical','Closed','Not Our Bug','2016-04-06 15:36:34','2016-04-06 15:36:34','2016-04-22 07:59:40','2017-03-24 18:54:01',3,NULL,227,227,22583,0,0,0,NULL,166197,166197,166526,12,4819);
INSERT INTO `Issue` VALUES (406741,159741,'TIMOB-23251','https://jira.appcelerator.org/rest/api/2/issue/159741','\"Windows: Modules do not build with \'appc run\'\"','\"Modules do not build when using {{appc run}}    {code}  appc new -t timodule -n module --id com.win.module  cd module\\windows  appc run -p windows --build-only  {code}    \"','\"\"\"Modules do not build when using {{appc run}}        \"\"\"','\"  appc new -t timodule -n module --id com.win.module  cd module\\windows  appc run -p windows --build-only  \"','Bug','Critical','Closed','Fixed','2016-04-20 20:03:20','2016-04-20 20:03:20','2016-04-21 14:51:08','2016-06-27 19:17:06',5,NULL,0,1119,1127,0,0,0,NULL,166018,166018,166018,12,4819);
INSERT INTO `Issue` VALUES (406744,159728,'TIMOB-23248','https://jira.appcelerator.org/rest/api/2/issue/159728','\"Windows: module project cmake generator should select VS version accordingly\"','\"Currently if you need to create module project for VS 2013, you need to run {{ti create -p windows -t module --wp-sdk 8.1}} . Unfortunately {{appc new --wp-sdk 8.1 ...}} doesn\'t work in this case. But basically Titanium CLI should be able to select appropriate VS version accordingly without demanding user input.    So on {{appc new}} or {{ti create}}, CLI should select VS version accordingly:    - When user installs VS 2013 only, cmake VS 2013 generator should be selected  - When user installs VS 2015 only, cmake VS 2015 generator should be selected  - When user installs both VS 2015 and VS 2013, cmake VS 2015 generator should be selected because it\'s newer    \"','\"\"\"Currently if you need to create module project for VS 2013, you need to run {{ti create -p windows -t module --wp-sdk 8.1}} . Unfortunately {{appc new --wp-sdk 8.1 ...}} doesn\'t work in this case. But basically Titanium CLI should be able to select appropriate VS version accordingly without demanding user input.    So on {{appc new}} or {{ti create}}, CLI should select VS version accordingly:    - When user installs VS 2013 only, cmake VS 2013 generator should be selected  - When user installs VS 2015 only, cmake VS 2015 generator should be selected  - When user installs both VS 2015 and VS 2013, cmake VS 2015 generator should be selected because it\'s newer    \"\"\"','','Bug','Critical','Closed','Fixed','2016-04-20 13:58:07','2016-04-20 13:58:07','2016-04-21 23:22:34','2016-05-25 20:30:41',5,NULL,633,1975,2004,0,0,0,NULL,166083,166083,166083,12,4819);
INSERT INTO `Issue` VALUES (406746,159725,'TIMOB-23246','https://jira.appcelerator.org/rest/api/2/issue/159725','\"Windows: Unable to create Module project\"','\"*Summary*    Creating module project doesn\'t work when Visual Studio 2015 is not installed.     *Steps to Reproduce*    Run {{appc new -n test --id com.example.test}} under the environment where Visual Studio 2015 is not installed.    *Expected Result*      - When user installs VS 2013 only, it shoud generate VS 2013 module project  - When user installs VS 2015 only, it should generate VS 2015 module project  - When user installs both VS 2015 and 2013, it should generate VS 2015 module project because it\'s newer    -------------------------------    Following the docs on creating a module (to be able to use background service or similar features) do not work. The error is that the module cannot be created due to this error:  {code}  PS Z:\\Users\\jorgenbuder\\Documents\\<USER>Studio_Workspace> appc new -n test --id com.example.test  <USER>Command-Line Interface, version 5.2.2  Copyright (c) 2014-2016, <USER> Inc.  All Rights Reserved.    ? What type of project are you creating? Titanium Module (timodule)  ? Do you want to overwrite? Yes  CMake Error at CMakeLists.txt:20 (project):    A Windows Phone component with CMake requires both the Windows Desktop SDK    as well as the Windows Phone \'8.1\' SDK.  Please make sure that you have    both installed  2016-04-20T11:06:42.061Z | ERROR  | titanium exited with non-zero exit code (1)  PS Z:\\Users\\jorgenbuder\\Documents\\<USER>Studio_Workspace>  {code}  This was not a problem when I tried crating a module poor to the new SDK 5.4.0.v20160419xxxxxx    Then again I did not use the same module create command, but this proposed method does not work. I want to ask you why the system complains about the when I indeed have Phone 8.1 installed. I create this bug on your request since this is stopping me to test the background service features you have added and is critical to us!    This is my setup:  {code}  Node:    v0.12.7    Appc info    PS Z:\\Users\\jorgenbuder\\Documents\\<USER>Studio_Workspace> appc info  <USER>Command-Line Interface, version 5.2.2  Copyright (c) 2014-2016, <USER> Inc.  All Rights Reserved.    Operating System    Name                        = Microsoft Windows 8.1 Pro    Version                     = 6.3.9600    Architecture                = 32bit    # CPUs                      = 4    Memory                      = 4.0GB    Node.js    Node.js Version             = 0.12.7    npm Version                 = 2.11.3    <USER>CLI    Installer                   = 4.2.4    Core Package                = 5.2.2    Titanium CLI    CLI Version                 = 5.0.6    node-appc Version           = 0.2.31    Titanium SDKs    5.4.0.v20160419234222      Version                   = 5.4.0      Install Location          = C:\\Users\\jorgenbuder\\Library\\Application Support\\Titanium\\mobilesdk\\win32\\5.4.0.v20160  9234222      Platforms                 = android, mobileweb, windows      git Hash                  = 743d79c      git Timestamp             = 04/19/16 23:42      node-appc Version         = 0.2.35    5.4.0.v20160418194101      Version                   = 5.4.0      Install Location          = C:\\Users\\jorgenbuder\\Library\\Application Support\\Titanium\\mobilesdk\\win32\\5.4.0.v20160  8194101      Platforms                 = android, mobileweb, windows      git Hash                  = ff3acd9      git Timestamp             = 04/18/16 19:41      node-appc Version         = 0.2.35    5.4.0.v20160406002717      Version                   = 5.4.0      Install Location          = Z:\\Users\\jorgenbuder\\Library\\Application Support\\Titanium\\mobilesdk\\win32\\5.4.0.v20160  6002717      Platforms                 = android, mobileweb, windows      git Hash                  = 3b4a229      git Timestamp             = 04/06/16 00:27      node-appc Version         = 0.2.35    5.4.0.v20160330202802      Version        