INSERT INTO `Issue` VALUES (406820,159347,'TIMOB-23159','https://jira.appcelerator.org/rest/api/2/issue/159347','\"Hyperloop: Android: Support inner classes\"','\"We currently dont support inner classes in Android (which we need for example when creating the builtins to check the target API level).\"','\"\"\"We currently dont support inner classes in Android (which we need for example when creating the builtins to check the target API level).\"\"\"','','Improvement','Critical','Closed','Fixed','2016-04-06 15:55:10','2016-04-06 15:55:10','2016-04-13 11:29:07','2016-07-14 21:51:58',5,NULL,0,9809,9813,0,0,0,NULL,166010,166010,166009,12,4819);
INSERT INTO `Issue` VALUES (406821,159344,'TIMOB-23158','https://jira.appcelerator.org/rest/api/2/issue/159344','\"Windows: Use of native module for UWP 10.0 fails\"','\"Enabling native module for Windows 10 app ({{--wp-sdk 10.0}}) causes build error. It is because Titanium CLI tries to link {{win10\\x86|arm\\XXX.lib}} but we don\'t build native module for {{win10}} target.    Let say you have created and installed your custom module named {{com.<USER>TIMOB23148}}.    {code:javascript}  var TIMOB23148 = require(\'com.<USER>TIMOB23148\');    var win = Ti.UI.createWindow({backgroundColor:\'green\'});    win.addEventListener(\'open\', function() {   Ti.API.info(typeof TIMOB23148);   Ti.API.info(Object.keys(TIMOB23148));   Ti.API.info(typeof TIMOB23148.myproperty);   Ti.API.info(typeof TIMOB23148.myfunction);  });  win.open();  {code}    This causes error when you build against {{--wp-sdk 10.0}}    {code}  ti build --platform windows --target ws-local --wp-sdk 10.0    [ERROR] LINK : fatal error LNK1181: cannot open input file \'C:\\ProgramData\\Application Data\\Titanium\\modules\\windows\\com.<USER>TIMOB23148\\1.0.0\\win10\\x86\\ComAppceleratorTIMOB23148.lib\' [TitaniumWindows_Native.vcxproj]  {code}  \"','\"\"\"Enabling native module for Windows 10 app ({{--wp-sdk 10.0}}) causes build error. It is because Titanium CLI tries to link {{win10\\x86|arm\\XXX.lib}} but we don\'t build native module for {{win10}} target.    Let say you have created and installed your custom module named {{com.<USER>TIMOB23148}}.        This causes error when you build against {{--wp-sdk 10.0}}      \"\"\"','\"  var TIMOB23148 = require(\'com.appcelerator.TIMOB23148\');    var win = Ti.UI.createWindow({backgroundColor:\'green\'});    win.addEventListener(\'open\', function() {   Ti.API.info(typeof TIMOB23148);   Ti.API.info(Object.keys(TIMOB23148));   Ti.API.info(typeof TIMOB23148.myproperty);   Ti.API.info(typeof TIMOB23148.myfunction);  });  win.open();    ti build --platform windows --target ws-local --wp-sdk 10.0    [ERROR] LINK : fatal error LNK1181: cannot open input file \'C:\\ProgramData\\Application Data\\Titanium\\modules\\windows\\com.appcelerator.TIMOB23148\\1.0.0\\win10\\x86\\ComAppceleratorTIMOB23148.lib\' [TitaniumWindows_Native.vcxproj]  \"','Bug','Critical','Closed','Fixed','2016-04-06 09:32:33','2016-04-06 09:32:33','2016-04-11 20:37:34','2016-06-30 17:21:25',8,NULL,639,6865,7865,0,0,0,NULL,166083,166083,166083,12,4819);
INSERT INTO `Issue` VALUES (406826,159281,'TIMOB-23150','https://jira.appcelerator.org/rest/api/2/issue/159281','\"EventListener issues in ScrollableView for IOS.\"','\"Hello,    Inside ScrollableView, i have added two views including some views & images. Their is a TableView & its rows in which scrollview is added.    Also i have added some EventListener\'s on images which are not executed in case of IOS. It\'s working perfectly on Android.     {code:java}  var args = $.args;    var table = Ti.UI.createTableView({   editable : \'true\',   // editing : \'true\',   //id : \'table\',   layout : \"\"vertical\"\",   separatorColor : \"\"#1268b3\"\"  });    var tableData = [];  var i, row, header;    for ( i = 0; i < 10; i++) {     row = Ti.UI.createTableViewRow({    id : i,    layout : \'horizontal\',    color : \'#0066cc\',    height : \'55\'   });     var dataView = Ti.UI.createView({    layout : \'horizontal\',    top : \'0\'   });     var textHolderView = Ti.UI.createView({    layout : \'vertical\',    width : \'50%\'   });     var iconView = Ti.UI.createView({    layout : \'horizontal\',    width : \'24.5%\' //35dp   });     header = Ti.UI.createLabel({       text : \"\"Some Text\"\"+i,       font : {        fontSize : \'12dp\',        fontFamily : \'OpenSans-Semibold\',        fontWeight : \'normal\'       },       height : \'38dp\',       left : \'15%\',            color : \'#000\',       width : \'85%\',       touchEnabled : false,       //borderColor:\"\"black\"\"      });         var image1 = Ti.UI.createImageView({    image : \"\"/images/individual.png\"\",    height : \'18dp\',    left : \'5dp\',    width : \'13%\',    top : \'25%\'    });     var slideOptionsView = Ti.UI.createView({    backgroundColor : \"\"#1268b3\"\",    layout : \"\"horizontal\"\"   });      var img_activity = Ti.UI.createImageView({    image : \"\"/images/activity_temp.png\"\",    height : \"\"30dp\"\",    width : \"\"70dp\"\",    left : \"\"10%\"\",    top : \"\"15dp\"\",    touchEnabled:true   });      textHolderView.add(header);   iconView.add(image1);   dataView.add(textHolderView);   dataView.add(iconView);      slideOptionsView.add(img_activity);      var scroll = Ti.UI.createScrollableView({       views : [dataView, slideOptionsView],       showPagingControl : false,           });       row.add(scroll);   tableData.push(row);   table.setData(tableData);       // Event Listeners on click event for above images   img_activity.addEventListener(\'click\', function(e) {    alert(\"\"img_activity\"\");   });       image1.addEventListener(\'click\', function(e) {    alert(\"\"image1\"\");   });   }    $.visitView.add(table);  $.index.open();  {code}      Attached some screenshots & files below.    *Versions Used:*  SDK 5.2.1.GA  CLI 5.2.1    Thanks.      Note:  I gave a try by removing TableView & row from above code.  Problem lies with ScrollableView where Listeners are not getting called on click of any image. Scroll & other Listener events are working fine.        {code:java}  // var table = Ti.UI.createTableView({   // id : \'table\',   // layout : \"\"vertical\"\",   // separatorColor : \"\"#1268b3\"\"  // });    var tableData = [];  var i,  header;      // var row = Ti.UI.createTableViewRow({   // id : i,   // layout : \'horizontal\',   // color : \'#0066cc\',   // height : \'55\'  // });    var dataView = Ti.UI.createView({   layout : \'horizontal\',   top : \'0\'  });    var textHolderView = Ti.UI.createView({   layout : \'vertical\',   width : \'50%\'  });    var iconView = Ti.UI.createView({   layout : \'horizontal\',   width : \'24.5%\' //35dp  });    header = Ti.UI.createLabel({   text : \"\"Some Text\"\",   font : {    fontSize : \'12dp\',    fontFamily : \'OpenSans-Semibold\',    fontWeight : \'normal\'   },   height : \'38dp\',   left : \'15%\',   color : \'#000\',   width : \'85%\',   touchEnabled : false,   //borderColor:\"\"black\"\"  });    var image1 = Ti.UI.createImageView({   image : \"\"/images/individual.png\"\",   height : \'18dp\',   left : \'5dp\',   width : \'13%\',   top : \'25%\'  });    var slideOptionsView = Ti.UI.createView({   backgroundColor : \"\"#1268b3\"\",   layout : \"\"horizontal\"\"  });    var img_activity = Ti.UI.createImageView({   image : \"\"/images/activity_temp.png\"\",   height : \"\"30dp\"\",   width : \"\"70dp\"\",   left : \"\"10%\"\",   top : \"\"15dp\"\",   touchEnabled : true  });    textHolderView.add(header);  iconView.add(image1);  dataView.add(textHolderView);  dataView.add(iconView);    slideOptionsView.add(img_activity);    var scroll = Ti.UI.createScrollableView({   views : [dataView, slideOptionsView],   showPagingControl : false,  });    // row.add(scroll);  // tableData.push(row);  // table.setData(tableData);    // Event Listeners on click for above images  // img_activity.addEventListener(\'click\', function(e) {   // alert(\"\"img_activity\"\");  // });    Ti.API.info(i);     // scroll.addEventListener(\'click\', function(e){    // alert(JSON.stringify(e.source));   // });    image1.addEventListener(\'click\', function(e) {   alert(\"\"image1\"\");  });  //table  $.someView.add(scroll);     $.index.open();  {code}\"','\"\"\"Hello,    Inside ScrollableView, i have added two views including some views & images. Their is a TableView & its rows in which scrollview is added.    Also i have added some EventListener\'s on images which are not executed in case of IOS. It\'s working perfectly on Android.           Attached some screenshots & files below.    *Versions Used:*  SDK 5.2.1.GA  CLI 5.2.1    Thanks.      Note:  I gave a try by removing TableView & row from above code.  Problem lies with ScrollableView where Listeners are not getting called on click of any image. Scroll & other Listener events are working fine.        \"\"\"','\"  var args = $.args;    var table = Ti.UI.createTableView({   editable : \'true\',   // editing : \'true\',   //id : \'table\',   layout : \"\"\"\"vertical\"\"\"\",   separatorColor : \"\"\"\"#1268b3\"\"\"\"  });    var tableData = [];  var i, row, header;    for ( i = 0; i < 10; i++) {     row = Ti.UI.createTableViewRow({    id : i,    layout : \'horizontal\',    color : \'#0066cc\',    height : \'55\'   });     var dataView = Ti.UI.createView({    layout : \'horizontal\',    top : \'0\'   });     var textHolderView = Ti.UI.createView({    layout : \'vertical\',    width : \'50%\'   });     var iconView = Ti.UI.createView({    layout : \'horizontal\',    width : \'24.5%\' //35dp   });     header = Ti.UI.createLabel({       text : \"\"\"\"Some Text\"\"\"\"+i,       font : {        fontSize : \'12dp\',        fontFamily : \'OpenSans-Semibold\',        fontWeight : \'normal\'       },       height : \'38dp\',       left : \'15%\',            color : \'#000\',       width : \'85%\',       touchEnabled : false,       //borderColor:\"\"\"\"black\"\"\"\"      });         var image1 = Ti.UI.createImageView({    image : \"\"\"\"/images/individual.png\"\"\"\",    height : \'18dp\',    left : \'5dp\',    width : \'13%\',    top : \'25%\'    });     var slideOptionsView = Ti.UI.createView({    backgroundColor : \"\"\"\"#1268b3\"\"\"\",    layout : \"\"\"\"horizontal\"\"\"\"   });      var img_activity = Ti.UI.createImageView({    image : \"\"\"\"/images/activity_temp.png\"\"\"\",    height : \"\"\"\"30dp\"\"\"\",    width : \"\"\"\"70dp\"\"\"\",    left : \"\"\"\"10%\"\"\"\",    top : \"\"\"\"15dp\"\"\"\",    touchEnabled:true   });      textHolderView.add(header);   iconView.add(image1);   dataView.add(textHolderView);   dataView.add(iconView);      slideOptionsView.add(img_activity);      var scroll = Ti.UI.createScrollableView({       views : [dataView, slideOptionsView],       showPagingControl : false,           });       row.add(scroll);   tableData.push(row);   table.setData(tableData);       // Event Listeners on click event for above images   img_activity.addEventListener(\'click\', function(e) {    alert(\"\"\"\"img_activity\"\"\"\");   });       image1.addEventListener(\'click\', function(e) {    alert(\"\"\"\"image1\"\"\"\");   });   }    $.visitView.add(table);  $.index.open();    // var table = Ti.UI.createTableView({   // id : \'table\',   // layout : \"\"\"\"vertical\"\"\"\",   // separatorColor : \"\"\"\"#1268b3\"\"\"\"  // });    var tableData = [];  var i,  header;      // var row = Ti.UI.createTableViewRow({   // id : i,   // layout : \'horizontal\',   // color : \'#0066cc\',   // height : \'55\'  // });    var dataView = Ti.UI.createView({   layout : \'horizontal\',   top : \'0\'  });    var textHolderView = Ti.UI.createView({   layout : \'vertical\',   width : \'50%\'  });    var iconView = Ti.UI.createView({   layout : \'horizontal\',   width : \'24.5%\' //35dp  });    header = Ti.UI.createLabel({   text : \"\"\"\"Some Text\"\"\"\",   font : {    fontSize : \'12dp\',    fontFamily : \'OpenSans-Semibold\',    fontWeight : \'normal\'   },   height : \'38dp\',   left : \'15%\',   color : \'#000\',   width : \'85%\',   touchEnabled : false,   //borderColor:\"\"\"\"black\"\"\"\"  });    var image1 = Ti.UI.createImageView({   image : \"\"\"\"/images/individual.png\"\"\"\",   height : \'18dp\',   left : \'5dp\',   width : \'13%\',   top : \'25%\'  });    var slideOptionsView = Ti.UI.createView({   backgroundColor : \"\"\"\"#1268b3\"\"\"\",   layout : \"\"\"\"horizontal\"\"\"\"  });    var img_activity = Ti.UI.createImageView({   image : \"\"\"\"/images/activity_temp.png\"\"\"\",   height : \"\"\"\"30dp\"\"\"\",   width : \"\"\"\"70dp\"\"\"\",   left : \"\"\"\"10%\"\"\"\",   top : \"\"\"\"15dp\"\"\"\",   touchEnabled : true  });    textHolderView.add(header);  iconView.add(image1);  dataView.add(textHolderView);  dataView.add(iconView);    slideOptionsView.add(img_activity);    var scroll = Ti.UI.createScrollableView({   views : [dataView, slideOptionsView],   showPagingControl : false,  });    // row.add(scroll);  // tableData.push(row);  // table.setData(tableData);    // Event Listeners on click for above images  // img_activity.addEventListener(\'click\', function(e) {   // alert(\"\"\"\"img_activity\"\"\"\");  // });    Ti.API.info(i);     // scroll.addEventListener(\'click\', function(e){    // alert(JSON.stringify(e.source));   // });    image1.addEventListener(\'click\', function(e) {   alert(\"\"\"\"image1\"\"\"\");  });  //table  $.someView.add(scroll);     $.index.open();  \"','Bug','High','Closed','Fixed','2016-04-04 08:11:34','2016-04-04 08:11:34','2016-04-13 18:04:49','2016-06-09 22:47:15',5,NULL,0,9809,13553,0,0,0,NULL,166319,166319,166550,12,4819);
INSERT INTO `Issue` VALUES (406828,159311,'TIMOB-23148','https://jira.appcelerator.org/rest/api/2/issue/159311','\"Windows: Native module How-To documentation\"','\"There\'s no documentation about how to create native module on Windows. Related: [How to call a method added to the windows native module of Appelerator Platform|http://stackoverflow.com/questions/36213930/how-to-call-a-method-added-to-the-windows-native-module-of-appelerator-platform]  \"','\"\"\"There\'s no documentation about how to create native module on Windows. Related: [How to call a method added to the windows native module of Appelerator Platform|http://stackoverflow.com/questions/36213930/how-to-call-a-method-added-to-the-windows-native-module-of-appelerator-platform]  \"\"\"','','Story','Medium','Closed','Done','2016-04-05 12:22:32','2016-04-05 12:22:32','2016-04-15 04:30:21','2016-04-15 04:30:21',5,NULL,0,0,13927,1,0,0,NULL,166083,166083,166083,12,4819);
INSERT INTO `Issue` VALUES (406832,159296,'TIMOB-23144','https://jira.appcelerator.org/rest/api/2/issue/159296','\"Hyperloop iOS - Example project crashing on device\"','\"Swift files not compiling for device, if ignored, the app will crash on one of the examples.\"','\"\"\"Swift files not compiling for device, if ignored, the app will crash on one of the examples.\"\"\"','','Bug','Critical','Closed','Fixed','2016-04-04 21:46:53','2016-04-04 21:46:53','2016-04-21 04:42:19','2016-07-26 16:53:37',5,NULL,21846,22982,23455,0,0,0,NULL,166620,166620,166198,12,4819);
INSERT INTO `Issue` VALUES (406833,159293,'TIMOB-23143','https://jira.appcelerator.org/rest/api/2/issue/159293','\"Windows: Lock orientation mode (Ti.UI.Window.orientationModes)\"','\"h6. Issue Description   Actually in windows there is no way to lock the orientation mode in portrait or landscape.    h6. Expected Behavior   Have a property in the window to lock the orientation.  \"','\"\"\"h6. Issue Description   Actually in windows there is no way to lock the orientation mode in portrait or landscape.    h6. Expected Behavior   Have a property in the window to lock the orientation.  \"\"\"','','New Feature','Critical','Closed','Fixed','2016-04-04 20:11:36','2016-04-04 20:11:36','2016-04-11 20:35:31','2016-06-24 16:40:47',5,NULL,0,913,10103,1,0,0,NULL,166197,166197,166083,12,4819);
INSERT INTO `Issue` VALUES (406836,159267,'TIMOB-23140','https://jira.appcelerator.org/rest/api/2/issue/159267','\"Android: Add lineSpacing property to Label\"','\"Add   {noformat}  lineSpacing: {add: float, multiply: float}  {noformat}     to Label    !http://migaweb.de/linespacing.png!    Android doc: http://developer.android.com/reference/android/widget/TextView.html#setLineSpacing%28float,%20float%29    *Example:*  {code:javascript}  var win = $.UI.create(\"\"Window\"\", {      layout: \"\"vertical\"\",      backgroundColor: \"\"#fff\"\"  });    var l = $.UI.create(\"\"Label\"\", {      lineSpacing: {          add: 20,          multiply: 1      },      text: \"\"asdfasdfasdf\\nasfasfasfasfafsd\\nasfasfasdfasdf\\nadsfasdfasdf\"\",      height: Ti.UI.SIZE,      width: Ti.UI.SIZE,      backgroundColor:\"\"red\"\"  });    var l2 = $.UI.create(\"\"Label\"\", {      lineSpacing: {          add: 0,          multiply: 1      },      text: \"\"qwerqwerqwer\\nqwerqwer\\nqwerqwerqwe\\nqwerqwerqwre\"\",      height: Ti.UI.SIZE,      width: Ti.UI.SIZE,      backgroundColor:\"\"green\"\"  });    var l3 = $.UI.create(\"\"Label\"\", {      lineSpacing: {          add: 10,          multiply: 0      },      text: \"\"yxcvyxcyvx\\nycxvyxcvyxc\\nyxvcyxcvyxcv\\nyxcvyxvyxc\\nyxcvyxcvyx\"\",      height: Ti.UI.SIZE,      width: Ti.UI.SIZE,      backgroundColor:\"\"yellow\"\"  });    win.add(l);  win.add(l2);  win.add(l3);  win.open();  {code}\"','\"\"\"Add        to Label    !http://migaweb.de/linespacing.png!    Android doc: http://developer.android.com/reference/android/widget/TextView.html#setLineSpacing%28float,%20float%29    *Example:*  \"\"\"','\"  lineSpacing: {add: float, multiply: float}    var win = $.UI.create(\"\"\"\"Window\"\"\"\", {      layout: \"\"\"\"vertical\"\"\"\",      backgroundColor: \"\"\"\"#fff\"\"\"\"  });    var l = $.UI.create(\"\"\"\"Label\"\"\"\", {      lineSpacing: {          add: 20,          multiply: 1      },      text: \"\"\"\"asdfasdfasdf\\nasfasfasfasfafsd\\nasfasfasdfasdf\\nadsfasdfasdf\"\"\"\",      height: Ti.UI.SIZE,      width: Ti.UI.SIZE,      backgroundColor:\"\"\"\"red\"\"\"\"  });    var l2 = $.UI.create(\"\"\"\"Label\"\"\"\", {      lineSpacing: {          add: 0,          multiply: 1      },      text: \"\"\"\"qwerqwerqwer\\nqwerqwer\\nqwerqwerqwe\\nqwerqwerqwre\"\"\"\",      height: Ti.UI.SIZE,      width: Ti.UI.SIZE,      backgroundColor:\"\"\"\"green\"\"\"\"  });    var l3 = $.UI.create(\"\"\"\"Label\"\"\"\", {      lineSpacing: {          add: 10,          multiply: 0      },      text: \"\"\"\"yxcvyxcyvx\\nycxvyxcvyxc\\nyxvcyxcvyxcv\\nyxcvyxvyxc\\nyxcvyxcvyx\"\"\"\",      height: Ti.UI.SIZE,      width: Ti.UI.SIZE,      backgroundColor:\"\"\"\"yellow\"\"\"\"  });    win.add(l);  win.add(l2);  win.add(l3);  win.open();  \"','New Feature','Critical','Closed','Fixed','2016-04-02 15:52:00','2016-04-02 15:52:00','2016-04-06 11:41:16','2016-05-27 21:02:02',1,NULL,0,0,5509,0,0,0,NULL,166025,166025,166526,12,4819);
INSERT INTO `Issue` VALUES (406869,155870,'TIMOB-20620','https://jira.appcelerator.org/rest/api/2/issue/155870','\"Android: Annotation.pincolor can\'t be changed if annotation added to mapView.\"','\"I am not sure if it is a bug or it needs improvement.    If annotation is created than changing it\'s pincolor by  {code}  annotation.pincolor = mapModule.ANNOTATION_AZURE;  //or  annotation.setPincolor =  mapModule.ANNOTATION_AZURE;  {code}  won\'t change annotation color unless it is removed and added again to mapView.\"','\"\"\"I am not sure if it is a bug or it needs improvement.    If annotation is created than changing it\'s pincolor by    won\'t change annotation color unless it is removed and added again to mapView.\"\"\"','\"  annotation.pincolor = mapModule.ANNOTATION_AZURE;  //or  annotation.setPincolor =  mapModule.ANNOTATION_AZURE;  \"','Bug','Critical','Closed','Fixed','2016-03-21 21:23:04','2016-03-21 21:23:04','2016-04-13 05:51:01','2017-03-31 22:04:43',5,NULL,1,2765,32187,1,0,0,NULL,166273,166273,166650,12,4819);
INSERT INTO `Issue` VALUES (406877,155881,'TIMOB-20611','https://jira.appcelerator.org/rest/api/2/issue/155881','\"Windows: Inform user of the need to open the app manually on device when building to Windows 10 mobile\"','\"h5.Description    When building to a Windows 10 Mobile device the app no longer open automatically as it did when building for 8.1, we should therefore inform the user of the need to open the app themselves similar to iOS    h5.Steps to reproduce    1. Build to a Windows 10 mobile device using {{appc run -p windows -T wp-device -S 10.0}}    h5.Actual result    The following will be logged, the user will not be informed of the need to open the app themselves    {code}  [INFO]  Finished building the application in 1m 8s 283ms  [INFO]  Finished building the application in 1m 9s 870ms  [INFO]  Installing and launching the application  [INFO]  Project built successfully in 1m 11s 72ms  **User opens app**  [INFO]  Finished launching the application  [INFO]  Waiting for app to connect to log relay  {code}    h5.Expected result    We should inform the user of the need to open the app on the device, similar to iOS\"','\"\"\"h5.Description    When building to a Windows 10 Mobile device the app no longer open automatically as it did when building for 8.1, we should therefore inform the user of the need to open the app themselves similar to iOS    h5.Steps to reproduce    1. Build to a Windows 10 mobile device using {{appc run -p windows -T wp-device -S 10.0}}    h5.Actual result    The following will be logged, the user will not be informed of the need to open the app themselves        h5.Expected result    We should inform the user of the need to open the app on the device, similar to iOS\"\"\"','\"  [INFO]  Finished building the application in 1m 8s 283ms  [INFO]  Finished building the application in 1m 9s 870ms  [INFO]  Installing and launching the application  [INFO]  Project built successfully in 1m 11s 72ms  **User opens app**  [INFO]  Finished launching the application  [INFO]  Waiting for app to connect to log relay  \"','Improvement','Medium','Closed','Fixed','2016-03-22 00:45:17','2016-03-22 00:45:17','2016-04-27 20:36:25','2016-04-28 23:48:57',3,NULL,9195,12945,53031,0,0,0,NULL,166007,166007,166009,12,4819);
INSERT INTO `Issue` VALUES (406881,155862,'TIMOB-20607','https://jira.appcelerator.org/rest/api/2/issue/155862','\"Windows: Move Source/Ti/src/Properties.cpp to Source/Ti/src/App/Properties.cpp\"','\"The files just lives in the wrong place on the filesystem compared to it\'s header and namespace.\"','\"\"\"The files just lives in the wrong place on the filesystem compared to it\'s header and namespace.\"\"\"','','Story','Low','Closed','Fixed','2016-03-21 13:41:02','2016-03-21 13:41:02','2016-04-12 17:58:24','2017-03-16 22:01:10',1,NULL,2,177,31937,0,0,0,NULL,166009,166009,166009,12,4819);
INSERT INTO `Issue` VALUES (406909,155750,'TIMOB-20575','https://jira.appcelerator.org/rest/api/2/issue/155750','\"Windows: no way to hide listview\'s section header and section header catch itemclick event\"','\"1. On android and ios if you don\'t set section header\'s title, then header is invisible. But not on Windows phone. Section header takes its place on screen as empty rectangle.  2. This rectangle catches \'itemclick\' event with e.itemIndex == -1.\"','\"\"\"1. On android and ios if you don\'t set section header\'s title, then header is invisible. But not on Windows phone. Section header takes its place on screen as empty rectangle.  2. This rectangle catches \'itemclick\' event with e.itemIndex == -1.\"\"\"','','Bug','Critical','Closed','Fixed','2016-03-15 17:52:52','2016-03-15 17:52:52','2016-04-11 23:04:28','2016-06-27 19:05:27',5,NULL,85,85,39191,0,0,0,NULL,166324,166324,166018,12,4819);
INSERT INTO `Issue` VALUES (406910,155759,'TIMOB-20572','https://jira.appcelerator.org/rest/api/2/issue/155759','\"Windows: Windows 10 Mobile device is listed as available to build to when not connected by USB\"','\"h5.Description    When a device is not connected to a PC but its on the same network as the PC, when building a project for wp-device then it will still show up as available. This is because the utility used to obtain the device information, WinAppDeploy, supports deployment of an app over wifi and therefore will detect devices on wifi. See the below output for the differences between the output.    However, I believe that for this to happen the device needs to have \'Device Discovery\' in \'For Developers\' enabled. I am not sure whether this is enabled by default.    It is possible to deploy to a device over the network, but as far as I know this is not supported yet so for now we should filter devices that are displayed by the tool but appear to be connected over the network.    {code: title=Connected via USB}  C:\\Users\\ewanh>\"\"C:\\Program Files (x86)\\Windows Kits\\10\\bin\\x86\\WinAppDeployCmd.exe\"\" devices  Windows App Deployment Tool  Version 10.0.0.0  Copyright (c) Microsoft Corporation. All rights reserved.    Discovering devices...  IP Address      GUID                                    Model/Name  127.0.0.1       00000015-4e57-1877-0000-000000000000    Lumia 930 (RM-1045)  {code}      {code: title=On same network}  C:\\Users\\ewanh>\"\"C:\\Program Files (x86)\\Windows Kits\\10\\bin\\x86\\WinAppDeployCmd.exe\"\" devices  Windows App Deployment Tool  Version 10.0.0.0  Copyright (c) Microsoft Corporation. All rights reserved.    Discovering devices...  IP Address      GUID                                    Model/Name  192.168.2.10    00000015-4e57-1877-0000-000000000000    Lumia930  {code}    h5.Steps to reproduce    1. Connect a device by USB and run {{\"\"C:\\Program Files (x86)\\Windows Kits\\10\\bin\\x86\\WinAppDeployCmd.exe\"\" devices}}  2. Run {{appc run -p windows -T wp-device}}  3. Disconnect the USB and ensure the device is on the same network as your PC  4. Run {{appc run -p windows -T wp-device}}    h5.Actual result    2. The device will be shown  4. The device will be shown    h5.Expected result    The device should only be shown when the device is able to be built to, ie connected by USB\"','\"\"\"h5.Description    When a device is not connected to a PC but its on the same network as the PC, when building a project for wp-device then it will still show up as available. This is because the utility used to obtain the device information, WinAppDeploy, supports deployment of an app over wifi and therefore will detect devices on wifi. See the below output for the differences between the output.    However, I believe that for this to happen the device needs to have \'Device Discovery\' in \'For Developers\' enabled. I am not sure whether this is enabled by default.    It is possible to deploy to a device over the network, but as far as I know this is not supported yet so for now we should filter devices that are displayed by the tool but appear to be connected over the network.    {code: title=Connected via USB}  C:\\Users\\ewanh>\"\"\"\"C:\\Program Files (x86)\\Windows Kits\\10\\bin\\x86\\WinAppDeployCmd.exe\"\"\"\" devices  Windows App Deployment Tool  Version 10.0.0.0  Copyright (c) Microsoft Corporation. All rights reserved.    Discovering devices...  IP Address      GUID                                    Model/Name  127.0.0.1       00000015-4e57-1877-0000-000000000000    Lumia 930 (RM-1045)      h5.Steps to reproduce    1. Connect a device by USB and run {{\"\"\"\"C:\\Program Files (x86)\\Windows Kits\\10\\bin\\x86\\WinAppDeployCmd.exe\"\"\"\" devices}}  2. Run {{appc run -p windows -T wp-device}}  3. Disconnect the USB and ensure the device is on the same network as your PC  4. Run {{appc run -p windows -T wp-device}}    h5.Actual result    2. The device will be shown  4. The device will be shown    h5.Expected result    The device should only be shown when the device is able to be built to, ie connected by USB\"\"\"','\"  C:\\Users\\ewanh>\"\"\"\"C:\\Program Files (x86)\\Windows Kits\\10\\bin\\x86\\WinAppDeployCmd.exe\"\"\"\" devices  Windows App Deployment Tool  Version 10.0.0.0  Copyright (c) Microsoft Corporation. All rights reserved.    Discovering devices...  IP Address      GUID                                    Model/Name  127.0.0.1       00000015-4e57-1877-0000-000000000000    Lumia 930 (RM-1045)    C:\\Users\\ewanh>\"\"\"\"C:\\Program Files (x86)\\Windows Kits\\10\\bin\\x86\\WinAppDeployCmd.exe\"\"\"\" devices  Windows App Deployment Tool  Version 10.0.0.0  Copyright (c) Microsoft Corporation. All rights reserved.    Discovering devices...  IP Address      GUID                                    Model/Name  192.168.2.10    00000015-4e57-1877-0000-000000000000    Lumia930  \"','Bug','None','Closed','Fixed','2016-03-16 02:25:40','2016-03-16 02:25:40','2016-04-15 13:49:25','2016-04-20 18:52:13',5,NULL,8,1311,43883,1,0,0,NULL,166007,166007,166018,12,4819);
INSERT INTO `Issue` VALUES (406911,155756,'TIMOB-20571','https://jira.appcelerator.org/rest/api/2/issue/155756','\"Windows: Improve the detection of the Windows SDK used to build a project\"','\"h5.Description    Currently when building a project the default SDK used will be 8.1, this means that if a user simply runs {{appc run -p windows -T wp-emulator}} then they will only be shown Windows 8.1 emulators, in order to be shown Windows 10 mobile emulators a user must run {{appc run -p windows -T wp-emulator -S 10.0}}. The CLI should show a user all possible emulators and then determine which Windows SDK is needed to build based off the choice made by the user.     h5.Steps to reproduce    1. Run {{appc run -p windows -T wp-emulator}}    h5.Actual result    You will be prompted to select from only 8.1 emulators    h5.Expected reult    You should be prompted to select from all possible emulators\"','\"\"\"h5.Description    Currently when building a project the default SDK used will be 8.1, this means that if a user simply runs {{appc run -p windows -T wp-emulator}} then they will only be shown Windows 8.1 emulators, in order to be shown Windows 10 mobile emulators a user must run {{appc run -p windows -T wp-emulator -S 10.0}}. The CLI should show a user all possible emulators and then determine which Windows SDK is needed to build based off the choice made by the user.     h5.Steps to reproduce    1. Run {{appc run -p windows -T wp-emulator}}    h5.Actual result    You will be prompted to select from only 8.1 emulators    h5.Expected reult    You should be prompted to select from all possible emulators\"\"\"','','Improvement','High','Closed','Fixed','2016-03-15 20:21:39','2016-03-15 20:21:39','2016-04-14 14:28:17','2016-04-19 23:05:57',13,NULL,1454,2587,42846,0,0,1,NULL,166007,166007,166018,12,4819);
INSERT INTO `Issue` VALUES (406998,155113,'TIMOB-20467','https://jira.appcelerator.org/rest/api/2/issue/155113','\"Android: Titanium.UI.ProgressBar \'color\' property has no effect on text\"','\"The \'color\' property of Titanium.UI.ProgressBar does not effect the text. The text stays \"\"white\"\" and thus invisible to a white background. The \'color\' property only effects the color of the bar itself.\"','\"\"\"The \'color\' property of Titanium.UI.ProgressBar does not effect the text. The text stays \"\"\"\"white\"\"\"\" and thus invisible to a white background. The \'color\' property only effects the color of the bar itself.\"\"\"','','Bug','High','Closed','Fixed','2016-02-24 19:51:51','2016-02-24 19:51:51','2016-04-21 04:12:44','2016-06-10 21:57:07',8,NULL,0,1246,81140,1,0,0,NULL,166684,166684,166650,12,4819);
INSERT INTO `Issue` VALUES (407009,155098,'TIMOB-20453','https://jira.appcelerator.org/rest/api/2/issue/155098','\"5.3.0 Regression: \"\"rendering artifact\"\" between launch image and first view\"','\"With TIMOB-19694 we have implemented support for Storyboard Launch Files.    This causes a regression that even if you do *not* use Storyboard Launch Files you now see a \"\"rendering artifact\"\" between after the Launch Image is dismissed and the first view of the app opened. This is in particular visible in apps that need to do some heavy stuff before they open the first view.    The following sample and attached [video|https://jira.<USER>org/secure/attachment/58387/artifact.mov] demonstrates:    {code:js}  var win = Ti.UI.createWindow({    backgroundColor: \'green\'  });    // simulating a delay when you need to do heavy stuff before opening the first window  setTimeout(function() {    win.open();  }, 3000);  {code}    If you *do* use Storyboard Launch Files you see similar behaviour, which TIMOB-20497 deals with.\"','\"\"\"With TIMOB-19694 we have implemented support for Storyboard Launch Files.    This causes a regression that even if you do *not* use Storyboard Launch Files you now see a \"\"\"\"rendering artifact\"\"\"\" between after the Launch Image is dismissed and the first view of the app opened. This is in particular visible in apps that need to do some heavy stuff before they open the first view.    The following sample and attached [video|https://jira.<USER>org/secure/attachment/58387/artifact.mov] demonstrates:    {code:js}  var win = Ti.UI.createWindow({    backgroundColor: \'green\'  });    // simulating a delay when you need to do heavy stuff before opening the first window  setTimeout(function() {    win.open();  }, 3000);  {code}    If you *do* use Storyboard Launch Files you see similar behaviour, which TIMOB-20497 deals with.\"\"\"','\"  var win = Ti.UI.createWindow({    backgroundColor: \'green\'  });    // simulating a delay when you need to do heavy stuff before opening the first window  setTimeout(function() {    win.open();  }, 3000);  \"','Bug','Critical','Closed','Fixed','2016-02-24 12:51:27','2016-02-24 12:51:27','2016-08-03 03:36:51','2016-08-03 20:00:07',5,NULL,0,4922,231285,1,0,1,NULL,166377,166377,166010,12,4822);
INSERT INTO `Issue` VALUES (407049,154947,'TIMOB-20409','https://jira.appcelerator.org/rest/api/2/issue/154947','\"iOS: Add rest of stylus properties to 3D touch events\"','\"Add the azimuthAngleInView and azimuthUnitVectorInView. The properties only being available if using a stylus.\"','\"\"\"Add the azimuthAngleInView and azimuthUnitVectorInView. The properties only being available if using a stylus.\"\"\"','','Improvement','Medium','Closed','Fixed','2016-02-16 18:00:33','2016-02-16 18:00:33','2016-07-21 18:38:13','2016-10-05 23:35:51',2,NULL,0,21555,224677,1,0,1,NULL,166550,166550,166550,12,4822);
INSERT INTO `Issue` VALUES (407101,154749,'TIMOB-20350','https://jira.appcelerator.org/rest/api/2/issue/154749','\"Windows: Update parity report generation/docs to show support for missing items\"','\"I\'m not sure if this is a doc issue or a problem with the scripts we use to generate the parity report.    In any case, looking at http://builds.<USER>com/mobile/master/mobilesdk-6.0.0.v20160203193439-parity.html I\'m seeing some APIs listed as unsupported though they really are:    - Global  - Modules.Cloud* (?)  - Titanium.BlobStream  - Titanium.BufferStream  - Titanium.Filesystem.FileStream  - Titanium.Map  - Titanium.Map.Annotation  - Titanium.Map.View  - Titanium.Module  - Titanium.Proxy  - Titanium.UI.AttributedString  - Titanium.UI.ListItem  - Titanium.UI.ListSection  - Titanium.UI.Picker  - Titanium.XML.CDATASection  - Titanium.XML.Comment  - Titanium.XML.DocumentFragment  - Titanium.XML.EntityReference  - Titanium.XML.Text\"','\"\"\"I\'m not sure if this is a doc issue or a problem with the scripts we use to generate the parity report.    In any case, looking at http://builds.<USER>com/mobile/master/mobilesdk-6.0.0.v20160203193439-parity.html I\'m seeing some APIs listed as unsupported though they really are:    - Global  - Modules.Cloud* (?)  - Titanium.BlobStream  - Titanium.BufferStream  - Titanium.Filesystem.FileStream  - Titanium.Map  - Titanium.Map.Annotation  - Titanium.Map.View  - Titanium.Module  - Titanium.Proxy  - Titanium.UI.AttributedString  - Titanium.UI.ListItem  - Titanium.UI.ListSection  - Titanium.UI.Picker  - Titanium.XML.CDATASection  - Titanium.XML.Comment  - Titanium.XML.DocumentFragment  - Titanium.XML.EntityReference  - Titanium.XML.Text\"\"\"','','Story','High','Closed','Done','2016-02-04 17:16:05','2016-02-04 17:16:05','2016-08-04 02:44:25','2018-10-10 16:30:04',5,NULL,99481,102420,261208,1,0,0,NULL,166009,166009,166009,12,4819);
INSERT INTO `Issue` VALUES (407109,154687,'TIMOB-20320','https://jira.appcelerator.org/rest/api/2/issue/154687','\"Android: Provide generic requestPermission(s) method\"','\"We need a generic method to request permissions that our own APIs do not use.    I know we\'ve discussed this and thought this was best to leave this to the modules that require them, but there are multiple reasons for having a generic one instead:    * So that module doesn\'t come up with different ways (method name, method arguments, callback/event response and payload)  * So that developers don\'t need to rely on maintainers of 3rd party modules to update their modules to support Android 6.0 runtime permissions    Also see the discussion in TIMOB-20144\"','\"\"\"We need a generic method to request permissions that our own APIs do not use.    I know we\'ve discussed this and thought this was best to leave this to the modules that require them, but there are multiple reasons for having a generic one instead:    * So that module doesn\'t come up with different ways (method name, method arguments, callback/event response and payload)  * So that developers don\'t need to rely on maintainers of 3rd party modules to update their modules to support Android 6.0 runtime permissions    Also see the discussion in TIMOB-20144\"\"\"','','Improvement','High','Closed','Fixed','2016-02-03 17:22:12','2016-02-03 17:22:12','2016-04-19 02:39:33','2016-07-04 08:33:29',3,NULL,0,5921,108557,0,0,0,NULL,166377,166377,166600,12,4819);
INSERT INTO `Issue` VALUES (407147,154535,'TIMOB-20279','https://jira.appcelerator.org/rest/api/2/issue/154535','\"Android: Ti.Contacts.getAllPeople() crashes with overflow on Android < 6\"','\"I am getting the “[ERROR] dalvikvm: JNI ERROR (app bug): local reference table overflow (max=512)” issue when simply calling Ti.Contacts.getAllPeople(). Literally, that ONE line of code is causing the error.    * I have 2900 contacts (and I know plenty of people with more), so I am not an abnormal use case.  * I know it is this one line because I have removed any other code around it (after the permissions of course), and the call works on Android 6.0+, but does not work on versions prior to Android 6.0.  * It works perfectly fine when I run it against an emulator with 0 contacts, or even 5 contacts. I suspect that it is not releasing the memory when it iterates over the contacts that it is retrieving.    The environments that I tested this on were:  1. Multiple Android emulators, but they all follow the same specs (besides the screen size) as the attached image shows  2. On a Galaxy S4 running Android 4.4.2    Here is a snippet of the code:    {code:javascript}  // Get permission to access the user\'s contacts  var contactsAuthorizationValue = Ti.Contacts.getContactsAuthorization();    if (contactsAuthorizationValue === Ti.Contacts.AUTHORIZATION_AUTHORIZED) {  var rawContacts = Ti.Contacts.getAllPeople(); // This is where the crash occurs    // Do more things down here  }  {code}\"','\"\"\"I am getting the “[ERROR] dalvikvm: JNI ERROR (app bug): local reference table overflow (max=512)” issue when simply calling Ti.Contacts.getAllPeople(). Literally, that ONE line of code is causing the error.    * I have 2900 contacts (and I know plenty of people with more), so I am not an abnormal use case.  * I know it is this one line because I have removed any other code around it (after the permissions of course), and the call works on Android 6.0+, but does not work on versions prior to Android 6.0.  * It works perfectly fine when I run it against an emulator with 0 contacts, or even 5 contacts. I suspect that it is not releasing the memory when it iterates over the contacts that it is retrieving.    The environments that I tested this on were:  1. Multiple Android emulators, but they all follow the same specs (besides the screen size) as the attached image shows  2. On a Galaxy S4 running Android 4.4.2    Here is a snippet of the code:    \"\"\"','\"  // Get permission to access the user\'s contacts  var contactsAuthorizationValue = Ti.Contacts.getContactsAuthorization();    if (contactsAuthorizationValue === Ti.Contacts.AUTHORIZATION_AUTHORIZED) {  var rawContacts = Ti.Contacts.getAllPeople(); // This is where the crash occurs    // Do more things down here  }  \"','Bug','Critical','Closed','Fixed','2016-01-27 18:39:42','2016-01-27 18:39:42','2016-07-21 03:21:05','2016-07-26 16:54:16',2,NULL,0,0,252521,1,0,0,NULL,166457,166457,166526,12,4822);
INSERT INTO `Issue` VALUES (407217,154159,'TIMOB-20204','https://jira.appcelerator.org/rest/api/2/issue/154159','\"iOS: ListView - onload events of template items not fired\"','\"For iOS, {{onload}} event attached to any listview template items is not fired. It does fire for Android.    h5. Step to reproduce  1. Run attach app on iOS Simulator  2. Run attach app on on Android Emulator  3. Compare both results    h5. Expected Result  On 3rd row, images are animating for both OS    h5. Actual Result  On 3rd row, images are animating on Android, but not on iOS.    \"','\"\"\"For iOS, {{onload}} event attached to any listview template items is not fired. It does fire for Android.    h5. Step to reproduce  1. Run attach app on iOS Simulator  2. Run attach app on on Android Emulator  3. Compare both results    h5. Expected Result  On 3rd row, images are animating for both OS    h5. Actual Result  On 3rd row, images are animating on Android, but not on iOS.    \"\"\"','','Bug','High','Closed','Fixed','2016-01-06 23:11:35','2016-01-06 23:11:35','2016-07-27 08:03:26','2016-10-01 23:11:30',5,NULL,1,9597,291411,0,0,0,NULL,166201,166201,166010,12,4822);
INSERT INTO `Issue` VALUES (407322,153581,'TIMOB-20090','https://jira.appcelerator.org/rest/api/2/issue/153581','\"Android: Cardview doc requires changes\"','\"API in docs mention 5.2.0. Instead, since it is being released in 5.1.2, the docs need to reflect 5.1.2 instead for Cardview (Android).\"','\"\"\"API in docs mention 5.2.0. Instead, since it is being released in 5.1.2, the docs need to reflect 5.1.2 instead for Cardview (Android).\"\"\"','','Bug','Medium','Closed','Fixed','2015-12-03 02:14:33','2015-12-03 02:14:33','2015-12-03 02:46:06','2016-01-05 18:08:44',1,NULL,0,0,31,0,0,0,NULL,166526,166526,166526,12,4828);
INSERT INTO `Issue` VALUES (407323,153563,'TIMOB-20089','https://jira.appcelerator.org/rest/api/2/issue/153563','\"Android: setting a view layout to null crashes the app\"','\"When setting a view\'s layout to \"\"null\"\", the app completely crashes:    {code}  [ERROR] TiApplication: (main) [396,396] Sending event: exception on thread: main msg:java.lang.RuntimeException: Unable to start activity ComponentInfo{com.jolicode.testview/org.<USER>titanium.TiActivity}: java.lang.NullPointerException: Attempt to invoke virtual method \'boolean java.lang.String.equals(java.lang.Object)\' on a null object reference; Titanium 5.0.2,2015/09/30 12:07,92c2265  [ERROR] TiApplication: java.lang.RuntimeException: Unable to start activity ComponentInfo{com.jolicode.testview/org.<USER>titanium.TiActivity}: java.lang.NullPointerException: Attempt to invoke virtual method \'boolean java.lang.String.equals(java.lang.Object)\' on a null object reference  [ERROR] TiApplication:  at android.app.ActivityThread.performLaunchActivity(ActivityThread.java:2325)  [ERROR] TiApplication:  at android.app.ActivityThread.handleLaunchActivity(ActivityThread.java:2387)  [ERROR] TiApplication:  at android.app.ActivityThread.access$800(ActivityThread.java:151)  [ERROR] TiApplication:  at android.app.ActivityThread$H.handleMessage(ActivityThread.java:1303)  [ERROR] TiApplication:  at android.os.Handler.dispatchMessage(Handler.java:102)  [ERROR] TiApplication:  at android.os.Looper.loop(Looper.java:135)  [ERROR] TiApplication:  at android.app.ActivityThread.main(ActivityThread.java:5254)  [ERROR] TiApplication:  at java.lang.reflect.Method.invoke(Native Method)  [ERROR] TiApplication:  at java.lang.reflect.Method.invoke(Method.java:372)  [ERROR] TiApplication:  at com.android.internal.os.ZygoteInit$MethodAndArgsCaller.run(ZygoteInit.java:903)  [ERROR] TiApplication:  at com.android.internal.os.ZygoteInit.main(ZygoteInit.java:698)  [ERROR] TiApplication: Caused by: java.lang.NullPointerException: Attempt to