INSERT INTO `Issue` VALUES (407434,153069,'TIMOB-19963','https://jira.appcelerator.org/rest/api/2/issue/153069','\"Windows: \"\"return\"\" and \"\"change\"\" event for Titanium.UI.TextArea \"','\"Implement {{change}} and {{return}} event for {{Titanium.UI.TextArea}} for Windows.\"','\"\"\"Implement {{change}} and {{return}} event for {{Titanium.UI.TextArea}} for Windows.\"\"\"','','Bug','High','Closed','Fixed','2015-11-13 08:46:19','2015-11-13 08:46:19','2015-12-01 14:07:52','2016-02-10 01:43:26',5,NULL,1008,1561,26241,0,0,0,NULL,166083,166083,166083,12,4828);
INSERT INTO `Issue` VALUES (407442,153060,'TIMOB-19955','https://jira.appcelerator.org/rest/api/2/issue/153060','\"Windows: Label only supports \"\"click\"\" event\"','\"Currently {{Ti.UI.Label}} only supports {{click}} event. [PR 477|https://github.com/<USER>titanium_mobile_windows/pull/477] should introduce some touch events on Label and it should work, and we want to make sure it works on Label.\"','\"\"\"Currently {{Ti.UI.Label}} only supports {{click}} event. [PR 477|https://github.com/<USER>titanium_mobile_windows/pull/477] should introduce some touch events on Label and it should work, and we want to make sure it works on Label.\"\"\"','','Bug','Medium','Closed','Fixed','2015-11-13 06:06:16','2015-11-13 06:06:16','2015-12-01 14:07:47','2016-02-10 01:25:57',5,NULL,1690,2242,26401,1,0,0,NULL,166083,166083,166083,12,4828);
INSERT INTO `Issue` VALUES (407444,153058,'TIMOB-19953','https://jira.appcelerator.org/rest/api/2/issue/153058','\"Windows: Button only supports \"\"click\"\" event\"','\"Currently {{Ti.UI.Button}} only supports {{click}} event. It should support {{dblclick}}, {{tap}} etc when possible.  Note that [PR 477|https://github.com/<USER>titanium_mobile_windows/pull/477] should introduce some touch events on Button and it should work, and we want to make sure it works on Button.\"','\"\"\"Currently {{Ti.UI.Button}} only supports {{click}} event. It should support {{dblclick}}, {{tap}} etc when possible.  Note that [PR 477|https://github.com/<USER>titanium_mobile_windows/pull/477] should introduce some touch events on Button and it should work, and we want to make sure it works on Button.\"\"\"','','Bug','High','Closed','Fixed','2015-11-13 05:38:57','2015-11-13 05:38:57','2015-12-01 14:07:43','2016-02-10 01:45:49',5,NULL,1690,2242,26428,0,0,0,NULL,166083,166083,166083,12,4828);
INSERT INTO `Issue` VALUES (407445,153057,'TIMOB-19952','https://jira.appcelerator.org/rest/api/2/issue/153057','\"Windows: Image support for Ti.UI.Button\"','\"Currently {{Ti.UI.Button}} doesn\'t support {{image}} property.    {code:javascript}  var window = Ti.UI.createWindow({      backgroundColor: \'green\'  });    var view = Ti.UI.createView({      backgroundColor: \'red\',      width: \'100%\',      height: 150  });    var button = Ti.UI.createButton({ title: \'Bar bar bar\' });  //button.image = \"\"http://www.<USER>com/wp-content/themes/appc-rwd/assets/media/images/logo.png\"\";  button.image = Ti.Filesystem.getFile(\'Logo.png\').read();    view.add(button);    window.add(view);  window.open();  {code}\"','\"\"\"Currently {{Ti.UI.Button}} doesn\'t support {{image}} property.    \"\"\"','\"  var window = Ti.UI.createWindow({      backgroundColor: \'green\'  });    var view = Ti.UI.createView({      backgroundColor: \'red\',      width: \'100%\',      height: 150  });    var button = Ti.UI.createButton({ title: \'Bar bar bar\' });  //button.image = \"\"\"\"http://www.appcelerator.com/wp-content/themes/appc-rwd/assets/media/images/logo.png\"\"\"\";  button.image = Ti.Filesystem.getFile(\'Logo.png\').read();    view.add(button);    window.add(view);  window.open();  \"','Bug','High','Closed','Fixed','2015-11-13 05:35:27','2015-11-13 05:35:27','2015-12-04 00:25:03','2016-02-05 00:04:30',5,NULL,3106,4033,29929,0,0,0,NULL,166083,166083,166083,12,4828);
INSERT INTO `Issue` VALUES (407449,153054,'TIMOB-19948','https://jira.appcelerator.org/rest/api/2/issue/153054','\"Windows: Use font cache for TextArea and Button\"','\"As of [PR 433|https://github.com/<USER>titanium_mobile_windows/pull/433], font cache is introduced to improve font lookup, but {{TextArea}} and {{Button}} are not using it. Make sure to use {{TitaniumWindows::UI::ViewHelper::SetFont}} for the font lookup.\"','\"\"\"As of [PR 433|https://github.com/<USER>titanium_mobile_windows/pull/433], font cache is introduced to improve font lookup, but {{TextArea}} and {{Button}} are not using it. Make sure to use {{TitaniumWindows::UI::ViewHelper::SetFont}} for the font lookup.\"\"\"','','Improvement','Medium','Closed','Fixed','2015-11-13 04:59:43','2015-11-13 04:59:43','2015-11-23 14:40:57','2016-02-19 23:24:10',5,NULL,2209,7990,14981,0,0,0,NULL,166083,166083,166083,12,4828);
INSERT INTO `Issue` VALUES (407466,153007,'TIMOB-19930','https://jira.appcelerator.org/rest/api/2/issue/153007','\"Windows: Implement Ti.Filesystem.File.deleteDirectory\"','\"{{Ti.Filesystem.File.deleteDirectory}} does not work when {{recursive}} is true.\"','\"\"\"{{Ti.Filesystem.File.deleteDirectory}} does not work when {{recursive}} is true.\"\"\"','','Bug','Medium','Closed','Fixed','2015-11-12 07:22:36','2015-11-12 07:22:36','2015-12-07 01:49:25','2016-02-09 22:31:00',5,NULL,3087,9416,35666,0,0,0,NULL,166083,166083,166018,12,4828);
INSERT INTO `Issue` VALUES (407467,153006,'TIMOB-19929','https://jira.appcelerator.org/rest/api/2/issue/153006','\"Windows: Implement Ti.Filesystem.File.append\"','\"{{Ti.Filesystem.File.append}} is not implemented for Windows.\"','\"\"\"{{Ti.Filesystem.File.append}} is not implemented for Windows.\"\"\"','','Bug','Medium','Closed','Fixed','2015-11-12 07:19:52','2015-11-12 07:19:52','2015-12-07 01:49:21','2016-02-09 23:13:43',5,NULL,3087,9416,35669,0,0,0,NULL,166083,166083,166018,12,4828);
INSERT INTO `Issue` VALUES (407471,153001,'TIMOB-19925','https://jira.appcelerator.org/rest/api/2/issue/153001','\"Windows: Implement Ti.App.Properties \"\"change\"\" event\"','\"\"\"change\"\" event should be fired when a property is changed.\"','\"\"\"\"\"\"\"change\"\"\"\" event should be fired when a property is changed.\"\"\"','','Bug','High','Closed','Fixed','2015-11-12 04:55:06','2015-11-12 04:55:06','2015-11-25 06:15:08','2016-02-12 23:43:45',5,NULL,1742,1920,18800,0,0,0,NULL,166083,166083,166018,12,4828);
INSERT INTO `Issue` VALUES (407475,152907,'TIMOB-19921','https://jira.appcelerator.org/rest/api/2/issue/152907','\"Windows: Implement missing View properties\"','\"From TIMOB-19837 Ti.UI.View TitaniumKit introduces a lot of properties. Ti.UI.View for Windows should implement them as much as possible.\"','\"\"\"From TIMOB-19837 Ti.UI.View TitaniumKit introduces a lot of properties. Ti.UI.View for Windows should implement them as much as possible.\"\"\"','','Bug','High','Closed','Fixed','2015-11-11 23:06:33','2015-11-11 23:06:33','2015-11-23 14:40:49','2017-03-21 22:38:16',13,NULL,10653,16436,16774,0,0,0,NULL,166083,166083,166083,12,4828);
INSERT INTO `Issue` VALUES (407484,152805,'TIMOB-19912','https://jira.appcelerator.org/rest/api/2/issue/152805','\"tintColor for Android ImageView\"','\"Adding tintColor property to Android using ImageView.setColorFilter()    Pull Request:   https://github.com/<USER>titanium_mobile/pull/7877    {code:java}  $.img2.setTintColor(\"\"#FF0000\"\");  $.img3.tintColor = \"\"#F0FF0F\"\";  $.index.open();  {code}    {code:java}  <Alloy>   <Window class=\"\"container\"\">    <ImageView id=\"\"img1\"\"></ImageView>    <ImageView id=\"\"img2\"\"></ImageView>    <ImageView id=\"\"img3\"\"></ImageView>   </Window>  </Alloy>  {code}    {code:java}  \"\".container\"\" : {      backgroundColor: \"\"white\"\"  }  \"\"#img1\"\" : {      image: \"\"/images/img.png\"\",      top: 0,      width: 150,      height: 150  }  \"\"#img2\"\" : {      image: \"\"/images/img.png\"\",      width: 150,      height: 150  }    \"\"#img3\"\" : {      image: \"\"/images/img.png\"\",      bottom: 0,      width: 150,      height: 150  }  {code}\"','\"\"\"Adding tintColor property to Android using ImageView.setColorFilter()    Pull Request:   https://github.com/<USER>titanium_mobile/pull/7877            \"\"\"','\"  $.img2.setTintColor(\"\"\"\"#FF0000\"\"\"\");  $.img3.tintColor = \"\"\"\"#F0FF0F\"\"\"\";  $.index.open();    <Alloy>   <Window class=\"\"\"\"container\"\"\"\">    <ImageView id=\"\"\"\"img1\"\"\"\"></ImageView>    <ImageView id=\"\"\"\"img2\"\"\"\"></ImageView>    <ImageView id=\"\"\"\"img3\"\"\"\"></ImageView>   </Window>  </Alloy>    \"\"\"\".container\"\"\"\" : {      backgroundColor: \"\"\"\"white\"\"\"\"  }  \"\"\"\"#img1\"\"\"\" : {      image: \"\"\"\"/images/img.png\"\"\"\",      top: 0,      width: 150,      height: 150  }  \"\"\"\"#img2\"\"\"\" : {      image: \"\"\"\"/images/img.png\"\"\"\",      width: 150,      height: 150  }    \"\"\"\"#img3\"\"\"\" : {      image: \"\"\"\"/images/img.png\"\"\"\",      bottom: 0,      width: 150,      height: 150  }  \"','New Feature','Medium','Closed','Fixed','2015-11-07 10:51:16','2015-11-07 10:51:16','2016-04-02 09:56:37','2016-06-27 21:06:28',5,NULL,0,0,211625,0,0,0,NULL,166025,166025,166010,12,4828);
INSERT INTO `Issue` VALUES (407488,152883,'TIMOB-19908','https://jira.appcelerator.org/rest/api/2/issue/152883','\"iOS: Ti.UI.ScrollableView was not shown\"','\"In use-autolayout enabled and specification the width/height properties.    Test case.    *tiapp.xml*    {code:xml}  <ios>    <use-autolayout>true</use-autolayout>  </ios>  {code}    *app.js*    {code:javascript}  var win = Ti.UI.createWindow(),    view0 = Ti.UI.createView({      backgroundColor: \'red\'    }),    view1 = Ti.UI.createView({      backgroundColor: \'green\'    }),    view2 = Ti.UI.createView({      backgroundColor: \'blue\'    }),    scrollableview = Ti.UI.createScrollableView({      width: 200, // not the Ti.UI.FILL or SIZE      height: 200, // not the Ti.UI.FILL or SIZE      views: [        view0,        view1,        view2      ]    });    win.add(scrollableview);  win.open();  {code}\"','\"\"\"In use-autolayout enabled and specification the width/height properties.    Test case.    *tiapp.xml*    {code:xml}  <ios>    <use-autolayout>true</use-autolayout>  </ios>  {code}    *app.js*    {code:javascript}  var win = Ti.UI.createWindow(),    view0 = Ti.UI.createView({      backgroundColor: \'red\'    }),    view1 = Ti.UI.createView({      backgroundColor: \'green\'    }),    view2 = Ti.UI.createView({      backgroundColor: \'blue\'    }),    scrollableview = Ti.UI.createScrollableView({      width: 200, // not the Ti.UI.FILL or SIZE      height: 200, // not the Ti.UI.FILL or SIZE      views: [        view0,        view1,        view2      ]    });    win.add(scrollableview);  win.open();  {code}\"\"\"','\"  <ios>    <use-autolayout>true</use-autolayout>  </ios>    var win = Ti.UI.createWindow(),    view0 = Ti.UI.createView({      backgroundColor: \'red\'    }),    view1 = Ti.UI.createView({      backgroundColor: \'green\'    }),    view2 = Ti.UI.createView({      backgroundColor: \'blue\'    }),    scrollableview = Ti.UI.createScrollableView({      width: 200, // not the Ti.UI.FILL or SIZE      height: 200, // not the Ti.UI.FILL or SIZE      views: [        view0,        view1,        view2      ]    });    win.add(scrollableview);  win.open();  \"','Bug','Low','Closed','Fixed','2015-11-10 23:50:43','2015-11-10 23:50:43','2016-04-04 13:39:44','2016-07-07 19:41:54',3,NULL,4506,11073,209629,0,0,0,NULL,166783,166783,166198,12,4828);
INSERT INTO `Issue` VALUES (407549,152575,'TIMOB-19843','https://jira.appcelerator.org/rest/api/2/issue/152575','\"Android: CardView\'s cardMaxElevation should (marked as) be creation-only\"','\"As explain in the [Android Reference|https://developer.android.com/reference/android/support/v7/widget/CardView.html#attr_android.support.v7.cardview:cardElevation] and confirmed by tests I did the {{cardMaxElevation}} property is creation-only. Changing it later has no effect.\"','\"\"\"As explain in the [Android Reference|https://developer.android.com/reference/android/support/v7/widget/CardView.html#attr_android.support.v7.cardview:cardElevation] and confirmed by tests I did the {{cardMaxElevation}} property is creation-only. Changing it later has no effect.\"\"\"','','Bug','Medium','Closed','Fixed','2015-11-02 12:44:28','2015-11-02 12:44:28','2015-12-01 08:25:56','2015-12-02 22:13:40',2,NULL,17235,17620,41501,0,0,0,NULL,166377,166377,166526,12,4828);
INSERT INTO `Issue` VALUES (407550,152573,'TIMOB-19842','https://jira.appcelerator.org/rest/api/2/issue/152573','\"Android: CardView cardPreventCornerOverlap and cardUseCompatPadding should not start with card\"','\"I think it\'s great that we follow the [platform API|https://developer.android.com/reference/android/support/v7/widget/CardView.html] for CardView, but for {{cardPreventCornerOverlap}} and {{cardUseCompatPadding}} we don\'t. On Android there are no properties, but only methods and these don\'t start with {{card}}. To match this in Titanium the properties shouldn\'t start with this either so our getters and setters match those of the platform.\"','\"\"\"I think it\'s great that we follow the [platform API|https://developer.android.com/reference/android/support/v7/widget/CardView.html] for CardView, but for {{cardPreventCornerOverlap}} and {{cardUseCompatPadding}} we don\'t. On Android there are no properties, but only methods and these don\'t start with {{card}}. To match this in Titanium the properties shouldn\'t start with this either so our getters and setters match those of the platform.\"\"\"','','Improvement','None','Closed','Fixed','2015-11-02 09:36:01','2015-11-02 09:36:01','2015-12-01 04:36:44','2015-12-02 23:12:48',3,NULL,17186,17340,41460,0,0,0,NULL,166377,166377,166526,12,4828);
INSERT INTO `Issue` VALUES (407588,152372,'TIMOB-19802','https://jira.appcelerator.org/rest/api/2/issue/152372','\"Android: CardView should use standard property names\"','\"The following sample shows that both {{backgroundColor}} and {{cardBackgroundColor}} work, but the one with {{backgroundColor}} doesn\'t show a border/corner radius. Because of TIMOB-19801 I cannot verify, but I guess when I would set both I would see a rectangle without radius behind one that has?    Is there an actual use case to have both (working, if we resolve TIMOB-19801)? If so, then we need to document the difference. If not, then I\'d say we rename {{cardBackgroundColor}} to {{backgroundColor}}.    {code:javascript}  var win = Ti.UI.createWindow({   layout: \'vertical\'  });    var card1 = Ti.UI.Android.createCardView({   top: 20,   left: 20,   right: 20,   contentPadding: 20,     cardBackgroundColor: \'#F00\'  });    card1.add(Ti.UI.createLabel({   text: \'cardBackgroundColor\',   color: \'#000\'  }));    win.add(card1);    var card2 = Ti.UI.Android.createCardView({   top: 20,   left: 20,   right: 20,   contentPadding: 20,     backgroundColor: \'#F00\'  });    card2.add(Ti.UI.createLabel({   text: \'backgroundColor\',   color: \'#000\'  }));    win.add(card2);    win.open();  {code}    *UPDATE:* I\'m not convinced deviating from standard properties like [backgroundColor|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.View-property-backgroundColor], [borderRadius|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.View-property-borderRadius], [elevation|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.View-property-elevation] and [*Padding|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.TextField-property-paddingLeft].    * *Pro:* Easier to translate what you read in the [Android reference|https://developer.android.com/reference/android/support/v7/widget/CardView.html] to your Titanium app.  * *Con:* Titanium developers are used to our naming conventions throughout what is after all a cross-platform SDK, even for platform-specific components.    Given my experience that most Titanium developers do not read the target platform references but rely on our docs and - lazy as developers are - the predictability of our API I think we should:    * Remove the {{card}} prefix from the CardView specific properties.  * Rename {{(card)CornerRadius}} to {{borderRadius}}.  * Remove the {{content}} prefix from the {{contentPadding*}} properties.\"','\"\"\"The following sample shows that both {{backgroundColor}} and {{cardBackgroundColor}} work, but the one with {{backgroundColor}} doesn\'t show a border/corner radius. Because of TIMOB-19801 I cannot verify, but I guess when I would set both I would see a rectangle without radius behind one that has?    Is there an actual use case to have both (working, if we resolve TIMOB-19801)? If so, then we need to document the difference. If not, then I\'d say we rename {{cardBackgroundColor}} to {{backgroundColor}}.        *UPDATE:* I\'m not convinced deviating from standard properties like [backgroundColor|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.View-property-backgroundColor], [borderRadius|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.View-property-borderRadius], [elevation|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.View-property-elevation] and [*Padding|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.TextField-property-paddingLeft].    * *Pro:* Easier to translate what you read in the [Android reference|https://developer.android.com/reference/android/support/v7/widget/CardView.html] to your Titanium app.  * *Con:* Titanium developers are used to our naming conventions throughout what is after all a cross-platform SDK, even for platform-specific components.    Given my experience that most Titanium developers do not read the target platform references but rely on our docs and - lazy as developers are - the predictability of our API I think we should:    * Remove the {{card}} prefix from the CardView specific properties.  * Rename {{(card)CornerRadius}} to {{borderRadius}}.  * Remove the {{content}} prefix from the {{contentPadding*}} properties.\"\"\"','\"  var win = Ti.UI.createWindow({   layout: \'vertical\'  });    var card1 = Ti.UI.Android.createCardView({   top: 20,   left: 20,   right: 20,   contentPadding: 20,     cardBackgroundColor: \'#F00\'  });    card1.add(Ti.UI.createLabel({   text: \'cardBackgroundColor\',   color: \'#000\'  }));    win.add(card1);    var card2 = Ti.UI.Android.createCardView({   top: 20,   left: 20,   right: 20,   contentPadding: 20,     backgroundColor: \'#F00\'  });    card2.add(Ti.UI.createLabel({   text: \'backgroundColor\',   color: \'#000\'  }));    win.add(card2);    win.open();  \"','Improvement','Low','Closed','Fixed','2015-10-27 12:05:36','2015-10-27 12:05:36','2015-12-02 22:58:24','2015-12-03 02:15:05',3,NULL,16939,17249,52492,1,0,0,NULL,166377,166377,166526,12,4828);
INSERT INTO `Issue` VALUES (407589,152371,'TIMOB-19801','https://jira.appcelerator.org/rest/api/2/issue/152371','\"Android: CardView causes crash when cardCornerRadius AND backgroundColor are set\"','\"The following sample demonstrates that the app crashes when you use both the {{backgroundColor}} and {{cardCornerRadius}} property on a CardView. If you use {{cardBackgroundColor}} instead it works.    {code:javascript}  var win = Ti.UI.createWindow();    var card = Ti.UI.Android.createCardView({   top: 20,   left: 20,   right: 20,   contentPadding: 20,     // Remove and it won\'t crash   cardCornerRadius: 20,     // Rename to cardBackgroundColor and it won\'t crash   backgroundColor: \'#F00\'  });    card.add(Ti.UI.createLabel({   text: \'Hello, world!\',   color: \'#000\'  }));    win.add(card);    win.open();  {code}    *Logs*    {code}  [ERROR] TiApplication: (main) [478,478] Sending event: exception on thread: main msg:java.lang.RuntimeException: Unable to start activity ComponentInfo{test.android/org.<USER>titanium.TiActivity}: java.lang.ClassCastException: android.graphics.drawable.ColorDrawable cannot be cast to android.support.v7.widget.RoundRectDrawable; Titanium 5.1.0,2015/10/26 16:46,c914b0f  [ERROR] TiApplication: java.lang.RuntimeException: Unable to start activity ComponentInfo{test.android/org.<USER>titanium.TiActivity}: java.lang.ClassCastException: android.graphics.drawable.ColorDrawable cannot be cast to android.support.v7.widget.RoundRectDrawable  [ERROR] TiApplication:  at android.app.ActivityThread.performLaunchActivity(ActivityThread.java:2325)  [ERROR] TiApplication:  at android.app.ActivityThread.handleLaunchActivity(ActivityThread.java:2387)  [ERROR] TiApplication:  at android.app.ActivityThread.access$800(ActivityThread.java:151)  [ERROR] TiApplication:  at android.app.ActivityThread$H.handleMessage(ActivityThread.java:1303)  [ERROR] TiApplication:  at android.os.Handler.dispatchMessage(Handler.java:102)  [ERROR] TiApplication:  at android.o