INSERT INTO `Issue` VALUES (407592,152345,'TIMOB-19798','https://jira.appcelerator.org/rest/api/2/issue/152345','\"CardView: contentPadding(X) and cardCornerRadius should use default unit\"','\"The following sample and attached screenshot demonstrate that the 5 {{contentPadding}} properties and {{cardCornerRadius}} do not use the default unit but are a Number used with {{px}}.    It should use the default unit like all views.    {code:javascript}  var win = Ti.UI.createWindow({   layout: \'vertical\'  });    var card = Ti.UI.Android.createCardView({   top: 20,   left: 20,   right: 20,     contentPadding: 20,   cardCornerRadius: 20  });    card.add(Ti.UI.createLabel({   text: \'PADDING AND TEXT NOT AS EXPECTED\',   color: \'#000\'  }));    win.add(card);    var card = Ti.UI.Android.createCardView({   top: 20,   left: 20,   right: 20,      contentPaddingBottom: 20,   contentPaddingLeft: 20,   contentPaddingRight: 20,   contentPaddingTop: 20,   cardCornerRadius: 20  });    card.add(Ti.UI.createLabel({   text: \'PADDING AND TEXT NOT AS EXPECTED\',   color: \'#000\'  }));    win.add(card);    var view = Ti.UI.createView({   top: 20,   left: 20,   right: 20,     height: Ti.UI.SIZE,     borderRadius: 20,     backgroundColor: \'white\'  });    view.add(Ti.UI.createLabel({   top: 20,   right: 20,   bottom: 20,   left: 20,     height: Ti.UI.SIZE,     text: \'PADDING & RADIUS AS EXPECTED\',   color: \'#000\'  }));    win.add(view);    win.open();  {code}\"','\"\"\"The following sample and attached screenshot demonstrate that the 5 {{contentPadding}} properties and {{cardCornerRadius}} do not use the default unit but are a Number used with {{px}}.    It should use the default unit like all views.    \"\"\"','\"  var win = Ti.UI.createWindow({   layout: \'vertical\'  });    var card = Ti.UI.Android.createCardView({   top: 20,   left: 20,   right: 20,     contentPadding: 20,   cardCornerRadius: 20  });    card.add(Ti.UI.createLabel({   text: \'PADDING AND TEXT NOT AS EXPECTED\',   color: \'#000\'  }));    win.add(card);    var card = Ti.UI.Android.createCardView({   top: 20,   left: 20,   right: 20,      contentPaddingBottom: 20,   contentPaddingLeft: 20,   contentPaddingRight: 20,   contentPaddingTop: 20,   cardCornerRadius: 20  });    card.add(Ti.UI.createLabel({   text: \'PADDING AND TEXT NOT AS EXPECTED\',   color: \'#000\'  }));    win.add(card);    var view = Ti.UI.createView({   top: 20,   left: 20,   right: 20,     height: Ti.UI.SIZE,     borderRadius: 20,     backgroundColor: \'white\'  });    view.add(Ti.UI.createLabel({   top: 20,   right: 20,   bottom: 20,   left: 20,     height: Ti.UI.SIZE,     text: \'PADDING & RADIUS AS EXPECTED\',   color: \'#000\'  }));    win.add(view);    win.open();  \"','Bug','High','Closed','Fixed','2015-10-26 16:01:16','2015-10-26 16:01:16','2015-12-01 07:59:00','2015-12-02 19:56:52',5,NULL,1,1431,51357,0,0,0,NULL,166377,166377,166526,12,4828);
INSERT INTO `Issue` VALUES (407594,152342,'TIMOB-19796','https://jira.appcelerator.org/rest/api/2/issue/152342','\"Android: CardView Layout property not working as expected\"','\"The new {{Ti.UI.CardView}} is [documented|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.Android.CardView-property-layout] to support the {{layout}} property - as one would expect - but it does not behave as expected.    The following sample code and attached screenshot demonstrates that none of the {{layout}} values work and that whatever mechanism is used by default is not composite since the labels are aligned top left instead of the expected centre. The first card has a view to wrap the labels to show what I\'d expect for the other vertical-card to be like. However, there as well is shows that thew view is not filling up the parent as it normally does.    {code:javascript}  var win = Ti.UI.createWindow({   backgroundColor: \'white\'  });    function createCard(layout, wrap) {     var card = Ti.UI.Android.createCardView({    top: 20,    width: Ti.UI.FILL,    height: 160,      layout: layout   });     var view;     if (wrap) {      view = Ti.UI.createView({     layout: layout    });      card.add(view);     } else {    view = card;   }     view.add(Ti.UI.createLabel({    width: 50,    height: 100,    backgroundColor: \'green\',    text: (wrap ? \'reference\' : layout) + \' in green\'   }));     view.add(Ti.UI.createLabel({    top: 10,    width: 100,    height: 50,    backgroundColor: \'red\',    text: (wrap ? \'reference\' : layout) + \' in red\'   }));     return card;  }    var scrollView = Ti.UI.createScrollView({   layout: \'vertical\'  });    scrollView.add(createCard(\'vertical\', true));  scrollView.add(createCard(\'composite\'));  scrollView.add(createCard(\'vertical\'));  scrollView.add(createCard(\'horizontal\'));    win.add(scrollView);  win.open();  {code}\"','\"\"\"The new {{Ti.UI.CardView}} is [documented|https://<USER>github.io/appc-docs/latest/#!/api/Titanium.UI.Android.CardView-property-layout] to support the {{layout}} property - as one would expect - but it does not behave as expected.    The following sample code and attached screenshot demonstrates that none of the {{layout}} values work and that whatever mechanism is used by default is not composite since the labels are aligned top left instead of the expected centre. The first card has a view to wrap the labels to show what I\'d expect for the other vertical-card to be like. However, there as well is shows that thew view is not filling up the parent as it normally does.    \"\"\"','\"  var win = Ti.UI.createWindow({   backgroundColor: \'white\'  });    function createCard(layout, wrap) {     var card = Ti.UI.Android.createCardView({    top: 20,    width: Ti.UI.FILL,    height: 160,      layout: layout   });     var view;     if (wrap) {      view = Ti.UI.createView({     layout: layout    });      card.add(view);     } else {    view = card;   }     view.add(Ti.UI.createLabel({    width: 50,    height: 100,    backgroundColor: \'green\',    text: (wrap ? \'reference\' : layout) + \' in green\'   }));     view.add(Ti.UI.createLabel({    top: 10,    width: 100,    height: 50,    backgroundColor: \'red\',    text: (wrap ? \'reference\' : layout) + \' in red\'   }));     return card;  }    var scrollView = Ti.UI.createScrollView({   layout: \'vertical\'  });    scrollView.add(createCard(\'vertical\', true));  scrollView.add(createCard(\'composite\'));  scrollView.add(createCard(\'vertical\'));  scrollView.add(createCard(\'horizontal\'));    win.add(scrollView);  win.open();  \"','Bug','High','Closed','Fixed','2015-10-26 15:04:02','2015-10-26 15:04:02','2015-12-01 02:30:49','2015-12-02 20:14:39',8,NULL,21815,40249,51086,1,0,0,NULL,166377,166377,166526,12,4828);
INSERT INTO `Issue` VALUES (407601,152333,'TIMOB-19789','https://jira.appcelerator.org/rest/api/2/issue/152333','\"Windows: Docs - Clarify requirements & installation\"','\"Per [~<USER> on TIMOB-19750:     {quote}  We might want to clarify http://docs.<USER>com/platform/latest/#!/guide/Installing_the_Windows_Phone_SDK-section-43306274_InstallingtheWindowsPhoneSDK-VisualStudio which could be read as Visual Studio 2015 being \"\"higher\"\" then VS2013 Community as well.  {quote}    Also, we might want to revisit installation docs about use with VS 2015 and Windows 10.\"','\"\"\"Per [~<USER> on TIMOB-19750:     {quote}  We might want to clarify http://docs.<USER>com/platform/latest/#!/guide/Installing_the_Windows_Phone_SDK-section-43306274_InstallingtheWindowsPhoneSDK-VisualStudio which could be read as Visual Studio 2015 being \"\"\"\"higher\"\"\"\" then VS2013 Community as well.  {quote}    Also, we might want to revisit installation docs about use with VS 2015 and Windows 10.\"\"\"','','Story','Medium','Closed','Fixed','2015-10-26 12:45:18','2015-10-26 12:45:18','2015-12-05 22:59:32','2017-03-16 22:39:28',5,NULL,46,7854,58214,0,0,0,NULL,166083,166083,166018,12,4828);
INSERT INTO `Issue` VALUES (407651,152046,'TIMOB-19725','https://jira.appcelerator.org/rest/api/2/issue/152046','\"iOS: Toggled action buttons display over keyboard\"','\"When all the action buttons are removed from above the keyboard and a keyboard button is pushed, the bar for the action buttons is hidden. If the action buttons are then toggled back on, they display on top of the keyboard. See attached gif:    !toggleoverlay.gif|thumbnail!    Example code:  {code}  var showUndoRedoActionsField = true;    var win = Ti.UI.createWindow({backgroundColor: \"\"#fff\"\",layout: \"\"vertical\"\"});  var field = Ti.UI.createTextArea({width: 300,height: 50,top: 100,backgroundColor: \"\"#f0f0f0\"\",value: \"\"Hello\"\" ,showUndoRedoActions:true});  var btn1 = Ti.UI.createButton({title: \"\"Toggle field\"\"});    field.autocorrect = false;  //field.showUndoRedoActions = showUndoRedoActionsField;    btn1.addEventListener(\"\"click\"\", function() {      showUndoRedoActionsField = !showUndoRedoActionsField;      field.showUndoRedoActions = showUndoRedoActionsField;  });    win.add(field);  win.add(btn1);  win.open();  {code}    *Steps to reproduce issue*  1. Launch an app using the above code on an iPad  2. Click on the textfield  3. Click the \'Toggle Field\' button  4. Click any key on the keyboard  5. Click the \'Toggle Field\' button    *Actual Results*  The action buttons are shown on top of the keyboard    *Expected Results*  The action button bar appears and contains the action buttons    *Notes*  This could be an iOS issue\"','\"\"\"When all the action buttons are removed from above the keyboard and a keyboard button is pushed, the bar for the action buttons is hidden. If the action buttons are then toggled back on, they display on top of the keyboard. See attached gif:    !toggleoverlay.gif|thumbnail!    Example code:      *Steps to reproduce issue*  1. Launch an app using the above code on an iPad  2. Click on the textfield  3. Click the \'Toggle Field\' button  4. Click any key on the keyboard  5. Click the \'Toggle Field\' button    *Actual Results*  The action buttons are shown on top of the keyboard    *Expected Results*  The action button bar appears and contains the action buttons    *Notes*  This could be an iOS issue\"\"\"','\"  var showUndoRedoActionsField = true;    var win = Ti.UI.createWindow({backgroundColor: \"\"\"\"#fff\"\"\"\",layout: \"\"\"\"vertical\"\"\"\"});  var field = Ti.UI.createTextArea({width: 300,height: 50,top: 100,backgroundColor: \"\"\"\"#f0f0f0\"\"\"\",value: \"\"\"\"Hello\"\"\"\" ,showUndoRedoActions:true});  var btn1 = Ti.UI.createButton({title: \"\"\"\"Toggle field\"\"\"\"});    field.autocorrect = false;  //field.showUndoRedoActions = showUndoRedoActionsField;    btn1.addEventListener(\"\"\"\"click\"\"\"\", function() {      showUndoRedoActionsField = !showUndoRedoActionsField;      field.showUndoRedoActions = showUndoRedoActionsField;  });    win.add(field);  win.add(btn1);  win.open();  \"','Bug','Medium','Closed','Fixed','2015-10-14 17:40:49','2015-10-14 17:40:49','2016-02-06 00:49:11','2016-02-06 00:50:23',3,NULL,0,18749,164588,0,0,0,NULL,166223,166223,166550,12,4828);
INSERT INTO `Issue` VALUES (407667,151912,'TIMOB-19704','https://jira.appcelerator.org/rest/api/2/issue/151912','\"Windows: Set up a Windows 10 build machine\"','\"We should really set up a Windows 10 and VS 2015 box to use as a Jenkins build agent, so we can compile JSC, HAL, Windows SDK against Win10.\"','\"\"\"We should really set up a Windows 10 and VS 2015 box to use as a Jenkins build agent, so we can compile JSC, HAL, Windows SDK against Win10.\"\"\"','','Story','Critical','Closed','Fixed','2015-10-09 16:57:47','2015-10-09 16:57:47','2015-11-23 15:42:13','2016-02-12 18:36:52',8,NULL,17302,17302,64724,0,0,0,NULL,166009,166009,166009,12,4828);
INSERT INTO `Issue` VALUES (407679,151877,'TIMOB-19692','https://jira.appcelerator.org/rest/api/2/issue/151877','\"KitchenSink: Make KitchenSink work for auto layout and refactor outdated methods\"','\"KitchenSink https://github.com/<USER>KitchenSink *master branch* is a comprehensive test suite for UI-related components and views, but it\'s been outdated. We should fix certain things to make sure it works with the latest master branch:    1. Update DefaultIcon.png to make sure it\'s the right size and that it doesn\'t have alpha channel.  2. Enable auto layout, add the following tag to the ios tag in tiapp.xml  <use-autolayout>true</use-autolayout>  3. With auto layout enabled, fix all deprecated warnings (mostly to do with AUTO property)  4. Any differences in UI behavior for auto layout enabled vs disabled should have tickets filed under the same epic with detailed descriptions so that we can tackle them one by one.\"','\"\"\"KitchenSink https://github.com/<USER>KitchenSink *master branch* is a comprehensive test suite for UI-related components and views, but it\'s been outdated. We should fix certain things to make sure it works with the latest master branch:    1. Update DefaultIcon.png to make sure it\'s the right size and that it doesn\'t have alpha channel.  2. Enable auto layout, add the following tag to the ios tag in tiapp.xml  <use-autolayout>true</use-autolayout>  3. With auto layout enabled, fix all deprecated warnings (mostly to do with AUTO property)  4. Any differences in UI behavior for auto layout enabled vs disabled should have tickets filed under the same epic with detailed descriptions so that we can tackle them one by one.\"\"\"','','Story','High','Closed','Done','2015-10-09 05:49:36','2015-10-09 05:49:36','2016-08-04 03:00:04','2016-08-04 03:00:04',5,NULL,0,56615,431830,1,0,0,NULL,166198,166198,166550,12,4828);
INSERT INTO `Issue` VALUES (407688,151785,'TIMOB-19682','https://jira.appcelerator.org/rest/api/2/issue/151785','\"iOS: Execute JavaScript on main thread by default\"','\"In TIMOB-18976 we added the ability to execute JS on the main thread. We now should set this as default.    Note, this can ONLY be merged in 5.1.0 if it causes NO behavior changes. If it does, then we must wait until 6.0.    {code}  <ios>      <run-on-main-thread>true</run-on-main-thread>      <!-- more iOS stuff here... -->  </ios>  {code}\"','\"\"\"In TIMOB-18976 we added the ability to execute JS on the main thread. We now should set this as default.    Note, this can ONLY be merged in 5.1.0 if it causes NO behavior changes. If it does, then we must wait until 6.0.    \"\"\"','\"  <ios>      <run-on-main-thread>true</run-on-main-thread>      <!-- more iOS stuff here... -->  </ios>  \"','Improvement','High','Closed','Fixed','2015-10-07 03:13:51','2015-10-07 03:13:51','2015-10-07 03:24:17','2015-10-29 23:14:27',8,NULL,0,0,10,0,0,0,NULL,166152,166152,166198,12,4860);
INSERT INTO `Issue` VALUES (407689,151777,'TIMOB-19681','https://jira.appcelerator.org/rest/api/2/issue/151777','\"Android 6.0: Adding TiMap module crashes app while start\"','\"h6.Issue Descriptions  Adding the TiMap module to Tiapp crashes an app when building for Android 6.0 (M). If the module is removed there is no crash.     h6.Steps to reproduce  1) Create a sample app having included a com.google.android.maps.v2.API_KEY  2) Get CI build 5.1.0.X or latest stable release  3) Run app on Android 6  4) Watch logs     h6.Stack Trace  {code}  10-06 17:43:25.363: E/AndroidRuntime(13751): FATAL EXCEPTION: KrollRuntimeThread   10-06 17:43:25.363: E/AndroidRuntime(13751): Process: com.app.id, PID: 13751   10-06 17:43:25.363: E/AndroidRuntime(13751): java.lang.UnsatisfiedLinkError: dlopen failed: /data/app/com.app.id-2/lib/arm/libti.map.so: has text relocations   10-06 17:43:25.363: E/AndroidRuntime(13751): at java.lang.Runtime.loadLibrary(Runtime.java:372)   10-06 17:43:25.363: E/AndroidRuntime(13751): at java.lang.System.loadLibrary(System.java:1076)   10-06 17:43:25.363: E/AndroidRuntime(13751): at org.<USER>kroll.runtime.v8.V8Runtime.loadExternalModules(V8Runtime.java:132)   10-06 17:43:25.363: E/AndroidRuntime(13751): at org.<USER>kroll.runtime.v8.V8Runtime.initRuntime(V8Runtime.java:99)   10-06 17:43:25.363: E/AndroidRuntime(13751): at org.<USER>kroll.KrollRuntime.doInit(KrollRuntime.java:185)   10-06 17:43:25.363: E/AndroidRuntime(13751): at org.<USER>kroll.KrollRuntime$KrollRuntimeThread.run(KrollRuntime.java:109)   10-06 17:43:25.364: W/ActivityManager(1990): Force finishing activity com.app.id/.PhoneActivity   10-06 17:43:25.670: I/WindowManager(1990): Screenshot max retries 4 of Token{2157417 ActivityRecord{71e9096 u0 com.app.id/.PhoneActivity t101 f}} appWin=Window{3f32588 u0 Starting com.mfoundry.enterprise.mbanking.push} drawState=4   {code}\"','\"\"\"h6.Issue Descriptions  Adding the TiMap module to Tiapp crashes an app when building for Android 6.0 (M). If the module is removed there is no crash.     h6.Steps to reproduce  1) Create a sample app having included a com.google.android.maps.v2.API_KEY  2) Get CI build 5.1.0.X or latest stable release  3) Run app on Android 6  4) Watch logs     h6.Stack Trace  \"\"\"','\"  10-06 17:43:25.363: E/AndroidRuntime(13751): FATAL EXCEPTION: KrollRuntimeThread   10-06 17:43:25.363: E/AndroidRuntime(13751): Process: com.app.id, PID: 13751   10-06 17:43:25.363: E/AndroidRuntime(13751): java.lang.UnsatisfiedLinkError: dlopen failed: /data/app/com.app.id-2/lib/arm/libti.map.so: has text relocations   10-06 17:43:25.363: E/AndroidRuntime(13751): at java.lang.Runtime.loadLibrary(Runtime.java:372)   10-06 17:43:25.363: E/AndroidRuntime(13751): at java.lang.System.loadLibrary(System.java:1076)   10-06 17:43:25.363: E/AndroidRuntime(13751): at org.appcelerator.kroll.runtime.v8.V8Runtime.loadExternalModules(V8Runtime.java:132)   10-06 17:43:25.363: E/AndroidRuntime(13751): at org.appcelerator.kroll.runtime.v8.V8Runtime.initRuntime(V8Runtime.java:99)   10-06 17:43:25.363: E/AndroidRuntime(13751): at org.appcelerator.kroll.KrollRuntime.doInit(KrollRuntime.java:185)   10-06 17:43:25.363: E/AndroidRuntime(13751): at org.appcelerator.kroll.KrollRuntime$KrollRuntimeThread.run(KrollRuntime.java:109)   10-06 17:43:25.364: W/ActivityManager(1990): Force finishing activity com.app.id/.PhoneActivity   10-06 17:43:25.670: I/WindowManager(1990): Screenshot max retries 4 of Token{2157417 ActivityRecord{71e9096 u0 com.app.id/.PhoneActivity t101 f}} appWin=Window{3f32588 u0 Starting com.mfoundry.enterprise.mbanking.push} drawState=4   \"','Bug','Critical','Closed','Fixed','2015-10-06 23:49:57','2015-10-06 23:49:57','2015-10-08 02:21:20','2015-10-13 00:35:33',1,NULL,0,1070,1591,1,0,0,NULL,166706,166706,166526,12,4860);
INSERT INTO `Issue` VALUES (407691,151730,'TIMOB-19679','https://jira.appcelerator.org/rest/api/2/issue/151730','\"Android: Added additional type support for IntentProxy\"','\"h6.Issue Description  Currently it is not possible to create a launcher shortcut programmatically using the Titanium platform. Titanium allows for the creation of an Android intent using Ti.Android.createIntent but the implementation of the putExtra method is incomplete. It currently only supports Java primitives. Creating a shortcut requires an intent and an image to be set. Ideally the following example should work:    {code:javascript}  var currentIntent = Ti.Android.currentActivity.getIntent();  currentIntent.setAction(Ti.Android.ACTION_MAIN);    // Add custom metadata to read when your App is launched from the shortcut.  currentIntent.putExtra(\"\"shortcut\"\", \"\"gallery\"\");    // Create an Intent  var shortcutIntent = Ti.Android.createIntent({    action: \"\"com.android.launcher.action.INSTALL_SHORTCUT\"\",  });    // Title that will appear with the shortcut  shortcutIntent.putExtra(Ti.Android.EXTRA_SHORTCUT_NAME, \"\"Gallery\"\");    shortcutIntent.putExtra(Ti.Android.EXTRA_SHORTCUT_INTENT, currentIntent); // Not currently possible  shortcutIntent.putExtra(\"\"duplicate\"\", false);    // Set the icon for the shortcut  var iconImage = Ti.Filesystem.getFile(Ti.Filesystem.resourcesDirectory, \"\"appicon.png\"\").read();  shortcutIntent.putExtra(Ti.Android.EXTRA_SHORTCUT_ICON, iconImage); // Not currently possible    // Adds the shortcut to the home screen.  Ti.Android.currentActivity.sendBroadcast(shortcutIntent);  {code}    I have created a pull request that adds the missing input types.  https://github.com/<USER>titanium_mobile/pull/7073\"','\"\"\"h6.Issue Description  Currently it is not possible to create a launcher shortcut programmatically using the Titanium platform. Titanium allows for the creation of an Android intent using Ti.Android.createIntent but the implementation of the putExtra method is incomplete. It currently only supports Java primitives. Creating a shortcut requires an intent and an image to be set. Ideally the following example should work:        I have created a pull request that adds the missing input types.  https://github.com/<USER>titanium_mobile/pull/7073\"\"\"','\"  var currentIntent = Ti.Android.currentActivity.getIntent();  currentIntent.setAction(Ti.Android.ACTION_MAIN);    // Add custom metadata to read when your App is launched from the shortcut.  currentIntent.putExtra(\"\"\"\"shortcut\"\"\"\", \"\"\"\"gallery\"\"\"\");    // Create an Intent  var shortcutIntent = Ti.Android.createIntent({    action: \"\"\"\"com.android.launcher.action.INSTALL_SHORTCUT\"\"\"\",  });    // Title that will appear with the shortcut  shortcutIntent.putExtra(Ti.Android.EXTRA_SHORTCUT_NAME, \"\"\"\"Gallery\"\"\"\");    shortcutIntent.putExtra(Ti.Android.EXTRA_SHORTCUT_INTENT, currentIntent); // Not currently possible  shortcutIntent.putExtra(\"\"\"\"duplicate\"\"\"\", false);    // Set the icon for the shortcut  var iconImage = Ti.Filesystem.getFile(Ti.Filesystem.resourcesDirectory, \"\"\"\"appicon.png\"\"\"\").read();  shortcutIntent.putExtra(Ti.Android.EXTRA_SHORTCUT_ICON, iconImage); // Not currently possible    // Adds the shortcut to the home screen.  Ti.Android.currentActivity.sendBroadcast(shortcutIntent);  \"','New Feature','Medium','Closed','Fixed','2015-10-05 18:52:39','2015-10-05 18:52:39','2015-12-03 03:47:42','2016-02-25 09:27:35',2,NULL,0,0,84055,1,0,0,NULL,166666,166666,166526,12,4828);
INSERT INTO `Issue` VALUES (407692,151754,'TIMOB-19678','https://jira.appcelerator.org/rest/api/2/issue/151754','\"Windows: noexcept mismatch when targeting Visual Studio 2015\"','\"Enabling {{noexcept}} on Visual Studio 2015 causes \"\"mismatch\"\" error. We have been disabling noexcept on Visual Studio 2013 (I think it\'s because it\'s shipped with some critical bugs). I think we can enable it for now.\"','\"\"\"Enabling {{noexcept}} on Visual Studio 2015 causes \"\"\"\"mismatch\"\"\"\" error. We have been disabling noexcept on Visual Studio 2013 (I think it\'s because it\'s shipped with some critical bugs). I think we can enable it for now.\"\"\"','','Bug','Medium','Closed','Fixed','2015-10-06 12:15:59','2015-10-06 12:15:59','2015-10-09 13:27:38','2015-11-03 20:35:29',5,NULL,2952,3764,4391,1,0,1,NULL,166083,166083,166083,12,4860);
INSERT INTO `Issue` VALUES (407693,151753,'TIMOB-19677','https://jira.appcelerator.org/rest/api/2/issue/151753','\"Windows: Compile targeting Windows 10 Universal\"','\"Some compile errors found in titanium_mobile_windows when targeting Windows 10 Store Apps. It also requires JavaScriptCore, HAL and gtest compiled under Visual Studio 2015.\"','\"\"\"Some compile errors found in titanium_mobile_windows when targeting Windows 10 Store Apps. It also requires JavaScriptCore, HAL and gtest compiled under Visual Studio 2015.\"\"\"','','Story','None','Closed','Fixed','2015-10-06 11:41:05','2015-10-06 11:41:05','2015-10-09 13:27:28','2015-11-03 20:38:47',8,NULL,2167,2978,4426,0,0,0,NULL,166083,166083,166083,12,4860);
INSERT INTO `Issue` VALUES (407694,151749,'TIMOB-19676','https://jira.appcelerator.org/rest/api/2/issue/151749','\"Windows: Compile HAL targeting Windows 10\"','\"Compile HAL targeting Windows 10. There\'s a link error when building *HAL* DLL under Windows 10 + Visual Studio 2015.    {code}  1>JSString.obj : error LNK2001: unresolved external symbol \"\"__declspec(dllimport) public: static class std::locale::id std::codecvt<char16_t,char,struct _Mbstatet>::id\"\" (__imp_?id@?$codecvt@_SDU_Mbstatet@@@std@@2V0locale@2@A)  {code}    That\'s a known issue introduced from Visual Studio 2015: https://connect.microsoft.com/VisualStudio/feedback/details/1348277/link-error-when-using-std-codecvt-utf8-utf16-char16-t\"','\"\"\"Compile HAL targeting Windows 10. There\'s a link error when building *HAL* DLL under Windows 10 + Visual Studio 2015.        That\'s a known issue introduced from Visual Studio 2015: https://connect.microsoft.com/VisualStudio/feedback/details/1348277/link-error-when-using-std-codecvt-utf8-utf16-char16-t\"\"\"','\"  1>JSString.obj : error LNK2001: unresolved external symbol \"\"\"\"__declspec(dllimport) public: static class std::locale::id std::codecvt<char16_t,char,struct _Mbstatet>::id\"\"\"\" (__imp_?id@?$codecvt@_SDU_Mbstatet@@@std@@2V0locale@2@A)  \"','Story','Medium','Closed','Fixed','2015-10-06 09:19:44','2015-10-06 09:19:44','2015-10-07 15:07:00','2015-11-04 00:38:24',5,NULL,604,983,1787,0,0,0,NULL,166083,166083,166083,12,4860);
INSERT INTO `Issue` VALUES (407696,151746,'TIMOB-19674','https://jira.appcelerator.org/rest/api/2/issue/151746','\"windowslib: winstore.detect always issues \"\"deployCmd not found\"\" error message\"','\"{{appc setup}} always shows {{Windows Store SDK is missing the deploy command}} error message on Windows even when Windows Store SDK is installed.    It is because {{deployCmd}} variable is not actually used for Windows Store apps but {{winstore.detect}} always checks it and issues error message.    {code}  $ appc setup  ...  The following WINDOWS issues were found in your environment:            Microsoft Windows Store SDK is missing the deploy command.          You will be unable to build Windows Store apps.    Some issues were detected for your environment            Please review the above found issues that were detected for your environment.          You should resolve these issues before building or running a cross platform app.          You can re-run setup once they are resolved to validate.    appc setup complete!  {code}    I was able to fix it locally, here\'s a PR: https://github.com/<USER>windowslib/pull/23\"','\"\"\"{{appc setup}} always shows {{Windows Store SDK is missing the deploy command}} error message on Windows even when Windows Store SDK is installed.    It is because {{deployCmd}} variable is not actually used for Windows Store apps but {{winstore.detect}} always checks it and issues error message.        I was able to fix it locally, here\'s a PR: https://github.com/<USER>windowslib/pull/23\"\"\"','\"  $ appc setup  ...  The following WINDOWS issues were found in your environment:            Microsoft Windows Store SDK is missing the deploy command.          You will be unable to build Windows Store apps.    Some issues were detected for your environment            Please review the above found issues that were detected for your environment.          You should resolve these issues before building or running a cross platform app.          You can re-run setup once they are resolved to validate.    appc setup complete!  \"','Improvement','High','Closed','Fixed','2015-10-06 05:34:36','2015-10-06 05:34:36','2015-10-06 23:40:58','2015-10-28 20:11:38',3,NULL,0,0,1086,0,0,0,NULL,166083,166083,166083,12,4860);
INSERT INTO `Issue` VALUES (407697,151745,'TIMOB-19673','https://jira.appcelerator.org/rest/api/2/issue/151745','\"windowslib: visualstudio.detect failed for VS 2015\"','\"{{windowslib.visualstudio.detect}} failed to detect Visual Studio 2015, when it is installed to the path which contains space.     {code}  PS > npm run-script test-visualstudio    > windowslib@0.1.15 test-visualstudio windowslib  > mocha --require test/init --reporter spec --check-leaks test/test-visualstudio          visualstudio      √ namespace should be an object      1) detect should find Visual Studio installations        1 passing (500ms)    1 failing      1) visualstudio detect should find Visual Studio installations:       Uncaught AssertionError: expected null to be a string        at Assertion.fail (windowslib\\node_modules\\should\\lib\\assertion.js:113:17)        at Assertion.prop.(anonymous function) [as String] (windowslib\\node_modules\\should\\lib\\ass  ertion.js:39:14)        at checkVisualStudio (windowslib\\test\\test-visualstudio.js:73:42)        at windowslib\\test\\test-visualstudio.js:34:4        at finalize (windowslib\\lib\\visualstudio.js:64:4)        at windowslib\\lib\\visualstudio.js:218:5        at done (windowslib\\node_modules\\async\\lib\\async.js:132:19)        at windowslib\\node_modules\\async\\lib\\async.js:32:16        at windowslib\\lib\\visualstudio.js:187:10        at ChildProcess.<anonymous> (windowslib\\node_modules\\node-appc\\lib\\subprocess.js:60:3)        at ChildProcess.EventEmitter.emit (events.js:98:17)        at maybeClose (child_process.js:753:16)        at Process.ChildProcess._handle.onexit (child_process.js:820:5)  {code}    It is because some spaces in {{vcvarsall}} variable is not properly escaped.     {code}  ## output from console.log(vcvarsall);  C:\\PROGRA~2\\Microsoft Visual Studio 14.0\\VC\\vcvarsall.bat  {code}    I was able to fix it locally, here\'s a PR: https://github.com/<USER>windowslib/pull/22\"','\"\"\"{{windowslib.visualstudio.detect}} failed to detect Visual Studio 2015, when it is installed to the path which contains space.         It is because some spaces in {{vcvarsall}} variable is not properly escaped.         I was able to fix it locally, here\'s a PR: https://github.com/<USER>windowslib/pull/22\"\"\"','\"  PS > npm run-script test-visualstudio    > windowslib@0.1.15 test-visualstudio windowslib  > mocha --require test/init --reporter spec --check-leaks test/test-visualstudio          visualstudio      √ namespace should be an object      1) detect should find Visual Studio installations        1 passing (500ms)    1 failing      1) visualstudio detect should find Visual Studio installations:       Uncaught AssertionError: expected null to be a string        at Assertion.fail (windowslib\\node_modules\\should\\lib\\assertion.js:113:17)        at Assertion.prop.(anonymous function) [as String] (windowslib\\node_modules\\should\\lib\\ass  ertion.js:39:14)        at checkVisualStudio (windowslib\\test\\test-visualstudio.js:73:42)        at windowslib\\test\\test-visualstudio.js:34:4        at finalize (windowslib\\lib\\visualstudio.js:64:4)        at windowslib\\lib\\visualstudio.js:218:5        at done (windowslib\\node_modules\\async\\lib\\async.js:132:19)        at windowslib\\node_modules\\async\\lib\\async.js:32:16        at windowslib\\lib\\visualstudio.js:187:10        at ChildProcess.<anonymous> (windowslib\\node_modules\\node-appc\\lib\\subprocess.js:60:3)        at ChildProcess.EventEmitter.emit (events.js:98:17)        at maybeClose (child_process.js:753:16)        at Process.ChildProcess._handle.onexit (child_process.js:820:5)    ## output from console.log(vcvarsall);  C:\\PROGRA~2\\Microsoft Visual Studio 14.0\\VC\\vcvarsall.bat  \"','Bug','High','Closed','Fixed','2015-10-06 05:26:37','2015-10-06 05:26:37','2016-04-06 05:48:15','2016-04-14 18:26:49',3,NULL,154,426,263541,0,0,0,NULL,166083,166083,166018,12,4860);
INSERT INTO `Issue` VALUES (407707,151678,'TIMOB-19662','https://jira.appcelerator.org/rest/api/2/issue/151678','\"Windows: Compile JavaScriptCore targeting Windows 10\"','\"Titanium Windows SDK and HAL will fail to build under Visual Studio 2015 because current JavaScriptCore.lib is compiled under Visual Studio 2013. VS compiler will complain about the compiler version.\"','\"\"\"Titanium Windows SDK and HAL will fail to build under Visual Studio 2015 because current JavaScriptCore.lib is compiled under Visual Studio 2013. VS compiler will complain about the compiler version.\"\"\"','','Story','Medium','Closed','Fixed','2015-10-02 07:19:38','2015-10-02 07:19:38','2015-10-09 13:28:10','2015-11-04 00:38:42',8,NULL,3496,8072,10448,1,0,0,NULL,166083,166083,166083,12,4860);
INSERT INTO `Issue` VALUES (407708,151673,'TIMOB-19661','https://jira.appcelerator.org/rest/api/2/issue/151673','\"Android: 5.0.0 GA SDK HTTPClient Fails to POST Form Data with File Correctly\"','\"I am unable to upload data to a remote server using the HTTPClient on Titanium SDK 5.0.0 GA.  The same code works correctly on SDK 4.1.0 GA.    The data object that is sent to HTTPClient looks like this:    {code:javascript}        var data = {          \"\"entry.id\"\": entryBean.id          , \"\"_eventName\"\": \"\"uploadPhoto\"\"          , \"\"imageData\"\": selectedImage          , \"\"caption\"\": $.caption.value          , \"\"fileName\"\": getFileNameFrom(selectedImage)      };    {code}    Where {{imageData}} is a photo selected from the device.      On the server, it seemed like the imageData was coming through, but nothing else: {{entry.id}}, {{_eventName}}, {{caption}}, and {{fileName}} were no populated on my server-side form.    In an effort to help debug the issue, I dumped the \"\"raw\"\" incoming POST data to the server console.  The results looked something like this:        {code:java}  --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"_eventName  Content-Type: ; charset=UTF-8  Content-Transfer-Encoding: 8bit    uploadPhoto  --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"fileName  Content-Type: ; charset=UTF-8  Content-Transfer-Encoding: 8bit    IMAG0527.jpg  --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"entry.id  Content-Type: ; charset=UTF-8  Content-Transfer-Encoding: 8bit    O1wJEoXb1lfhdYfwkn38UawovA4pG6hHecZ6DGv2-Wx0Ww-rmjihfM41D4jyCXs4  --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"imageData\"\"; filename=\"\"tixhr-1575133492.jpeg\"\"  Content-Type: image/jpeg  Content-Transfer-Encoding: binary    (lots of binary data for the image)    --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"caption  Content-Type: ; charset=UTF-8  Content-Transfer-Encoding: 8bit    final.  --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ--    {code}        I immediately saw the problem.  Note how for the non-binary fields, such as {{_eventName}} at the top, the right quote is missing at the end of the name value.      This explains why my web framework was unable to correctly populate the data model with the form data; it was unable to read it due to the missing double quote.    This is a new regression from 4.1.0.  It works correctly if I use the 4.1.0 SDK.    For those who are seeing this bug, one possible work around is to convert the file to be  uploaded to a base64 encoded string.  This is how my example from above updated to use a base64 encoded string:      {code:javascript}       var data = {          \"\"entry.id\"\": entryBean.id          , \"\"_eventName\"\": \"\"uploadPhoto\"\"          // , \"\"imageData\"\": selectedImage          , encodedImage: Ti.Utils.base64encode(selectedImage).toString()          , \"\"caption\"\": $.caption.value          , \"\"fileName\"\": getFileNameFrom(selectedImage)      };    {code}    Of course, this only works if you also control the server-side and can handle the base64 encoded file appropriately.    \"','\"\"\"I am unable to upload data to a remote server using the HTTPClient on Titanium SDK 5.0.0 GA.  The same code works correctly on SDK 4.1.0 GA.    The data object that is sent to HTTPClient looks like this:        Where {{imageData}} is a photo selected from the device.      On the server, it seemed like the imageData was coming through, but nothing else: {{entry.id}}, {{_eventName}}, {{caption}}, and {{fileName}} were no populated on my server-side form.    In an effort to help debug the issue, I dumped the \"\"\"\"raw\"\"\"\" incoming POST data to the server console.  The results looked something like this:                I immediately saw the problem.  Note how for the non-binary fields, such as {{_eventName}} at the top, the right quote is missing at the end of the name value.      This explains why my web framework was unable to correctly populate the data model with the form data; it was unable to read it due to the missing double quote.    This is a new regression from 4.1.0.  It works correctly if I use the 4.1.0 SDK.    For those who are seeing this bug, one possible work around is to convert the file to be  uploaded to a base64 encoded string.  This is how my example from above updated to use a base64 encoded string:          Of course, this only works if you also control the server-side and can handle the base64 encoded file appropriately.    \"\"\"','\"        var data = {          \"\"\"\"entry.id\"\"\"\": entryBean.id          , \"\"\"\"_eventName\"\"\"\": \"\"\"\"uploadPhoto\"\"\"\"          , \"\"\"\"imageData\"\"\"\": selectedImage          , \"\"\"\"caption\"\"\"\": $.caption.value          , \"\"\"\"fileName\"\"\"\": getFileNameFrom(selectedImage)      };      --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"\"\"_eventName  Content-Type: ; charset=UTF-8  Content-Transfer-Encoding: 8bit    uploadPhoto  --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"\"\"fileName  Content-Type: ; charset=UTF-8  Content-Transfer-Encoding: 8bit    IMAG0527.jpg  --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"\"\"entry.id  Content-Type: ; charset=UTF-8  Content-Transfer-Encoding: 8bit    O1wJEoXb1lfhdYfwkn38UawovA4pG6hHecZ6DGv2-Wx0Ww-rmjihfM41D4jyCXs4  --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"\"\"imageData\"\"\"\"; filename=\"\"\"\"tixhr-1575133492.jpeg\"\"\"\"  Content-Type: image/jpeg  Content-Transfer-Encoding: binary    (lots of binary data for the image)    --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ  Content-Disposition: form-data; name=\"\"\"\"caption  Content-Type: ; charset=UTF-8  Content-Transfer-Encoding: 8bit    final.  --4UVkNoCkrozvPT0TuugeoVAr0YbFCJ--           var data = {          \"\"\"\"entry.id\"\"\"\": entryBean.id          , \"\"\"\"_eventName\"\"\"\": \"\"\"\"uploadPhoto\"\"\"\"          // , \"\"\"\"imageData\"\"\"\": selectedImage          , encodedImage: Ti.Utils.base64encode(selectedImage).toString()          , \"\"\"\"caption\"\"\"\": $.caption.value          , \"\"\"\"fileName\"\"\"\": getFileNameFrom(selectedImage)      };    \"','Bug','Medium','Closed','Fixed','2015-10-02 02:08:58','2015-10-02 02:08:58','2015-10-02 07:28:55','2015-11-02 19:19:11',1,NULL,1,8,319,0,0,0,NULL,166833,166833,166526,12,4860);
INSERT INTO `Issue` VALUES (407709,151676,'TIMOB-19660','https://jira.appcelerator.org/rest/api/2/issue/151676','\"Android: 5.0.2 GA HTTPClient handleResponse error\"','\"HttpClient on Android was reported to have this error:  {code}  10-02 15:36:24.554: E/TiHTTPClient(22545): (TiHttpClient-25) [63819,195465] HTTP Error (java.lang.NullPointerException): Attempt to invoke virtual method \'java.lang.String[] java.lang.String.split(java.lang.String)\' on a null object reference  10-02 15:36:24.554: E/TiHTTPClient(22545): java.lang.NullPointerException: Attempt to invoke virtual method \'java.lang.String[] java.lang.String.split(java.lang.String)\' on a null object reference  10-02 15:36:24.554: E/TiHTTPClient(22545):     at ti.modules.titanium.network.TiHTTPClient.handleResponse(TiHTTPClient.java:195)  10-02 15:36:24.554: E/TiHTTPClient(22545):     at ti.modules.titanium.network.TiHTTPClient.access$1200(TiHTTPClient.java:84)  10-02 15:36:24.554: E/TiHTTPClient(22545):     at ti.modules.titanium.network.TiHTTPClient$ClientRunnable.run(TiHTTPClient.java:1194)  10-02 15:36:24.554: E/TiHTTPClient(22545):     at java.lang.Thread.run(Thread.java:818)\"\"  {code}\"','\"\"\"HttpClient on Android was reported to have this error:  \"\"\"','\"  10-02 15:36:24.554: E/TiHTTPClient(22545): (TiHttpClient-25) [63819,195465] HTTP Error (java.lang.NullPointerException): Attempt to invoke virtual method \'java.lang.String[] java.lang.String.split(java.lang.String)\' on a null object reference  10-02 15:36:24.554: E/TiHTTPClient(22545): java.lang.NullPointerException: Attempt to invoke virtual method \'java.lang.String[] java.lang.String.split(java.lang.String)\' on a null object reference  10-02 15:36:24.554: E/TiHTTPClient(22545):     at ti.modules.titanium.network.TiHTTPClient.handleResponse(TiHTTPClient.java:195)  10-02 15:36:24.554: E/TiHTTPClient(22545):     at ti.modules.titanium.network.TiHTTPClient.access$1200(TiHTTPClient.java:84)  10-02 15:36:24.554: E/TiHTTPClient(22545):     at ti.modules.titanium.network.TiHTTPClient$ClientRunnable.run(TiHTTPClient.java:1194)  10-02 15:36:24.554: E/TiHTTPClient(22545):     at java.lang.Thread.run(Thread.java:818)\"\"\"\"  \"','Bug','High','Closed','Fixed','2015-10-02 03:46:26','2015-10-02 03:46:26','2015-10-02 04:19:32','2016-06-05 21:29:18',1,NULL,32,32,33,0,0,0,NULL,166526,166526,166526,12,4860);
INSERT INTO `Issue` VALUES (407714,151654,'TIMOB-19655','https://jira.appcelerator.org/rest/api/2/issue/151654','\"Windows: HAL compile error with Visual Studio 2015\"','\"HAL causes compile error on Visual Studio 2015. It usually isn\'t a issue when compiling titanium_mobile_windows project because we use pre-built DLL, but causes error when compile everything from source.\"','\"\"\"HAL causes compile error on Visual Studio 2015. It usually isn\'t a issue when compiling titanium_mobile_windows project because we use pre-built DLL, but causes error when compile everything from source.\"\"\"','','Bug','Medium','Closed','Fixed','2015-10-01 12:10:47','2015-10-01 12:10:47','2015-10-05 14:52:13','2017-03-16 21:59:07',5,NULL,1124,5920,5921,0,0,0,NULL,166083,166083,166083,12,4860);
INSERT INTO `Issue` VALUES (407715,151650,'TIMOB-19654','https://jira.appcelerator.org/rest/api/2/issue/151650','\"Android: Error accessing Camera on device below M\"','\"Running code:   {code}  Titanium.Media.showCamera({   success:function(event) {    // called when media returned from the camera    Ti.API.debug(\'Our type was: \'+event.mediaType);    if(event.mediaType == Ti.Media.MEDIA_TYPE_PHOTO) {     var imageView = Ti.UI.createImageView({      width:win.width,      height:win.height,      image:event.media     });     win.add(imageView);    } else {     alert(\"\"got the wrong type back =\"\"+event.mediaType);    }   },   cancel:function() {    // called when user cancels taking a picture   },   error:function(error) {    // called when there\'s an error    var a = Titanium.UI.createAlertDialog({title:\'Camera\'});    a.setMessage(JSON.stringify(error));    a.show();   },   saveToPhotoGallery:true  });  {code}    Gives rise to log error:  {code}  10-01 13:07:22.718: E/TiExceptionHandler(27510): (main) [51,51] ----- Titanium Javascript Runtime Error -----  10-01 13:07:22.718: E/TiExceptionHandler(27510): (main) [0,51] - In app.js:1,16  10-01 13:07:22.718: E/TiExceptionHandler(27510): (main) [1,52] - Message: Uncaught Error: android.app.Activity.checkSelfPermission  10-01 13:07:22.718: E/TiExceptionHandler(27510): (main) [0,52] - Source: Titanium.Media.showCamera({  {code}    Due to https://github.com/<USER>titanium_mobile/blob/32600b01047b4654c92b341c6f0b61d38fa702b1/android/modules/media/src/java/ti/modules/titanium/media/MediaModule.java#L288    http://developer.android.com/reference/android/content/Context.html#checkSelfPermission(java.lang.String) Being only available in API Level 23 and above.    More logs:  {code}  10-01 13:07:22.628: W/System.err(27510): java.lang.NoSuchMethodError: android.app.Activity.checkSelfPermission  10-01 13:07:22.628: W/System.err(27510):  at ti.modules.titanium.media.MediaModule.hasPermissions(MediaModule.java:288)  10-01 13:07:22.628: W/System.err(27510):  at ti.modules.titanium.media.MediaModule.showCamera(MediaModule.java:300)  10-01 13:07:22.628: W/System.err(27510):  at org.<USER>kroll.runtime.v8.V8Runtime.nativeRunModule(Native Method)  10-01 13:07:22.628: W/System.err(27510):  at org.<USER>kroll.runtime.v8.V8Runtime.doRunModule(V8Runtime.java:177)  10-01 13:07:22.628: W/System.err(27510):  at org.<USER>kroll.KrollRuntime.handleMessage(KrollRuntime.java:299)  10-01 13:07:22.628: W/System.err(27510):  at org.<USER>kroll.runtime.v8.V8Runtime.handleMessage(V8Runtime.java:203)  10-01 13:07:22.628: W/System.err(27510):  at android.os.Handler.dispatchMessage(Handler.java:98)  10-01 13:07:22.628: W/System.err(27510):  at android.os.Looper.loop(Looper.java:136)  10-01 13:07:22.628: W/System.err(27510):  at org.<USER>kroll.KrollRuntime$KrollRuntimeThread.run(KrollRuntime.java:112)  {code}\"','\"\"\"Running code:       Gives rise to log error:      Due to https://github.com/<USER>titanium_mobile/blob/32600b01047b4654c92b341c6f0b61d38fa702b1/android/modules/media/src/java/ti/modules/titanium/media/MediaModule.java#L288    http://developer.android.com/reference/android/content/Context.html#checkSelfPermission(java.lang.String) Being only available in API Level 23 and above.    More logs:  \"\"\"','\"  Titanium.Media.showCamera({   success:function(event) {    // called when media returned from the camera    Ti.API.debug(\'Our type was: \'+event.mediaType);    if(event.mediaType == Ti.Media.MEDIA_TYPE_PHOTO) {     var imageView = Ti.UI.createImageView({      width:win.width,      height:win.height,      image:event.media     });     win.add(imageView);    } else {     alert(\"\"\"\"got the wrong type back =\"\"\"\"+event.mediaType);    }   },   cancel:function() {    // called when user cancels taking a picture   },   error:function(error) {    // called when there\'s an error    var a = Titanium.UI.createAlertDialog({title:\'Camera\'});    a.setMessage(JSON.stringify(error));    a.show();   },   saveToPhotoGallery:true  });    10-01 13:07:22.718: E/TiExceptionHandler(27510): (main) [51,51] ----- Titanium Javascript Runtime Error -----  10-01 13:07:22.718: E/TiExceptionHandler(27510): (main) [0,51] - In app.js:1,16  10-01 13:07:22.718: E/TiExceptionHandler(27510): (main) [1,52] - Message: Uncaught Error: android.app.Activity.checkSelfPermission  10-01 13:07:22.718: E/TiExceptionHandler(27510): (main) [0,52] - Source: Titanium.Media.showCamera({    10-01 13:07:22.628: W/System.err(27510): java.lang.NoSuchMethodError: android.app.Activity.checkSelfPermission  10-01 13:07:22.628: W/System.err(27510):  at ti.modules.titanium.media.MediaModule.hasPermissions(MediaModule.java:288)  10-01 13:07:22.628: W/System.err(27510):  at ti.modules.titanium.media.MediaModule.showCamera(MediaModule.java:300)  10-01 13:07:22.628: W/System.err(27510):  at org.appcelerator.kroll.runtime.v8.V8Runtime.nativeRunModule(Native Method)  10-01 13:07:22.628: W/System.err(27510):  at org.appcelerator.kroll.runtime.v8.V8Runtime.doRunModule(V8Runtime.java:177)  10-01 13:07:22.628: W/System.err(27510):  at org.appcelerator.kroll.KrollRuntime.handleMessage(KrollRuntime.java:299)  10-01 13:07:22.628: W/System.err(27510):  at org.appcelerator.kroll.runtime.v8.V8Runtime.handleMessage(V8Runtime.java:203)  10-01 13:07:22.628: W/System.err(27510):  at android.os.Handler.dispatchMessage(Handler.java:98)  10-01 13:07:22.628: W/System.err(27510):  at android.os.Looper.loop(Looper.java:136)  10-01 13:07:22.628: W/System.err(27510):  at org.appcelerator.kroll.KrollRuntime$KrollRuntimeThread.run(KrollRuntime.java:112)  \"','Bug','Critical','Closed','Duplicate','2015-10-01 05:12:28','2015-10-01 05:12:28','2015-10-08 02:40:32','2017-03-21 23:01:07',3,NULL,0,9817,9928,0,0,0,NULL,166526,166526,166650,12,4860);
INSERT INTO `Issue` VALUES (407718,151631,'TIMOB-19651','https://jira.appcelerator.org/rest/api/2/issue/151631','\"Windows: Windows 10 support for cmake\"','\"Latest cmake 3.3.2 doesn\'t support {{CMAKE_SYSTEM_VERSION=10.0}}. Seems like latest [MS version of cmake|https://github.com/Microsoft/CMake] does support it, so we need to build/get the binary and update our cmake.    {code}  (time cmake -G \"\"Visual Studio 14 2015\"\" -DCMAKE_SYSTEM_NAME=WindowsStore -DCMAKE_SYSTEM_VERSION=10.0 -DTitaniumWindows_DISABLE_TESTS= -DTitaniumWindows_Global_DISABLE_TESTS=ON -DTitaniumWindows_Ti_DISABLE_TESTS=ON -DTitaniumWindows_UI_DISABLE_TESTS=ON -DTitaniumKit_DISABLE_TESTS=ON -DHAL_DISABLE_TESTS=ON \"\"C:/titanium_mobile_windows/Examples/NG\"\")  Re-run cmake no build system arguments  CMake Error at CMakeLists.txt:17 (project):    Visual Studio 14 2015 supports Windows Store \'8.0\' and \'8.1\', but not    \'10.0\'.  Check CMAKE_SYSTEM_VERSION.  {code}\"','\"\"\"Latest cmake 3.3.2 doesn\'t support {{CMAKE_SYSTEM_VERSION=10.0}}. Seems like latest [MS version of cmake|https://github.com/Microsoft/CMake] does support it, so we need to build/get the binary and update our cmake.    \"\"\"','\"  (time cmake -G \"\"\"\"Visual Studio 14 2015\"\"\"\" -DCMAKE_SYSTEM_NAME=WindowsStore -DCMAKE_SYSTEM_VERSION=10.0 -DTitaniumWindows_DISABLE_TESTS= -DTitaniumWindows_Global_DISABLE_TESTS=ON -DTitaniumWindows_Ti_DISABLE_TESTS=ON -DTitaniumWindows_UI_DISABLE_TESTS=ON -DTitaniumKit_DISABLE_TESTS=ON -DHAL_DISABLE_TESTS=ON \"\"\"\"C:/titanium_mobile_windows/Examples/NG\"\"\"\")  Re-run cmake no build system arguments  CMake Error at CMakeLists.txt:17 (project):    Visual Studio 14 2015 supports Windows Store \'8.0\' and \'8.1\', but not    \'10.0\'.  Check CMAKE_SYSTEM_VERSION.  \"','Story','Medium','Closed','Fixed','2015-10-01 00:01:02','2015-10-01 00:01:02','2015-10-06 23:34:29','2017-03-16 22:33:01',5,NULL,5511,7890,8613,0,0,0,NULL,166083,166083,166083,12,4860);
INSERT INTO `Issue` VALUES (407719,151629,'TIMOB-19650','https://jira.appcelerator.org/rest/api/2/issue/151629','\"Windows: Builder.createAppIconSet ignores existing assets\"','\"Let say we want to create app icons with several sizes and create them during build <USER>like below.    {code:title=cli/commands/_build/copy.js}   function createAppIconSet(next) {    var appIconSetDir = path.join(this.buildDir, \'Assets\'),     missingIcons = [     // Square44x44Logo     {      description: \'Square44x44Logo.png - Used for logo\',      file: path.join(appIconSetDir, \'Square44x44Logo.png\'),      width: 44,      height: 44,      required: true     },       // Square71x71Logo     {      description: \'Square71x71Logo.png - Used for logo\',      file: path.join(appIconSetDir, \'Square71x71Logo.png\'),      width: 71,      height: 71,      required: true     },       // Square150x150Logo     {      description: \'Square150x150Logo.png - Used for logo\',      file: path.join(appIconSetDir, \'Square150x150Logo.png\'),      width: 150,      height: 150,      required: true     }    ];    this.generateAppIcons(missingIcons, next);   }  {code}     Even when you want to use custom images and place those images in your project (e.g. place custom images under platform/windows/ or project root directory), they are always ignored by the builder during the build.    !vs.png|thumbnail!\"','\"\"\"Let say we want to create app icons with several sizes and create them during build <USER>like below.    {code:title=cli/commands/_build/copy.js}   function createAppIconSet(next) {    var appIconSetDir = path.join(this.buildDir, \'Assets\'),     missingIcons = [     // Square44x44Logo     {      description: \'Square44x44Logo.png - Used for logo\',      file: path.join(appIconSetDir, \'Square44x44Logo.png\'),      width: 44,      height: 44,      required: true     },       // Square71x71Logo     {      description: \'Square71x71Logo.png - Used for logo\',      file: path.join(appIconSetDir, \'Square71x71Logo.png\'),      width: 71,      height: 71,      required: true     },       // Square150x150Logo     {      description: \'Square150x150Logo.png - Used for logo\',      file: path.join(appIconSetDir, \'Square150x150Logo.png\'),      width: 150,      height: 150,      required: true     }    ];    this.generateAppIcons(missingIcons, next);   }  {code}     Even when you want to use custom images and place those images in your project (e.g. place custom images under platform/windows/ or project root directory), they are always ignored by the builder during the build.    !vs.png|thumbnail!\"\"\"','\"   function createAppIconSet(next) {    var appIconSetDir = path.join(this.buildDir, \'Assets\'),     missingIcons = [     // Square44x44Logo     {      description: \'Square44x44Logo.png - Used for logo\',      file: path.join(appIconSetDir, \'Square44x44Logo.png\'),      width: 44,      height: 44,      required: true     },       // Square71x71Logo     {      description: \'Square71x71Logo.png - Used for logo\',      file: path.join(appIconSetDir, \'Square71x71Logo.png\'),      width: 71,      height: 71,      required: true     },       // Square150x150Logo     {      description: \'Square150x150Logo.png - Used for logo\',      file: path.join(appIconSetDir, \'Square150x150Logo.png\'),      width: 150,      height: 150,      required: true     }    ];    this.generateAppIcons(missingIcons, next);   }  \"','Bug','Medium','Closed','Fixed','2015-09-30 21:03:09','2015-09-30 21:03:09','2015-10-05 12:40:11','2018-08-06 17:49:27',5,NULL,1607,5578,6697,1,0,0,NULL,166083,166083,166018,12,4860);
