INSERT INTO `Issue` VALUES (407775,151524,'TIMOB-19588','https://jira.appcelerator.org/rest/api/2/issue/151524','\"Android: Expose color property of ProgressBar\"','\"Android Progress Bar\'s color property is not exposed. This can be exposed.\"','\"\"\"Android Progress Bar\'s color property is not exposed. This can be exposed.\"\"\"','','Improvement','High','Closed','Fixed','2015-09-28 03:55:27','2015-09-28 03:55:27','2015-09-29 02:20:19','2016-02-26 03:08:26',1,NULL,0,1338,1344,0,0,1,NULL,166526,166526,166526,12,4860);
