INSERT INTO `Issue` VALUES (407794,151377,'TIMOB-19566','https://jira.appcelerator.org/rest/api/2/issue/151377','\"Ti.Locale.currentLanguage returns locale on iOS 9\"','\"Since iOS 9 the same Titanium SDK returns a different value for {{Ti.Locale.currentLanguage}}. It now returns the full locale instead of just the language:    *app.js*  {code}  console.log(\'currentLanguage \' + Ti.Locale.currentLanguage);  console.log(\'currentCountry \' + Ti.Locale.currentCountry);  console.log(\'currentLocale \' + Ti.Locale.currentLocale);  {code}    *iOS 8.4*  {code}  [INFO]  currentLanguage en  [INFO]  currentCountry US  [INFO]  currentLocale en-US  {code}    *iOS 9*  {code}  [INFO]  currentLanguage en-US  [INFO]  currentCountry US  [INFO]  currentLocale en-US  {code}    *Code*  * https://github.com/<USER>titanium_mobile/blob/master/iphone/Classes/LocaleModule.m#L26-L29  * https://github.com/<USER>titanium_mobile/blob/master/iphone/Classes/TiLocale.m#L32-L42    Found by Q&A user  https://community.<USER>com/topic/3430/ti-locale-getcurrentlanguage-on-ios-9-returns-en-us-instead-en\"','\"\"\"Since iOS 9 the same Titanium SDK returns a different value for {{Ti.Locale.currentLanguage}}. It now returns the full locale instead of just the language:    *app.js*      *iOS 8.4*      *iOS 9*      *Code*  * https://github.com/<USER>titanium_mobile/blob/master/iphone/Classes/LocaleModule.m#L26-L29  * https://github.com/<USER>titanium_mobile/blob/master/iphone/Classes/TiLocale.m#L32-L42    Found by Q&A user  https://community.<USER>com/topic/3430/ti-locale-getcurrentlanguage-on-ios-9-returns-en-us-instead-en\"\"\"','\"  console.log(\'currentLanguage \' + Ti.Locale.currentLanguage);  console.log(\'currentCountry \' + Ti.Locale.currentCountry);  console.log(\'currentLocale \' + Ti.Locale.currentLocale);    [INFO]  currentLanguage en  [INFO]  currentCountry US  [INFO]  currentLocale en-US    [INFO]  currentLanguage en-US  [INFO]  currentCountry US  [INFO]  currentLocale en-US  \"','Bug','High','Closed','Fixed','2015-09-22 13:31:10','2015-09-22 13:31:10','2015-10-05 21:22:51','2016-01-22 00:51:36',2,NULL,0,7289,19191,0,0,0,NULL,166377,166377,166550,12,4860);
INSERT INTO `Issue` VALUES (407796,151275,'TIMOB-19564','https://jira.appcelerator.org/rest/api/2/issue/151275','\"Android: HttpClient patch method doesn\'t work from 5.0.0\"','\"From release 5.0.0, the patch method doesn\'t work.  {code}  <sdk-version>5.0.0.GA</sdk-version>  android:targetSdkVersion=\"\"23\"\"  android device version=4.3  {code}    CONSOLE :  {code}  [ERROR] :  TiHTTPClient: (TiHttpClient-19) [18578,155345] HTTP Error (java.net.ProtocolException): Unknown method \'PATCH\'; must be one of [OPTIONS, GET, HEAD, POST, PUT, DELETE, TRACE]  [ERROR] :  TiHTTPClient: java.net.ProtocolException: Unknown method \'PATCH\'; must be one of [OPTIONS, GET, HEAD, POST, PUT, DELETE, TRACE]  [ERROR] :  TiHTTPClient:  at java.net.HttpURLConnection.setRequestMethod(HttpURLConnection.java:677)  [ERROR] :  TiHTTPClient:  at ti.modules.titanium.network.TiHTTPClient$ClientRunnable.run(TiHTTPClient.java:1124)  {code}\"','\"\"\"From release 5.0.0, the patch method doesn\'t work.      CONSOLE :  \"\"\"','\"  <sdk-version>5.0.0.GA</sdk-version>  android:targetSdkVersion=\"\"\"\"23\"\"\"\"  android device version=4.3    [ERROR] :  TiHTTPClient: (TiHttpClient-19) [18578,155345] HTTP Error (java.net.ProtocolException): Unknown method \'PATCH\'; must be one of [OPTIONS, GET, HEAD, POST, PUT, DELETE, TRACE]  [ERROR] :  TiHTTPClient: java.net.ProtocolException: Unknown method \'PATCH\'; must be one of [OPTIONS, GET, HEAD, POST, PUT, DELETE, TRACE]  [ERROR] :  TiHTTPClient:  at java.net.HttpURLConnection.setRequestMethod(HttpURLConnection.java:677)  [ERROR] :  TiHTTPClient:  at ti.modules.titanium.network.TiHTTPClient$ClientRunnable.run(TiHTTPClient.java:1124)  \"','Bug','High','Closed','Not Our Bug','2015-09-18 14:58:09','2015-09-18 14:58:09','2016-03-11 08:59:52','2018-08-06 17:52:04',5,NULL,4317,11378,251641,0,0,1,NULL,166858,166858,166019,12,4860);
INSERT INTO `Issue` VALUES (407839,151172,'TIMOB-19516','https://jira.appcelerator.org/rest/api/2/issue/151172','\"Windows: Support setting Content property of ContentControl subclasses with a simple string content\"','\"If you\'re using native API access and create something like a Windows.UI.Xaml.Controls.Button, you\'d naturally want to set a text label for the button. But the Content property is a Platform.Object with the understanding it could be a String or it could be an UIElement (in fact it could be a UIElement, and if it\'s not then it\'s basically converted to a String representation, though how that\'s done isn\'t really talked about).    We need to understand this nuance of the API and support settings string values easily, i.e.  {code}  button.Content = \"\"Click me!\"\";  {code}    https://msdn.microsoft.com/en-us/library/windows/apps/windows.ui.xaml.controls.contentcontrol.content\"','\"\"\"If you\'re using native API access and create something like a Windows.UI.Xaml.Controls.Button, you\'d naturally want to set a text label for the button. But the Content property is a Platform.Object with the understanding it could be a String or it could be an UIElement (in fact it could be a UIElement, and if it\'s not then it\'s basically converted to a String representation, though how that\'s done isn\'t really talked about).    We need to understand this nuance of the API and support settings string values easily, i.e.      https://msdn.microsoft.com/en-us/library/windows/apps/windows.ui.xaml.controls.contentcontrol.content\"\"\"','\"  button.Content = \"\"\"\"Click me!\"\"\"\";  \"','Improvement','High','Closed','Fixed','2015-09-14 23:08:06','2015-09-14 23:08:06','2015-09-28 09:42:55','2015-11-03 22:21:41',5,NULL,0,3882,19354,0,0,0,NULL,166009,166009,166009,12,4860);
INSERT INTO `Issue` VALUES (407861,151070,'TIMOB-19488','https://jira.appcelerator.org/rest/api/2/issue/151070','\"iOS9: 3D-Touch: Support UIPreviewActions (\"\"Peek and Pop\"\")\"','\"Apple just presented the new 3DTouch feature of the iPhone6S. User can press a view and will review an instant feedback providing a preview of a view to select different actions, called {{UIPreviewAction}}. Each action have a {{title}}, {{style}} and {{handler}} property. Multiple actions can also be assigned to {{UIPreviewActionGroup}}. That group can have have a {{title}}, {{style}} and {{actions}} property to keep track of the assigned actions.    *Related documents:*  - https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewAction_Class/  - https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewActionGroup_Class/    *Example:*  {code}  var sendAction = Ti.UI.iOS.createPreviewAction({   title : \"\"Send per Mail\"\",   style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DEFAULT  });    sendAction.addEventListener(\"\"click\"\", function() {   alert(\"\"send mail!\"\");  });    var confirmAction = Ti.UI.iOS.createPreviewAction({   title : \"\"Confirm\"\",   style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE  });    var cancelAction = Ti.UI.iOS.createPreviewAction({   title : \"\"Cancel\"\"  });    var deleteAction = Ti.UI.iOS.createPreviewActionGroup({   title : \"\"Delete\"\",   actions : [confirmAction, cancelAction],   style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE  });    confirmAction.addEventListener(\"\"click\"\", function() {   alert(\"\"delete!\"\");  });    var win = Ti.UI.createWindow({   backgroundColor : \"\"white\"\"  });    // The view to be previewed while popping.  var previewView = Ti.UI.createView({   backgroundColor : \"\"blue\"\"  });    previewView.add(Ti.UI.createLabel({   color : \"\"#fff\"\",   text : \"\"Preview!\"\"  }));    // The window to be opened after popping the preview.  var detailWindow = Ti.UI.createWindow({   backgroundColor : \"\"yellow\"\"  });    detailWindow.add(Ti.UI.createLabel({   text : \"\"You made it!\"\"  }));    // Create the preview context  var context = Ti.UI.iOS.createPreviewContext({   preview : previewView,   actions : [sendAction, deleteAction], // Can have both Ti.UI.iOS.PreviewAction + Ti.UI.iOS.PreviewActionGroup   contentHeight : 100, // When unspecified, we use the available height   pop : function(e) {// Called after popping the preview    detailWindow.open();   }  });    // Assign the preview context  var trigger = Ti.UI.createButton({   title: \"\"Peek here!\"\",   backgroundColor : \"\"#000\"\",   tintColor: \"\"#fff\"\",   width : 200,   height : 50,   previewContext : context  });    win.add(trigger);  win.open();   {code}\"','\"\"\"Apple just presented the new 3DTouch feature of the iPhone6S. User can press a view and will review an instant feedback providing a preview of a view to select different actions, called {{UIPreviewAction}}. Each action have a {{title}}, {{style}} and {{handler}} property. Multiple actions can also be assigned to {{UIPreviewActionGroup}}. That group can have have a {{title}}, {{style}} and {{actions}} property to keep track of the assigned actions.    *Related documents:*  - https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewAction_Class/  - https://developer.apple.com/library/prerelease/ios/documentation/UIKit/Reference/UIPreviewActionGroup_Class/    *Example:*  \"\"\"','\"  var sendAction = Ti.UI.iOS.createPreviewAction({   title : \"\"\"\"Send per Mail\"\"\"\",   style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DEFAULT  });    sendAction.addEventListener(\"\"\"\"click\"\"\"\", function() {   alert(\"\"\"\"send mail!\"\"\"\");  });    var confirmAction = Ti.UI.iOS.createPreviewAction({   title : \"\"\"\"Confirm\"\"\"\",   style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE  });    var cancelAction = Ti.UI.iOS.createPreviewAction({   title : \"\"\"\"Cancel\"\"\"\"  });    var deleteAction = Ti.UI.iOS.createPreviewActionGroup({   title : \"\"\"\"Delete\"\"\"\",   actions : [confirmAction, cancelAction],   style : Ti.UI.iOS.PREVIEW_ACTION_STYLE_DESTRUCTIVE  });    confirmAction.addEventListener(\"\"\"\"click\"\"\"\", function() {   alert(\"\"\"\"delete!\"\"\"\");  });    var win = Ti.UI.createWindow({   backgroundColor : \"\"\"\"white\"\"\"\"  });    // The view to be previewed while popping.  var previewView = Ti.UI.createView({   backgroundColor : \"\"\"\"blue\"\"\"\"  });    previewView.add(Ti.UI.createLabel({   color : \"\"\"\"#fff\"\"\"\",   text : \"\"\"\"Preview!\"\"\"\"  }));    // The window to be opened after popping the preview.  var detailWindow = Ti.UI.createWindow({   backgroundColor : \"\"\"\"yellow\"\"\"\"  });    detailWindow.add(Ti.UI.createLabel({   text : \"\"\"\"You made it!\"\"\"\"  }));    // Create the preview context  var context = Ti.UI.iOS.createPreviewContext({   preview : previewView,   actions : [sendAction, deleteAction], // Can have both Ti.UI.iOS.PreviewAction + Ti.UI.iOS.PreviewActionGroup   contentHeight : 100, // When unspecified, we use the available height   pop : function(e) {// Called after popping the preview    detailWindow.open();   }  });    // Assign the preview context  var trigger = Ti.UI.createButton({   title: \"\"\"\"Peek here!\"\"\"\",   backgroundColor : \"\"\"\"#000\"\"\"\",   tintColor: \"\"\"\"#fff\"\"\"\",   width : 200,   height : 50,   previewContext : context  });    win.add(trigger);  win.open();   \"','New Feature','Medium','Closed','Fixed','2015-09-09 23:13:10','2015-09-09 23:13:10','2015-10-08 01:09:14','2015-10-27 07:48:17',13,NULL,14427,14427,40436,1,0,0,NULL,166010,166010,166010,12,4860);
INSERT INTO `Issue` VALUES (407862,151061,'TIMOB-19487','https://jira.appcelerator.org/rest/api/2/issue/151061','\"Windows: Generate missing app icons based on DefaultIcon.png\"','\"If any of the app icons are missing, then search for -{{<project-dir>/platforms/windows/DefaultIcon.png}}- and {{<project-dir>/DefaultIcon.png}} and us it to generate missing app icons.    You simply need to the base Builder object\'s {{generateAppIcons()}} method:    {code}  var missingIcons = [      {          description: \'Resources/<platform>/appicon.png - Used for iPhone\', // some meaningful description... iOS build dynamically generates this          file: \'/path/to/dest.png\', // MUST be a png and MUST have an extension          width: 100, // whatever is required          height: 100, // should match width          required: true // when DefaultIcon.png isn\'t big enough, true will trigger an error and false will skip the icon      }  ];    this.generateAppIcons(missingIcons, function (err) {      // err is either true if there was an error or undefined if it was successful  });  {code}    Here\'s a good article on MSDN about the assets for Windows apps: https://msdn.microsoft.com/en-us/library/windows/apps/mt412102.aspx\"','\"\"\"If any of the app icons are missing, then search for -{{<project-dir>/platforms/windows/DefaultIcon.png}}- and {{<project-dir>/DefaultIcon.png}} and us it to generate missing app icons.    You simply need to the base Builder object\'s {{generateAppIcons()}} method:        Here\'s a good article on MSDN about the assets for Windows apps: https://msdn.microsoft.com/en-us/library/windows/apps/mt412102.aspx\"\"\"','\"  var missingIcons = [      {          description: \'Resources/<platform>/appicon.png - Used for iPhone\', // some meaningful description... iOS build dynamically generates this          file: \'/path/to/dest.png\', // MUST be a png and MUST have an extension          width: 100, // whatever is required          height: 100, // should match width          required: true // when DefaultIcon.png isn\'t big enough, true will trigger an error and false will skip the icon      }  ];    this.generateAppIcons(missingIcons, function (err) {      // err is either true if there was an error or undefined if it was successful  });  \"','Improvement','Medium','Closed','Fixed','2015-09-09 21:45:35','2015-09-09 21:45:35','2015-11-18 01:17:32','2017-03-31 22:06:59',8,NULL,9494,17348,99571,0,0,0,NULL,166050,166050,166018,12,4860);
INSERT INTO `Issue` VALUES (407870,151042,'TIMOB-19479','https://jira.appcelerator.org/rest/api/2/issue/151042','\"Parity for Android and iOS on handling of permissions\"','\"The M Developer Preview introduces a new app permissions model which streamlines the <USER>for users to install and upgrade apps. If an app running on the M Preview supports the new permissions model, the user does not have to grant any permissions when they install or upgrade the app. Instead, the app requests permissions as it needs them, and the system shows a dialog to the user asking for the permission. This is similar to the current iOS implementation on Titanium, so we should work towards parity for both platforms in this regard.\"','\"\"\"The M Developer Preview introduces a new app permissions model which streamlines the <USER>for users to install and upgrade apps. If an app running on the M Preview supports the new permissions model, the user does not have to grant any permissions when they install or upgrade the app. Instead, the app requests permissions as it needs them, and the system shows a dialog to the user asking for the permission. This is similar to the current iOS implementation on Titanium, so we should work towards parity for both platforms in this regard.\"\"\"','','Epic','High','Closed','Fixed','2015-09-09 03:03:15','2015-09-09 03:03:15','2015-10-08 02:03:05','2016-07-19 18:33:43',1,NULL,0,247,41699,0,0,0,NULL,166198,166198,166010,12,4860);
INSERT INTO `Issue` VALUES (407901,150865,'TIMOB-19442','https://jira.appcelerator.org/rest/api/2/issue/150865','\"Windows: ti build failed when logo image assets with invalid dimension exits\"','\"{{ti build}} failes when Ti project has special kind of image assets (Logo.png, SplashScreen.png) with invalid dimension. This happens especially when you bring Ti project from other platforms which already has splash screen / app icon assets, like [Movies|https://github.com/<USER>movies] app.    {noformat}  [ERROR] 6>C:\\movies\\phone.x86\\Package.appxmanifest(40,11):   error APPX1619: App manifes references the square 150x150 logo image \'Logo.png\'   which does not have valid dimensions. It must be 150x150 pixels.   [C:\\movies\\phone.x86\\Movies.vcxproj]       6>Done Building Project \"\"C:\\movies\\phone.x86\\Movies.vcxproj\"\" (default targets) --  LED.  -- FAILED.  {noformat}    Possible workaround would be to convert these images to valid dimension at pre-build, or just ignore these special assets only when it has invalid dimension.\"','\"\"\"{{ti build}} failes when Ti project has special kind of image assets (Logo.png, SplashScreen.png) with invalid dimension. This happens especially when you bring Ti project from other platforms which already has splash screen / app icon assets, like [Movies|https://github.com/<USER>movies] app.        Possible workaround would be to convert these images to valid dimension at pre-build, or just ignore these special assets only when it has invalid dimension.\"\"\"','\"  [ERROR] 6>C:\\movies\\phone.x86\\Package.appxmanifest(40,11):   error APPX1619: App manifes references the square 150x150 logo image \'Logo.png\'   which does not have valid dimensions. It must be 150x150 pixels.   [C:\\movies\\phone.x86\\Movies.vcxproj]       6>Done Building Project \"\"\"\"C:\\movies\\phone.x86\\Movies.vcxproj\"\"\"\" (default targets) --  LED.  -- FAILED.  \"','Bug','Medium','Closed','Fixed','2015-09-01 01:24:37','2015-09-01 01:24:37','2015-09-30 09:02:36','2017-03-16 22:32:26',5,NULL,212,212,42217,1,0,0,NULL,166083,166083,166083,12,4860);
INSERT INTO `Issue` VALUES (407963,150517,'TIMOB-19375','https://jira.appcelerator.org/rest/api/2/issue/150517','\"Android: Android M new runtime permissions model\"','\"This preview introduces a new permissions model, where users can now directly manage app permissions at runtime. This model gives users improved visibility and control over permissions, while streamlining the installation and auto-update processes for app developers. Users can grant or revoke permissions individually for installed apps.    http://developer.android.com/preview/features/runtime-permissions.html  \"','\"\"\"This preview introduces a new permissions model, where users can now directly manage app permissions at runtime. This model gives users improved visibility and control over permissions, while streamlining the installation and auto-update processes for app developers. Users can grant or revoke permissions individually for installed apps.    http://developer.android.com/preview/features/runtime-permissions.html  \"\"\"','','Sub-task','Critical','Closed','Fixed','2015-08-19 04:48:52','2015-08-19 04:48:52','2015-10-08 02:38:07','2016-03-10 12:32:34',21,NULL,33423,33425,71869,0,0,0,NULL,166198,166198,166600,12,4860);
